    try {
        startParam = tgWebApp && tgWebApp.initDataUnsafe && tgWebApp.initDataUnsafe.start_param;
    } catch (e) {}
    if (!startParam || startParam.indexOf("groupAdminSettings") !== 0 || !tgWebApp || !tgWebApp.initData) return;
