function measureRefreshRate(done) {
    let finished = false;
    const finish = function(value) {
        if (finished) return;
        finished = true;
        done(value);
    };
    try {
        if (!window.requestAnimationFrame) {
            finish(null);
            return;
        }
        const gaps = [];
        let last = 0;
        const step = function(ts) {
            if (last) gaps.push(ts - last);
            last = ts;
            if (gaps.length < 40) {
                requestAnimationFrame(step);
            } else {
                gaps.sort(function(a, b) {
                    return a - b;
                });
                const best = gaps[Math.floor(gaps.length * 0.2)];
                finish(best > 2 ? Math.round(1e3 / best) : null);
            }
        };
        requestAnimationFrame(step);
        setTimeout(function() {
            finish(null);
        }, 1500);
    } catch (e) {
        finish(null);
    }
}

function fpHash(str) {
    let h1 = 0xdeadbeef,
        h2 = 0x41c6ce57,
        h3 = 0x9e3779b9,
        h4 = 0x85ebca6b;
    for (let i = 0; i < str.length; i++) {
        const ch = str.charCodeAt(i);
        h1 = Math.imul(h1 ^ ch, 2654435761);
        h2 = Math.imul(h2 ^ ch, 1597334677);
        h3 = Math.imul(h3 ^ ch, 3266489909);
        h4 = Math.imul(h4 ^ ch, 668265263);
    }
    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h3 ^ (h3 >>> 13), 3266489909);
    h3 = Math.imul(h3 ^ (h3 >>> 16), 2246822507) ^ Math.imul(h4 ^ (h4 >>> 13), 3266489909);
    h4 = Math.imul(h4 ^ (h4 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
    return [h1, h2, h3, h4].map(function(x) {
        return (x >>> 0).toString(16).padStart(8, "0");
    }).join("");
}

let hwCache;

function computeHw() {
    if (hwCache !== undefined) return hwCache;
    hwCache = null;
    try {
        const parts = [];
        const scr = window.screen || {};
        const nav = navigator;
        let gl = null;
        try {
            const cv = document.createElement("canvas");
            gl = cv.getContext("webgl") || cv.getContext("experimental-webgl");
        } catch (e) {}
        if (gl) {
            const ext = gl.getExtension("WEBGL_debug_renderer_info");
            parts.push(ext ? gl.getParameter(ext.UNMASKED_VENDOR_WEBGL) : gl.getParameter(gl.VENDOR));
            parts.push(ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER));
            parts.push(gl.getParameter(gl.MAX_TEXTURE_SIZE));
            parts.push(String(gl.getParameter(gl.MAX_VIEWPORT_DIMS)));
            parts.push(String(gl.getParameter(gl.ALIASED_LINE_WIDTH_RANGE)));
            parts.push((gl.getSupportedExtensions() || []).length);
        }
        try {
            const c2 = document.createElement("canvas");
            c2.width = 220;
            c2.height = 50;
            const x = c2.getContext("2d");
            x.textBaseline = "top";
            x.font = "15px Arial";
            x.fillStyle = "#f60";
            x.fillRect(110, 2, 60, 20);
            x.fillStyle = "#069";
            x.fillText("MjrStar fp 0123", 2, 14);
            x.fillStyle = "rgba(102,204,0,0.7)";
            x.fillText("MjrStar fp 0123", 4, 16);
            parts.push(c2.toDataURL());
        } catch (e) {}
        parts.push(Math.min(scr.width || 0, scr.height || 0) + "x" + Math.max(scr.width || 0, scr.height || 0));
        parts.push(scr.colorDepth);
        parts.push(Math.round((window.devicePixelRatio || 1) * 100));
        parts.push(nav.hardwareConcurrency);
        parts.push(nav.deviceMemory);
        parts.push(nav.maxTouchPoints);
        parts.push(nav.platform);
        hwCache = fpHash(parts.join("|"));
    } catch (e) {}
    return hwCache;
}

function loadDid() {
    try {
        return localStorage.getItem("eterna_did") || "";
    } catch (e) {
        return "";
    }
}

function saveDid(did) {
    try {
        if (did) localStorage.setItem("eterna_did", did);
    } catch (e) {}
    if (did) extraDidWrite(did);
}

function didIdbOpen(cb) {
    try {
        const req = indexedDB.open("eterna_dev", 1);
        req.onupgradeneeded = function() {
            try {
                req.result.createObjectStore("k");
            } catch (e) {}
        };
        req.onsuccess = function() {
            cb(req.result);
        };
        req.onerror = function() {
            cb(null);
        };
    } catch (e) {
        cb(null);
    }
}

function didIdbRead(cb) {
    didIdbOpen(function(db) {
        if (!db) {
            cb("");
            return;
        }
        try {
            const r = db.transaction("k", "readonly").objectStore("k").get("did");
            r.onsuccess = function() {
                cb(String(r.result || ""));
            };
            r.onerror = function() {
                cb("");
            };
        } catch (e) {
            cb("");
        }
    });
}

function didIdbWrite(did) {
    didIdbOpen(function(db) {
        if (!db) return;
        try {
            db.transaction("k", "readwrite").objectStore("k").put(did, "did");
        } catch (e) {}
    });
}

function didTgStores() {
    const out = [];
    try {
        if (tgWebApp && tgWebApp.isVersionAtLeast && tgWebApp.isVersionAtLeast("9.0")) {
            ["DeviceStorage", "SecureStorage"].forEach(function(name) {
                if (tgWebApp[name]) out.push(tgWebApp[name]);
            });
        }
    } catch (e) {}
    return out;
}

function didTgRead(cb) {
    const stores = didTgStores();
    if (!stores.length) {
        cb([]);
        return;
    }
    const found = [];
    let left = stores.length;
    stores.forEach(function(st) {
        let done = false;
        const fin = function(v) {
            if (done) return;
            done = true;
            if (v) found.push(String(v));
            if (--left === 0) cb(found);
        };
        try {
            st.getItem("eterna_did", function(err, val) {
                fin(err ? "" : val);
            });
        } catch (e) {
            fin("");
        }
        setTimeout(function() {
            fin("");
        }, 700);
    });
}

function extraDidWrite(did) {
    didIdbWrite(did);
    didTgStores().forEach(function(st) {
        try {
            st.setItem("eterna_did", did, function() {});
        } catch (e) {}
    });
}

function collectExtraDids(cb) {
    const out = [];
    let pending = 2;
    let finished = false;
    const finish = function() {
        if (finished) return;
        finished = true;
        cb(out.filter(function(v, i) {
            return v && out.indexOf(v) === i;
        }));
    };
    const step = function() {
        if (--pending === 0) finish();
    };
    didIdbRead(function(v) {
        if (v) out.push(v);
        step();
    });
    didTgRead(function(list) {
        list.forEach(function(v) {
            out.push(v);
        });
        step();
    });
    setTimeout(finish, 1200);
}

let blockedAppClosed = false;

function closeBlockedApp() {
    blockedAppClosed = true;
    try {
        document.documentElement.style.display = "none";
    } catch (e) {}
    try {
        if (tgWebApp && tgWebApp.close) tgWebApp.close();
    } catch (e) {}
}

function reportDevice() {
    try {
        const nav = navigator;
        const scr = window.screen || {};
        const conn = nav.connection || {};
        const payload = {
            tgp: tgWebApp && tgWebApp.platform,
            tgv: tgWebApp && tgWebApp.version,
            scheme: tgWebApp && tgWebApp.colorScheme,
            sw: scr.width,
            sh: scr.height,
            vw: window.innerWidth,
            vh: window.innerHeight,
            dpr: window.devicePixelRatio,
            lang: nav.language,
            tz: (Intl.DateTimeFormat().resolvedOptions() || {}).timeZone,
            tzo: -new Date().getTimezoneOffset(),
            cores: nav.hardwareConcurrency,
            mem: nav.deviceMemory,
            net: conn.effectiveType,
            dl: conn.downlink,
            rtt: conn.rtt,
            touch: (nav.maxTouchPoints || 0) > 0,
            hw: computeHw(),
            did: loadDid()
        };
        try {
            if (window.CSS && CSS.supports) payload.wk26 = CSS.supports("anchor-name", "--a");
            const inset = tgWebApp && tgWebApp.safeAreaInset;
            if (inset && typeof inset.top === "number") payload.sat = inset.top;
        } catch (e) {}
        let hzValue = null;
        let hzDone = false;
        let uadValue = null;
        let uadDone = false;
        let didsValue = null;
        let didsDone = false;
        const flush = function() {
            if (!hzDone || !uadDone || !didsDone) return;
            if (hzValue) payload.hz = hzValue;
            if (uadValue) payload.uad = uadValue;
            if (didsValue && didsValue.length) payload.dids = didsValue;
            fetch("/api/device", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify(payload)
            }).then(function(r) {
                return r.json();
            }).then(function(data) {
                if (data && data.banned) closeBlockedApp();
            }).catch(function() {});
        };
        collectExtraDids(function(list) {
            didsValue = list;
            didsDone = true;
            const mine = loadDid();
            if (mine && list.indexOf(mine) === -1) extraDidWrite(mine);
            flush();
        });
        measureRefreshRate(function(hz) {
            hzValue = hz;
            hzDone = true;
            flush();
        });
        const send = function(uad) {
            uadValue = uad;
            uadDone = true;
            flush();
        };
        const ud = nav.userAgentData;
        if (ud && ud.getHighEntropyValues) {
            ud.getHighEntropyValues(["model", "platformVersion", "fullVersionList"]).then(function(v) {
                send({
                    model: v.model,
                    pv: v.platformVersion,
                    plat: ud.platform,
                    mobile: ud.mobile,
                    fv: ((v.fullVersionList || [])[0] || {}).version
                });
            }).catch(function() {
                send(null);
            });
        } else {
            send(null);
        }
    } catch (e) {}
}

if (tgWebApp && tgWebApp.initData) {
    fetch("/api/auth/telegram", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            initData: tgWebApp.initData,
            did: loadDid(),
            hw: computeHw()
        })
    }).then(function(r) {
        return r.json();
    }).then(function(data) {
        if (data && data.did) saveDid(data.did);
        if (data && data.banned) {
            closeBlockedApp();
        } else if (data && data.ok) {
            reportDevice();
        } else if (data && data.code === "WEBAPP_BACKEND_UNAVAILABLE") {
            const notice = document.createElement("div");
            notice.className = "backend-unavailable-notice";
            notice.setAttribute("role", "status");
            notice.textContent = data.error;
            document.body.appendChild(notice);
        }
    }).catch(() => {});
}

