function fairCheckBtnIconHTML() {
    return '<span class="fair-check-btn-icon"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/ПроверкиЧестностиВторой.lottie"), "", "") + "</span>";
}

const EMOJI_OUTCOME_ARROWS = {
    "Шар1>Шар2": "Шар 1 › Шар 2",
    "Шар2>Шар1": "Шар 1 ‹ Шар 2",
    "Куб1>Куб2": "Куб 1 › Куб 2",
    "Куб2>Куб1": "Куб 1 ‹ Куб 2"
};

const DICE_STREET_DIR_TEXT = {
    asc: "по возрастанию",
    any: "любой",
    desc: "по убыванию"
};

function diceFaceInlineHTML(n) {
    const v = parseInt(n, 10);
    if (!(v >= 1 && v <= 6)) return escapeHtml(String(n));
    return '<img class="dice-face-inline" src="' + diceFacePngUrl(v) + '" alt="' + v + '">';
}

function diceFacesInlineHTML(csv) {
    return csv.split(",").filter(Boolean).map(diceFaceInlineHTML).join(" | ");
}

function diceStreetTextHTML(outcome) {
    const rest = outcome.slice("Стрит:".length);
    const cut = rest.indexOf("|");
    const dirs = new Set((cut >= 0 ? rest.slice(0, cut) : rest).split(",").filter(Boolean));
    const nums = new Set((cut >= 0 ? rest.slice(cut + 1) : "").split(",").filter(Boolean));
    const numsShown = nums.size ? STREET_TRIPLE_ORDER.filter(k => nums.has(k)).map(k => STREET_TRIPLE_VALUES[k].join(",")).join(" | ") : "любой набор";
    if (dirs.size === 1 && dirs.has("any") && !nums.size) return numsShown;
    return ["asc", "any", "desc"].filter(t => dirs.has(t)).map(t => DICE_STREET_DIR_TEXT[t]).join(", ") + "; " + numsShown;
}

function diceOutcomeDisplayHTML(outcome) {
    const after = prefix => outcome.slice(prefix.length);
    if (outcome.startsWith("Числа:")) return "Числа (" + diceFacesInlineHTML(after("Числа:")) + ")";
    if (outcome.startsWith("Нет числа:")) return "Нет числа (не " + diceFaceInlineHTML(after("Нет числа:")) + ")";
    if (outcome.startsWith("Дубль:")) return "Дубль (" + diceFacesInlineHTML(after("Дубль:")) + ")";
    if (outcome.startsWith("Трипл:")) return "Трипл (" + diceFacesInlineHTML(after("Трипл:")) + ")";
    if (outcome.startsWith("Комбинация:")) return "Комбинация (" + diceFacesInlineHTML(after("Комбинация:")) + ")";
    if (outcome.startsWith("Квадро:")) return "Квадро (" + diceFacesInlineHTML(after("Квадро:")) + ")";
    if (outcome.startsWith("Точный исход 2к:") || outcome.startsWith("Точный исход 3к:")) {
        const parts = after("Точный исход 2к:").split("|");
        return "Точный исход (" + parts.map(x => x ? diceFacesInlineHTML(x) : "любое").join(" / ") + ")";
    }
    if (outcome.startsWith("Стрит:")) return "Стрит (" + diceStreetTextHTML(outcome) + ")";
    if (outcome.startsWith("Большой куб:")) return "Большой куб (" + escapeHtml(after("Большой куб:")) + "-й куб)";
    if (outcome.startsWith("Хотя бы:")) return "Хотя бы (" + diceFacesInlineHTML(after("Хотя бы:")) + ")";
    if (outcome.startsWith("Сумма 2к:")) {
        const s = diceSum2Parse(outcome);
        if (s) return diceSumLabel(s.op, s.n);
    }
    if (outcome.startsWith("Итог 2к:")) return "Итог (" + after("Итог 2к:").split(",").join(" | ") + ")";
    if (outcome === "Без 1 и 6") return "Без " + diceFaceInlineHTML(1) + " и " + diceFaceInlineHTML(6);
    if (DICE_SUM_FIXED_RE.test(outcome)) {
        const m = DICE_SUM_FIXED_RE.exec(outcome);
        return diceSumLabel(m[2], parseInt(m[3], 10));
    }
    if (DICE_FOUR_HAND_NAME[outcome]) return DICE_FOUR_HAND_NAME[outcome];
    if (outcome.startsWith("Больший куб:")) return "Больший куб (" + escapeHtml(after("Больший куб:")) + "-й куб)";
    if (outcome.startsWith("Коридор ")) {
        const c = diceCorridorParse(outcome);
        if (c) return "Коридор (" + c.lo + "–" + c.hi + ")";
    }
    if (outcome === "Рост 3к" || outcome === "Рост 4к") return "Рост";
    if (outcome === "Спад 3к" || outcome === "Спад 4к") return "Спад";
    if (outcome === "Все разные 4к" || outcome === "Уникальные") return "Все разные";
    if (outcome.startsWith("Произведение ")) return "Произведение " + outcome.slice("Произведение ".length, "Произведение ".length + 1) + " " + outcome.slice("Произведение ".length + 1);
    if (DICE_LADDERS[outcome]) return diceLadderTitle(outcome);
    return escapeHtml(outcome);
}

function emojiOutcomeDisplayHTML(gameKey, outcome) {
    if (!outcome) return "";
    if (gameKey === "слоты") return slotsOutcomeDisplayHTML(outcome);
    if (EMOJI_OUTCOME_ARROWS[outcome]) return EMOJI_OUTCOME_ARROWS[outcome];
    if (gameKey === "кости") return diceOutcomeDisplayHTML(outcome);
    if (TX_GAME_BY_KEY[gameKey]) return txOutcomeDisplayHTML(TX_GAME_BY_KEY[gameKey], outcome);
    return escapeHtml(outcome);
}

function slotsOutcomeDisplayHTML(outcome) {
    if (!outcome) return "";
    const iconGroup = list => list.map(sym => '<img class="slot-symbol-icon slot-symbol-icon-sm" src="' + CAPTCHA_SYMBOL_URLS[sym] + '" alt="' + escapeHtml(sym) + '">').join("");
    if (outcome.startsWith("Точный исход:")) {
        const parts = outcome.slice("Точный исход:".length).split("|");
        return "Своя комбинация: " + parts.map(p => p ? iconGroup(p.split(",")) : "любой").join(" | ");
    }
    if (outcome.startsWith("Кол-во:")) {
        const parts = outcome.split(":");
        return "Точный исход: " + iconGroup([parts[1]]) + " — ровно " + escapeHtml(parts[2] || "") + (parts[2] === "1" ? " раз" : " раза");
    }
    if (SLOTS_DISPLAY[outcome]) return escapeHtml(SLOTS_DISPLAY[outcome]);
    if (outcome.startsWith("Комбинация:")) {
        const picks = outcome.slice("Комбинация:".length).split(",").filter(Boolean);
        return "Комбинация: " + iconGroup(picks);
    }
    if (outcome.startsWith("Дуэль:")) {
        const parts = outcome.split(":");
        return "Дуэль: " + iconGroup([parts[1]]) + " " + escapeHtml(parts[2] || "");
    }
    return escapeHtml(outcome);
}

function emojiHistoryRowHTML(gameKey, r, i, fallbackOutcome) {
    let meta = {};
    try {
        meta = JSON.parse(r.meta || "{}");
    } catch (e) {}
    const isWin = r.result === "win";
    const isDraw = r.result === "draw";
    const inChatRound = !!(r.in_chat || meta.inChat);
    const botBadge = inChatRound ? '<span class="gv-history-bot-badge">Чат</span>' : meta.playedInBot ? '<span class="gv-history-bot-badge">Бот</span>' : "";
    const isMe = r.user_id == null || r.user_id === CURRENT_UID;
    const rowName = isMe ? currentUser.displayName || "Игрок" : r.username || "Игрок";
    const avatarHTML = isMe ? lazyImgTag(currentUser.avatarUrl, currentUser.displayName) : r.anon ? "?" : lazyImgTag("/api/avatar/" + r.user_id, rowName);
    const outcomeText = emojiOutcomeDisplayHTML(gameKey, meta.outcome || fallbackOutcome);
    return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-avatar">' + (isMe || !r.anon ? '<div class="skel-box"></div>' : "") + avatarHTML + "</div>" + '<div class="gv-history-mid">' + '<div class="gv-history-name"><span class="gv-history-name-text">' + escapeHtml(rowName) + "</span>" + botBadge + "</div>" + historyTimeHTML(r.created_at) + "</div>" + '<div class="gv-history-right">Сумма ставки: <b>' + fmtNum(r.bet) + "⭐️</b><br>" + '<span class="gv-history-outcome">Исход: <b>' + outcomeText + "</b></span><br>" + (isDraw ? '<span class="gv-history-draw">Ничья: возврат ' + fmtNum(r.win_amount) + "⭐️</span>" : isWin ? '<span class="gv-history-win">Выигрыш: ' + fmtNum(r.win_amount) + "⭐️</span>" : Number(r.win_amount) > 0 ? '<span class="gv-history-lose">Проигрыш, возврат ' + fmtNum(r.win_amount) + "⭐️</span>" : '<span class="gv-history-lose">Проигрыш</span>') + "</div>" + "</div>" + (meta.checkLink ? '<button class="crash-history-fair-btn" type="button" data-game="' + gameKey + '" data-idx="' + i + '">' + fairCheckBtnIconHTML() + "Проверить честность</button>" : "") + "</div>";
}

const EMOJI_GAME_LABELS = {
    "кости": "Кости",
    "боулинг": "Боулинг",
    "дартс": "Дартс",
    "баскетбол": "Баскетбол",
    "футбол": "Футбол",
    "слоты": "Слоты"
};

function emojiRoundMediaHTML(gameKey, meta) {
    if (gameKey === "слоты") {
        const raw = meta.reels || [];
        const groups = Array.isArray(raw[0]) ? raw : (raw.length ? [raw] : []);
        const mapSrc = sym => SLOT_SYMBOL_URLS[sym] || SLOT_IDLE_URL;
        if (groups.length > 1) {
            const labels = slotsLabelsFor(slotsGameTypeOf(meta.outcome || "")) || ["Бросок 1", "Бросок 2", "Бросок 3"];
            return '<div class="dice-img-wrap pair' + (groups.length > 2 ? " slots-three" : "") + '" style="flex-direction:column; align-items:stretch;">' + groups.map((g, i) => slotReelsRowHTML(g.map(mapSrc), labels[i])).join('<div class="my-games-divider"></div>') + "</div>";
        }
        const srcs = (groups[0] || []).map(mapSrc);
        return '<div class="dice-img-wrap pair">' + slotReelsHTML(srcs.length === 3 ? srcs : [SLOT_IDLE_URL, SLOT_IDLE_URL, SLOT_IDLE_URL]) + "</div>";
    }
    const urlFns = {
        "кости": diceFaceUrl,
        "боулинг": bowlPinUrl,
        "дартс": dartsRingUrl,
        "баскетбол": basketBallUrl,
        "футбол": footBallUrl
    };
    const urlFn = urlFns[gameKey];
    const values = meta.values || meta.dice || [];
    if (!urlFn || !values.length) {
        return '<div class="dice-img-wrap"><span class="img-frame"><div class="skel-box"></div></span></div>';
    }
    if (values.length === 1) {
        return '<div class="dice-img-wrap"><span class="img-frame"><div class="skel-box"></div>' + lazyImgTag(urlFn(values[0]), "", "dice-img") + "</span></div>";
    }
    if (values.length >= 3 && gameKey === "кости") {
        const type3 = diceGameTypeOf(meta.outcome || "");
        const labels3 = diceLabelsFor(type3) || ["Кубик 1", "Кубик 2", "Кубик 3"];
        return '<div class="dice-img-wrap pair">' + diceMultiHTML(values.map(urlFn), labels3) + "</div>";
    }
    if (values.length >= 3) {
        return '<div class="dice-img-wrap pair">' + txMultiHTML(values.map(urlFn), values.map((_, i) => "Бросок " + (i + 1))) + "</div>";
    }
    const labels = /^Дуэль/.test(meta.outcome || "") ? ["Игрок", "Бот"] : ["Бросок 1", "Бросок 2"];
    return '<div class="dice-img-wrap pair">' + dicePairHTML([urlFn(values[0]), urlFn(values[1])], labels) + "</div>";
}

function emojiProofLinksHTML(meta) {
    const links = Array.isArray(meta.checkLinks) ? meta.checkLinks : [];
    return links.slice(1).map((url, index) => /^https:\/\/t\.me\/(?:c\/\d+|[A-Za-z0-9_]+)\/\d+$/.test(url) ? '<a class="gv-fair" style="position:static" href="' + url + '" target="_blank" rel="noopener">Бросок ' + (index + 2) + '</a>' : "").join("");
}

function openEmojiRoundModal(gameKey, r, meta, playerName) {
    const modal = document.getElementById("emojiRoundModal");
    if (!modal) return;
    const isWin = r.result === "win";
    const isDraw = r.result === "draw";
    const msgId = String(meta.checkLink || "").split("/").filter(Boolean).pop() || "—";
    document.getElementById("emojiRoundTitle").textContent = (EMOJI_GAME_LABELS[gameKey] || gameKey) + " #" + msgId;
    document.getElementById("emojiRoundPlayerValue").textContent = playerName || currentUser.displayName || "Игрок";
    const statusEl = document.getElementById("emojiRoundStatus");
    statusEl.className = "emoji-round-status " + (isDraw ? "draw" : isWin ? "win" : "lose");
    statusEl.textContent = isDraw ? "Ничья: возврат " + fmtNum(r.win_amount) + "⭐️" : isWin ? "Выигрыш +" + fmtNum(r.win_amount) + "⭐️" : Number(r.win_amount) > 0 ? "Проигрыш −" + fmtNum(r.bet - r.win_amount) + "⭐️ (возврат " + fmtNum(r.win_amount) + "⭐️)" : "Проигрыш −" + fmtNum(r.bet) + "⭐️";
    const coefEl = document.getElementById("emojiRoundCoef");
    coefEl.textContent = meta.mult != null ? "Коэффициент x" + fmtCoef(meta.mult) : "";
    document.getElementById("emojiRoundMedia").innerHTML = emojiRoundMediaHTML(gameKey, meta);
    document.getElementById("emojiRoundBetValue").textContent = fmtNum(r.bet) + "⭐️";
    const outcomeValueEl = document.getElementById("emojiRoundOutcomeValue");
    if (meta.outcome) outcomeValueEl.innerHTML = emojiOutcomeDisplayHTML(gameKey, meta.outcome);
    else outcomeValueEl.textContent = "—";
    const resultEl = document.getElementById("emojiRoundResultValue");
    resultEl.className = "emoji-round-info-value " + (isDraw ? "draw" : isWin ? "win" : "lose");
    resultEl.textContent = isDraw ? "Ничья: " + fmtNum(r.win_amount) + "⭐️" : isWin ? "Выигрыш: " + fmtNum(r.win_amount) + "⭐️" : Number(r.win_amount) > 0 ? "Проигрыш, возврат " + fmtNum(r.win_amount) + "⭐️" : "Проигрыш";
    document.getElementById("emojiRoundTimeValue").textContent = mskStr(r.created_at);
    const sourceEl = document.getElementById("emojiRoundSourceValue");
    const inChatRound = !!(r.in_chat || meta.inChat);
    if (sourceEl) sourceEl.textContent = inChatRound ? "Игровой чат (Telegram)" : meta.playedInBot ? "Привате с ботом (Telegram)" : "MiniApp";
    const uidEl = document.getElementById("emojiRoundUid");
    uidEl.dataset.copy = msgId;
    uidEl.innerHTML = fairHashHTML(msgId);
    const tgLink = document.getElementById("emojiRoundTgLink");
    let proofs = document.getElementById("emojiRoundProofLinks");
    if (!proofs) {
        proofs = document.createElement("div");
        proofs.id = "emojiRoundProofLinks";
        proofs.style.cssText = "display:flex;flex-wrap:wrap;gap:8px";
        tgLink.insertAdjacentElement("afterend", proofs);
    }
    proofs.innerHTML = inChatRound ? "" : emojiProofLinksHTML(meta);
    if (meta.checkLink && !inChatRound) {
        tgLink.href = meta.checkLink;
        tgLink.style.display = "";
    } else {
        tgLink.style.display = "none";
    }
    modal.classList.add("active");
}

function closeEmojiRoundModal() {
    const modal = document.getElementById("emojiRoundModal");
    if (modal) modal.classList.remove("active");
}

document.getElementById("emojiRoundClose").addEventListener("click", closeEmojiRoundModal);

document.getElementById("emojiRoundModal").addEventListener("click", e => {
    if (e.target === document.getElementById("emojiRoundModal")) closeEmojiRoundModal();
});

document.addEventListener("click", e => {
    const btn = e.target.closest(".crash-history-fair-btn[data-game]");
    if (!btn) return;
    const rows = EMOJI_HISTORY_CACHE[btn.dataset.game];
    const idx = Number(btn.dataset.idx);
    const r = rows && rows[idx];
    if (!r) return;
    let meta = {};
    try {
        meta = JSON.parse(r.meta || "{}");
    } catch (err) {}
    const rowIsMe = r.user_id == null || r.user_id === CURRENT_UID;
    openEmojiRoundModal(btn.dataset.game, r, meta, rowIsMe ? undefined : r.username || "Игрок");
});

function resyncBalance() {
    fetch("/api/state?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (data && data.ok && typeof data.balance === "number") applyBalance(data.balance);
    }).catch(() => {});
}

function resyncBalanceSoon() {
    resyncBalance();
    setTimeout(resyncBalance, 5000);
    setTimeout(resyncBalance, 15000);
}

function cleanBalance(value) {
    const n = Number(value);
    return Number.isFinite(n) ? Math.round(n * 1e6) / 1e6 : 0;
}

function applyBalance(amount) {
    amount = cleanBalance(amount);
    const from = currentUser.balance;
    currentUser.balance = amount;
    if (window.gvRepeatReady) gvRepeatRefresh();
    if (!userDataLoaded) return;
    if (from === amount) {
        document.querySelectorAll(".balance-pill .amount").forEach(el => {
            setBalanceAmount(el, amount);
            el.classList.remove("text-skel");
        });
        const wvAmount = document.querySelector(".wallet-balance-amount");
        if (wvAmount) {
            setBalanceAmount(wvAmount, amount);
            wvAmount.classList.remove("text-skel");
        }
        const balanceModalAmount = document.getElementById("balanceModalAmount");
        if (balanceModalAmount) {
            setBalanceAmount(balanceModalAmount, amount);
            balanceModalAmount.classList.remove("text-skel");
        }
        return;
    }
    animateBalanceNumber(from, amount, BALANCE_ANIM_MS);
}

function applyUserToUI() {
    if (!userDataLoaded) return;
    document.querySelectorAll("#brandName, #subHelloName, #profileName, #wvBrandName, #wvBalanceBrandName").forEach(el => {
        el.textContent = currentUser.displayName;
        el.classList.remove("text-skel");
    });
    applyBalance(currentUser.balance);
    const dateEl = document.getElementById("profileDate");
    if (dateEl) dateEl.textContent = formatDate(currentUser.registrationDate);
    const uidEl = document.getElementById("profileUid");
    if (uidEl) {
        uidEl.textContent = "ID " + currentUser.id;
        uidEl.classList.remove("text-skel");
    }
    document.querySelectorAll("#brandMark, #profileAvatar, #wvBrandMark, #wvBalanceBrandMark").forEach(el => {
        el.innerHTML = '<div class="skel-box"></div>' + lazyImgTag(currentUser.avatarUrl, currentUser.displayName);
    });
}

