const DOTLOTTIE_CDN = "https://cdn.jsdelivr.net/npm/@lottiefiles/dotlottie-web@0.80.0/dist/";

let _dotLottieModulePromise = null;

function loadDotLottie() {
    if (!_dotLottieModulePromise) {
        _dotLottieModulePromise =
            import (DOTLOTTIE_CDN + "index.js").then(mod => {
                mod.DotLottie.setWasmUrl(DOTLOTTIE_CDN + "dotlottie-player.wasm");
                return mod.DotLottie;
            });
    }
    return _dotLottieModulePromise;
}

const LOTTIE_DPR = Math.min(window.devicePixelRatio || 1, 2);

const LOTTIE_SMALL_PX = 96;

function lottieDprFor(canvas) {
    const dpr = window.devicePixelRatio || 1;
    if (document.documentElement.classList.contains("perf-low")) return LOTTIE_DPR;
    let w = 0;
    try {
        w = canvas.clientWidth || parseFloat(getComputedStyle(canvas).width) || 0;
    } catch (e) {}
    return w > 0 && w <= LOTTIE_SMALL_PX ? Math.min(Math.max(dpr, 2), 3) : Math.min(Math.max(dpr, 1.5), 2);
}

function lottieSettleSize(canvas, dl, tries) {
    if (canvas._dotLottie !== dl || !canvas.isConnected) return;
    const lw = canvas.clientWidth;
    if (!lw) return;
    const rectW = canvas.getBoundingClientRect().width;
    if (Math.abs(rectW - lw) > .5 && tries < 14) {
        setTimeout(() => lottieSettleSize(canvas, dl, tries + 1), 220);
        return;
    }
    try {
        if (Math.abs(canvas.width - Math.round(lw * (canvas._lottieDpr || LOTTIE_DPR))) > 1) dl.resize();
    } catch (e) {}
}

const LOTTIE_IDLE_MAX_PX = 64;

const LOTTIE_IDLE_GAP_MS = 7000;

const LOTTIE_IDLE_JITTER_MS = 5000;

const _lottieLive = new Set();

const LOTTIE_REST_FRAME = {};

const _lottiePausedByHide = new Set();

function lottieIsDecorative(canvas) {
    try {
        const w = getComputedStyle(canvas).width;
        return /px$/.test(w) && parseFloat(w) > 0 && parseFloat(w) <= LOTTIE_IDLE_MAX_PX;
    } catch (e) {
        return false;
    }
}

function replayLottie(canvas) {
    const dl = canvas && canvas._dotLottie;
    if (!dl) return;
    try {
        dl.stop();
        dl.play();
    } catch (e) {}
}

function gvLottieOnceDone(canvas) {
    canvas._lottieOnceDone = true;
    canvas.dispatchEvent(new Event("lottieonce"));
}

function gvLottieOnce(id) {
    const root = typeof id === "string" ? document.getElementById(id) : id;
    if (!root) return;
    root.querySelectorAll("canvas.lottie-canvas").forEach(c => {
        c.dataset.lottieOnce = "1";
    });
}

function gvAfterResultAnim(id, fn, maxMs) {
    const root = typeof id === "string" ? document.getElementById(id) : id;
    const canvases = root ? Array.from(root.querySelectorAll("canvas.lottie-canvas[data-lottie-once]")) : [];
    if (!canvases.length) {
        fn();
        return;
    }
    let finished = false;
    let poll = 0;
    let cap = 0;
    const check = () => {
        if (canvases.every(c => c._lottieOnceDone)) run();
    };
    const run = () => {
        if (finished) return;
        finished = true;
        clearInterval(poll);
        clearTimeout(cap);
        canvases.forEach(c => c.removeEventListener("lottieonce", check));
        fn();
    };
    canvases.forEach(c => c.addEventListener("lottieonce", check));
    poll = setInterval(() => {
        if (!root.isConnected || canvases.every(c => !c.isConnected || c._lottieOnceDone)) run();
    }, 250);
    cap = setTimeout(run, maxMs || 7e3);
    check();
}

function destroyLottie(canvas) {
    const dl = canvas && canvas._dotLottie;
    if (!dl) return;
    canvas._dotLottie = null;
    _lottieLive.delete(dl);
    _lottiePausedByHide.delete(dl);
    if (canvas._lottieIdleTimer) {
        clearTimeout(canvas._lottieIdleTimer);
        canvas._lottieIdleTimer = 0;
    }
    const kill = () => {
        try {
            dl.destroy();
        } catch (e) {}
    };
    if (dl.isLoaded === false) {
        let done = false;
        const once = () => {
            if (done) return;
            done = true;
            kill();
        };
        dl.addEventListener("load", once);
        dl.addEventListener("loadError", once);
        setTimeout(once, 8e3);
    } else {
        kill();
    }
}

function mountLottieCanvas(canvas) {
    if (!canvas || canvas.dataset.lottieMounted) return;
    const src = canvas.getAttribute("data-lottie-src");
    if (!src) return;
    canvas.dataset.lottieMounted = "1";
    const idle = lottieIsDecorative(canvas);
    const once = !!canvas.dataset.lottieOnce;
    const dotLottieOpts = {
        canvas: canvas,
        src: src,
        loop: !idle && !once,
        autoplay: true,
        renderConfig: {
            autoResize: true,
            devicePixelRatio: lottieDprFor(canvas),
            freezeOnOffscreen: true
        }
    };
    canvas._lottieDpr = dotLottieOpts.renderConfig.devicePixelRatio;
    if (decodeURIComponent(src).indexOf("/ИграКости/") !== -1) dotLottieOpts.layout = {
        align: [.5, .35]
    };
    loadDotLottie().then(DotLottie => {
        if (!canvas.isConnected) return;
        const dl = new DotLottie(dotLottieOpts);
        canvas._dotLottie = dl;
        _lottieLive.add(dl);
        dl.addEventListener("load", () => {
            markLazyImgLoaded(canvas);
            setTimeout(() => lottieSettleSize(canvas, dl, 0), 120);
        });
        dl.addEventListener("loadError", () => {
            markLazyImgLoaded(canvas);
            if (once) gvLottieOnceDone(canvas);
        });
        if (once) dl.addEventListener("complete", () => gvLottieOnceDone(canvas));
        if (idle && !once) {
            dl.addEventListener("complete", () => {
                const restAt = LOTTIE_REST_FRAME[decodeURIComponent(src)];
                if (restAt != null) {
                    try {
                        dl.setFrame(Math.floor((dl.totalFrames || 0) * restAt));
                    } catch (e) {}
                }
                if (canvas._lottieIdleTimer) clearTimeout(canvas._lottieIdleTimer);
                canvas._lottieIdleTimer = setTimeout(function again() {
                    canvas._lottieIdleTimer = 0;
                    if (canvas._dotLottie !== dl || !canvas.isConnected) return;
                    if (document.visibilityState !== "visible" || !canvas.offsetParent) {
                        canvas._lottieIdleTimer = setTimeout(again, LOTTIE_IDLE_GAP_MS);
                        return;
                    }
                    replayLottie(canvas);
                }, LOTTIE_IDLE_GAP_MS + Math.random() * LOTTIE_IDLE_JITTER_MS);
            });
        }
    }).catch(() => {
        markLazyImgLoaded(canvas);
        if (once) gvLottieOnceDone(canvas);
    });
}

document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") {
        _lottieLive.forEach(dl => {
            try {
                if (dl.isPlaying) {
                    dl.pause();
                    _lottiePausedByHide.add(dl);
                }
            } catch (e) {}
        });
    } else {
        _lottiePausedByHide.forEach(dl => {
            try {
                dl.play();
            } catch (e) {}
        });
        _lottiePausedByHide.clear();
    }
});

function setCheckActivateIconSrc(lottiePath, allowLite) {
    const wantImg = allowLite && currentUser.liteUiEnabled;
    let el = document.getElementById("checkActivateIcon");
    if (!el) return;
    if (wantImg) {
        const pngPath = lottiePath.replace(/\.lottie$/i, ".png");
        if (el.tagName === "IMG") {
            if (el.getAttribute("src") === pngPath) return;
            el.classList.remove("loaded");
            el.setAttribute("src", pngPath);
            return;
        }
        el.outerHTML = '<img class="subgate-icon lazy-img" id="checkActivateIcon" src="' + pngPath + '" alt="">';
        return;
    }
    if (el.tagName !== "CANVAS") {
        el.outerHTML = '<canvas class="subgate-icon lazy-img lottie-canvas" id="checkActivateIcon" width="512" height="512"></canvas>';
        el = document.getElementById("checkActivateIcon");
    }
    setLottieCanvasSrc(el, lottiePath);
}

function setLottieCanvasSrc(canvas, src) {
    if (!canvas) return;
    destroyLottie(canvas);
    canvas.classList.remove("loaded");
    const prevSkel = canvas.previousElementSibling;
    if (prevSkel && prevSkel.classList && prevSkel.classList.contains("skel-box")) prevSkel.classList.remove("loaded");
    canvas.setAttribute("data-lottie-src", src);
    delete canvas.dataset.lottieMounted;
    mountLottieCanvas(canvas);
}

function sweepLottieCanvases(root) {
    (root.querySelectorAll ? root.querySelectorAll("canvas.lottie-canvas") : []).forEach(mountLottieCanvas);
}

function sweepCompleteLazyImgs(root) {
    (root.querySelectorAll ? root.querySelectorAll("img.lazy-img") : []).forEach(img => {
        if (img.complete && img.naturalWidth > 0 && !img.classList.contains("loaded")) markLazyImgLoaded(img);
    });
    sweepLottieCanvases(root);
}

function releaseRemovedLotties(nodes) {
    const found = [];
    nodes.forEach(node => {
        if (node.nodeType !== 1) return;
        if (node.matches && node.matches("canvas.lottie-canvas")) found.push(node);
        if (node.querySelectorAll) node.querySelectorAll("canvas.lottie-canvas").forEach(c => found.push(c));
    });
    if (!found.length) return;
    setTimeout(() => found.forEach(c => {
        if (!c.isConnected) destroyLottie(c);
    }), 0);
}

new MutationObserver(mutations => {
    for (const m of mutations) {
        if (m.removedNodes.length) releaseRemovedLotties(m.removedNodes);
        for (const node of m.addedNodes) {
            if (node.nodeType !== 1) continue;
            if (node.matches && node.matches("img.lazy-img") && node.complete && node.naturalWidth > 0) markLazyImgLoaded(node);
            if (node.matches && node.matches("canvas.lottie-canvas")) mountLottieCanvas(node);
            if (node.querySelectorAll) sweepCompleteLazyImgs(node);
        }
    }
}).observe(document.body, {
    childList: true,
    subtree: true
});

sweepCompleteLazyImgs(document);

document.addEventListener("error", function(e) {
    const img = e.target;
    if (!img || img.tagName !== "IMG" || !img.classList || !img.classList.contains("lazy-img")) return;
    const box = img.previousElementSibling;
    const src = img.getAttribute("src");
    if (!src) {
        if (box && box.classList && box.classList.contains("skel-box")) box.classList.add("loaded", "img-error");
        return;
    }
    const base = src.replace(/([?&])_r=\d+&?/, "$1").replace(/[?&]$/, "");
    const sep = base.indexOf("?") === -1 ? "?" : "&";
    setTimeout(() => {
        if (img.isConnected) img.src = base + sep + "_r=" + Date.now();
    }, 3e3);
}, true);

(function initDragScroll() {
    let dragEl = null,
        startX = 0,
        startScroll = 0,
        moved = false;
    const DRAG_THRESHOLD = 6;
    document.addEventListener("mousedown", e => {
        const el = e.target.closest(".lb-tabs");
        if (!el) return;
        dragEl = el;
        startX = e.pageX;
        startScroll = el.scrollLeft;
        moved = false;
    });
    document.addEventListener("mousemove", e => {
        if (!dragEl) return;
        const dx = e.pageX - startX;
        if (Math.abs(dx) > DRAG_THRESHOLD) {
            if (!moved) dragEl.classList.add("dragging");
            moved = true;
        }
        if (moved) dragEl.scrollLeft = startScroll - dx;
    });

    function endDrag() {
        if (dragEl) dragEl.classList.remove("dragging");
        dragEl = null;
    }
    document.addEventListener("mouseup", endDrag);
    document.addEventListener("mouseleave", endDrag);
    document.addEventListener("click", e => {
        if (moved && e.target.closest(".lb-tabs")) {
            e.preventDefault();
            e.stopPropagation();
        }
        moved = false;
    }, true);
})();

function pluralReferrals(n) {
    const mod10 = n % 10,
        mod100 = n % 100;
    if (mod10 === 1 && mod100 !== 11) return "Реферал";
    if ([2, 3, 4].includes(mod10) && ![12, 13, 14].includes(mod100)) return "Реферала";
    return "Рефералов";
}

