loadPvpCommission();

function loadUserState() {
    const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
    const timeout = setTimeout(() => { if (controller) controller.abort(); }, 15000);
    fetch("/api/state?uid=" + CURRENT_UID, controller ? {signal: controller.signal} : {}).then(r => {
        if (!r.ok) {
            const error = new Error("Profile HTTP " + r.status);
            error.status = r.status;
            throw error;
        }
        return r.json();
    }).then(data => {
        if (!data || !data.ok) throw new Error("bad response");
        const notice = document.getElementById("profile-load-error");
        if (notice) notice.remove();
        if (data.banned) {
            try {
                document.documentElement.style.display = "none";
            } catch (e) {}
            try {
                if (tgWebApp && tgWebApp.close) tgWebApp.close();
            } catch (e) {}
            return;
        }
        userDataLoaded = true;
        if (typeof data.serverTz === "number") window.SERVER_TZ_MIN = data.serverTz;
        window.__staffUser = data.isAdmin === true;
        currentUser.displayName = data.displayName || data.username || "Игрок";
        currentUser.balance = cleanBalance(data.balance);
        currentUser.avatarUrl = data.avatarUrl || "";
        currentUser.registrationDate = data.registrationDate || "";
        currentUser.botUsername = data.botUsername || currentUser.botUsername;
        currentUser.hapticsEnabled = data.hapticsEnabled !== false;
        currentUser.liteUiEnabled = data.liteUiEnabled === true;
        currentUser.tgBgEnabled = data.tgBgEnabled === true;
        currentUser.fullscreenEnabled = data.fullscreenEnabled === true;
        applyUserToUI();
        updateHapticsToggleUI();
        applyLiteUiUI();
        applyTgBg();
        applyFullscreenUI();
        if (data.isAdmin) loadThemeDraftPreview();
        window.dispatchEvent(new CustomEvent("eternacas:profileReady"));
    }).catch(err => {
        console.warn("[user] /api/state failed:", err);
        let notice = document.getElementById("profile-load-error");
        if (!notice) {
            notice = document.createElement("div");
            notice.id = "profile-load-error";
            notice.className = "backend-unavailable-notice";
            notice.setAttribute("role", "status");
            document.body.appendChild(notice);
        }
        const authFailure = [401, 403, 404].includes(err.status);
        notice.textContent = authFailure
            ? "Профиль не загружен: /api/state вернул HTTP " + err.status + ". Закройте и заново откройте Mini App из бота. Если ошибка повторится, проверьте маршрут API, токен бота и время сервера."
            : "Профиль временно не загружен: " + (err.status ? "HTTP " + err.status : "ошибка сети или ответа сервера") + ". Повторяем запрос. Баланс и аватар пока недоступны.";
        // A rejected session or missing route will not recover by polling every four seconds.
        if (!authFailure) setTimeout(loadUserState, 4e3);
    }).finally(() => clearTimeout(timeout));
}

function loadReferralBase() {
    fetch("/api/referral?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (!data || !data.ok) throw new Error("bad response");
        refDataLoaded = true;
        currentUser.refLink = data.link || currentUser.refLink;
        currentUser.refCount = data.count || 0;
        currentUser.refEarnings = data.earnings || 0;
        applyRefBlockToUI();
    }).catch(err => {
        console.warn("[user] /api/referral failed, retry in 4s:", err);
        setTimeout(loadReferralBase, 4e3);
    });
}

function loadCurrentUser() {
    loadUserState();
    loadReferralBase();
    loadSubscriptionState();
}

const BALANCE_POLL_MS = 2e4;

const BALANCE_ANIM_MS = 900;

let balancePollTimer = null;

let balanceAnimToken = 0;

function easeOutCubic(t) {
    return 1 - Math.pow(1 - t, 3);
}

function animateBalanceNumber(fromValue, toValue, durationMs) {
    const targets = [];
    document.querySelectorAll(".balance-pill .amount").forEach(el => targets.push(el));
    const wvAmount = document.querySelector(".wallet-balance-amount");
    if (wvAmount) targets.push(wvAmount);
    const balanceModalAmount = document.getElementById("balanceModalAmount");
    if (balanceModalAmount) targets.push(balanceModalAmount);
    targets.forEach(el => el.classList.remove("text-skel"));
    const myToken = ++balanceAnimToken;
    const start = Date.now();
    currentUser.balance = cleanBalance(toValue);

    function step() {
        if (myToken !== balanceAnimToken) return;
        const t = Math.min(1, (Date.now() - start) / durationMs);
        const value = fromValue + (toValue - fromValue) * easeOutCubic(t);
        targets.forEach(el => {
            setBalanceAmount(el, value);
        });
        if (t < 1) setTimeout(step, 16);
    }
    step();
}

function pollBalanceOnce() {
    if (!userDataLoaded || document.visibilityState !== "visible") return;
    fetch("/api/state?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (!data || !data.ok) return;
        const newBalance = data.balance || 0;
        if (newBalance === currentUser.balance) return;
        applyBalance(newBalance);
    }).catch(() => {});
}

function startBalancePolling() {
    if (balancePollTimer) return;
    balancePollTimer = setInterval(pollBalanceOnce, BALANCE_POLL_MS);
}

function stopBalancePolling() {
    if (!balancePollTimer) return;
    clearInterval(balancePollTimer);
    balancePollTimer = null;
}

document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") {
        pollBalanceOnce();
        startBalancePolling();
    } else {
        stopBalancePolling();
    }
});

window.addEventListener("eternacas:profileReady", () => {
    if (document.visibilityState === "visible") startBalancePolling();
}, {
    once: true
});

