function openSubscriptionGate(channels) {
    const modal = document.getElementById("subGateModal");
    if (!modal) return;
    channels = channels && channels.length ? channels : [{
        name: "Игровой канал",
        url: "#",
        buttonText: "Подписаться на Игровой канал"
    }];
    const textEl = document.getElementById("subGateText");
    if (textEl) textEl.textContent = channels.length > 1 ? "Подпишитесь на все каналы:" : "Чтобы пользоваться приложением, подпишитесь на канал:";
    const list = document.getElementById("subGateChannelsList");
    if (list) {
        list.innerHTML = channels.map(function(ch, i) {
            return '<div class="subgate-channel"><span class="subgate-channel-dot">•</span>' + '<span class="subgate-channel-name">' + escapeHtml(ch.name || "Канал") + "</span></div>" + '<a class="subgate-btn subgate-btn-primary" href="' + escapeHtml(ch.url || "#") + '" target="_blank" rel="noopener">' + escapeHtml(ch.buttonText || "Подписаться на " + (ch.name || "канал")) + "</a>";
        }).join("");
    }
    modal.classList.add("active");
    document.documentElement.classList.add("rs-lock-scroll");
}

function closeSubscriptionGate() {
    const modal = document.getElementById("subGateModal");
    if (modal) modal.classList.remove("active");
    document.documentElement.classList.remove("rs-lock-scroll");
    maybeShowUsernameGate();
    maybeShowPendingCheckActivate();
}

function maybeShowSubscriptionGate() {
    if (!rsPreloaderHidden || !subscriptionState) return;
    if (groupCaptchaLaunch) return;
    if (subscriptionState.required && !subscriptionState.subscribed) {
        const chans = (subscriptionState.channels || []).filter(function(c) {
            return !c.subscribed;
        });
        openSubscriptionGate(chans.length ? chans : subscriptionState.channels);
    } else {
        maybeShowUsernameGate();
    }
}

function loadSubscriptionState() {
    fetch("/api/subscription/check?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (!data || !data.ok) throw new Error("bad response");
        subscriptionState = data;
        maybeShowSubscriptionGate();
    }).catch(err => {
        console.warn("[user] /api/subscription/check failed, retry in 4s:", err);
        setTimeout(loadSubscriptionState, 4e3);
    });
}

