let captchaGateTimer = null;

function openCaptchaGate() {
    const modal = document.getElementById("captchaGateModal");
    if (!modal || modal.classList.contains("active")) return;
    const btn = document.getElementById("captchaGateBotBtn");
    if (btn) btn.setAttribute("href", "https://t.me/" + currentUser.botUsername);
    modal.classList.add("active");
    document.documentElement.classList.add("rs-lock-scroll");
    clearInterval(captchaGateTimer);
    captchaGateTimer = setInterval(function() {
        refreshCaptchaGate(false);
    }, 4e3);
}

function closeCaptchaGate() {
    clearInterval(captchaGateTimer);
    captchaGateTimer = null;
    const modal = document.getElementById("captchaGateModal");
    if (modal && modal.classList.contains("active")) {
        modal.classList.remove("active");
        document.documentElement.classList.remove("rs-lock-scroll");
    }
}

function refreshCaptchaGate(manual) {
    return fetch("/api/captcha/status").then(r => r.json()).then(function(data) {
        if (!data || !data.ok) return;
        if (data.required) {
            const cm = document.getElementById("captchaModal");
            if (cm && cm.classList.contains("active")) return;
            openCaptchaGate();
            if (manual && typeof showToast === "function") showToast("Капча ещё не пройдена", "warning");
            return;
        }
        const wasOpen = document.getElementById("captchaGateModal").classList.contains("active");
        closeCaptchaGate();
        if (wasOpen && typeof showToast === "function") showToast("Спасибо, капча пройдена!", "success");
    }).catch(function() {});
}

function maybeShowCaptchaGate() {
    if (!rsPreloaderHidden || groupCaptchaLaunch || pendingCaptcha || pendingGroupCaptcha) return;
    const capModal = document.getElementById("captchaModal");
    if (capModal && capModal.classList.contains("active")) return;
    refreshCaptchaGate(false);
}

