const subGateCheckBtn = document.getElementById("subGateCheckBtn");

const SUBGATE_CHECK_MAX_ATTEMPTS = 3;

const SUBGATE_CHECK_COOLDOWN_MS = 6e4;

let subGateCheckAttempts = 0;

let subGateCheckLockUntil = 0;

let subGateCheckTimer = null;

function subGateCheckLockRemaining() {
    return Math.max(0, Math.ceil((subGateCheckLockUntil - Date.now()) / 1e3));
}

function startSubGateCheckCountdown() {
    if (!subGateCheckBtn) return;
    if (subGateCheckTimer) clearInterval(subGateCheckTimer);
    subGateCheckBtn.classList.add("is-locked");

    function tick() {
        const left = subGateCheckLockRemaining();
        if (left <= 0) {
            clearInterval(subGateCheckTimer);
            subGateCheckTimer = null;
            subGateCheckBtn.classList.remove("is-locked");
            subGateCheckBtn.textContent = "Проверить подписку";
            subGateCheckAttempts = 0;
            return;
        }
        subGateCheckBtn.textContent = "Подождите " + left + "с…";
    }
    tick();
    subGateCheckTimer = setInterval(tick, 1e3);
}

if (subGateCheckBtn) {
    subGateCheckBtn.addEventListener("click", function() {
        if (Date.now() < subGateCheckLockUntil) return;
        subGateCheckAttempts++;
        if (subGateCheckAttempts > SUBGATE_CHECK_MAX_ATTEMPTS) {
            subGateCheckLockUntil = Date.now() + SUBGATE_CHECK_COOLDOWN_MS;
            try {
                if (tgWebApp && tgWebApp.HapticFeedback) tgWebApp.HapticFeedback.notificationOccurred("error");
            } catch (e) {}
            if (typeof showToast === "function") showToast("Слишком много попыток — попробуйте через минуту", "warning");
            startSubGateCheckCountdown();
            return;
        }
        const prevText = subGateCheckBtn.textContent;
        subGateCheckBtn.classList.add("is-loading");
        subGateCheckBtn.textContent = "Проверяем…";
        fetch("/api/subscription/check?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
            if (subGateCheckBtn.classList.contains("is-locked")) return;
            subGateCheckBtn.classList.remove("is-loading");
            subGateCheckBtn.textContent = prevText;
            if (!data || !data.ok) return;
            subscriptionState = data;
            if (!data.required || data.subscribed) {
                try {
                    if (tgWebApp && tgWebApp.HapticFeedback) tgWebApp.HapticFeedback.notificationOccurred("success");
                } catch (e) {}
                closeSubscriptionGate();
                if (typeof showToast === "function") showToast("Спасибо за подписку!", "success");
                subGateCheckAttempts = 0;
            } else {
                try {
                    if (tgWebApp && tgWebApp.HapticFeedback) tgWebApp.HapticFeedback.notificationOccurred("error");
                } catch (e) {}
                if (typeof showToast === "function") showToast("Вы ещё не подписаны на канал", "warning");
                const remaining = (data.channels || []).filter(function(c) {
                    return !c.subscribed;
                });
                if (remaining.length) openSubscriptionGate(remaining);
            }
        }).catch(function() {
            if (subGateCheckBtn.classList.contains("is-locked")) return;
            subGateCheckBtn.classList.remove("is-loading");
            subGateCheckBtn.textContent = prevText;
        });
    });
}

