let checksStack = [];

let checksNotifEnabled = true;

let checksLimits = {
    minAmount: .1,
    maxAmount: 1e6,
    minActivations: 2,
    maxActivations: 100
};

function checksApplyLimits(l) {
    if (!l) return;
    checksLimits = {
        minAmount: Number(l.minAmount) || checksLimits.minAmount,
        maxAmount: Number(l.maxAmount) || checksLimits.maxAmount,
        minActivations: Number(l.minActivations) || checksLimits.minActivations,
        maxActivations: Number(l.maxActivations) || checksLimits.maxActivations
    };
    const range = document.getElementById("checksActRange");
    if (range) range.textContent = checksLimits.minActivations + "–" + checksLimits.maxActivations;
}

function checksLoadLimits() {
    fetch("/api/checks/overview?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (data && data.ok) {
            checksApplyLimits(data.limits);
            checksApplyCaptcha(data.captcha);
        }
    }).catch(function() {});
}

function checksModalCardEl() {
    return document.getElementById("checksModal").querySelector(".checks-modal-card");
}

function checksSetChrome(title, showBack) {
    document.getElementById("checksTitle").textContent = title;
    document.getElementById("checksBackBtn").style.display = showBack ? "flex" : "none";
    checksModalCardEl().classList.toggle("has-back", !!showBack);
}

function checksPush(renderFn) {
    const args = Array.prototype.slice.call(arguments, 1);
    checksStack.push([renderFn, args]);
    renderFn.apply(null, args);
}

function checksReplaceTop(renderFn) {
    const args = Array.prototype.slice.call(arguments, 1);
    checksStack[checksStack.length - 1] = [renderFn, args];
    renderFn.apply(null, args);
}

function checksBack() {
    checksStack.pop();
    const prev = checksStack[checksStack.length - 1];
    if (!prev) {
        closeChecksModal();
        return;
    }
    prev[0].apply(null, prev[1]);
}

function checksReset() {
    checksStack = [];
}

let checksJumpCallback = null;

function checksPaginationHTML(context, page, totalPages, scope) {
    if (totalPages <= 1) return "";
    const attrs = 'data-context="' + context + '" data-page="' + page + '" data-total="' + totalPages + '"' + (scope ? ' data-scope="' + scope + '"' : "");
    return '<div class="wv-pagination" ' + attrs + ">" + '<button class="wv-page-btn" type="button" data-action="checks-page-prev"' + (page <= 0 ? " disabled" : "") + ">‹</button>" + '<button class="wv-page-label wv-page-label-btn" type="button" data-action="checks-page-jump">' + (page + 1) + " из " + totalPages + "</button>" + '<button class="wv-page-btn" type="button" data-action="checks-page-next"' + (page >= totalPages - 1 ? " disabled" : "") + ">›</button>" + "</div>";
}

function checksGotoPage(context, scope, page) {
    if (context === "my") checksReplaceTop(checksRenderMy, page);
    else checksReplaceTop(checksRenderHistory, scope, page);
}

function checksOpenJumpModal(page, totalPages, onJump) {
    checksJumpCallback = onJump;
    const sub = document.getElementById("checksJumpSub");
    if (sub) sub.textContent = "Стр. " + (page + 1) + " из " + totalPages;
    const quickPages = Array.from(new Set([1, page + 1, page + 2, totalPages].filter(p => p >= 1 && p <= totalPages))).slice(0, 4);
    const quickEl = document.getElementById("checksJumpQuick");
    if (quickEl) {
        quickEl.innerHTML = quickPages.map(p => '<div class="mg-jump-quick-btn' + (p === page + 1 ? " active" : "") + '" data-page="' + p + '"><span class="mg-jump-quick-btn-num">' + p + "</span></div>").join("");
    }
    const input = document.getElementById("checksJumpInput");
    if (input) {
        input.value = page + 1;
        input.classList.remove("error");
    }
    const errorEl = document.getElementById("checksJumpError");
    if (errorEl) errorEl.classList.remove("show");
    document.getElementById("checksJumpModal").classList.add("active");
}

function checksCloseJumpModal() {
    document.getElementById("checksJumpModal").classList.remove("active");
}

const checksJumpQuickEl = document.getElementById("checksJumpQuick");

if (checksJumpQuickEl) {
    checksJumpQuickEl.addEventListener("click", function(e) {
        const btn = e.target.closest(".mg-jump-quick-btn");
        if (!btn || !checksJumpCallback) return;
        checksCloseJumpModal();
        checksJumpCallback(Number(btn.dataset.page) - 1);
    });
}

const checksJumpGoBtnEl = document.getElementById("checksJumpGoBtn");

if (checksJumpGoBtnEl) {
    checksJumpGoBtnEl.addEventListener("click", function() {
        const input = document.getElementById("checksJumpInput");
        const errorEl = document.getElementById("checksJumpError");
        const raw = input.value.trim();
        const pageNum = parseInt(raw, 10);
        const subText = (document.getElementById("checksJumpSub").textContent.match(/из (\d+)/) || [])[1];
        const totalPages = subText ? parseInt(subText, 10) : 1;
        const valid = raw !== "" && Number.isInteger(pageNum) && pageNum >= 1 && pageNum <= totalPages;
        if (!valid) {
            input.classList.add("error");
            if (errorEl) {
                errorEl.textContent = "Введите номер страницы от 1 до " + totalPages;
                errorEl.classList.add("show");
            }
            return;
        }
        input.classList.remove("error");
        if (errorEl) errorEl.classList.remove("show");
        checksCloseJumpModal();
        if (checksJumpCallback) checksJumpCallback(pageNum - 1);
    });
}

const checksJumpCloseEl = document.getElementById("checksJumpClose");

if (checksJumpCloseEl) checksJumpCloseEl.addEventListener("click", checksCloseJumpModal);

const checksJumpModalEl = document.getElementById("checksJumpModal");

if (checksJumpModalEl) checksJumpModalEl.addEventListener("click", function(e) {
    if (e.target === checksJumpModalEl) checksCloseJumpModal();
});

