function checksSubmitCreate(type) {
    const amountRaw = (document.getElementById("checksAmountInput").value || "").replace(",", ".");
    const amount = Math.round(parseFloat(amountRaw) * 100) / 100;
    const errEl = document.getElementById("checksCreateError");
    if (errEl) errEl.textContent = "";
    if (!amount || amount <= 0) {
        if (errEl) errEl.textContent = "Введите корректную сумму";
        return;
    }
    if (amount < checksLimits.minAmount || amount > checksLimits.maxAmount) {
        if (errEl) errEl.textContent = "Сумма чека - от " + fmtNum(checksLimits.minAmount) + " до " + fmtNum(checksLimits.maxAmount) + "⭐️";
        return;
    }
    let firstNameVal = "";
    try {
        firstNameVal = tgWebApp && tgWebApp.initDataUnsafe && tgWebApp.initDataUnsafe.user && tgWebApp.initDataUnsafe.user.first_name || "";
    } catch (e) {}
    const passwordVal = (document.getElementById("checksPasswordInput") && document.getElementById("checksPasswordInput").value || "").trim();
    const wagerAmountRaw = (document.getElementById("checksWagerAmountInput") && document.getElementById("checksWagerAmountInput").value || "").trim();
    const wagerGamesRaw = (document.getElementById("checksWagerGamesInput") && document.getElementById("checksWagerGamesInput").value || "").trim();
    if ((wagerAmountRaw && !wagerGamesRaw) || (!wagerAmountRaw && wagerGamesRaw)) {
        if (errEl) errEl.textContent = "Укажите и сумму, и количество игр вейджера (или оставьте оба поля пустыми)";
        return;
    }
    let wagerAmountVal = null;
    let wagerGamesVal = null;
    if (wagerAmountRaw && wagerGamesRaw) {
        wagerAmountVal = parseFloat(wagerAmountRaw.replace(",", "."));
        wagerGamesVal = parseInt(wagerGamesRaw, 10);
        if (!wagerAmountVal || wagerAmountVal <= 0 || !wagerGamesVal || wagerGamesVal <= 0) {
            if (errEl) errEl.textContent = "Сумма и количество игр вейджера должны быть больше 0";
            return;
        }
    }
    const reqBodyFields = {
        deposit: "reqDeposit",
        turnover: "reqTurnover",
        withdraw: "reqWithdraw"
    };
    const reqValues = {};
    for (const kind in reqBodyFields) {
        const amountInput = document.getElementById("checksCreateReq" + kind + "AmountInput");
        const periodInput = document.getElementById("checksCreateReq" + kind + "PeriodInput");
        const rawAmount = (amountInput && amountInput.value || "").trim();
        if (!rawAmount) continue;
        const reqAmount = parseFloat(rawAmount.replace(",", "."));
        if (!reqAmount || reqAmount <= 0) {
            if (errEl) errEl.textContent = "Сумма условия по " + kind + " должна быть больше 0";
            return;
        }
        reqValues[reqBodyFields[kind] + "Amount"] = reqAmount;
        reqValues[reqBodyFields[kind] + "Period"] = (periodInput && periodInput.value) || "all";
    }
    const expireEl = document.getElementById("checksExpireInput");
    const expireRaw = (expireEl && expireEl.value || "").trim();
    let expireHoursVal = 48;
    if (expireRaw) {
        expireHoursVal = parseInt(expireRaw, 10);
        if (!expireHoursVal || expireHoursVal < 1 || expireHoursVal > 720) {
            if (errEl) errEl.textContent = "Срок жизни чека - от 1 до 720 часов";
            return;
        }
    }
    const body = Object.assign({
        uid: CURRENT_UID,
        type: type,
        amount: amount,
        expireHours: expireHoursVal,
        firstName: firstNameVal,
        password: passwordVal || undefined,
        premiumOnly: checksCreateSettings.premiumOnly,
        verifiedOnly: checksCreateSettings.verifiedOnly,
        referralOnly: checksCreateSettings.referralOnly,
        captchaLevel: checksCreateSettings.captchaLevel == null ? undefined : checksCreateSettings.captchaLevel,
        wagerAmount: wagerAmountVal != null ? wagerAmountVal : undefined,
        wagerGames: wagerGamesVal != null ? wagerGamesVal : undefined
    }, reqValues);
    if (type === "personal") {
        const t = (document.getElementById("checksTargetInput").value || "").trim().replace(/^@/, "");
        if (!t) {
            if (errEl) errEl.textContent = "Укажите юзернейм получателя";
            return;
        }
        body.targetUsername = t;
    }
    if (type === "multi") {
        const a = parseInt(document.getElementById("checksActivationsInput").value || "0", 10);
        if (!a || a < checksLimits.minActivations || a > checksLimits.maxActivations) {
            if (errEl) errEl.textContent = "Количество активаций - от " + checksLimits.minActivations + " до " + checksLimits.maxActivations;
            return;
        }
        body.activations = a;
    }
    checksPush(checksRenderCreating);
    fetch("/api/checks/create", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify(body)
    }).then(r => r.json()).then(data => {
        if (!data || !data.ok) {
            checksReplaceTop(checksRenderCreateError, data && data.error || null);
            return;
        }
        const spent = type === "multi" ? amount * (body.activations || 1) : amount;
        if (currentUser) {
            currentUser.balance -= spent;
            applyUserToUI();
        }
        const typeText = type === "multi" ? "Мульти-чек на сумму " + fmtNum(spent) + "⭐️ (" + fmtNum(amount) + "⭐️ × " + body.activations + ")" : type === "personal" ? "Персональный чек на сумму " + fmtNum(amount) + "⭐️" : "Чек на сумму " + fmtNum(amount) + "⭐️";
        checksReplaceTop(checksRenderCreateSuccess, data.code, data.link, typeText);
    }).catch(function() {
        checksReplaceTop(checksRenderCreateError, null);
    });
}

