function openProjectRulesModal() {
    const body = document.getElementById("projectRulesText");
    if (body) body.innerHTML = projectRulesHtml();
    const modal = document.getElementById("projectRulesModal");
    if (modal) modal.classList.add("active");
}

const projectRulesModal = document.getElementById("projectRulesModal");

const projectRulesClose = document.getElementById("projectRulesClose");

if (projectRulesModal) {
    if (projectRulesClose) projectRulesClose.addEventListener("click", () => projectRulesModal.classList.remove("active"));
    projectRulesModal.addEventListener("click", e => {
        if (e.target === projectRulesModal) projectRulesModal.classList.remove("active");
    });
}

function releaseGroupCaptchaLaunch() {
    groupCaptchaLaunch = false;
    applyFullscreenUI();
    maybeShowSubscriptionGate();
}

function maybeShowPendingCheckActivate() {
    const subModal = document.getElementById("subGateModal");
    if (subModal && subModal.classList.contains("active")) return;
    if (pendingGroupCaptcha) {
        const groupToken = pendingGroupCaptcha;
        pendingGroupCaptcha = null;
        fetch("/api/gcaptcha/status?token=" + encodeURIComponent(groupToken)).then(function(r) {
            return r.json();
        }).then(function(data) {
            if (data && data.ok && data.mine && data.pending) {
                captchaGroupToken = groupToken;
                captchaInfo = {
                    chatTitle: data.chatTitle || "",
                    secondsLeft: data.secondsLeft || 0
                };
                openCaptchaModal();
                return;
            }
            releaseGroupCaptchaLaunch();
        }).catch(function() {
            releaseGroupCaptchaLaunch();
        });
        return;
    }
    if (pendingCaptcha) {
        pendingCaptcha = false;
        captchaInfo = null;
        openCaptchaModal();
        return;
    }
    if (pendingProjectRules) {
        pendingProjectRules = false;
        openProjectRulesModal();
        return;
    }
    if (pendingSupportTicket) {
        const sid = pendingSupportTicket;
        pendingSupportTicket = null;
        openHelp();
        loadSupport().then(S => S.openTicket(sid));
        return;
    }
    if (pendingSupportOpen) {
        pendingSupportOpen = false;
        openHelp();
        return;
    }
    if (pendingWalletPromo) {
        const promoCode = pendingWalletPromo;
        pendingWalletPromo = null;
        walletPromoPrefill = promoCode;
        openWallet();
        return;
    }
    if (pendingCheckActivateCode) {
        const code = pendingCheckActivateCode;
        pendingCheckActivateCode = null;
        checksOpenActivate(code);
        return;
    }
    if (pendingOpenCreateCheck) {
        pendingOpenCreateCheck = false;
        document.getElementById("checksModal").classList.add("active");
        checksGotoCreateType();
        return;
    }
    if (pendingGameSection) {
        const section = pendingGameSection;
        pendingGameSection = null;
        if (section === "блэкджек-pvp") {
            openGame("блэкджек");
            setBlackjackMode(true);
        } else {
            openGame(section);
        }
        return;
    }
    if (pendingPvpGameSection) {
        const section = pendingPvpGameSection;
        pendingPvpGameSection = null;
        openGame(section);
        return;
    }
    if (pendingPvpGameId) {
        const roomId = pendingPvpGameId;
        pendingPvpGameId = null;
        pvpOpenFromDeepLink(roomId);
        return;
    }
    if (pendingCrashRoundId) {
        const roundId = pendingCrashRoundId;
        pendingCrashRoundId = null;
        openCrashRoundModal(roundId);
        return;
    }
    if (pendingRouletteRoundId) {
        const roundId = pendingRouletteRoundId;
        pendingRouletteRoundId = null;
        openRouletteRoundModal(roundId);
        return;
    }
    if (pendingWheelRoundId) {
        const roundId = pendingWheelRoundId;
        pendingWheelRoundId = null;
        openWheelRoundModal(roundId);
        return;
    }
    if (pendingUpgradeRoundId) {
        const roundId = pendingUpgradeRoundId;
        pendingUpgradeRoundId = null;
        openUpgradeRoundModal(roundId);
        return;
    }
    if (pendingBlackjackRoundId) {
        const roundId = pendingBlackjackRoundId;
        pendingBlackjackRoundId = null;
        openBlackjackRoundModal(roundId);
        return;
    }
    if (pendingArenaRoundId) {
        const roundId = pendingArenaRoundId;
        pendingArenaRoundId = null;
        if (window.arenaOpenDeepLink) window.arenaOpenDeepLink(roundId);
        return;
    }
    if (pendingCoinflipRoundId) {
        const roundId = pendingCoinflipRoundId;
        pendingCoinflipRoundId = null;
        openCoinflipRoundModal(roundId);
        return;
    }
    if (pendingClawRoundId) {
        const roundId = pendingClawRoundId;
        pendingClawRoundId = null;
        openClawRoundModal(roundId);
        return;
    }
    if (pendingBaccaratRoundId && window.baccaratKit) {
        const roundId = pendingBaccaratRoundId;
        pendingBaccaratRoundId = null;
        window.baccaratKit.openRound(roundId);
        return;
    }
    if (pendingEscapeRoundId) {
        const roundId = pendingEscapeRoundId;
        pendingEscapeRoundId = null;
        if (window.escapeOpenRound) window.escapeOpenRound(roundId);
        return;
    }
    if (pendingEscapeDuelId) {
        const duelId = pendingEscapeDuelId;
        pendingEscapeDuelId = null;
        if (window.escapeOpenDuel) window.escapeOpenDuel(duelId);
        return;
    }
    if (pendingRaceRoundId) {
        const roundId = pendingRaceRoundId;
        pendingRaceRoundId = null;
        if (window.raceOpenDeepLink) window.raceOpenDeepLink(roundId);
        return;
    }
    if (pendingBonusWheel) {
        pendingBonusWheel = false;
        if (window.bonusOpenWheel) window.bonusOpenWheel();
        return;
    }
    if (pendingBoardGame) {
        const boardGame = pendingBoardGame;
        pendingBoardGame = null;
        openGame(boardGame);
        return;
    }
    if (pendingPotRound) {
        const potRound = pendingPotRound;
        pendingPotRound = null;
        if (window.potGames && window.potGames[potRound.key]) window.potGames[potRound.key].openDeepLink(potRound.id);
        return;
    }
    if (pendingDogHouseRoundId) {
        const roundId = pendingDogHouseRoundId;
        pendingDogHouseRoundId = null;
        openDogHouse({
            replay: roundId
        });
        return;
    }
    if (pendingDogHouseOpen) {
        pendingDogHouseOpen = false;
        openDogHouse();
    }
}

