if (pvpGamesCloseBtn) pvpGamesCloseBtn.addEventListener("click", closePvpGamesModal);

if (pvpGamesModal) pvpGamesModal.addEventListener("click", e => {
    if (e.target === pvpGamesModal) closePvpGamesModal();
});

let pvpDiceRoomIds = [];

let pvpDicePollTimer = null;

let pvpDicePollInFlight = false;

let pvpDicePrimaryActive = false;

let pvpDiceUiMode = "create";

let pvpDiceBusy = false;

let pvpDiceHistoryScope = "all";

function pvpDiceFaceHTML(label, src, avatarUrl) {
    const labelHtml = avatarUrl ? '<span class="pvp-player-label"><img class="pvp-player-avatar" src="' + avatarUrl + '" alt=""><span>' + label + "</span></span>" : label;
    return '<div class="dice-slot"><div class="dice-slot-label">' + labelHtml + "</div>" + '<span class="img-frame"><div class="skel-box"></div>' + lazyImgTag(src, "", "dice-img") + "</span></div>";
}

function renderPvpDicePair(myVal, oppVal, spinning, oppAvatarUrl) {
    const mySrc = spinning ? DICE_SPIN_URL : myVal ? diceFaceUrl(myVal) : diceIdleSrc();
    const oppSrc = spinning ? DICE_SPIN_URL : oppVal ? diceFaceUrl(oppVal) : diceIdleSrc();
    const myAvatarUrl = currentUser && currentUser.avatarUrl || null;
    return '<div class="dice-pair">' + pvpDiceFaceHTML("Вы", mySrc, myAvatarUrl) + '<div class="dice-divider"></div>' + pvpDiceFaceHTML("Соперник", oppSrc, oppAvatarUrl) + "</div>";
}

function renderPvpDice() {
    return '<div class="gv-photo">' + '<div class="dice-result" id="pvpDiceResult"></div>' + '<div id="pvpDicePairWrap">' + renderPvpDicePair(null, null) + "</div>" + '<div class="pvp-status-line" id="pvpDiceStatusLine"></div>' + '<div class="gv-fair" id="pvpDiceFairBox" style="display:none;"></div>' + '<div class="gv-howto" data-action="howto" id="pvpDiceHowtoInPhoto"><span>Как играть</span><span class="gv-howto-q">?</span></div>' + "</div>" + '<div class="pvp-init-skel" id="pvpDiceInitSkel">' + '<div class="skel-box" style="height:70px; border-radius:16px; margin:16px 16px 0;"></div>' + '<div class="skel-box" style="height:52px; border-radius:999px; margin:14px 16px 0;"></div>' + "</div>" + '<div class="pvp-active-row" id="pvpDiceActiveRow">' + '<button class="pvp-active-inline-btn" type="button" id="pvpDiceActiveBtn">' + lazyImgTag(liteAsset("/lottie/images/PvpEmoji.lottie"), "", "pvp-active-icon") + "Активные игры</button>" + '<button class="ah-share-btn" type="button" id="pvpDiceShareBtn" style="display:none;">' + lazyImgTag(liteAsset("/lottie/АренаHub/ПоделитьсяИгрой.lottie"), "", "ah-share-ic") + "Отправить</button>" + '<div class="gv-howto pvp-howto-external" data-action="howto" id="pvpDiceHowtoExternal" style="display:none;"><span>Как играть</span><span class="gv-howto-q">?</span></div>' + "</div>" + '<div class="gv-panel" id="pvpDicePanel" style="display:none;">' + '<div class="gv-label">Сумма ставки</div>' + betRowHTML("0.1") + '<div class="pvp-hint" id="pvpDiceCommissionHint">' + pvpCommissionHintHTML() + "</div>" + "</div>" + '<button class="gv-start-btn" type="button" id="pvpDicePlayAgainBtn" style="display:none;">Сыграть ещё раз</button>' + '<button class="gv-start-btn dim" type="button" id="pvpDiceCreateBtn" style="display:none;">Создать PvP комнату</button>' + '<button class="gv-start-btn" type="button" id="pvpDiceCreateMoreBtn" style="display:none;">Создать ещё одну комнату</button>' + '<button class="gv-start-btn" type="button" id="pvpDiceMyRoomsBtn" style="display:none;">Мои созданные комнаты</button>' + '<button class="gv-start-btn pvp-danger-btn" type="button" id="pvpDiceCancelBtn" style="display:none;">Отменить комнату</button>' + '<div class="gv-history">' + '<div class="gv-history-head">' + '<h3 class="gv-history-title">' + lazyImgTag(liteAsset("/lottie/images/ОгоньЭмоджи.lottie"), "", "flame-gif") + " Последние игры</h3>" + '<div class="gv-history-tabs">' + '<button class="gv-history-tab active" type="button" data-pvp-scope="all">Все</button>' + '<button class="gv-history-tab" type="button" data-pvp-scope="mine">Мои</button>' + "</div>" + "</div>" + gvHistorySearchRowHTML("pvpDiceHistorySearchInput") + '<div class="gv-history-list" id="pvpDiceHistoryList"><div class="dice-history-empty">Загрузка…</div></div>' + "</div>";
}

function pvpDiceReadyState() {
    const betInput = gvBody.querySelector(".gv-bet-input");
    const bet = betInput ? parseFloat(betInput.value) : NaN;
    return {
        bet: bet,
        hasBet: bet > 0,
        enoughBalance: bet > 0 && bet <= currentUser.balance + 1e-6
    };
}

function updatePvpDiceCreateState() {
    const btn = document.getElementById("pvpDiceCreateBtn");
    if (!btn || pvpDiceBusy) return;
    const state = pvpDiceReadyState();
    btn.classList.toggle("dim", !(betsAccepted && state.hasBet && state.enoughBalance && !betLimitIssue("pvp_dice", state.bet)));
}

function stopPvpDicePolling() {
    clearInterval(pvpDicePollTimer);
    pvpDicePollTimer = null;
}

function pvpDiceSetStatus(text) {
    const el = document.getElementById("pvpDiceStatusLine");
    if (el) el.textContent = text || "";
}

function pvpShareBtnSync(id, roomId) {
    const btn = document.getElementById(id);
    if (!btn) return;
    btn.style.display = roomId ? "" : "none";
    if (roomId) btn.dataset.roomId = roomId;
    else btn.removeAttribute("data-room-id");
}

function pvpShareBtnWire(id) {
    const btn = document.getElementById(id);
    if (!btn) return;
    btn.addEventListener("click", () => {
        const roomId = btn.dataset.roomId;
        if (roomId) trySwitchInlineQuery("sharegame_" + roomId);
    });
}

function pvpDiceSetFairBox(roomId, checkLink) {
    const box = document.getElementById("pvpDiceFairBox");
    if (!box) return;
    pvpShareBtnSync("pvpDiceShareBtn", roomId && !checkLink ? roomId : null);
    if (!roomId) {
        box.style.display = "none";
        box.innerHTML = "";
        box.removeAttribute("data-room-id");
        box.removeAttribute("data-mode");
        box.style.cursor = "";
        return;
    }
    box.style.display = "";
    box.dataset.roomId = roomId;
    if (checkLink) {
        box.dataset.mode = "result";
        box.style.cursor = "";
        box.innerHTML = '<a href="' + checkLink + '" target="_blank" rel="noopener" style="display:flex; align-items:center; gap:6px; color:inherit; text-decoration:none;">' + '<span class="gv-fair-icon">✓</span><span>Проверить результат</span></a>';
    } else {
        box.dataset.mode = "waiting";
        box.style.cursor = "pointer";
        box.innerHTML = '<span class="gv-fair-icon">#</span><span>' + escapeHtml(roomId) + "</span>";
    }
}

function showPvpDiceResultBox(cls, html) {
    const el = document.getElementById("pvpDiceResult");
    if (!el) return;
    el.className = "dice-result show " + cls;
    el.innerHTML = html;
}

function hidePvpDiceResultBox() {
    const el = document.getElementById("pvpDiceResult");
    if (el) el.className = "dice-result";
}

function updatePvpDiceCancelLabel() {
    const btn = document.getElementById("pvpDiceCancelBtn");
    if (!btn) return;
    btn.textContent = "Отменить комнату";
}

function hidePvpDiceInitSkel() {
    const skel = document.getElementById("pvpDiceInitSkel");
    if (skel) skel.style.display = "none";
}

function pvpDiceSetHowtoPlacement(inPhoto) {
    const inner = document.getElementById("pvpDiceHowtoInPhoto");
    const outer = document.getElementById("pvpDiceHowtoExternal");
    if (inner) inner.style.display = inPhoto ? "" : "none";
    if (outer) outer.style.display = inPhoto ? "none" : "";
    const statusLine = document.getElementById("pvpDiceStatusLine");
    if (statusLine) statusLine.classList.toggle("pvp-status-line-compact", !inPhoto);
    const photo = inner && inner.closest(".gv-photo");
    if (photo) photo.classList.toggle("pvp-photo-compact", !inPhoto);
}

const pvpDiceMaxRooms = 10;

function pvpDiceSyncActionButtons() {
    const createBtn = document.getElementById("pvpDiceCreateBtn");
    const panel = document.getElementById("pvpDicePanel");
    const moreBtn = document.getElementById("pvpDiceCreateMoreBtn");
    const cancelBtn = document.getElementById("pvpDiceCancelBtn");
    const myRoomsBtn = document.getElementById("pvpDiceMyRoomsBtn");
    const playAgainBtn = document.getElementById("pvpDicePlayAgainBtn");
    if (pvpDiceUiMode === "waiting") {
        if (playAgainBtn) playAgainBtn.style.display = "none";
        if (createBtn) createBtn.style.display = "none";
        if (panel) panel.style.display = "none";
        const showMore = pvpDiceRoomIds.length < pvpDiceMaxRooms;
        if (moreBtn) moreBtn.style.display = showMore ? "" : "none";
        if (cancelBtn) cancelBtn.style.display = "";
        const showMyRooms = pvpDiceRoomIds.length > 2;
        if (myRoomsBtn) myRoomsBtn.style.display = showMyRooms ? "" : "none";
        if (moreBtn) moreBtn.classList.toggle("pvp-tight-top", showMore);
        if (myRoomsBtn) myRoomsBtn.classList.toggle("pvp-tight-top", !showMore && showMyRooms);
        if (cancelBtn) cancelBtn.classList.toggle("pvp-tight-top", !showMore && !showMyRooms);
    } else if (pvpDiceUiMode === "postresult") {
        if (createBtn) createBtn.style.display = "none";
        if (panel) panel.style.display = "none";
        if (moreBtn) {
            moreBtn.style.display = "none";
            moreBtn.classList.remove("pvp-tight-top");
        }
        if (cancelBtn) {
            cancelBtn.style.display = "none";
            cancelBtn.classList.remove("pvp-tight-top");
        }
        if (myRoomsBtn) {
            myRoomsBtn.style.display = "none";
            myRoomsBtn.classList.remove("pvp-tight-top");
        }
        if (playAgainBtn) playAgainBtn.style.display = "";
    } else {
        if (playAgainBtn) playAgainBtn.style.display = "none";
        if (createBtn) {
            createBtn.style.display = "";
            createBtn.disabled = false;
            createBtn.textContent = "Создать PvP комнату";
        }
        if (panel) panel.style.display = "";
        if (moreBtn) {
            moreBtn.style.display = "none";
            moreBtn.classList.remove("pvp-tight-top");
        }
        if (cancelBtn) {
            cancelBtn.style.display = "none";
            cancelBtn.classList.remove("pvp-tight-top");
        }
        if (myRoomsBtn) myRoomsBtn.style.display = pvpDiceRoomIds.length ? "" : "none";
    }
    updatePvpDiceCancelLabel();
    updatePvpDiceCreateState();
}

function pvpDiceShowCreateForm() {
    hidePvpDiceResultBox();
    hidePvpDiceInitSkel();
    pvpDiceUiMode = "create";
    pvpDiceSetHowtoPlacement(false);
    const pairWrap = document.getElementById("pvpDicePairWrap");
    if (pairWrap) pairWrap.innerHTML = renderPvpDicePair(null, null);
    pvpDiceSetStatus("");
    pvpDiceSetFairBox(null);
    pvpDiceSyncActionButtons();
}

function pvpDiceShowWaitingUI() {
    hidePvpDiceResultBox();
    hidePvpDiceInitSkel();
    pvpDiceUiMode = "waiting";
    pvpDiceSetHowtoPlacement(true);
    pvpDicePrimaryActive = false;
    const pairWrap = document.getElementById("pvpDicePairWrap");
    if (pairWrap) pairWrap.innerHTML = renderPvpDicePair(null, null);
    pvpDiceSetStatus("Ожидание соперника…");
    pvpDiceSetFairBox(pvpDiceRoomIds[0], null);
    pvpDiceSyncActionButtons();
}

function pvpDiceRefreshButtonsAfterResult() {
    if (pvpDiceRoomIds.length) pvpDiceShowWaitingUI();
    else pvpDiceShowCreateForm();
}

function pvpDiceShowResult(result) {
    const iAmCreator = result.creatorId === CURRENT_UID;
    const myVal = iAmCreator ? result.creatorResult : result.opponentResult;
    const oppVal = iAmCreator ? result.opponentResult : result.creatorResult;
    const myCheckLink = iAmCreator ? result.creatorCheckLink : result.opponentCheckLink;
    const oppId = iAmCreator ? result.opponentId : result.creatorId;
    const oppAvatarUrl = oppId ? "/api/avatar/" + oppId : null;
    const pairWrap = document.getElementById("pvpDicePairWrap");
    if (pairWrap) pairWrap.innerHTML = renderPvpDicePair(myVal, oppVal, false, oppAvatarUrl);
    gvLottieOnce("pvpDicePairWrap");
    gvAfterResultAnim("pvpDicePairWrap", () => {
        pvpDiceSetStatus("");
        pvpDiceSetFairBox(result.roomId, myCheckLink);
        if (result.isDraw) {
            showPvpDiceResultBox("draw", '<span style="font-weight:400;">Ничья ' + myVal + ":" + oppVal + " — ставка " + fmtNum(result.betAmount) + "⭐️ возвращена</span>");
        } else {
            const won = iAmCreator ? result.winnerId === result.creatorId : result.winnerId === result.opponentId;
            if (won) showPvpDiceResultBox("win", '<span style="font-weight:400;">Выигрыш +' + fmtNum(result.winAmount) + "⭐️</span>");
            else showPvpDiceResultBox("lose", '<span style="font-weight:400;">Проигрыш ' + fmtNum(result.betAmount) + "⭐️</span>");
        }
        loadUserState();
        loadPvpDiceHistory();
        pvpDiceUiMode = "postresult";
        pvpDiceSyncActionButtons();
    });
}

function pvpDiceShowRollingUI(roomId) {
    hidePvpDiceResultBox();
    hidePvpDiceInitSkel();
    pvpDiceSetHowtoPlacement(true);
    const pairWrap = document.getElementById("pvpDicePairWrap");
    if (pairWrap) pairWrap.innerHTML = renderPvpDicePair(null, null, true);
    pvpDiceSetStatus("Бросаем кубики…");
    pvpDiceSetFairBox(roomId, null);
    document.getElementById("pvpDiceCreateBtn").style.display = "none";
    document.getElementById("pvpDiceCreateMoreBtn").style.display = "none";
    document.getElementById("pvpDicePanel").style.display = "none";
    document.getElementById("pvpDiceCancelBtn").style.display = "none";
    document.getElementById("pvpDiceMyRoomsBtn").style.display = "none";
}

function pvpDiceFetchAndShowFinished(roomId) {
    fetch("/api/pvp/dice/round?id=" + encodeURIComponent(roomId)).then(r => r.json()).then(data => {
        if (data && data.ok) {
            pvpDiceShowResult(data);
            return;
        }
        fetch("/api/pvp/dice/room?id=" + encodeURIComponent(roomId)).then(r2 => r2.json()).then(d2 => {
            if (d2 && d2.ok && d2.room.status === "error") showToast("Не удалось провести бой, ставка возвращена", "error");
            pvpDiceRefreshButtonsAfterResult();
        }).catch(() => pvpDiceRefreshButtonsAfterResult());
    }).catch(() => pvpDiceRefreshButtonsAfterResult());
}

function pvpDicePollRooms() {
    if (pvpDicePollInFlight) return;
    pvpDicePollInFlight = true;
    fetch("/api/pvp/dice/my-rooms?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        pvpDicePollInFlight = false;
        if (!data || !data.ok) return;
        const rooms = data.rooms || [];
        const currentIds = rooms.map(r => r.id);
        const primaryWasShown = pvpDiceRoomIds[0];
        const disappeared = pvpDiceRoomIds.filter(id => currentIds.indexOf(id) === -1);
        pvpDiceRoomIds = currentIds;
        if (!currentIds.length) stopPvpDicePolling();
        if (disappeared.indexOf(primaryWasShown) !== -1) {
            pvpDicePrimaryActive = false;
            pvpDiceFetchAndShowFinished(primaryWasShown);
            return;
        }
        if (disappeared.length) {
            showToast("Одна из ваших комнат была завершена — смотрите «Активные игры»", "success");
            pvpDiceRefreshButtonsAfterResult();
        }
        const primaryRoom = rooms.find(r => r.id === pvpDiceRoomIds[0]);
        if (primaryRoom && primaryRoom.status === "active" && !pvpDicePrimaryActive) {
            pvpDicePrimaryActive = true;
            pvpDiceShowRollingUI(pvpDiceRoomIds[0]);
        }
    }).catch(() => {
        pvpDicePollInFlight = false;
    });
}

function pvpDiceCreateRoom() {
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const state = pvpDiceReadyState();
    if (!state.hasBet || !state.enoughBalance || pvpDiceBusy) return;
    const diceLimitIssue = betLimitIssue("pvp_dice", state.bet);
    if (diceLimitIssue) {
        showToast(diceLimitIssue, "error");
        return;
    }
    if (pvpDiceRoomIds.length >= pvpDiceMaxRooms) {
        showToast("Нельзя создать больше " + pvpDiceMaxRooms + " комнат одновременно", "error");
        return;
    }
    pvpDiceBusy = true;
    const createBtn = document.getElementById("pvpDiceCreateBtn");
    createBtn.disabled = true;
    createBtn.classList.add("dim");
    createBtn.textContent = "Создаём…";
    fetch("/api/pvp/dice/create", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            bet: state.bet
        })
    }).then(r => r.json()).then(data => {
        pvpDiceBusy = false;
        createBtn.disabled = false;
        createBtn.textContent = "Создать PvP комнату";
        if (!data || !data.ok) {
            updatePvpDiceCreateState();
            showToast(data && data.error || "Ошибка сервера", "error");
            return;
        }
        if (typeof data.balance === "number") applyBalance(data.balance);
        pvpDiceRoomIds.push(data.roomId);
        pvpDiceShowWaitingUI();
        if (!pvpDicePollTimer) pvpDicePollTimer = setInterval(pvpDicePollRooms, 1500);
        showToast("Комната создана, ждём соперника", "success");
    }).catch(() => {
        pvpDiceBusy = false;
        createBtn.disabled = false;
        createBtn.textContent = "Создать PvP комнату";
        updatePvpDiceCreateState();
        showToast("Не удалось связаться с сервером", "error");
    });
}

function pvpDiceCancelRoom() {
    const roomId = pvpDiceRoomIds[0];
    if (!roomId) return;
    pvpGenericConfirm("Отменить комнату?", "Вы точно хотите отменить эту созданную PvP игру? Ставка будет возвращена в полном объёме.", () => {
        fetch("/api/pvp/dice/cancel", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                uid: CURRENT_UID,
                roomId: roomId
            })
        }).then(r => r.json()).then(data => {
            if (!data || !data.ok) {
                showToast(data && data.error || "Ошибка сервера", "error");
                return;
            }
            loadUserState();
            pvpDiceRoomIds.shift();
            if (!pvpDiceRoomIds.length) stopPvpDicePolling();
            pvpDiceRefreshButtonsAfterResult();
            showToast("Комната отменена, ставка возвращена", "success");
        }).catch(() => showToast("Не удалось связаться с сервером", "error"));
    });
}

function pvpDiceHistoryRowHTML(r) {
    const resultLabel = r.isDraw ? '<span class="gv-history-draw">Ничья</span>' : '<span class="gv-history-win">' + escapeHtml(r.winnerId === r.creatorId ? r.creatorName : r.opponentName) + " выиграл " + fmtNum(r.winAmount) + "⭐️</span>";
    return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-mid pvp-history-mid">' + "<div>" + '<div class="gv-history-name">' + escapeHtml(r.creatorName || "—") + " vs " + escapeHtml(r.opponentName || "—") + "</div>" + historyTimeHTML(r.finishedAt || r.createdAt) + "</div>" + pvpHistoryAvatarsHTML(r.creatorId, r.opponentId) + "</div>" + '<div class="gv-history-right">Ставка: <b>' + fmtNum(r.betAmount) + "⭐️</b><br>" + resultLabel + "</div>" + "</div>" + '<button class="crash-history-fair-btn" type="button" data-pvp-dice-round="' + escapeHtml(r.roomId) + '">' + fairCheckBtnIconHTML() + "Проверить честность</button>" + "</div>";
}

function pvpSearchResultRowHTML(r) {
    if (r.status === "finished") {
        const resultLabel = r.isDraw ? '<span class="gv-history-draw">Ничья</span>' : '<span class="gv-history-win">' + escapeHtml(r.winnerId === r.creatorId ? r.creatorName : r.opponentName) + " выиграл " + fmtNum(r.winAmount) + "⭐️</span>";
        return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-mid pvp-history-mid">' + "<div>" + '<div class="gv-history-name">' + escapeHtml(r.creatorName || "—") + " vs " + escapeHtml(r.opponentName || "—") + "</div>" + historyTimeHTML(r.finishedAt || r.createdAt) + "</div>" + pvpHistoryAvatarsHTML(r.creatorId, r.opponentId) + "</div>" + '<div class="gv-history-right">Ставка: <b>' + fmtNum(r.betAmount) + "⭐️</b><br>" + resultLabel + "</div>" + "</div>" + '<button class="crash-history-fair-btn" type="button" data-pvp-round="' + escapeHtml(r.roomId) + '" data-pvp-round-game="' + escapeHtml(r.game || "dice") + '">' + fairCheckBtnIconHTML() + "Проверить честность</button>" + "</div>";
    }
    if (r.status === "waiting" || r.status === "active") {
        const isMine = r.creatorId === CURRENT_UID;
        const subLabel = r.status === "active" ? "Бой уже идёт…" : "Ждёт соперника";
        return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-mid pvp-history-mid">' + "<div>" + '<div class="gv-history-name">' + escapeHtml(r.creatorName || "—") + (r.opponentName ? " vs " + escapeHtml(r.opponentName) : "") + "</div>" + '<div class="gv-history-time">' + subLabel + "</div>" + "</div>" + pvpHistoryAvatarsHTML(r.creatorId, r.opponentId) + "</div>" + '<div class="gv-history-right">Ставка: <b>' + fmtNum(r.betAmount) + "⭐️</b></div>" + "</div>" + '<button class="crash-history-fair-btn" type="button" data-pvp-goto-room="' + escapeHtml(r.roomId) + '" data-pvp-goto-game="' + escapeHtml(r.game || "dice") + '" data-pvp-goto-mine="' + (isMine ? "1" : "0") + '"' + (r.status === "active" ? " disabled" : "") + ">Перейти к игре</button>" + "</div>";
    }
    return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-mid">' + '<div class="gv-history-name">' + escapeHtml(r.creatorName || "—") + "</div>" + '<div class="gv-history-time">Комната отменена</div>' + "</div>" + "</div>" + "</div>";
}

function pvpSearchGoToRoom(game, roomId, isMine) {
    closePvpGamesModal();
    if (!game || game === "dice") {
        openGame("pvp-кости");
        if (isMine) return;
        setTimeout(() => {
            const modal = document.getElementById("pvpActiveModal");
            if (modal) modal.classList.add("active");
            pvpActiveConfirmJoin(roomId);
        }, 350);
        return;
    }
    const cfg = PVP_GEN_CONFIGS[game];
    if (!cfg) return;
    openGame("pvp-" + cfg.ru);
    if (isMine) return;
    setTimeout(() => {
        const modal = document.getElementById("pvpGenActiveModal");
        if (modal) modal.classList.add("active");
        pvpGenActiveConfirmJoin(roomId);
    }, 350);
}

function loadPvpDiceHistory(scope, append) {
    if (scope) {
        pvpDiceHistoryScope = scope;
        append = false;
    }
    gvHistoryLoad("pvpDiceHistoryList", off => "/api/pvp/dice/history?uid=" + CURRENT_UID + "&scope=" + pvpDiceHistoryScope + "&offset=" + off, 12, (rows, isAppend) => {
        const list = document.getElementById("pvpDiceHistoryList");
        const html = rows.map(pvpDiceHistoryRowHTML).join("");
        if (isAppend) list.insertAdjacentHTML("beforeend", html);
        else list.innerHTML = html;
    }, '<div class="dice-history-empty">Пока никто не сыграл в PvP Кости</div>', append);
}

function initPvpDiceGame() {
    pvpDiceBusy = false;
    pvpDiceRoomIds = [];
    pvpDiceUiMode = "create";
    stopPvpDicePolling();
    hidePvpDiceResultBox();
    pvpDiceSetStatus("");
    pvpDiceSetFairBox(null);
    updatePvpDiceCreateState();
    const betInput = gvBody.querySelector(".gv-bet-input");
    if (betInput) betInput.addEventListener("input", updatePvpDiceCreateState);
    document.getElementById("pvpDiceCreateBtn").addEventListener("click", pvpDiceCreateRoom);
    document.getElementById("pvpDiceCreateMoreBtn").addEventListener("click", pvpDiceShowCreateForm);
    document.getElementById("pvpDiceCancelBtn").addEventListener("click", pvpDiceCancelRoom);
    document.getElementById("pvpDiceActiveBtn").addEventListener("click", openPvpActiveModal);
    pvpShareBtnWire("pvpDiceShareBtn");
    document.getElementById("pvpDiceMyRoomsBtn").addEventListener("click", openPvpMyRoomsModal);
    document.getElementById("pvpDicePlayAgainBtn").addEventListener("click", () => {
        pvpDiceUiMode = "create";
        pvpDiceSyncActionButtons();
    });
    const pvpDiceFairBoxEl = document.getElementById("pvpDiceFairBox");
    if (pvpDiceFairBoxEl) {
        pvpDiceFairBoxEl.addEventListener("click", () => {
            if (pvpDiceFairBoxEl.dataset.mode === "waiting" && pvpDiceFairBoxEl.dataset.roomId) {
                openPvpInviteModal(pvpDiceFairBoxEl.dataset.roomId);
            }
        });
    }
    loadPvpDiceHistory("all");
    gvHistoryWireSearch("pvpDiceHistorySearchInput", () => loadPvpDiceHistory(), value => {
        gvHistorySearch("pvpDiceHistoryList", () => "/api/pvp/dice/history?uid=" + CURRENT_UID + "&scope=" + pvpDiceHistoryScope + "&q=" + encodeURIComponent(value), rows => {
            document.getElementById("pvpDiceHistoryList").innerHTML = rows.map(pvpDiceHistoryRowHTML).join("");
        });
    });
    fetch("/api/pvp/dice/my-rooms?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        const rooms = data && data.ok && data.rooms || [];
        pvpDiceRoomIds = rooms.map(r => r.id);
        if (pvpDiceRoomIds.length) {
            pvpDiceShowWaitingUI();
            pvpDicePollTimer = setInterval(pvpDicePollRooms, 1500);
        } else {
            pvpDiceShowCreateForm();
        }
    }).catch(() => pvpDiceShowCreateForm());
}

function pvpGenericConfirm(title, text, onYes) {
    const modal = document.getElementById("pvpConfirmModal");
    if (!modal) return;
    document.getElementById("pvpConfirmTitle").textContent = title;
    document.getElementById("pvpConfirmText").textContent = text;
    const oldYes = document.getElementById("pvpConfirmModalYes");
    const newYes = oldYes.cloneNode(true);
    oldYes.parentNode.replaceChild(newYes, oldYes);
    newYes.addEventListener("click", () => {
        modal.classList.remove("active");
        onYes();
    });
    document.getElementById("pvpConfirmModalNo").onclick = () => modal.classList.remove("active");
    modal.classList.add("active");
}

