function pvpDiceJoinRoom(roomId) {
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    closePvpActiveModal();
    pvpDiceShowRollingUI(roomId);
    fetch("/api/pvp/dice/join", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            roomId: roomId
        })
    }).then(r => r.json()).then(data => {
        if (!data || !data.ok) {
            showToast(data && data.error || "Ошибка сервера", "error");
            pvpDiceRefreshButtonsAfterResult();
            return;
        }
        if (typeof data.balance === "number") applyBalance(data.balance);
        pvpDiceShowResult(data);
    }).catch(() => {
        showToast("Не удалось связаться с сервером", "error");
        pvpDiceRefreshButtonsAfterResult();
    });
}

