function pvpGamesSearchById(query) {
    const grid = document.getElementById("pvpGamesGrid");
    const resultBox = document.getElementById("pvpSearchByIdResult");
    if (!grid || !resultBox) return;
    const q = (query || "").trim();
    if (!q) {
        resultBox.style.display = "none";
        resultBox.innerHTML = "";
        grid.style.display = "";
        return;
    }
    grid.style.display = "none";
    resultBox.style.display = "";
    resultBox.innerHTML = gvHistSkeletonRowsHTML(1);
    fetch("/api/pvp/search?id=" + encodeURIComponent(q.toUpperCase())).then(r => r.json()).then(data => {
        if (!data || !data.ok || data.game === "blackjack") {
            resultBox.innerHTML = pvpSearchNotFoundHTML();
            return;
        }
        resultBox.innerHTML = pvpSearchResultRowHTML(data);
    }).catch(() => {
        resultBox.innerHTML = pvpSearchNotFoundHTML();
    });
}

