if (pvpSearchByIdInput) {
    let pvpSearchTimer = null;
    pvpSearchByIdInput.addEventListener("input", () => {
        clearTimeout(pvpSearchTimer);
        const val = pvpSearchByIdInput.value;
        pvpSearchTimer = setTimeout(() => pvpGamesSearchById(val), 300);
    });
}

const pvpSearchByIdResultEl = document.getElementById("pvpSearchByIdResult");

if (pvpSearchByIdResultEl) {
    pvpSearchByIdResultEl.addEventListener("click", e => {
        const trigger = e.target.closest("[data-pvp-round]");
        if (trigger) {
            const g = trigger.dataset.pvpRoundGame;
            if (!g || g === "dice") openPvpDiceRoundModal(trigger.dataset.pvpRound);
            else if (g === "blackjack") openBlackjackPvpRoundModal(trigger.dataset.pvpRound);
            else openPvpGenRoundModal(g, trigger.dataset.pvpRound);
            return;
        }
        const goto = e.target.closest("[data-pvp-goto-room]");
        if (goto && !goto.disabled) pvpSearchGoToRoom(goto.dataset.pvpGotoGame, goto.dataset.pvpGotoRoom, goto.dataset.pvpGotoMine === "1");
    });
}

const PVP_ALL_GAME_LABELS = {
    dice: "🎲 Кости",
    bowling: "🎳 Боулинг",
    darts: "🎯 Дартс",
    basketball: "🏀 Баскетбол",
    football: "⚽️ Футбол",
    slots: "🎰 Слоты"
};

let pvpAllActiveFilter = "all";

let pvpAllActiveOffset = 0;

let pvpAllActiveHasMore = true;

let pvpAllActiveLoading = false;

function pvpAllActiveRoomRowHTML(room) {
    const isMine = !!room.isMine;
    const disabled = isMine || room.bet > currentUser.balance;
    const gameLabel = PVP_ALL_GAME_LABELS[room.game] || room.game;
    return '<div class="crash-player-row" data-room-id="' + escapeHtml(room.roomId) + '" data-room-game="' + escapeHtml(room.game) + '">' + '<div class="crash-player-avatar"><img src="' + room.avatarUrl + '" alt=""></div>' + '<div class="crash-player-mid">' + '<div class="crash-player-name">' + escapeHtml(room.creatorName) + (isMine ? ' <span style="color:var(--text-2); font-weight:600;">(вы)</span>' : "") + "</div>" + '<div class="crash-player-sub">' + gameLabel + " · Ставка " + fmtNum(room.bet) + "⭐️ · #" + escapeHtml(room.roomId) + "</div>" + "</div>" + '<button class="pvp-room-join-btn' + (disabled ? " disabled" : "") + '" type="button"' + (disabled ? " disabled" : "") + ">Войти</button>" + "</div>";
}

function loadPvpAllActiveList(append) {
    const list = document.getElementById("pvpAllActiveList");
    if (!list) return;
    if (!append) {
        pvpAllActiveOffset = 0;
        pvpAllActiveHasMore = true;
    }
    if (pvpAllActiveLoading || !pvpAllActiveHasMore) return;
    pvpAllActiveLoading = true;
    if (append) list.insertAdjacentHTML("beforeend", '<div class="gv-history-loadmore-skel">' + gvHistSkeletonRowsHTML(2) + "</div>");
    else list.innerHTML = pvpRoomListSkeletonHTML();
    const gameParam = pvpAllActiveFilter === "all" ? "" : "&game=" + encodeURIComponent(pvpAllActiveFilter);
    fetch("/api/pvp/active-all?uid=" + CURRENT_UID + "&offset=" + pvpAllActiveOffset + gameParam).then(r => r.json()).then(data => {
        pvpAllActiveLoading = false;
        const skelEl = list.querySelector(".gv-history-loadmore-skel");
        if (skelEl) skelEl.remove();
        const rooms = data && data.ok && data.rooms || [];
        pvpAllActiveHasMore = rooms.length >= 20;
        pvpAllActiveOffset += rooms.length;
        if (!append && !rooms.length) {
            list.innerHTML = '<div class="dice-history-empty">Пока никто не создал комнату</div>';
            return;
        }
        const html = rooms.map(pvpAllActiveRoomRowHTML).join("");
        if (append) list.insertAdjacentHTML("beforeend", html);
        else list.innerHTML = html;
    }).catch(() => {
        pvpAllActiveLoading = false;
        const skelEl = list.querySelector(".gv-history-loadmore-skel");
        if (skelEl) skelEl.remove();
        if (!append) list.innerHTML = '<div class="dice-history-empty">Не удалось загрузить</div>';
    });
}

function openPvpAllActiveModal() {
    const modal = document.getElementById("pvpAllActiveModal");
    if (!modal) return;
    modal.classList.add("active");
    loadPvpAllActiveList(false);
}

function closePvpAllActiveModal() {
    const modal = document.getElementById("pvpAllActiveModal");
    if (modal) modal.classList.remove("active");
}

const pvpPickerActiveBtn = document.getElementById("pvpPickerActiveBtn");

if (pvpPickerActiveBtn) pvpPickerActiveBtn.addEventListener("click", openPvpAllActiveModal);

const pvpAllActiveModalEl = document.getElementById("pvpAllActiveModal");

const pvpAllActiveCloseBtn = document.getElementById("pvpAllActiveClose");

if (pvpAllActiveCloseBtn) pvpAllActiveCloseBtn.addEventListener("click", closePvpAllActiveModal);

if (pvpAllActiveModalEl) pvpAllActiveModalEl.addEventListener("click", e => {
    if (e.target === pvpAllActiveModalEl) closePvpAllActiveModal();
});

const pvpAllActiveFilterEl = document.getElementById("pvpAllActiveFilter");

if (pvpAllActiveFilterEl) {
    pvpAllActiveFilterEl.querySelectorAll("[data-pvp-filter-name]").forEach(btn => {
        const img = btn.querySelector(".pvp-filter-icon");
        const sourceCard = document.querySelector('#gamesGrid .game-card[data-name="' + btn.dataset.pvpFilterName + '"] img.icon-img');
        if (img && sourceCard && sourceCard.src) img.src = sourceCard.src;
    });
    pvpAllActiveFilterEl.addEventListener("click", e => {
        const btn = e.target.closest("[data-pvp-filter-game]");
        if (!btn) return;
        pvpAllActiveFilterEl.querySelectorAll(".privacy-mode-btn").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        pvpAllActiveFilter = btn.dataset.pvpFilterGame;
        loadPvpAllActiveList(false);
    });
}

const pvpAllActiveListEl = document.getElementById("pvpAllActiveList");

if (pvpAllActiveListEl) {
    pvpAllActiveListEl.addEventListener("click", e => {
        const joinBtn = e.target.closest(".pvp-room-join-btn");
        if (!joinBtn || joinBtn.disabled) return;
        const row = joinBtn.closest("[data-room-id]");
        if (!row) return;
        const game = row.dataset.roomGame;
        const roomId = row.dataset.roomId;
        closePvpAllActiveModal();
        pvpSearchGoToRoom(game, roomId, false);
    });
}

let pvpAllActiveScrollTimer = null;

document.addEventListener("scroll", function(e) {
    const card = e.target;
    if (!card || !pvpAllActiveModalEl || card.parentElement !== pvpAllActiveModalEl) return;
    if (pvpAllActiveScrollTimer) return;
    pvpAllActiveScrollTimer = setTimeout(() => {
        pvpAllActiveScrollTimer = null;
        if (!pvpAllActiveHasMore || pvpAllActiveLoading) return;
        if (card.scrollTop + card.clientHeight >= card.scrollHeight - 200) {
            loadPvpAllActiveList(true);
        }
    }, 100);
}, true);

