(function initNavGestures() {
    const nav = document.querySelector(".bottom-nav");
    if (!nav) return;
    const items = Array.from(nav.querySelectorAll(".nav-item"));
    const DRAG_THRESHOLD = 5;
    let drag = null;
    let suppressClick = false;

    function geometry() {
        const r = nav.getBoundingClientRect();
        const inner = r.width - 10;
        return {
            left: r.left + 5,
            inner: inner,
            w: inner / items.length
        };
    }

    function idxAt(clientX) {
        const g = geometry();
        return Math.max(0, Math.min(items.length - 1, Math.floor((clientX - g.left) / g.w)));
    }

    function moveLens(clientX) {
        const g = geometry();
        const x = Math.max(0, Math.min(g.inner - g.w, clientX - g.left - g.w / 2));
        nav.style.setProperty("--lens-x", x + "px");
    }

    function setHover(i) {
        items.forEach((it, n) => it.classList.toggle("hover", n === i));
    }
    nav.addEventListener("pointerdown", e => {
        if (e.pointerType === "mouse" && e.button !== 0) return;
        if (typeof expandNav === "function") expandNav();
        nav.classList.add("pressed");
        drag = {
            id: e.pointerId,
            startX: e.clientX,
            moved: false,
            idx: idxAt(e.clientX)
        };
    });
    nav.addEventListener("pointermove", e => {
        if (!drag || e.pointerId !== drag.id) return;
        if (!drag.moved) {
            if (Math.abs(e.clientX - drag.startX) < DRAG_THRESHOLD) return;
            drag.moved = true;
            nav.classList.add("dragging");
            try {
                nav.setPointerCapture(e.pointerId);
            } catch (err) {}
            haptic("impact", "light");
        }
        moveLens(e.clientX);
        const i = idxAt(e.clientX);
        if (i !== drag.idx) {
            drag.idx = i;
            setHover(i);
            haptic("selection");
        } else if (!items.some(it => it.classList.contains("hover"))) {
            setHover(i);
        }
        if (e.cancelable) e.preventDefault();
    });

    function finish(e, cancelled) {
        if (!drag || e.pointerId !== drag.id) return;
        const d = drag;
        drag = null;
        nav.classList.remove("pressed", "dragging");
        setHover(-1);
        try {
            nav.releasePointerCapture(d.id);
        } catch (err) {}
        if (!d.moved) return;
        nav.style.removeProperty("--lens-x");
        if (!cancelled) {
            const target = items[idxAt(e.clientX)];
            if (target && !target.classList.contains("active")) target.click();
        }
        suppressClick = true;
        setTimeout(() => {
            suppressClick = false;
        }, 120);
    }
    nav.addEventListener("pointerup", e => finish(e, false));
    nav.addEventListener("pointercancel", e => finish(e, true));
    nav.addEventListener("click", e => {
        if (suppressClick) {
            e.stopPropagation();
            e.preventDefault();
        }
    }, true);
})();

(function initCardAnimator() {
    const SEL = ".blackjack-cards, .hilo-card-row";
    const prevSigs = new Map();

    function unitSig(u) {
        const img = u.querySelector && u.querySelector("img.blackjack-card-img");
        if (img) return img.getAttribute("src") || "img";
        if (u.classList.contains("blackjack-card-back") || u.querySelector && u.querySelector(".blackjack-card-back")) return "back";
        return "x:" + u.className;
    }
    const BJ_JITTER = [0, -1.4, 1.1, -.7, 1.5, -1, .8, -1.3];

    function bjFan(units) {
        const n = units.length;
        const mid = (n - 1) / 2;
        const spread = n <= 3 ? 4.6 : n <= 5 ? 3.6 : 2.8;
        units.forEach((u, i) => {
            const rot = (i - mid) * spread + (n > 1 ? BJ_JITTER[i % 8] : -2.1);
            const ty = Math.pow(Math.abs(i - mid), 1.4) * 2 + BJ_JITTER[(i + 3) % 8] * 1.2;
            u.style.setProperty("--rot", rot.toFixed(2) + "deg");
            u.style.setProperty("--ty", ty.toFixed(1) + "px");
        });
    }

    function containerKey(c) {
        if (c.id) return c.id;
        const box = c.closest(".blackjack-table-box, .gv-mines-box");
        const all = box ? Array.from(box.querySelectorAll(SEL)) : [c];
        return "auto:" + (box ? box.className : "") + ":" + all.indexOf(c);
    }

    function process(c) {
        const key = containerKey(c);
        const box = c.closest(".blackjack-table-box, .gv-mines-box");
        const all = box ? Array.from(box.querySelectorAll(SEL)) : [c];
        c.dataset.bjSide = all.indexOf(c) > 0 ? "bottom" : "top";
        const units = Array.from(c.children);
        const sigs = units.map(unitSig);
        const prev = prevSigs.get(key) || [];
        prevSigs.set(key, sigs);
        let n = 0;
        units.forEach((u, i) => {
            if (prev[i] === sigs[i]) return;
            const el = u.classList.contains("hilo-card-wrap") ? u : u;
            el.style.setProperty("--bj-i", n++);
            el.classList.add(prev[i] === "back" && sigs[i] !== "back" ? "bj-flip" : "bj-in");
        });
        if (c.classList.contains("blackjack-cards") && !c.classList.contains("blackjack-cards-sm")) bjFan(units);
    }
    new MutationObserver(mutations => {
        const todo = new Set();
        for (const m of mutations) {
            for (const n of m.addedNodes) {
                if (n.nodeType !== 1) continue;
                if (n.matches && n.matches(SEL)) todo.add(n);
                if (n.querySelectorAll) n.querySelectorAll(SEL).forEach(x => todo.add(x));
                const par = n.parentElement;
                if (par && par.matches && par.matches(SEL)) todo.add(par);
            }
        }
        todo.forEach(process);
    }).observe(document.body, {
        childList: true,
        subtree: true
    });
})();

let expandNav = null;

(function initNavCompact() {
    const nav = document.querySelector(".bottom-nav");
    if (!nav) return;
    let compact = false;
    let lastY = window.scrollY || 0;
    let ticking = false;

    function set(v) {
        if (compact === v) return;
        compact = v;
        nav.classList.toggle("compact", v);
    }
    expandNav = () => set(false);
    window.addEventListener("scroll", () => {
        if (ticking) return;
        ticking = true;
        requestAnimationFrame(() => {
            ticking = false;
            const y = window.scrollY || 0;
            const dy = y - lastY;
            if (Math.abs(dy) < 6) return;
            lastY = y;
            if (y < 60) set(false);
            else set(dy > 0);
        });
    }, {
        passive: true
    });
})();

