const MIN_BET = .1,
    MAX_BET = 1e6;

let betLimits = {};

function betMin(key) {
    const l = key && betLimits[key];
    return l && l.min > 0 ? l.min : MIN_BET;
}

function betMax(key) {
    const l = key && betLimits[key];
    if (l && l.max === null) return Infinity;
    return l && l.max > 0 ? l.max : MAX_BET;
}

function currentLimitKey() {
    const data = gamesData[currentGame];
    if (!data) return null;
    if (data.type === "pvp_generic") return "pvp_" + data.pvpKey;
    if (data.type === "blackjack" && blackjackPvpMode) return "pvp_blackjack";
    if (data.type === "escape" && window.escapePvpActive && window.escapePvpActive()) return "escape_pvp";
    return data.type;
}

function betLimitIssue(key, bet) {
    if (!(bet > 0)) return null;
    if (bet < betMin(key)) return "Минимальная ставка — " + fmtNum(betMin(key)) + "⭐️";
    if (bet > betMax(key)) return "Максимальная ставка — " + fmtNum(betMax(key)) + "⭐️";
    return null;
}

function loadBetLimits() {
    fetch("/api/bet-limits").then(r => r.json()).then(data => {
        if (data && data.ok && data.limits) {
            betLimits = data.limits;
            refreshBetsLockUI();
        }
    }).catch(function() {});
}

loadBetLimits();

setInterval(loadBetLimits, 6e4);

document.addEventListener("visibilitychange", function() {
    if (!document.hidden) loadBetLimits();
});

let currentGame = null;

let currentRoundId = 0,
    currentSeed = "",
    currentHash = null,
    currentPlayed = false;

async function sha256Hex(text) {
    const enc = (new TextEncoder).encode(text);
    const buf = await crypto.subtle.digest("SHA-256", enc);
    return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, "0")).join("");
}

function randomBits(n) {
    let s = "";
    for (let i = 0; i < n; i++) s += Math.random() < .5 ? "0" : "1";
    return s;
}

function randomHex(bytes) {
    return Array.from(crypto.getRandomValues(new Uint8Array(bytes))).map(b => b.toString(16).padStart(2, "0")).join("");
}

function newRound() {
    currentRoundId = Math.floor(7e4 + Math.random() * 9e3);
    currentSeed = randomBits(25) + "_" + randomHex(16);
    currentHash = null;
    currentPlayed = false;
}

function betRowHTML(defaultValue) {
    const val = (defaultValue === undefined ? "100" : defaultValue) + "⭐️";
    return '<div class="gv-bet-row">' + '<div class="gv-bet-group">' + '<button class="gv-chip" type="button" data-action="min">MIN</button>' + '<button class="gv-chip" type="button" data-action="half">/2</button>' + "</div>" + '<input type="text" inputmode="decimal" autocomplete="off" class="gv-bet-input" placeholder="100⭐️" value="' + val + '">' + '<div class="gv-bet-group">' + '<button class="gv-chip" type="button" data-action="double">x2</button>' + '<button class="gv-chip" type="button" data-action="max">MAX</button>' + "</div>" + "</div>";
}

function howtoHTML(extraStyle) {
    return '<div class="gv-howto" data-action="howto"' + (extraStyle ? ' style="' + extraStyle + '"' : "") + '><span>Как играть</span><span class="gv-howto-q">?</span></div>';
}

function fairHTML(extraStyle) {
    return '<div class="gv-fair" data-action="fair"' + (extraStyle ? ' style="' + extraStyle + '"' : "") + '><span class="gv-fair-icon">#</span><span>' + currentRoundId + "</span></div>";
}

function multRowHTML(values) {
    return '<div class="gv-mult-row">' + values.map((v, i) => (i > 0 ? '<span class="gv-mult-arrow">›</span>' : "") + '<span class="gv-mult-chip' + (i === 0 ? " now" : "") + '">' + v + "</span>").join("") + "</div>";
}

function historyHTML(data) {
    const outcomes = data.historyOutcomes || data.outcomes || ["—"];
    const times = ["13:00", "12:57", "12:41", "12:26", "12:10", "11:58", "11:42", "11:19"];
    const bets = ["1000⭐️", "750⭐️", "300⭐️", "1500⭐️", "200⭐️", "980⭐️", "450⭐️", "2000⭐️"];
    const rows = times.map((time, i) => ({
        time: time,
        bet: bets[i],
        outcome: outcomes[i % outcomes.length]
    }));
    return '<div class="gv-history">' + '<div class="gv-history-head">' + '<h3 class="gv-history-title">' + lazyImgTag(liteAsset("/lottie/images/ОгоньЭмоджи.lottie"), "", "flame-gif") + " Последние игры</h3>" + '<div class="gv-history-tabs">' + '<button class="gv-history-tab active" type="button">Все</button>' + '<button class="gv-history-tab" type="button">Мои</button>' + "</div>" + "</div>" + '<div class="gv-history-list">' + rows.map(r => '<div class="gv-history-row">' + '<div class="gv-history-avatar">?</div>' + '<div class="gv-history-mid">' + '<div class="gv-history-name">Игрок</div>' + '<div class="gv-history-time">' + r.time + "</div>" + "</div>" + '<div class="gv-history-right">Ставка: <b>' + r.bet + "</b><br>Исход: <b>" + r.outcome + "</b></div>" + "</div>").join("") + "</div>" + "</div>";
}

const LIVE_MULT = {};

const LIVE_FAM = {};

const LIVE_DUEL = {};

const LIVE_EXT = {};

const DICE_LADDERS = {
    "Лесенка низкий риск": [0, 0.35, 0.85, 0, 1.45, 2.2],
    "Лесенка высокий риск": [0, 0, 0, 1.3, 1.6, 3.1]
};

function diceLadderTitle(outcome) {
    return "Лесенка — " + (outcome.indexOf("низкий") >= 0 ? "низкий" : "высокий") + " риск";
}

function diceLadderFace(outcome, face) {
    const live = LIVE_MULT.dice;
    const key = outcome + ":" + face;
    if (live && Object.prototype.hasOwnProperty.call(live, key)) return Number(live[key]);
    return DICE_LADDERS[outcome][face - 1];
}

function diceLadderActive() {
    return Object.keys(DICE_LADDERS).filter(o => !ocOff("dice", o));
}

function diceLadderMax(outcome) {
    return Math.max.apply(null, [1, 2, 3, 4, 5, 6].map(f => diceLadderFace(outcome, f)));
}

function diceLadderMaxActive() {
    const list = diceLadderActive();
    return Math.max.apply(null, (list.length ? list : Object.keys(DICE_LADDERS)).map(diceLadderMax));
}

const DICE_SUM_WAYS = (function() {
    const out = {
        2: {},
        3: {},
        4: {}
    };
    for (let a = 1; a <= 6; a++)
        for (let b = 1; b <= 6; b++) out[2][a + b] = (out[2][a + b] || 0) + 1;
    for (let a = 1; a <= 6; a++)
        for (let b = 1; b <= 6; b++)
            for (let c = 1; c <= 6; c++) {
                out[3][a + b + c] = (out[3][a + b + c] || 0) + 1;
                for (let d = 1; d <= 6; d++) out[4][a + b + c + d] = (out[4][a + b + c + d] || 0) + 1;
            }
    return out;
})();

function diceCorridorParse(outcome) {
    const m = /^Коридор ([34])к:(\d+)-(\d+)$/.exec(outcome);
    if (!m) return null;
    const n = parseInt(m[1], 10),
        lo = parseInt(m[2], 10),
        hi = parseInt(m[3], 10);
    if (!(n <= lo && lo <= hi && hi <= 6 * n)) return null;
    return {
        n: n,
        lo: lo,
        hi: hi
    };
}

const DICE_SUM_FIXED_RE = /^Сумма ([34])к ([‹=›])(\d{1,2})$/;

const DICE_FOUR_HAND_NAME = {
    "Четыре меньше": "Все меньше",
    "Четыре больше": "Все больше",
    "Пара 4к": "Пара",
    "Трипл 4к": "Трипл",
    "Каре 4к": "Каре",
    "Две пары 4к": "Две пары",
    "Стрит 4к": "Стрит",
    "Зеркало": "Зеркало",
    "Края равны": "Края равны"
};

function diceFloorMult(total, ways) {
    if (!(ways > 0)) return total;
    return Math.max(1.03, Math.floor(total * 100 / ways) / 100);
}

function diceSumWays(count, op, n) {
    const dist = DICE_SUM_WAYS[count] || {};
    let ways = 0;
    Object.keys(dist).forEach(key => {
        const s = parseInt(key, 10);
        if (op === "‹" ? s < n : op === "›" ? s > n : s === n) ways += dist[key];
    });
    return ways;
}

function diceSumMult(count, op, n) {
    return diceFloorMult(Math.pow(6, count), diceSumWays(count, op, n));
}

function diceTotal2Mult(sums) {
    let ways = 0;
    sums.forEach(s => {
        ways += DICE_SUM_WAYS[2][s] || 0;
    });
    return diceFloorMult(36, ways);
}

function diceSumLabel(op, n) {
    return op === "=" ? "Сумма ровно " + n : "Сумма " + op + " " + n;
}

function diceSum2Parse(outcome) {
    const m = /^Сумма 2к:([‹=›])(\d{1,2})$/.exec(outcome);
    if (!m) return null;
    const n = parseInt(m[2], 10);
    if (!(n >= 2 && n <= 12) || diceSumWays(2, m[1], n) <= 0) return null;
    return {
        op: m[1],
        n: n
    };
}

function diceCorridorBase(n, lo, hi) {
    let ways = 0;
    for (let s = lo; s <= hi; s++) ways += DICE_SUM_WAYS[n][s] || 0;
    return ways ? Math.round(Math.pow(6, n) / ways * 100) / 100 : 0;
}

function dicePickerTileText(p, outcome) {
    if (p.kind === "ladder") return diceLadderTitle(outcome);
    if (p.kind === "atleast") return "Хотя бы " + p.vals.slice().sort((x, y) => x - y).join(", ");
    if (p.kind === "sum2") {
        const s = diceSum2Parse(outcome);
        return s ? diceSumLabel(s.op, s.n) : "Сумма";
    }
    if (p.kind === "total2") return "Итог " + p.sums.slice().sort((x, y) => x - y).join(", ");
    if (p.kind === "corridor3") return "Коридор " + p.lo + "–" + p.hi;
    return dicePickerTitle(p.kind);
}

function famApply(gameKey, family, value) {
    const f = (LIVE_FAM[gameKey] || {})[family];
    if (typeof f !== "number" || f === 1 || !(value > 1)) return value;
    return Math.max(1.01, Math.round(value * f * 100) / 100);
}

function fmtCoef(v) {
    const n = Number(v);
    if (!isFinite(n)) return String(v);
    return (Math.round(n * 100) / 100).toString();
}

function coefFor(gameKey, outcome, fallback) {
    const live = LIVE_MULT[gameKey];
    if (live && Object.prototype.hasOwnProperty.call(live, outcome)) return fmtCoef(live[outcome]);
    return fallback;
}

function coefIsLive(gameKey, outcome) {
    const live = LIVE_MULT[gameKey];
    return !!(live && Object.prototype.hasOwnProperty.call(live, outcome));
}

function updateMultBadge(badgeId, gameKey, outcome, fallback, isPair) {
    const el = document.getElementById(badgeId);
    if (!el) return;
    el.classList.remove("waiting");
    if (!outcome || fallback == null) {
        el.classList.remove("show");
        return;
    }
    el.textContent = (gameKey === "dice" && DICE_LADDERS[outcome] || (gameKey === "foot" || gameKey === "basket" || gameKey === "bowl" || gameKey === "darts") && outcome === "Лесенка" ? "до x" : "x") + coefFor(gameKey, outcome, fallback);
    el.classList.add("show");
    el.classList.toggle("centered", !!isPair);
}

function findTileMultText(tiles, outcome, submenus) {
    const t = tiles.find(x => x.outcome === outcome);
    if (t && t.multText) return t.multText;
    if (submenus) {
        for (const key in submenus) {
            const opt = (submenus[key].options || []).find(o => o.outcome === outcome);
            if (opt) return opt.multText;
        }
    }
    return null;
}

function coefSpanHTML(gameKey, outcome, fallback) {
    const loaded = coefIsLive(gameKey, outcome);
    const val = loaded ? fmtCoef(LIVE_MULT[gameKey][outcome]) : fallback;
    return '<span class="tile-coef' + (loaded ? "" : " text-skel") + '">' + val + "</span>";
}

function loadLiveMultipliers(gameKey, endpoint, onReady) {
    fetch(endpoint).then(r => r.json()).then(data => {
        if (data && data.ok && data.multipliers) {
            LIVE_MULT[gameKey] = data.multipliers;
            if (data.families) LIVE_FAM[gameKey] = data.families;
            if (data.duel) LIVE_DUEL[gameKey] = data.duel;
            if (data.ladder || data.pick) LIVE_EXT[gameKey] = {
                ladder: data.ladder || null,
                pick: data.pick || null
            };
            if (data.paytables) LIVE_EXT[gameKey] = Object.assign(LIVE_EXT[gameKey] || {}, {
                paytables: data.paytables
            });
            if (onReady) onReady(data.multipliers);
        }
    }).catch(() => {});
}

function refreshTileCoefs(containerId, tiles, gameKey) {
    const container = document.getElementById(containerId);
    if (!container) return;
    tiles.forEach(t => {
        if (t.group) return;
        const btn = container.querySelector('.gv-outcome[data-outcome="' + t.outcome + '"]');
        if (!btn) return;
        const span = btn.querySelector(".tile-coef");
        if (!span) return;
        span.textContent = coefFor(gameKey, t.outcome, t.multText);
        span.classList.remove("text-skel");
    });
}

