function ocKey(game, outcome) {
    const text = String(outcome == null ? "" : outcome);
    if (game === "slots" && text.indexOf("Дуэль:") === 0) {
        const parts = text.split(":");
        return parts.length >= 3 ? "Дуэль:" + parts[parts.length - 1] : text;
    }
    const at = text.indexOf(":");
    if (at > 0) {
        const head = text.slice(0, at);
        const families = OC_FAMILIES[game];
        if (families && families.indexOf(head) !== -1) return head;
    }
    return text;
}

function ocOff(game, outcome) {
    const set = OUTCOME_OFF.games[game];
    return !!set && set.has(ocKey(game, outcome));
}

function ocFamilyOff(game, picker) {
    const family = (OC_PICKER_FAMILY[game] || {})[picker];
    const set = OUTCOME_OFF.games[game];
    return !!family && !!set && set.has(family);
}

function ocOptionVisible(game, option, submenus) {
    if (game === "dice" && option.picker === "ladder") return Object.keys(DICE_LADDERS).some(o => !ocOff("dice", o));
    if ((game === "foot" || game === "basket" || game === "bowl" || game === "darts") && option.picker === "ladder") return !ocOff(game, "Лесенка");
    if (option.picker) return !ocFamilyOff(game, option.picker);
    if (option.nav) {
        if (game === "slots" && option.nav === "duel2") return ["<", ">", "="].some(op => !ocOff(game, "Дуэль:" + op));
        const sub = submenus && submenus[option.nav];
        return sub ? ocOptions(game, sub.options, submenus).length > 0 : true;
    }
    return option.outcome == null ? true : !ocOff(game, option.outcome);
}

function ocOptions(game, options, submenus) {
    return options.filter(o => ocOptionVisible(game, o, submenus));
}

function ocTileVisible(game, tile, submenus) {
    if (tile.group) {
        const sub = submenus && submenus[tile.group];
        return sub ? ocOptions(game, sub.options, submenus).length > 0 : true;
    }
    return !ocOff(game, tile.outcome);
}

function ocTilesHTML(game, tiles, submenus) {
    return tiles.filter(t => ocTileVisible(game, t, submenus)).map(t => {
        const isGroup = !!t.group;
        const text = isGroup ? t.label : t.label + " (x" + coefSpanHTML(game, t.outcome, t.multText) + ")";
        const attrs = isGroup ? ' data-group="' + t.group + '"' : ' data-outcome="' + t.outcome + '"';
        return '<button class="gv-outcome' + (isGroup ? " group-tile" : "") + '" type="button"' + attrs + ">" + text + "</button>";
    }).join("");
}

function ocRefreshOpen() {
    OC_GAMES.forEach(g => {
        const box = document.getElementById(g.box);
        if (!box) return;
        const selected = g.selected();
        const keep = selected && !ocOff(g.key, selected);
        if (selected && !keep) g.drop();
        box.innerHTML = ocTilesHTML(g.key, g.tiles(), g.subs());
        if (keep) {
            const tile = box.querySelector('.gv-outcome[data-outcome="' + selected + '"]');
            if (tile) tile.classList.add("selected");
        }
        refreshTileCoefs(g.box, g.tiles(), g.key);
    });
    if (currentGame === "claw" && typeof clawOnOutcomeChange === "function") clawOnOutcomeChange();
    if (currentGame === "baccarat" && window.baccaratKit) window.baccaratKit.onOutcomeChange();
}

function ocApply(data) {
    const games = {};
    Object.keys(data.off || {}).forEach(g => {
        games[g] = new Set(data.off[g]);
    });
    const changed = data.ver !== OUTCOME_OFF.ver;
    OUTCOME_OFF.games = games;
    OUTCOME_OFF.ver = data.ver;
    if (changed) ocRefreshOpen();
}

function ocLoad() {
    if (OUTCOME_OFF.busy) return;
    OUTCOME_OFF.busy = true;
    fetch("/api/outcomes/off", {
        cache: "no-store"
    }).then(r => r.json()).then(data => {
        if (data && data.ok) ocApply(data);
    }).catch(() => {}).then(() => {
        OUTCOME_OFF.busy = false;
    });
}

function ocSeen(ver) {
    if (typeof ver === "number" && ver !== OUTCOME_OFF.ver) ocLoad();
}

function ocOnPlay(data) {
    if (data && data.outcomeOff) ocLoad();
    return data;
}

ocLoad();

document.addEventListener("visibilitychange", () => {
    if (!document.hidden) ocLoad();
});

