function liteUiBadgeHTML() {
    if (!currentUser.liteUiEnabled) return "";
    return '<div class="gv-liteui-badge show"><img src="/lottie/LiteUi.png" alt="">Lite UI</div>';
}

function relocateLiteBadgeToTitle() {
    if (!gvTitle || !gvBody) return;
    let slot = gvTitle.querySelector(".gv-title-lite-slot");
    const inBody = Array.from(gvBody.querySelectorAll(".gv-liteui-badge"));
    if (!currentUser.liteUiEnabled) {
        inBody.forEach(b => b.remove());
        if (slot) slot.remove();
        return;
    }
    if (!slot) {
        slot = document.createElement("span");
        slot.className = "gv-title-lite-slot";
        gvTitle.appendChild(slot);
    }
    if (!slot.querySelector(".gv-liteui-badge")) {
        if (inBody.length) slot.appendChild(inBody.shift());
        else slot.insertAdjacentHTML("beforeend", liteUiBadgeHTML());
    }
    inBody.forEach(b => b.remove());
}

if (gvTitle) gvTitle.addEventListener("click", e => {
    if (e.target.closest(".gv-liteui-badge")) openLiteUiInfoModal();
});

(function watchLiteBadgeInGames() {
    if (!gvBody) return;
    new MutationObserver(mutations => {
        for (const m of mutations) {
            for (const n of m.addedNodes) {
                if (n.nodeType !== 1) continue;
                if (n.matches && n.matches(".gv-liteui-badge") || n.querySelector && n.querySelector(".gv-liteui-badge")) {
                    relocateLiteBadgeToTitle();
                    return;
                }
            }
        }
    }).observe(gvBody, {
        childList: true,
        subtree: true
    });
})();

function syncLiteUiBadges() {
    relocateLiteBadgeToTitle();
    document.querySelectorAll(".gv-photo, #crashBox").forEach(box => {
        if (gvBody && gvBody.contains(box)) return;
        const existing = box.querySelector(".gv-liteui-badge");
        if (currentUser.liteUiEnabled && !existing) {
            box.insertAdjacentHTML("afterbegin", liteUiBadgeHTML());
        } else if (!currentUser.liteUiEnabled && existing) {
            existing.remove();
        }
    });
}

