let diceSelectedOutcome = null;

let diceBusy = false;

let diceMode = "start";

let diceActiveType = "single";

function diceReadyState() {
    const betInput = gvBody.querySelector(".gv-bet-input");
    const bet = betInput ? parseFloat(betInput.value) : NaN;
    return {
        bet: bet,
        hasOutcome: !!diceSelectedOutcome,
        hasBet: bet > 0,
        enoughBalance: bet > 0 && bet <= currentUser.balance + 1e-6,
        overMax: bet > betMax("dice"),
        underMin: bet > 0 && bet < betMin("dice")
    };
}

function updateDiceStartState() {
    const btn = document.getElementById("diceStartBtn");
    if (btn) {
        const ready = !diceBusy && betsAccepted && !!diceSelectedOutcome;
        btn.classList.toggle("dim", !ready);
    }
    const outcomes = document.getElementById("diceOutcomes");
    if (outcomes) outcomes.classList.toggle("bets-locked", !betsAccepted);

    const confirmBtn = document.getElementById("diceBetConfirmBtn");
    if (confirmBtn) {
        const state = diceReadyState();
        const confirmReady = !diceBusy && betsAccepted && state.hasOutcome && state.hasBet && state.enoughBalance && !state.overMax && !state.underMin;
        confirmBtn.classList.toggle("dim", !confirmReady);
    }
}

