function slotsPaytables() {
    const live = (LIVE_EXT.slots || {}).paytables;
    return live || SLOTS_PAY_DEFAULT;
}

function slotsPayMax(kind) {
    const t = slotsPaytables()[kind] || SLOTS_PAY_DEFAULT[kind];
    return Number(t.max);
}

function slotsCountMult(k) {
    const t = slotsPaytables().count || SLOTS_PAY_DEFAULT.count;
    return Number(t[String(k)]);
}

const SLOTS_PAY_OUTCOME = {
    ladder: "Лесенка",
    piggy: "Копилка",
    lucky: "Лаки 7"
};

function slotsPickMultText(o) {
    if (o.picker === "ladder" || o.picker === "piggy" || o.picker === "lucky") return "до x" + fmtCoef(slotsPayMax(o.picker));
    if (o.picker === "count") return "до x" + fmtCoef(slotsCountMult(2));
    return o.multText;
}

function slotsPayOutcomeKind(outcome) {
    return outcome === "Лесенка" ? "ladder" : outcome === "Копилка" ? "piggy" : outcome === "Лаки 7" ? "lucky" : null;
}

function slotsBadgeText(outcome) {
    const kind = slotsPayOutcomeKind(outcome);
    if (kind) return "до x" + fmtCoef(slotsPayMax(kind));
    if (typeof outcome === "string" && outcome.indexOf("Кол-во:") === 0) {
        const parts = outcome.split(":");
        return "x" + fmtCoef(slotsCountMult(parts[2]));
    }
    return null;
}

