let slotsSelectedOutcome = null;

let slotsBusy = false;

let slotsMode = "start";

let slotsActiveType = "single";

function slotsReadyState() {
    const betInput = gvBody.querySelector(".gv-bet-input");
    const bet = betInput ? parseFloat(betInput.value) : NaN;
    return {
        bet: bet,
        hasOutcome: !!slotsSelectedOutcome,
        hasBet: bet > 0,
        enoughBalance: bet > 0 && bet <= currentUser.balance + 1e-6,
        overMax: bet > betMax("slots"),
        underMin: bet > 0 && bet < betMin("slots")
    };
}

function updateSlotsStartState() {
    const btn = document.getElementById("slotsStartBtn");
    if (btn) {
        const ready = !slotsBusy && betsAccepted && !!slotsSelectedOutcome;
        btn.classList.toggle("dim", !ready);
    }
    const outcomes = document.getElementById("slotsOutcomes");
    if (outcomes) outcomes.classList.toggle("bets-locked", !betsAccepted);

    const confirmBtn = document.getElementById("slotsBetConfirmBtn");
    if (confirmBtn) {
        const state = slotsReadyState();
        const confirmReady = !slotsBusy && betsAccepted && state.hasOutcome && state.hasBet && state.enoughBalance && !state.overMax && !state.underMin;
        confirmBtn.classList.toggle("dim", !confirmReady);
    }
}

