function slotsGameTypeOf(outcome) {
    if (outcome === "Дуэль") return "duel";
    if (SLOTS_EXTRA_TWO_THROW_OUTCOMES.has(outcome) || outcome.startsWith("Дуэль:")) return "extra2";
    if (SLOTS_EXTRA_THREE_THROW_OUTCOMES.has(outcome)) return "extra3";
    return "single";
}

function slotsLabelsFor(type) {
    if (type === "duel") return ["Ваши барабаны", "Барабаны бота"];
    if (type === "extra2") return ["Бросок 1", "Бросок 2"];
    if (type === "extra3") return ["Бросок 1", "Бросок 2", "Бросок 3"];
    return null;
}

const SLOT_PREVIEW_SYMBOL = {
    "3 Семёрки": "Семёрка",
    "3 Лимона": "Лимон",
    "3 Винограда": "Виноград",
    "3 Бара": "Бар"
};

function selectSlotsOutcome(outcome, tileEl) {
    if (!betsAccepted) return;
    slotsSelectedOutcome = outcome;
    loadEmojiQuote("slots", outcome).catch(() => {});
    slotsMoveBadgeToTitle();
    document.querySelectorAll("#slotsOutcomes .gv-outcome").forEach(b => b.classList.remove("selected"));
    if (tileEl) tileEl.classList.add("selected");
    slotsActiveType = slotsGameTypeOf(outcome);
    if (slotsActiveType === "duel" || slotsActiveType === "extra2" || slotsActiveType === "extra3") {
        setSlotsReels(null, false, true, slotsLabelsFor(slotsActiveType));
    } else {
        const sym = SLOT_PREVIEW_SYMBOL[outcome];
        setSlotsReels(sym ? {
            reels: [sym, sym, sym]
        } : null, false, true);
    }
    const extraBadge = slotsBadgeText(outcome);
    if (extraBadge) {
        const badge = document.getElementById("slotsMultBadge");
        if (badge) {
            badge.classList.remove("waiting");
            badge.textContent = extraBadge;
            badge.classList.add("show");
            badge.classList.remove("centered");
        }
    } else {
        updateMultBadge("slotsMultBadge", "slots", outcome, findTileMultText(SLOT_TILES, outcome, SLOT_SUBMENUS), slotsActiveType !== "single");
    }
    updateSlotsStartState();
}

