function resetSlotsUI() {
    slotsMode = "start";
    slotsSelectedOutcome = null;
    slotsActiveType = "single";
    closeSlotsBetModal();
    hideSlotsResult();
    setSlotsCheckLink(null);
    setSlotsReels(null);
    updateMultBadge("slotsMultBadge", "slots", null, null);
    slotsMoveBadgeToTitle();
    const outcomesEl = document.getElementById("slotsOutcomes");
    if (outcomesEl) {
        outcomesEl.querySelectorAll(".gv-outcome").forEach(tile => {
            tile.classList.remove("selected");
            if (tile.dataset.group) {
                const base = SLOT_TILES.find(t => t.group === tile.dataset.group);
                if (base) tile.textContent = base.label;
            }
        });
    }
    const panel = document.getElementById("slotsPanel");
    if (panel) panel.classList.remove("gv-collapsed");
    const btn = document.getElementById("slotsStartBtn");
    if (btn) {
        btn.style.display = "";
        btn.textContent = "Начать игру";
    }
    updateSlotsStartState();
}

function playSlots() {
    if (slotsBusy) return;
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const state = slotsReadyState();
    if (!state.hasOutcome) {
        showToast("Сначала выберите комбинацию ставки", "error");
        return;
    }
    if (!state.hasBet) {
        showToast("Введите сумму ставки", "error");
        return;
    }
    if (!state.enoughBalance) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    if (state.underMin) {
        showToast("Минимальная ставка — " + fmtNum(betMin("slots")) + "⭐️", "error");
        return;
    }
    if (state.overMax) {
        showToast("Максимальная ставка — " + fmtNum(betMax("slots")) + "⭐️", "error");
        return;
    }
    const bet = state.bet;
    const balanceBeforeBet = currentUser.balance;
    closeSlotsBetModal();
    slotsBusy = true;
    slotsMode = "rolling";
    hideSlotsResult();
    setSlotsCheckLink(null);
    setSlotsReels(null, true, false, slotsActiveType !== "single" ? slotsLabelsFor(slotsActiveType) : null);
    applyBalance(balanceBeforeBet - bet);
    const panel = document.getElementById("slotsPanel");
    const startBtn = document.getElementById("slotsStartBtn");
    if (panel) panel.classList.add("gv-collapsed");
    if (startBtn) startBtn.classList.add("gv-collapsed");
    (function() {
        var hl = document.getElementById("slotsHistoryList");
        if (hl) hl.classList.add("gv-history-full");
    })();
    const startedAt = Date.now();
    const finish = fn => {
        const wait = Math.max(0, SLOTS_MIN_SPIN_MS - (Date.now() - startedAt));
        setTimeout(fn, wait);
    };
    gamePlayFetch("/api/slots/play", {
        uid: CURRENT_UID,
        outcome: slotsSelectedOutcome,
        bet: bet
    }).then(ocOnPlay).then(data => finish(() => {
        slotsBusy = false;
        slotsMode = "again";
        if (!data || !data.ok) {
            setSlotsReels(null);
            applyBalance(balanceBeforeBet);
            resyncBalanceSoon();
            const msg = data && data.error || "Ошибка сервера";
            showSlotsResult("error", msg);
            showToast(msg, "error");
            if (startBtn) {
                startBtn.classList.remove("gv-collapsed");
                startBtn.textContent = "Создать новую игру";
            }
            (function() {
                var hl = document.getElementById("slotsHistoryList");
                if (hl) hl.classList.remove("gv-history-full");
            })();
            return;
        }
        slotsMoveBadgeToPhoto();
        setSlotsReels(data);
        gvLottieOnce("slotsReelsWrap");
        gvAfterResultAnim("slotsReelsWrap", () => {
            applyBalance(data.newBalance);
            setSlotsCheckLink(data.checkLink);
            const landed = slotsResultLandedHTML(data);
            if (data.isDraw) {
                showSlotsResult("draw", 'Ничья<span class="dr-sub">' + landed + "</span>");
                showToast("Ничья — возврат " + fmtNum(data.winAmount) + "⭐️", "warning");
            } else if (data.win) {
                showSlotsResult("win", "Выигрыш +" + fmtNum(data.winAmount) + '⭐️<span class="dr-sub">' + landed + "</span>");
                showGameWinToast(data.winAmount);
            } else if (data.refund > 0) {
                showSlotsResult("draw", "Возврат +" + fmtNum(data.refund) + "⭐️ из " + fmtNum(data.betAmount) + '⭐️<span class="dr-sub">' + landed + "</span>");
                showToast("Вернулось " + fmtNum(data.refund) + "⭐️ из " + fmtNum(data.betAmount) + "⭐️", "warning");
            } else {
                showSlotsResult("lose", "Проигрыш −" + fmtNum(data.betAmount) + '⭐️<span class="dr-sub">' + landed + "</span>");
            }
            if (startBtn) {
                startBtn.classList.remove("gv-collapsed");
                startBtn.textContent = "Создать новую игру";
            }
            (function() {
                var hl = document.getElementById("slotsHistoryList");
                if (hl) hl.classList.remove("gv-history-full");
            })();
            loadSlotsHistory();
        });
    })).catch(() => finish(() => {
        slotsBusy = false;
        slotsMode = "again";
        setSlotsReels(null);
        applyBalance(balanceBeforeBet);
        resyncBalanceSoon();
        showSlotsResult("error", "Не удалось связаться с сервером");
        showToast("Не удалось связаться с сервером", "error");
        if (startBtn) {
            startBtn.classList.remove("gv-collapsed");
            startBtn.textContent = "Создать новую игру";
        }
        (function() {
            var hl = document.getElementById("slotsHistoryList");
            if (hl) hl.classList.remove("gv-history-full");
        })();
    }));
}

let slotsPicker = null;

function sxExactMult(rows) {
    let p = 1;
    for (const sel of rows) {
        const k = sel.length ? sel.length : 4;
        p *= k / 4;
    }
    if (p <= 0) return 64;
    return Math.round((1 / p) * 100) / 100;
}

function sxComboOrderings(picks) {
    const counts = {};
    picks.forEach(v => counts[v] = (counts[v] || 0) + 1);
    const best = Math.max(...Object.values(counts));
    if (best === 3) return 1;
    if (best === 2) return 3;
    return 6;
}

function sxComboMult(picks) {
    if (picks.length !== 3) return null;
    return Math.round((64 / sxComboOrderings(picks)) * 100) / 100;
}

const SLOTS_DUEL_SELF_MULT = {
    "<": 3.2,
    ">": 3.2,
    "=": 5.05
};

function sxFmtNum(n) {
    return (Math.round(n * 100) / 100).toString();
}

function slotsPickerTitle(kind) {
    return {
        exact: "Своя комбинация — 3 барабана",
        combo: "Комбинация — 3 символа",
        duel2: "Дуэль — символ и исход сравнения",
        count: "Точный исход — символ и число выпадений",
        ladder: "Лесенка — один бросок",
        piggy: "Копилка — один бросок",
        lucky: "Лаки 7 — два броска"
    }[kind] || "Выберите исход";
}

function openSlotsPickerModal(kind, group) {
    slotsPicker = {
        kind,
        group
    };
    if (kind === "exact") slotsPicker.rows = [
        [],
        [],
        []
    ];
    else if (kind === "combo") slotsPicker.picks = [];
    else if (kind === "count") {
        slotsPicker.sym = null;
        slotsPicker.cnt = null;
    }
    document.getElementById("slotsSubTitle").textContent = slotsPickerTitle(kind);
    const textEl = document.getElementById("slotsSubText");
    textEl.textContent = "";
    textEl.style.display = "none";
    document.getElementById("slotsSubOptions").style.display = "none";
    document.getElementById("slotsPickerWrap").style.display = "";
    renderSlotsPicker();
}

function closeSlotsPickerModal() {
    slotsPicker = null;
    const wrap = document.getElementById("slotsPickerWrap");
    if (wrap) wrap.style.display = "none";
    const opts = document.getElementById("slotsSubOptions");
    if (opts) opts.style.display = "";
}

function slotSymbolBtnHTML(sym, selected, attrs) {
    return '<button class="dice-picker-face' + (selected ? " selected" : "") + '" type="button" ' + attrs + '><img src="' + CAPTCHA_SYMBOL_URLS[sym] + '" alt="' + sym + '"></button>';
}

function slotsPickerFooterHTML(playLabel, playDisabled) {
    return '<div class="dice-picker-footer-row">' + '<button class="dice-picker-tool-btn" type="button" data-sxaction="reset"><img src="' + DICE_PICKER_RESET_ICON + '" alt="">Сбросить</button>' + '<button class="dice-picker-tool-btn" type="button" data-sxaction="random"><img src="' + DICE_PICKER_RANDOM_ICON + '" alt="">Рандомно</button>' + "</div>" + '<button class="dice-modal-opt wide' + (playDisabled ? " dim" : "") + '" type="button" data-sxaction="done">' + playLabel + "</button>";
}

function slotsPayInfoHTML(kind) {
    const pt = slotsPaytables()[kind] || SLOTS_PAY_DEFAULT[kind];
    let cells;
    let hint;
    if (kind === "lucky") {
        cells = Object.keys(pt.table).sort().map(n => {
            const m = Number(pt.table[n]);
            return '<div class="dice-ladder-cell ' + (m > 1 ? "win" : m > 0 ? "back" : "zero") + '"><span class="tx-ladder-name">' + n + (Number(n) < 5 ? " семёрки" : " семёрок") + "</span><b>x" + fmtCoef(m) + "</b><small>" + (m > 1 ? "выигрыш" : m > 0 ? "возврат" : "проигрыш") + "</small></div>";
        });
        hint = "Множитель зависит от числа семёрок на шести барабанах двух вращений. Меньше трёх семёрок — ставка проигрывается.";
    } else {
        cells = SLOTS_SYMBOL_PAY_ORDER.map(sym => {
            const m = Number(pt.table[sym]);
            const cls = kind === "ladder" ? (m > 1 ? "win" : m > 0 ? "back" : "zero") : "back";
            const note = kind === "ladder" ? (m > 1 ? "выигрыш" : m > 0 ? "возврат" : "проигрыш") : "за барабан";
            return '<div class="dice-ladder-cell ' + cls + '"><img src="' + CAPTCHA_SYMBOL_URLS[sym] + '" alt="' + escapeHtml(sym) + '"><b>x' + fmtCoef(m) + "</b><small>" + note + "</small></div>";
        });
        hint = kind === "ladder" ? "Выплата только за тройку одинаковых символов, без тройки ставка проигрывается. Ниже x1 возвращается только часть ставки, выше x1 — выигрыш." : "Выигрыш равен сумме множителей трёх выпавших символов (максимум x" + fmtCoef(Number(pt.max)) + "). Ниже x1 возвращается только часть ставки, выше x1 — выигрыш.";
    }
    return '<div class="dice-ladder-grid four">' + cells.join("") + "</div>" + '<div class="dice-picker-hint">' + hint + "</div>" +
        '<button class="dice-modal-opt wide" type="button" data-sxaction="done">Играть (до x' + fmtCoef(Number(pt.max)) + ")</button>";
}

function renderSlotsPicker() {
    const wrap = document.getElementById("slotsPickerWrap");
    const p = slotsPicker;
    if (!p || !wrap) return;
    if (p.kind === "ladder" || p.kind === "piggy" || p.kind === "lucky") {
        wrap.innerHTML = slotsPayInfoHTML(p.kind);
        return;
    }
    if (p.kind === "count") {
        const ready = !!(p.sym && p.cnt);
        let countHtml = '<div class="dice-picker-hint">Выберите символ и сколько раз он выпадет на трёх барабанах. Выигрыш — только если символ выпадет ровно столько раз.</div>';
        countHtml += '<div class="dice-picker-grid four-col">' + SLOTS_SYMBOLS_ORDER.map(sym => slotSymbolBtnHTML(sym, p.sym === sym, 'data-sxcsym="' + sym + '"')).join("") + "</div>";
        countHtml += '<div class="dice-modal-options grid">' + [1, 2].map(k => '<button class="dice-modal-opt' + (p.cnt === k ? " tx-on" : "") + '" type="button" data-sxcnt="' + k + '">' + k + (k === 1 ? " раз" : " раза") + " (x" + fmtCoef(slotsCountMult(k)) + ")</button>").join("") + "</div>";
        countHtml += slotsPickerFooterHTML(ready ? "Играть (x" + fmtCoef(slotsCountMult(p.cnt)) + ")" : "Играть", !ready);
        wrap.innerHTML = countHtml;
        return;
    }

    if (p.kind === "exact") {
        const mult = sxExactMult(p.rows);
        let html = '<div class="dice-picker-hint">Не выбранный барабан — любой символ. Выигрыш, если каждый барабан совпал с выбором. Чем меньше символов выбрано, тем выше коэффициент.</div>';
        p.rows.forEach((sel, reelIdx) => {
            html += '<div class="dice-picker-row-label">Барабан ' + (reelIdx + 1) + (sel.length ? ": " + sel.join(", ") : ": любой символ") + "</div>";
            html += '<div class="dice-picker-grid four-col">' + SLOTS_SYMBOLS_ORDER.map(sym => slotSymbolBtnHTML(sym, sel.includes(sym), 'data-sxreel="' + reelIdx + '" data-sxval="' + sym + '"')).join("") + "</div>";
        });
        const tooWide = mult > 64 + 1e-9;
        html += slotsPickerFooterHTML("Играть (x" + sxFmtNum(famApply("slots", "Точный исход", mult)) + ")", tooWide);
        wrap.innerHTML = html;
    } else if (p.kind === "combo") {
        const counts = {};
        p.picks.forEach(v => counts[v] = (counts[v] || 0) + 1);
        const mult = sxComboMult(p.picks);
        let html = '<div class="dice-picker-hint">Выберите ровно 3 символа (повторы разрешены). Выбрано (' + p.picks.length + "/3): " + (p.picks.length ? p.picks.join(", ") : "—") + "</div>";
        html += '<div class="dice-picker-grid four-col">' + SLOTS_SYMBOLS_ORDER.map(sym => slotSymbolBtnHTML(sym, !!counts[sym], 'data-sxval="' + sym + '"')).join("") + "</div>";
        html += slotsPickerFooterHTML(mult ? "Играть (x" + sxFmtNum(famApply("slots", "Комбинация", mult)) + ")" : "Играть", p.picks.length !== 3);
        wrap.innerHTML = html;
    } else if (p.kind === "duel2") {
        let html = '<div class="dice-picker-hint">Сравниваем силу комбинации 1-го и 2-го броска (тройка > пара > без пары, при равенстве — по редкости символа: Семёрка > Лимон > Виноград > Бар). «‹» — 2-й бросок сильнее на выбранном символе, «›» — 1-й сильнее, «=» — броски равны.</div>';
        html += '<div class="dice-picker-duel-rows">' + SLOTS_SYMBOLS_ORDER.map(sym => (
            '<div class="dice-picker-duel-row">' +
            '<img class="slot-symbol-icon" src="' + CAPTCHA_SYMBOL_URLS[sym] + '" alt="">' + [
                ["<", "‹ (x" + sxFmtNum((LIVE_DUEL.slots || SLOTS_DUEL_SELF_MULT)["<"]) + ")"],
                ["=", "= (x" + sxFmtNum((LIVE_DUEL.slots || SLOTS_DUEL_SELF_MULT)["="]) + ")"],
                [">", "› (x" + sxFmtNum((LIVE_DUEL.slots || SLOTS_DUEL_SELF_MULT)[">"]) + ")"]
            ].map(([op, label]) => (
                '<button class="dice-modal-opt" type="button" data-sxduel-symbol="' + sym + '" data-sxduel-op="' + op + '">' + label + "</button>"
            )).join("") +
            "</div>"
        )).join("") + "</div>";
        wrap.innerHTML = html;
        wrap.querySelectorAll("[data-sxduel-op]").forEach(b => {
            if (ocOff("slots", "Дуэль:" + b.dataset.sxduelSymbol + ":" + b.dataset.sxduelOp)) b.remove();
        });
        wrap.querySelectorAll(".dice-picker-duel-row").forEach(r => {
            if (!r.querySelector("[data-sxduel-op]")) r.remove();
        });
    }
}

function slotsTileText(kind) {
    return {
        exact: "Своя комбинация",
        combo: "Комбинация",
        count: "Точный исход",
        ladder: "Лесенка",
        piggy: "Копилка",
        lucky: "Лаки 7"
    }[kind] || slotsPickerTitle(kind);
}

function slotsHandlePickerClick(e) {
    const p = slotsPicker;
    if (!p) return;
    if (p.kind === "count") {
        const symBtn = e.target.closest("[data-sxcsym]");
        if (symBtn) {
            p.sym = symBtn.dataset.sxcsym;
            renderSlotsPicker();
            return;
        }
        const cntBtn = e.target.closest("[data-sxcnt]");
        if (cntBtn) {
            p.cnt = parseInt(cntBtn.dataset.sxcnt, 10);
            renderSlotsPicker();
            return;
        }
    }
    const duelBtn = e.target.closest("[data-sxduel-symbol]");
    if (duelBtn && p.kind === "duel2") {
        const outcome = "Дуэль:" + duelBtn.dataset.sxduelSymbol + ":" + duelBtn.dataset.sxduelOp;
        const group = p.group;
        const tile = document.querySelector('#slotsOutcomes .gv-outcome[data-group="' + group + '"]');
        if (tile) {
            const baseLabel = SLOT_TILES.find(t => t.group === group).label;
            tile.textContent = baseLabel + ": Дуэль (" + duelBtn.dataset.sxduelSymbol + " " + duelBtn.dataset.sxduelOp + ")";
        }
        closeSlotsPickerModal();
        selectSlotsOutcome(outcome, tile);
        closeSlotsSubModal();
        return;
    }
    const faceBtn = e.target.closest(".dice-picker-face");
    if (faceBtn && p.kind === "exact") {
        const reelIdx = parseInt(faceBtn.dataset.sxreel, 10);
        const val = faceBtn.dataset.sxval;
        const sel = p.rows[reelIdx];
        const i = sel.indexOf(val);
        if (i >= 0) sel.splice(i, 1);
        else if (sel.length < 3) sel.push(val);
        renderSlotsPicker();
        return;
    }
    if (faceBtn && p.kind === "combo") {
        const val = faceBtn.dataset.sxval;
        if (p.picks.length < 3) p.picks.push(val);
        else p.picks = [val];
        renderSlotsPicker();
        return;
    }
    const actionBtn = e.target.closest("[data-sxaction]");
    if (!actionBtn) return;
    const action = actionBtn.dataset.sxaction;
    if (action === "reset") {
        if (p.kind === "exact") p.rows = p.rows.map(() => []);
        else if (p.kind === "combo") p.picks = [];
        else if (p.kind === "count") {
            p.sym = null;
            p.cnt = null;
        }
        renderSlotsPicker();
        return;
    }
    if (action === "random") {
        if (p.kind === "count") {
            p.sym = SLOTS_SYMBOLS_ORDER[Math.floor(Math.random() * SLOTS_SYMBOLS_ORDER.length)];
            p.cnt = 1 + Math.floor(Math.random() * 2);
        } else if (p.kind === "exact") {
            p.rows = p.rows.map(() => {
                const count = 1 + Math.floor(Math.random() * 3);
                const pool = SLOTS_SYMBOLS_ORDER.slice().sort(() => Math.random() - 0.5);
                return pool.slice(0, count);
            });
        } else if (p.kind === "combo") {
            p.picks = [1, 2, 3].map(() => SLOTS_SYMBOLS_ORDER[Math.floor(Math.random() * SLOTS_SYMBOLS_ORDER.length)]);
        }
        renderSlotsPicker();
        return;
    }
    if (action === "done") {
        let outcome = null;
        if (p.kind === "exact") {
            if (!p.rows.some(r => r.length)) {
                showToast("Выберите хотя бы один символ", "error");
                return;
            }
            const mult = sxExactMult(p.rows);
            if (mult > 64 + 1e-9) {
                showToast("Слишком узкий выбор — максимальный коэффициент x64", "error");
                return;
            }
            outcome = "Точный исход:" + p.rows.map(r => r.join(",")).join("|");
        } else if (p.kind === "combo") {
            if (p.picks.length !== 3) {
                showToast("Выберите ровно 3 символа", "error");
                return;
            }
            outcome = "Комбинация:" + p.picks.join(",");
        } else if (p.kind === "count") {
            if (!p.sym || !p.cnt) {
                showToast("Выберите символ и сколько раз он выпадет", "error");
                return;
            }
            outcome = "Кол-во:" + p.sym + ":" + p.cnt;
        } else if (SLOTS_PAY_OUTCOME[p.kind]) {
            outcome = SLOTS_PAY_OUTCOME[p.kind];
            if (ocOff("slots", outcome)) {
                showToast("Этот исход временно недоступен", "error");
                return;
            }
        }
        if (!outcome) return;
        const group = p.group;
        const tile = document.querySelector('#slotsOutcomes .gv-outcome[data-group="' + group + '"]');
        if (tile) {
            const baseLabel = SLOT_TILES.find(t => t.group === group).label;
            tile.textContent = baseLabel + ": " + slotsTileText(p.kind);
        }
        closeSlotsPickerModal();
        selectSlotsOutcome(outcome, tile);
        closeSlotsSubModal();
    }
}

