function openDartsBetModal() {
    if (!dartsSelectedOutcome) {
        showToast("Сначала выберите исход ставки", "error");
        return;
    }
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const modal = document.getElementById("dartsBetModal");
    if (modal) modal.classList.add("active");
    updateDartsStartState();
}

function closeDartsBetModal() {
    const modal = document.getElementById("dartsBetModal");
    if (modal) modal.classList.remove("active");
}

let dartsSelectedOutcome = null;

let dartsBusy = false;

let dartsMode = "start";

let dartsActiveType = "single";

function dartsReadyState() {
    const betInput = gvBody.querySelector(".gv-bet-input");
    const bet = betInput ? parseFloat(betInput.value) : NaN;
    return {
        bet: bet,
        hasOutcome: !!dartsSelectedOutcome,
        hasBet: bet > 0,
        enoughBalance: bet > 0 && bet <= currentUser.balance + 1e-6,
        overMax: bet > betMax("darts"),
        underMin: bet > 0 && bet < betMin("darts")
    };
}

function updateDartsStartState() {
    const btn = document.getElementById("dartsStartBtn");
    if (btn) {
        const ready = !dartsBusy && betsAccepted && !!dartsSelectedOutcome;
        btn.classList.toggle("dim", !ready);
    }
    const outcomes = document.getElementById("dartsOutcomes");
    if (outcomes) outcomes.classList.toggle("bets-locked", !betsAccepted);

    const confirmBtn = document.getElementById("dartsBetConfirmBtn");
    if (confirmBtn) {
        const state = dartsReadyState();
        const confirmReady = !dartsBusy && betsAccepted && state.hasOutcome && state.hasBet && state.enoughBalance && !state.overMax && !state.underMin;
        confirmBtn.classList.toggle("dim", !confirmReady);
    }
}

function openDartsSubModal(group) {
    const menu = DARTS_SUBMENUS[group];
    if (!menu) return;
    document.getElementById("dartsSubTitle").textContent = menu.title;
    const textEl = document.getElementById("dartsSubText");
    textEl.textContent = menu.text || "";
    textEl.style.display = menu.text ? "" : "none";
    const wrap = document.getElementById("dartsSubOptions");
    wrap.className = "dice-modal-options" + (menu.grid ? " grid" : "");
    txReset("darts");
    wrap.innerHTML = ocOptions("darts", menu.options, DARTS_SUBMENUS).map(o => {
        if (o.picker) return txOptionHTML("darts", o, group);
        const attr = o.nav ? ' data-nav="' + o.nav + '"' : ' data-outcome="' + o.outcome + '"';
        const coefHTML = o.nav ? '<span class="tile-coef">' + o.multText + "</span>" : coefSpanHTML("darts", o.outcome, o.multText);
        return '<button class="dice-modal-opt' + (o.wide ? " wide" : "") + '" type="button"' + attr + ' data-group="' + group + '">' + o.baseLabel + " (x" + coefHTML + ")" + "</button>";
    }).join("");
    document.getElementById("dartsSubModal").classList.add("active");
}

function closeDartsSubModal() {
    document.getElementById("dartsSubModal").classList.remove("active");
}

function dartsGameTypeOf(outcome) {
    if (outcome === "Дуэль") return "duel";
    if (DARTS_EXTRA_THREE_THROW_OUTCOMES.has(outcome)) return "extra3";
    if (DARTS_EXTRA_TWO_THROW_OUTCOMES.has(outcome)) return "extra2";
    return "single";
}

function dartsLabelsFor(type) {
    if (type === "duel") return ["Игрок", "Бот"];
    if (type === "extra2") return ["Дротик 1", "Дротик 2"];
    if (type === "extra3") return ["Дротик 1", "Дротик 2", "Дротик 3"];
    return null;
}

const DARTS_PREVIEW_VALUES = {
    "Центр": [6],
    "Промах": [1],
    "Сектор 1 🔴": [2],
    "Сектор 1 ⚪️": [3],
    "Сектор 2 🔴": [4],
    "Сектор 2 ⚪️": [5],
    "Любой белый сектор": [3, 5],
    "Сектор или Центр": [2, 4, 6],
    "Любой сектор": [2, 3, 4, 5]
};

function selectDartsOutcome(outcome, tileEl) {
    if (!betsAccepted) return;
    dartsSelectedOutcome = outcome;
    loadEmojiQuote("darts", outcome).catch(() => {});
    dartsMoveBadgeToTitle();
    document.querySelectorAll("#dartsOutcomes .gv-outcome").forEach(b => b.classList.remove("selected"));
    if (tileEl) tileEl.classList.add("selected");
    dartsActiveType = dartsGameTypeOf(outcome);
    if (currentUser.liteUiEnabled) {
        setDartsRings(null, outcome);
    } else if (dartsActiveType === "duel") {
        setDartsRings(randDuelPreview(), outcome);
    } else if (dartsActiveType === "extra2" || dartsActiveType === "extra3") {
        setDartsRings(null, outcome);
    } else {
        const preview = randomPreviewValue(DARTS_PREVIEW_VALUES, outcome);
        setDartsRings(preview ? [preview] : null, outcome);
    }
    updateMultBadge("dartsMultBadge", "darts", outcome, findTileMultText(DARTS_TILES, outcome, DARTS_SUBMENUS) || txOutcomeMultText("darts", outcome), dartsIsPairOutcome(outcome));
    updateDartsStartState();
}

function showDartsResult(cls, html) {
    const el = document.getElementById("dartsResult");
    if (!el) return;
    el.className = "dice-result show " + cls;
    el.innerHTML = html;
}

function hideDartsResult() {
    const el = document.getElementById("dartsResult");
    if (el) el.className = "dice-result";
}

function dartsRingUrl(value) {
    return DARTS_RING_URLS[value] || DARTS_IDLE_URL;
}

function dartsPairLabels(outcome) {
    return dartsLabelsFor(dartsGameTypeOf(outcome)) || ["Игрок", "Бот"];
}

function dartsIsPairOutcome(outcome) {
    const t = dartsGameTypeOf(outcome);
    return t === "duel" || t === "extra2" || t === "extra3";
}

function setDartsRings(values, outcomeForLabels) {
    const wrap = document.getElementById("dartsImgWrap");
    if (!wrap) return;
    clearGvWaiting("dartsImgWrap");
    if (!values || !values.length) {
        if (dartsIsPairOutcome(outcomeForLabels)) {
            const idleLabels = dartsPairLabels(outcomeForLabels);
            wrap.className = "dice-img-wrap pair";
            wrap.innerHTML = idleLabels.length > 2 ? txMultiHTML(idleLabels.map(() => dartsIdleSrc()), idleLabels) : dicePairHTML([dartsIdleSrc(), dartsIdleSrc()], idleLabels);
            return;
        }
        wrap.className = "dice-img-wrap";
        wrap.innerHTML = '<span class="img-frame"><div class="skel-box"></div>' + lazyImgTag(dartsIdleSrc(), "Дартс", "dice-img") + "</span>";
        return;
    }
    if (values.length === 1) {
        wrap.className = "dice-img-wrap";
        wrap.innerHTML = '<span class="img-frame"><div class="skel-box"></div>' + lazyImgTag(dartsRingUrl(values[0]), "Дартс", "dice-img") + "</span>";
    } else if (values.length === 2) {
        wrap.className = "dice-img-wrap pair";
        wrap.innerHTML = dicePairHTML([dartsRingUrl(values[0]), dartsRingUrl(values[1])], dartsPairLabels(outcomeForLabels));
    } else {
        wrap.className = "dice-img-wrap pair";
        wrap.innerHTML = txMultiHTML(values.map(dartsRingUrl), dartsPairLabels(outcomeForLabels));
    }
}

function loadDartsHistory(append) {
    gvHistoryLoad("dartsHistoryList", off => emojiHistoryUrl("дартс", "&offset=" + off), 12, (rows, append) => {
        const startIdx = append ? (EMOJI_HISTORY_CACHE["дартс"] || []).length : 0;
        EMOJI_HISTORY_CACHE["дартс"] = append ? (EMOJI_HISTORY_CACHE["дартс"] || []).concat(rows) : rows.slice();
        const html = rows.map((r, i) => emojiHistoryRowHTML("дартс", r, startIdx + i, "Дартс")).join("");
        const list = document.getElementById("dartsHistoryList");
        if (append) list.insertAdjacentHTML("beforeend", html);
        else list.innerHTML = html;
    }, GV_HISTORY_EMPTY_HTML, append);
}

GV_HISTORY_BY_GAME["дартс"] = {
    listId: "dartsHistoryList",
    load: () => loadDartsHistory(true)
};

let dartsQueueTimer = null;

function renderDartsQueue(items) {
    const el = document.getElementById("dartsQueue");
    if (!el) return;
    if (!items || !items.length) {
        el.style.display = "none";
        el.innerHTML = "";
        return;
    }
    el.style.display = "";
    el.innerHTML = '<div class="dice-queue-title">' + lazyImgTag(liteAsset("/lottie/images/ОгоньЭмоджи.lottie"), "", "flame-gif") + " Очередь ставок (" + items.length + ")</div>" + items.map(it => '<div class="dice-queue-row"><span>' + escapeHtml(it.userName || "Игрок") + "</span><b>" + fmtNum(it.betAmount) + "⭐️" + (it.outcome ? " · " + emojiOutcomeDisplayHTML("дартс", it.outcome) : "") + "</b></div>").join("");
}

function loadDartsQueue() {
    fetch("/api/games/queue").then(r => r.json()).then(data => {
        if (!data || !data.ok) return;
        renderDartsQueue(data.items || []);
    }).catch(() => {});
}

function startDartsQueuePolling() {
    loadDartsQueue();
    stopDartsQueuePolling();
    dartsQueueTimer = setInterval(loadDartsQueue, 4e3);
}

function stopDartsQueuePolling() {
    if (dartsQueueTimer) {
        clearInterval(dartsQueueTimer);
        dartsQueueTimer = null;
    }
}

const DARTS_MIN_SPIN_MS = 2600;

function setDartsCheckLink(url) {
    const el = document.getElementById("dartsCheckLink");
    if (!el) return;
    if (url) {
        el.href = url;
        el.style.display = "";
    } else {
        el.style.display = "none";
    }
}

function dartsMoveBadgeToTitle() {
    const slot = document.getElementById("dartsMultBadgeTitleSlot");
    const badge = document.getElementById("dartsMultBadge");
    if (slot && badge && badge.parentElement !== slot) slot.appendChild(badge);
}

function dartsMoveBadgeToPhoto() {
    const badge = document.getElementById("dartsMultBadge");
    const imgWrap = document.getElementById("dartsImgWrap");
    if (badge && imgWrap && badge.parentElement !== imgWrap.parentElement) {
        imgWrap.parentElement.insertBefore(badge, imgWrap);
    }
}

function resetDartsUI() {
    dartsMode = "start";
    dartsSelectedOutcome = null;
    dartsActiveType = "single";
    closeDartsBetModal();
    hideDartsResult();
    setDartsCheckLink(null);
    setDartsRings(null);
    updateMultBadge("dartsMultBadge", "darts", null, null);
    dartsMoveBadgeToTitle();
    const outcomesEl = document.getElementById("dartsOutcomes");
    if (outcomesEl) {
        outcomesEl.querySelectorAll(".gv-outcome").forEach(tile => {
            tile.classList.remove("selected");
            if (tile.dataset.group) {
                const base = DARTS_TILES.find(t => t.group === tile.dataset.group);
                if (base) tile.textContent = base.label;
            }
        });
    }
    const panel = document.getElementById("dartsPanel");
    if (panel) panel.classList.remove("gv-collapsed");
    const btn = document.getElementById("dartsStartBtn");
    if (btn) {
        btn.style.display = "";
        btn.textContent = "Начать игру";
    }
    updateDartsStartState();
}

function playDarts() {
    if (dartsBusy) return;
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const state = dartsReadyState();
    if (!state.hasOutcome) {
        showToast("Сначала выберите исход ставки", "error");
        return;
    }
    if (!state.hasBet) {
        showToast("Введите сумму ставки", "error");
        return;
    }
    if (!state.enoughBalance) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    if (state.underMin) {
        showToast("Минимальная ставка — " + fmtNum(betMin("darts")) + "⭐️", "error");
        return;
    }
    if (state.overMax) {
        showToast("Максимальная ставка — " + fmtNum(betMax("darts")) + "⭐️", "error");
        return;
    }
    const bet = state.bet;
    const outcome = dartsSelectedOutcome;
    const balanceBeforeBet = currentUser.balance;
    closeDartsBetModal();
    dartsBusy = true;
    dartsMode = "rolling";
    hideDartsResult();
    setDartsCheckLink(null);
    showGvWaiting("dartsImgWrap", dartsIsPairOutcome(outcome), "dartsMultBadge", dartsPairLabels(outcome));
    applyBalance(balanceBeforeBet - bet);
    const panel = document.getElementById("dartsPanel");
    const startBtn = document.getElementById("dartsStartBtn");
    if (panel) panel.classList.add("gv-collapsed");
    if (startBtn) startBtn.classList.add("gv-collapsed");
    (function() {
        var hl = document.getElementById("dartsHistoryList");
        if (hl) hl.classList.add("gv-history-full");
    })();
    const startedAt = Date.now();
    const finish = fn => {
        const wait = Math.max(0, DARTS_MIN_SPIN_MS - (Date.now() - startedAt));
        setTimeout(fn, wait);
    };
    gamePlayFetch("/api/darts/play", {
        uid: CURRENT_UID,
        outcome: outcome,
        bet: bet
    }).then(ocOnPlay).then(data => finish(() => {
        dartsBusy = false;
        dartsMode = "again";
        if (!data || !data.ok) {
            setDartsRings(null, outcome);
            applyBalance(balanceBeforeBet);
            resyncBalanceSoon();
            const msg = data && data.error || "Ошибка сервера";
            showDartsResult("error", msg);
            showToast(msg, "error");
            if (startBtn) {
                startBtn.classList.remove("gv-collapsed");
                startBtn.textContent = "Создать новую игру";
            }
            (function() {
                var hl = document.getElementById("dartsHistoryList");
                if (hl) hl.classList.remove("gv-history-full");
            })();
            return;
        }
        dartsMoveBadgeToPhoto();
        setDartsRings(data.values, outcome);
        gvLottieOnce("dartsImgWrap");
        gvAfterResultAnim("dartsImgWrap", () => {
            applyBalance(data.newBalance);
            setDartsCheckLink(data.checkLink);
            if (data.isDraw) {
                showDartsResult("draw", 'Ничья<span class="dr-sub">' + data.details + "</span>");
                showToast("Ничья — возврат " + fmtNum(data.winAmount) + "⭐️", "warning");
            } else if (data.refund > 0) {
                showDartsResult("draw", "Возврат +" + fmtNum(data.refund) + "⭐️ из " + fmtNum(data.betAmount) + '⭐️<span class="dr-sub">' + data.details + "</span>");
                showToast("Вернулось " + fmtNum(data.refund) + "⭐️ из " + fmtNum(data.betAmount) + "⭐️", "warning");
            } else if (data.win) {
                showDartsResult("win", "Выигрыш +" + fmtNum(data.winAmount) + '⭐️<span class="dr-sub">' + data.details + "</span>");
                showGameWinToast(data.winAmount);
            } else {
                showDartsResult("lose", "Проигрыш −" + fmtNum(data.betAmount) + '⭐️<span class="dr-sub">' + data.details + "</span>");
            }
            if (startBtn) {
                startBtn.classList.remove("gv-collapsed");
                startBtn.textContent = "Создать новую игру";
            }
            (function() {
                var hl = document.getElementById("dartsHistoryList");
                if (hl) hl.classList.remove("gv-history-full");
            })();
            loadDartsHistory();
        });
    })).catch(() => finish(() => {
        dartsBusy = false;
        dartsMode = "again";
        setDartsRings(null, outcome);
        applyBalance(balanceBeforeBet);
        resyncBalanceSoon();
        showDartsResult("error", "Не удалось связаться с сервером");
        showToast("Не удалось связаться с сервером", "error");
        if (startBtn) {
            startBtn.classList.remove("gv-collapsed");
            startBtn.textContent = "Создать новую игру";
        }
        (function() {
            var hl = document.getElementById("dartsHistoryList");
            if (hl) hl.classList.remove("gv-history-full");
        })();
    }));
}

