const TX_GAME_BY_KEY = {
    "футбол": "foot",
    "баскетбол": "basket",
    "боулинг": "bowl",
    "дартс": "darts"
};

let txPicker = null;

function txLadderTable(game) {
    const cfg = TX_GAMES[game];
    const live = (LIVE_EXT[game] || {}).ladder;
    const out = {};
    cfg.faces.forEach(f => {
        let v = cfg.ladder[f];
        if (live && live.table && live.table[f] != null) v = Number(live.table[f]);
        out[f] = v;
    });
    return out;
}

function txLadderMax(game) {
    const t = txLadderTable(game);
    return Math.max.apply(null, TX_GAMES[game].faces.map(f => t[f]));
}

function txPickMult(game, count) {
    const live = (LIVE_EXT[game] || {}).pick;
    if (live && live[count] != null) return Number(live[count]);
    return famApply(game, "Выбор", Math.floor(TX_GAMES[game].n * 100 / count + 1e-9) / 100);
}

function txPickValues(outcome, game) {
    if (typeof outcome !== "string" || outcome.indexOf("Выбор:") !== 0) return null;
    const n = TX_GAMES[game].n;
    const list = outcome.slice("Выбор:".length).split(",").map(x => parseInt(x, 10)).filter(x => x >= 1 && x <= n);
    return list.length ? list : null;
}

function txOutcomeDisplayHTML(game, outcome) {
    const cfg = TX_GAMES[game];
    const vals = txPickValues(outcome, game);
    if (!vals) return escapeHtml(cfg.display && cfg.display[outcome] || outcome);
    return "Выбор: " + cfg.order.filter(v => vals.indexOf(v) >= 0).map(v => escapeHtml(cfg.names[v])).join(", ");
}

function txOutcomeMultText(game, outcome) {
    if (outcome === "Лесенка") return fmtCoef(txLadderMax(game));
    const vals = txPickValues(outcome, game);
    return vals ? fmtCoef(txPickMult(game, vals.length)) : null;
}

function txOptionHTML(game, o, group) {
    const cls = "dice-modal-opt" + (o.wide ? " wide" : "");
    if (o.picker) {
        const label = o.picker === "ladder" ? "Лесенка (до x" + fmtCoef(txLadderMax(game)) + ")" : "Выбор исходов (до x" + fmtCoef(txPickMult(game, 1)) + ")";
        return '<button class="' + cls + '" type="button" data-picker="' + o.picker + '" data-group="' + group + '">' + label + "</button>";
    }
    return '<button class="' + cls + '" type="button" data-outcome="' + o.outcome + '" data-group="' + group + '">' + o.baseLabel + " (x" + coefSpanHTML(game, o.outcome, o.multText) + ")" + "</button>";
}

function txMultiHTML(srcs, labels, extraClasses) {
    const slots = srcs.map((s, i) => '<div class="dice-slot"><div class="dice-slot-label">' + labels[i] + '</div><span class="img-frame"><div class="skel-box"></div>' + lazyImgTag(s, "", extraClasses && extraClasses[i] || "") + "</span></div>");
    return '<div class="dice-pair">' + slots.join('<div class="dice-divider"></div>') + "</div>";
}

function txWrap(game) {
    let wrap = document.getElementById(game + "PickerWrap");
    if (!wrap) {
        const opts = document.getElementById(TX_GAMES[game].optsId);
        if (!opts) return null;
        wrap = document.createElement("div");
        wrap.id = game + "PickerWrap";
        wrap.style.display = "none";
        opts.insertAdjacentElement("afterend", wrap);
        wrap.addEventListener("click", txHandleClick);
    }
    return wrap;
}

function txReset(game) {
    txPicker = null;
    const wrap = document.getElementById(game + "PickerWrap");
    if (wrap) wrap.style.display = "none";
    const opts = document.getElementById(TX_GAMES[game].optsId);
    if (opts) opts.style.display = "";
}

function openTxPicker(game, kind, group) {
    const cfg = TX_GAMES[game];
    const wrap = txWrap(game);
    if (!wrap) return;
    txPicker = {
        game: game,
        kind: kind,
        group: group,
        sel: []
    };
    document.getElementById(cfg.titleId).textContent = kind === "ladder" ? cfg.ladderTitle : "Выбор исходов";
    const textEl = document.getElementById(cfg.textId);
    textEl.textContent = "";
    textEl.style.display = "none";
    document.getElementById(cfg.optsId).style.display = "none";
    wrap.style.display = "";
    txRender();
}

function txRender() {
    const p = txPicker;
    if (!p) return;
    const wrap = document.getElementById(p.game + "PickerWrap");
    if (!wrap) return;
    const cfg = TX_GAMES[p.game];
    if (p.kind === "ladder") {
        const table = txLadderTable(p.game);
        const names = cfg.ladderNames || cfg.names;
        let html = '<div class="dice-ladder-grid">' + cfg.ladderOrder.map(f => {
            const m = table[f];
            const kind = m > 1 ? "win" : m > 0 ? "back" : "zero";
            const note = m > 1 ? "выигрыш" : m > 0 ? "возврат" : "проигрыш";
            return '<div class="dice-ladder-cell ' + kind + '"><span class="tx-ladder-name">' + escapeHtml(names[f]) + "</span><b>x" + fmtCoef(m) + "</b><small>" + note + "</small></div>";
        }).join("") + "</div>";
        html += '<div class="dice-picker-hint">' + cfg.ladderHint + "</div>";
        html += '<button class="dice-modal-opt wide" type="button" data-txaction="done">Играть (до x' + fmtCoef(txLadderMax(p.game)) + ")</button>";
        wrap.innerHTML = html;
        return;
    }
    const n = p.sel.length;
    const shown = cfg.order.filter(v => p.sel.indexOf(v) >= 0);
    let html = '<div class="dice-picker-hint">' + cfg.pickHint + "</div>";
    html += '<div class="dice-modal-options grid">' + cfg.order.map((v, i) => '<button class="dice-modal-opt' + (cfg.order.length % 2 && i === cfg.order.length - 1 ? " wide" : "") + (p.sel.indexOf(v) >= 0 ? " tx-on" : "") + '" type="button" data-txval="' + v + '">' + escapeHtml(cfg.names[v]) + "</button>").join("") + "</div>";
    html += '<div class="dice-picker-hint">' + (n ? "Выбрано (" + n + "): " + shown.map(v => escapeHtml(cfg.names[v])).join(", ") : "Выберите от 1 до " + cfg.pickMax + " исходов") + "</div>";
    html += '<div class="dice-picker-footer-row">' + '<button class="dice-picker-tool-btn" type="button" data-txaction="reset"><img src="' + DICE_PICKER_RESET_ICON + '" alt="">Сбросить</button>' + '<button class="dice-picker-tool-btn" type="button" data-txaction="random"><img src="' + DICE_PICKER_RANDOM_ICON + '" alt="">Рандомно</button>' + "</div>";
    html += '<button class="dice-modal-opt wide' + (n ? "" : " dim") + '" type="button" data-txaction="done">' + (n ? "Играть (x" + fmtCoef(txPickMult(p.game, n)) + ")" : "Играть") + "</button>";
    wrap.innerHTML = html;
}

function txHandleClick(e) {
    const p = txPicker;
    if (!p) return;
    const cfg = TX_GAMES[p.game];
    const valBtn = e.target.closest("[data-txval]");
    if (valBtn && p.kind === "pick") {
        const v = parseInt(valBtn.dataset.txval, 10);
        const at = p.sel.indexOf(v);
        if (at >= 0) p.sel.splice(at, 1);
        else if (p.sel.length >= cfg.pickMax) {
            showToast("Максимум " + cfg.pickMax + " исходов из " + cfg.n, "error");
            return;
        } else p.sel.push(v);
        txRender();
        return;
    }
    const act = e.target.closest("[data-txaction]");
    if (!act) return;
    const action = act.dataset.txaction;
    if (action === "reset") {
        p.sel = [];
        txRender();
        return;
    }
    if (action === "random") {
        const all = cfg.faces.slice();
        for (let i = all.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            const tmp = all[i];
            all[i] = all[j];
            all[j] = tmp;
        }
        p.sel = all.slice(0, 1 + Math.floor(Math.random() * cfg.pickMax));
        txRender();
        return;
    }
    if (action !== "done") return;
    let outcome;
    let tileText;
    if (p.kind === "ladder") {
        if (ocOff(p.game, "Лесенка")) {
            showToast("Этот исход временно недоступен", "error");
            return;
        }
        outcome = "Лесенка";
        tileText = "Лесенка";
    } else {
        if (!p.sel.length) {
            showToast("Выберите хотя бы один исход", "error");
            return;
        }
        outcome = "Выбор:" + p.sel.slice().sort((a, b) => a - b).join(",");
        tileText = "Выбор исходов (" + p.sel.length + ")";
    }
    const group = p.group;
    const game = p.game;
    const tile = document.querySelector("#" + cfg.boxId + ' .gv-outcome[data-group="' + group + '"]');
    if (tile) {
        const base = cfg.tiles().find(t => t.group === group);
        tile.textContent = (base ? base.label : "") + ": " + tileText;
    }
    txReset(game);
    cfg.select(outcome, tile);
    cfg.close();
}

