let kenoPicks = [];

let kenoBusy = false;

let kenoMode = "select";

let kenoHistoryScope = "all";

let kenoCurrentRoundInfo = null;

let kenoLastResult = null;

let kenoRisk = "medium";

let kenoTable = {};

const KENO_BOARD_SIZE = 40;

const KENO_MAX_PICKS = 10;

const KENO_RISK_LABELS = {
    low: "Низкий",
    medium: "Средний",
    high: "Высокий"
};

const KENO_RISK_ICONS = {
    low: "/ИграКено/НизкийРиск.png",
    medium: "/ИграКено/СреднийРиск.png",
    high: "/ИграКено/ВысокийРиск.png"
};

const KENO_REVEAL_MS = {
    normal: 120,
    fast: 55,
    turbo: 0
};

let kenoRevealSeq = 0;

function kenoEnsureBallDefs() {
    if (document.getElementById("kenoBallDefs")) return;
    const wrap = document.createElement("div");
    wrap.id = "kenoBallDefs";
    wrap.setAttribute("aria-hidden", "true");
    wrap.style.cssText = "position:absolute;width:0;height:0;overflow:hidden;pointer-events:none";
    wrap.innerHTML = '<svg width="0" height="0" focusable="false"><defs>' + '<radialGradient id="kbGrayBody" cx="36%" cy="30%" r="78%"><stop offset="0" stop-color="#8d98b3"/><stop offset=".42" stop-color="#4b5775"/><stop offset="1" stop-color="#1e2538"/></radialGradient>' + '<radialGradient id="kbBlueBody" cx="36%" cy="30%" r="78%"><stop offset="0" stop-color="#5a9bff"/><stop offset=".42" stop-color="#1d66f7"/><stop offset="1" stop-color="#0a36a6"/></radialGradient>' + '<radialGradient id="kbShine" cx="32%" cy="24%" r="38%"><stop offset="0" stop-color="#fff" stop-opacity=".6"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient>' + '<radialGradient id="kbRim" cx="50%" cy="50%" r="50%"><stop offset=".7" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".5"/></radialGradient>' + '<clipPath id="kbClip"><circle cx="50" cy="50" r="47"/></clipPath>' + "</defs></svg>";
    document.body.appendChild(wrap);
}

function kenoBallHTML(n, hit) {
    const body = hit ? "kbBlueBody" : "kbGrayBody";
    const patch = hit ? "#e3ecff" : "#cdd5e8";
    const sticker = hit ? "#e8efff" : "#dde3f1";
    const ink = hit ? "#2e62e8" : "#2a334a";
    const size = String(n).length > 1 ? 31 : 38;
    return '<svg class="keno-ball ' + (hit ? "hit" : "drawn") + '" viewBox="0 0 100 100" aria-hidden="true">' + '<circle cx="50" cy="50" r="47" fill="url(#' + body + ')"/>' + '<g clip-path="url(#kbClip)"><g class="kb-spin" fill="' + patch + '" opacity=".9">' + '<ellipse cx="20" cy="13" rx="27" ry="14" transform="rotate(-30 20 13)"/>' + '<ellipse cx="82" cy="88" rx="27" ry="14" transform="rotate(-30 82 88)"/>' + '<ellipse cx="95" cy="34" rx="9" ry="17" transform="rotate(12 95 34)"/>' + '<ellipse cx="5" cy="66" rx="9" ry="17" transform="rotate(12 5 66)"/>' + "</g></g>" + '<circle cx="50" cy="50" r="47" fill="url(#kbRim)"/>' + '<g class="kb-spin"><circle cx="50" cy="50" r="29" fill="' + sticker + '"/>' + '<text x="50" y="51" text-anchor="middle" dominant-baseline="central" font-family="inherit" font-weight="800" font-size="' + size + '" fill="' + ink + '">' + n + "</text></g>" + '<circle cx="50" cy="50" r="47" fill="url(#kbShine)"/>' + "</svg>";
}

function kenoMarkCell(n, state, still, stepMs) {
    const cell = document.querySelector('#kenoGrid .gv-keno-cell[data-num="' + n + '"]');
    if (!cell) return;
    kenoEnsureBallDefs();
    cell.style.setProperty("--kb-d", Math.max(.38, Math.min(.8, (stepMs || 120) * 5 / 1000)).toFixed(2) + "s");
    cell.classList.remove("selected", "miss");
    cell.classList.add(state, "has-ball");
    if (still) cell.classList.add("still");
    cell.innerHTML = kenoBallHTML(n, state === "hit");
}

function kenoRevealResult(data, stepMs, onDone) {
    const seq = ++kenoRevealSeq;
    const drawn = data.drawn || [];
    const picks = data.picks || [];
    const pickSet = new Set(picks);
    const finish = () => {
        if (seq !== kenoRevealSeq) return;
        picks.forEach(n => {
            if (drawn.indexOf(n) !== -1) return;
            const cell = document.querySelector('#kenoGrid .gv-keno-cell[data-num="' + n + '"]');
            if (cell) {
                cell.classList.remove("selected");
                cell.classList.add("miss");
            }
        });
        onDone();
    };
    if (!stepMs) {
        drawn.forEach(n => kenoMarkCell(n, pickSet.has(n) ? "hit" : "drawn", true));
        finish();
        return;
    }
    let i = 0;
    let hits = 0;
    const next = () => {
        if (seq !== kenoRevealSeq || !document.getElementById("kenoGrid")) return;
        if (i >= drawn.length) {
            finish();
            return;
        }
        const n = drawn[i++];
        const isHit = pickSet.has(n);
        kenoMarkCell(n, isHit ? "hit" : "drawn", false, stepMs);
        if (isHit) {
            hits++;
            haptic("impact", "light");
            updateKenoMultRow(hits);
        }
        setTimeout(next, stepMs);
    };
    next();
}

function kenoDeferBalance(data, stepMs) {
    if (typeof data.balance !== "number") return;
    setTimeout(() => applyBalance(data.balance), (data.drawn || []).length * stepMs + 180);
}

function kenoCellHTML(n) {
    return '<div class="gv-keno-cell" data-num="' + n + '">' + n + "</div>";
}

function kenoGridHTML() {
    let html = "";
    for (let n = 1; n <= KENO_BOARD_SIZE; n++) html += kenoCellHTML(n);
    return html;
}

function kenoRiskRowHTML() {
    return '<div class="mines-bomb-row" id="kenoRiskRow">' + Object.keys(KENO_RISK_LABELS).map(r => '<button class="mines-bomb-btn' + (r === kenoRisk ? " selected" : "") + '" type="button" data-keno-risk="' + r + '"><img class="keno-risk-icon" src="' + KENO_RISK_ICONS[r] + '" alt="">' + KENO_RISK_LABELS[r] + "</button>").join("") + "</div>";
}

function selectKenoRisk(risk) {
    if (!KENO_RISK_LABELS[risk] || kenoMode !== "select" || kenoRisk === risk) return;
    kenoRisk = risk;
    const row = document.getElementById("kenoRiskRow");
    if (row) row.querySelectorAll(".mines-bomb-btn").forEach(btn => btn.classList.toggle("selected", btn.dataset.kenoRisk === risk));
    fetchKenoTable();
}

function kenoMultRowHTML(highlightHits) {
    const picksCount = kenoPicks.length || (kenoLastResult ? kenoLastResult.picks.length : 0);
    if (!picksCount) return '<div class="gv-mult-chip now">Выберите числа</div>';
    let chips = "";
    for (let h = 0; h <= picksCount; h++) {
        const v = kenoTable[h];
        if (v === undefined) continue;
        chips += (h > 0 ? '<span class="gv-mult-arrow">›</span>' : "") + '<span class="gv-mult-chip' + (h === highlightHits ? " now" : "") + '">x' + fmtCoef(v) + "</span>";
    }
    return chips || '<div class="gv-mult-chip now">—</div>';
}

function updateKenoMultRow(highlightHits) {
    const row = document.getElementById("kenoMultRow");
    if (!row) return;
    row.innerHTML = kenoMultRowHTML(highlightHits);
    const now = row.querySelector(".gv-mult-chip.now");
    if (now) now.scrollIntoView({
        block: "nearest",
        inline: "center"
    });
}

function fetchKenoTable() {
    const picksCount = kenoPicks.length;
    if (!picksCount) {
        kenoTable = {};
        updateKenoMultRow();
        return Promise.resolve();
    }
    return fetch("/api/keno/paytable?risk=" + kenoRisk + "&picksCount=" + picksCount).then(r => r.json()).then(data => {
        if (!data || !data.ok) return;
        kenoTable = data.table || {};
        updateKenoMultRow(kenoMode === "result" && kenoLastResult ? kenoLastResult.hits : undefined);
    }).catch(() => {});
}

function setupKenoMultRowScroll(rowId) {
    const row = document.getElementById(rowId || "kenoMultRow");
    if (!row || row.dataset.dragWired) return;
    row.dataset.dragWired = "1";
    row.addEventListener("wheel", e => {
        if (Math.abs(e.deltaY) > Math.abs(e.deltaX)) {
            row.scrollLeft += e.deltaY;
            e.preventDefault();
        }
    }, {
        passive: false
    });
    let isDown = false,
        startX = 0,
        startScroll = 0,
        moved = false;
    row.addEventListener("pointerdown", e => {
        isDown = true;
        moved = false;
        startX = e.clientX;
        startScroll = row.scrollLeft;
    });
    row.addEventListener("pointermove", e => {
        if (!isDown) return;
        const dx = e.clientX - startX;
        if (Math.abs(dx) > 3) moved = true;
        row.scrollLeft = startScroll - dx;
    });
    const endDrag = () => {
        isDown = false;
    };
    row.addEventListener("pointerup", endDrag);
    row.addEventListener("pointerleave", endDrag);
    row.addEventListener("click", e => {
        if (moved) {
            e.stopPropagation();
            moved = false;
        }
    }, true);
}

function kenoStatusHTML() {
    if (kenoMode === "result" && kenoLastResult) {
        const r = kenoLastResult;
        const outcomeHtml = r.win ? '<span class="gv-history-win">Выигрыш: ' + fmtNum(r.winAmount) + "⭐️ (x" + fmtCoef(r.multiplier) + ")</span>" : '<span class="gv-history-lose">Проигрыш</span>';
        return "Совпадений: <b>" + r.hits + " / " + r.picks.length + "</b> · " + outcomeHtml;
    }
    return "Выбрано чисел: <b>" + kenoPicks.length + " / " + KENO_MAX_PICKS + "</b>";
}

function updateKenoStatus() {
    const el = document.getElementById("kenoStatus");
    if (el) el.innerHTML = kenoStatusHTML();
}

function setKenoPanelLocked(locked) {
    const panel = document.getElementById("kenoPanel");
    if (panel) panel.classList.toggle("locked", locked);
    const riskPanel = document.getElementById("kenoRiskPanel");
    if (riskPanel) riskPanel.classList.toggle("locked", locked);
}

function setKenoStartBtn(mode) {
    const btn = document.getElementById("kenoStartBtn");
    if (!btn) return;
    if (mode === "play") btn.textContent = "Играть";
    else if (mode === "again") btn.textContent = "Создать новую игру";
}

function kenoReadyState() {
    const betInput = gvBody.querySelector(".gv-bet-input");
    const bet = betInput ? parseFloat(betInput.value) : NaN;
    return {
        bet: bet,
        hasBet: bet > 0,
        enoughBalance: bet > 0 && bet <= currentUser.balance + 1e-6,
        overMax: bet > betMax("keno"),
        underMin: bet > 0 && bet < betMin("keno"),
        validPicks: kenoPicks.length >= 1 && kenoPicks.length <= KENO_MAX_PICKS
    };
}

function updateKenoStartState() {
    const btn = document.getElementById("kenoStartBtn");
    if (!btn || kenoMode === "result") return;
    const state = kenoReadyState();
    const ready = !kenoBusy && betsAccepted && state.hasBet && state.enoughBalance && !state.overMax && !state.underMin && state.validPicks;
    btn.classList.toggle("dim", !ready);
}

function updateKenoRoundIdLabel() {
    const el = document.getElementById("kenoRoundIdLabel");
    if (!el) return;
    const roundId = kenoCurrentRoundInfo && kenoCurrentRoundInfo.roundId;
    if (roundId) {
        el.textContent = roundId;
        el.classList.remove("text-skel");
    } else {
        el.textContent = "KXXXXXXXX";
        el.classList.add("text-skel");
    }
}

function resetKenoGrid() {
    const grid = document.getElementById("kenoGrid");
    if (!grid) return;
    grid.querySelectorAll(".gv-keno-cell").forEach(cell => {
        cell.classList.remove("selected", "hit", "miss", "drawn", "has-ball", "still");
        if (cell.querySelector(".keno-ball")) cell.textContent = cell.dataset.num;
    });
}

function kenoAutoHideDone() {
    if (kenoAutoRun && !kenoAutoRun.active) {
        kenoAutoShowLive(false);
        kenoAutoRun = null;
    }
}

function resetKenoUI() {
    kenoRevealSeq++;
    kenoAutoHideDone();
    kenoMode = "select";
    kenoBusy = false;
    kenoPicks = [];
    kenoCurrentRoundInfo = null;
    kenoLastResult = null;
    kenoTable = {};
    resetKenoGrid();
    setKenoPanelLocked(false);
    setKenoStartBtn("play");
    updateKenoStatus();
    updateKenoStartState();
    updateKenoRoundIdLabel();
    updateKenoMultRow();
    updateKenoResetRow();
    const autoRow = document.getElementById("kenoAutoRow");
    if (autoRow) autoRow.style.display = "";
}

function toggleKenoPick(n) {
    if (kenoMode !== "select" || kenoBusy) return;
    kenoAutoHideDone();
    const cell = document.querySelector('#kenoGrid .gv-keno-cell[data-num="' + n + '"]');
    const idx = kenoPicks.indexOf(n);
    if (idx !== -1) {
        kenoPicks.splice(idx, 1);
        if (cell) cell.classList.remove("selected");
    } else {
        if (kenoPicks.length >= KENO_MAX_PICKS) {
            showToast("Максимум " + KENO_MAX_PICKS + " чисел", "error");
            return;
        }
        kenoPicks.push(n);
        if (cell) cell.classList.add("selected");
    }
    haptic("selection");
    updateKenoStatus();
    updateKenoStartState();
    updateKenoResetRow();
    fetchKenoTable();
}

function updateKenoResetRow() {
    const row = document.getElementById("kenoResetRow");
    if (row) row.style.display = kenoMode === "select" && kenoPicks.length > 0 ? "" : "none";
}

function clearKenoPicks() {
    if (kenoMode !== "select" || kenoBusy || !kenoPicks.length) return;
    kenoAutoHideDone();
    kenoPicks = [];
    resetKenoGrid();
    haptic("selection");
    updateKenoStatus();
    updateKenoStartState();
    updateKenoResetRow();
    fetchKenoTable();
}

function autoPickKeno() {
    if (kenoMode !== "select" || kenoBusy) return;
    kenoAutoHideDone();
    const pool = [];
    for (let n = 1; n <= KENO_BOARD_SIZE; n++) pool.push(n);
    for (let i = pool.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    kenoPicks = pool.slice(0, KENO_MAX_PICKS).sort((a, b) => a - b);
    resetKenoGrid();
    kenoPicks.forEach(n => {
        const cell = document.querySelector('#kenoGrid .gv-keno-cell[data-num="' + n + '"]');
        if (cell) cell.classList.add("selected");
    });
    haptic("selection");
    updateKenoStatus();
    updateKenoStartState();
    updateKenoResetRow();
    fetchKenoTable();
}

function playKeno() {
    if (kenoBusy || kenoMode !== "select") return;
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const state = kenoReadyState();
    if (!state.validPicks) {
        showToast("Выберите от 1 до " + KENO_MAX_PICKS + " чисел", "error");
        return;
    }
    if (!state.hasBet) return;
    if (!state.enoughBalance) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    if (state.underMin) {
        showToast("Минимальная ставка — " + fmtNum(betMin("keno")) + "⭐️", "error");
        return;
    }
    if (state.overMax) {
        showToast("Максимальная ставка — " + fmtNum(betMax("keno")) + "⭐️", "error");
        return;
    }
    kenoAutoHideDone();
    kenoBusy = true;
    setKenoPanelLocked(true);
    document.getElementById("kenoStartBtn").classList.add("dim");
    fetch("/api/keno/play", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            bet: state.bet,
            picks: kenoPicks,
            risk: kenoRisk
        })
    }).then(r => r.json()).then(data => {
        if (!data || !data.ok) {
            kenoBusy = false;
            showToast(data && data.error || "Ошибка сервера", "error");
            setKenoPanelLocked(false);
            updateKenoStartState();
            return;
        }
        kenoMode = "result";
        kenoLastResult = data;
        updateKenoResetRow();
        const autoRow = document.getElementById("kenoAutoRow");
        if (autoRow) autoRow.style.display = "none";
        kenoCurrentRoundInfo = {
            roundId: data.roundId,
            seedHash: data.seedHash,
            serverSeed: data.serverSeed,
            status: "finished",
            picks: data.picks,
            drawn: data.drawn,
            hits: data.hits,
            multiplier: data.multiplier,
        };
        updateKenoRoundIdLabel();
        kenoDeferBalance(data, KENO_REVEAL_MS.normal);
        kenoRevealResult(data, KENO_REVEAL_MS.normal, () => {
            kenoBusy = false;
            updateKenoStatus();
            updateKenoMultRow(data.hits);
            setKenoStartBtn("again");
            const startBtn = document.getElementById("kenoStartBtn");
            if (startBtn) startBtn.classList.remove("dim");
            if (data.win) showGameWinToast(data.winAmount, "Выигрыш ", "⭐️!");
            else showGameLoseToast("Не повезло — попробуйте ещё раз");
            loadKenoHistory(null, true);
        });
    }).catch(() => {
        kenoBusy = false;
        setKenoPanelLocked(false);
        showToast("Не удалось связаться с сервером", "error");
        updateKenoStartState();
    });
}

function renderKeno(data) {
    return '<div class="gv-mines-box">' + '<div class="gv-mult-row" id="kenoMultRow" data-action="keno-paytable-info"><div class="gv-mult-chip now">Выберите числа</div></div>' + '<div class="gv-keno-grid" id="kenoGrid">' + kenoGridHTML() + "</div>" + '<div class="mines-status keno-status-sm" id="kenoStatus"></div>' + '<div class="mines-auto-row keno-auto-row-sm" id="kenoAutoRow">' + '<button class="mines-auto-btn" type="button" id="kenoAutoBtn"><img class="lazy-img mines-auto-icon" src="/lottie/ИграМиныЛесенка/АвтоВыбор.png" alt=""><span>Случайный выбор</span></button>' + '<button class="haptics-info-btn" type="button" id="kenoAutoInfoBtn" data-action="keno-auto-info">Что это?</button>' + "</div>" + '<div class="mines-auto-row keno-auto-row-sm" id="kenoResetRow" style="display:none;">' + '<button class="mines-auto-btn" type="button" id="kenoResetBtn"><img class="lazy-img mines-auto-icon" src="/ИграКено/Сбросить.png" alt=""><span>Сбросить</span></button>' + "</div>" + '<div class="gv-mines-howto">' + '<div class="gv-fair" data-action="keno-fair"><span class="gv-fair-icon">#</span><span id="kenoRoundIdLabel" class="text-skel">KXXXXXXXX</span></div>' + howtoHTML("position:static;") + "</div>" + "</div>" + '<div class="keno-auto-live" id="kenoAutoLive" hidden></div>' + '<div class="gv-panel" id="kenoRiskPanel">' + '<div class="gv-label keno-label-row"><span>Уровень риска</span><button class="keno-auto-pill" type="button" id="kenoAutoOpenBtn">' + UPG_AUTO_ICON + "Авто-игра</button></div>" + kenoRiskRowHTML() + "</div>" + '<div class="gv-panel" id="kenoPanel">' + '<div class="gv-label">Сумма ставки</div>' + betRowHTML() + "</div>" + '<button class="gv-start-btn dim" type="button" id="kenoStartBtn">Играть</button>' + '<div class="gv-history">' + '<div class="gv-history-head">' + '<h3 class="gv-history-title">' + lazyImgTag(liteAsset("/lottie/images/ОгоньЭмоджи.lottie"), "", "flame-gif") + " Последние игры</h3>" + '<div class="gv-history-tabs">' + '<button class="gv-history-tab active" type="button" data-keno-scope="all">Все</button>' + '<button class="gv-history-tab" type="button" data-keno-scope="mine">Мои</button>' + "</div>" + "</div>" + gvHistorySearchRowHTML("kenoHistorySearchInput") + '<div class="gv-history-list" id="kenoHistoryList"><div class="dice-history-empty">Загрузка…</div></div>' + "</div>";
}

