function kenoAutoCleanNum(v) {
    let t = String(v == null ? "" : v).replace(",", ".").replace(/[^0-9.]/g, "");
    const i = t.indexOf(".");
    if (i >= 0) t = t.slice(0, i + 1) + t.slice(i + 1).replace(/\./g, "");
    return t.slice(0, 9);
}

function kenoAutoNum(v) {
    const t = String(v == null ? "" : v).trim();
    if (!t) return null;
    const n = parseFloat(t);
    return isFinite(n) && n > 0 ? n : NaN;
}

function kenoAutoClampPct(v, fallback) {
    const n = Math.round(Number(v));
    return isFinite(n) && n >= 1 && n <= 1000 ? n : fallback;
}

function kenoAutoWord(n) {
    const m10 = n % 10;
    const m100 = n % 100;
    if (m10 === 1 && m100 !== 11) return "раунд";
    if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return "раунда";
    return "раундов";
}

function kenoAutoSigned(n) {
    const v = Math.round(n * 100) / 100;
    return (v > 0 ? "+" : v < 0 ? "−" : "") + fmtNum(Math.abs(v)) + "⭐️";
}

function kenoAutoSettings() {
    if (kenoAutoSet) return kenoAutoSet;
    const d = {
        rounds: 10,
        stopWin: false,
        profit: "",
        loss: "",
        bigWin: "",
        onLoss: "same",
        lossPct: 100,
        onWin: "same",
        winPct: 50,
        cap: "",
        picks: "mine",
        speed: "normal"
    };
    try {
        const raw = JSON.parse(localStorage.getItem(KENO_AUTO_STORE) || "null");
        if (raw && typeof raw === "object") {
            if (KENO_AUTO_ROUNDS.indexOf(raw.rounds) >= 0) d.rounds = raw.rounds;
            d.stopWin = raw.stopWin === true;
            ["profit", "loss", "bigWin", "cap"].forEach(k => {
                d[k] = kenoAutoCleanNum(raw[k]);
            });
            if (raw.onLoss === "up") d.onLoss = "up";
            if (raw.onWin === "reset" || raw.onWin === "up") d.onWin = raw.onWin;
            d.lossPct = kenoAutoClampPct(raw.lossPct, d.lossPct);
            d.winPct = kenoAutoClampPct(raw.winPct, d.winPct);
            if (raw.picks === "random") d.picks = "random";
            if (KENO_AUTO_SPEEDS[raw.speed]) d.speed = raw.speed;
        }
    } catch (e) {}
    kenoAutoSet = d;
    return d;
}

function kenoAutoSave() {
    try {
        localStorage.setItem(KENO_AUTO_STORE, JSON.stringify(kenoAutoSettings()));
    } catch (e) {}
}

function kenoAutoTotalRounds() {
    const max = kenoAutoCfg ? kenoAutoCfg.maxRounds : 100;
    const r = kenoAutoSettings().rounds;
    return r ? Math.min(r, max) : max;
}

function kenoAutoLabel() {
    const r = kenoAutoSettings().rounds;
    return "Запустить авто · " + (r ? r + " " + kenoAutoWord(r) : "∞");
}

function kenoAutoSummaryText() {
    const s = kenoAutoSettings();
    const total = kenoAutoTotalRounds();
    const parts = ["до " + total + " " + kenoAutoWord(total)];
    const stops = [];
    if (s.stopWin) stops.push("первый выигрыш");
    if (kenoAutoNum(s.profit) > 0) stops.push("прибыль +" + s.profit + "⭐️");
    if (kenoAutoNum(s.loss) > 0) stops.push("убыток −" + s.loss + "⭐️");
    if (kenoAutoNum(s.bigWin) > 0) stops.push("выигрыш от " + s.bigWin + "⭐️");
    if (stops.length) parts.push("стоп: " + stops.join(", "));
    parts.push(s.picks === "random" ? "новые случайные числа каждый раунд" : "ваши числа");
    if (s.onLoss === "up") parts.push("после проигрыша +" + s.lossPct + "%");
    if (s.onWin === "reset") parts.push("после выигрыша — начальная ставка");
    else if (s.onWin === "up") parts.push("после выигрыша +" + s.winPct + "%");
    if (kenoAutoNum(s.cap) > 0) parts.push("потолок " + s.cap + "⭐️");
    parts.push(KENO_AUTO_SPEEDS[s.speed].label.toLowerCase() + " скорость");
    return parts.join(" · ");
}

function kenoAutoWarnText() {
    const s = kenoAutoSettings();
    const hasLoss = kenoAutoNum(s.loss) > 0;
    const hasCap = kenoAutoNum(s.cap) > 0;
    if (s.onLoss === "up" && !hasLoss && !hasCap) return "Ставка растёт после каждого проигрыша — длинная серия поражений быстро её раздует. Задайте стоп-лосс или потолок ставки.";
    if (!s.rounds && !hasLoss && !(kenoAutoNum(s.profit) > 0) && !s.stopWin) return "Без стоп-условий серия идёт до лимита раундов или пока хватает баланса.";
    return "";
}

function kenoAutoSetupHTML() {
    const s = kenoAutoSettings();
    const cfg = kenoAutoCfg;
    if (cfg && !cfg.enabled) return '<div class="upg-auto-off">Авто-игра сейчас отключена администратором. Играйте вручную.</div>';
    const rounds = KENO_AUTO_ROUNDS.map(n => '<button class="upg-chip' + (s.rounds === n ? " on" : "") + '" type="button" data-kn-rounds="' + n + '">' + (n ? n : "∞") + "</button>").join("");
    const field = (key, sign, name, ph) => '<label class="upg-field"><span class="upg-field-name">' + name + '</span><span class="upg-input"><em>' + sign + '</em><input type="text" inputmode="decimal" autocomplete="off" maxlength="9" data-kn-in="' + key + '" placeholder="' + ph + '" value="' + escapeHtml(s[key]) + '"><b>⭐️</b></span></label>';
    const seg = (key, items, cur) => '<div class="upg-seg" data-kn-seg="' + key + '">' + items.map(it => '<button class="upg-seg-btn' + (cur === it[0] ? " on" : "") + '" type="button" data-kn-val="' + it[0] + '">' + it[1] + "</button>").join("") + "</div>";
    const pct = which => {
        const mode = which === "loss" ? s.onLoss : s.onWin;
        if (mode !== "up") return "";
        const cur = which === "loss" ? s.lossPct : s.winPct;
        const chips = [25, 50, 100, 200].map(p => '<button class="upg-chip small' + (cur === p ? " on" : "") + '" type="button" data-kn-pct="' + which + ":" + p + '">+' + p + "%</button>").join("");
        return '<div class="upg-pct-row">' + chips + '<span class="upg-input mini"><em>+</em><input type="text" inputmode="numeric" autocomplete="off" maxlength="4" data-kn-pctin="' + which + '" value="' + cur + '"><b>%</b></span></div>';
    };
    const capHint = cfg && cfg.maxBet > 0 ? "до " + fmtNum(cfg.maxBet) : "выкл.";
    const warn = kenoAutoWarnText();
    return '<div class="upg-auto-head"><span class="upg-auto-title">' + UPG_AUTO_ICON + 'Авто-игра</span><span class="upg-auto-limit">' + (cfg ? "до " + cfg.maxRounds + " " + kenoAutoWord(cfg.maxRounds) + " за серию" : "") + "</span></div>" + '<div class="gv-label">Количество раундов</div>' + '<div class="upg-chip-row">' + rounds + "</div>" + '<div class="gv-label">Числа в каждом раунде</div>' + seg("picks", [
        ["mine", "Мои числа"],
        ["random", "Случайные"]
    ], s.picks) + '<div class="gv-label">Остановить, если</div>' + '<div class="upg-stops">' + '<button class="upg-toggle' + (s.stopWin ? " on" : "") + '" type="button" data-kn-toggle="stopWin"><span>Выпал первый выигрыш</span><i class="upg-sw"></i></button>' + field("profit", "+", "Цель по прибыли", "выкл.") + field("loss", "−", "Стоп-лосс", "выкл.") + field("bigWin", "≥", "Крупный выигрыш", "выкл.") + "</div>" + '<div class="gv-label">Ставка после проигрыша</div>' + seg("onLoss", [
        ["same", "Не менять"],
        ["up", "Увеличить"]
    ], s.onLoss) + pct("loss") + '<div class="gv-label">Ставка после выигрыша</div>' + seg("onWin", [
        ["same", "Не менять"],
        ["reset", "Сбросить"],
        ["up", "Увеличить"]
    ], s.onWin) + pct("win") + '<div class="gv-label">Потолок ставки</div>' + field("cap", "≤", "Ставка не выше этой", capHint) + '<div class="gv-label">Скорость</div>' + seg("speed", [
        ["normal", "Обычная"],
        ["fast", "Быстрая"],
        ["turbo", "Турбо"]
    ], s.speed) + '<div class="upg-auto-warn" id="knAutoWarn"' + (warn ? "" : " hidden") + ">" + escapeHtml(warn) + "</div>" + '<div class="upg-auto-sum" id="knAutoSum">' + escapeHtml(kenoAutoSummaryText()) + "</div>";
}

function kenoAutoRenderModal() {
    const body = document.getElementById("kenoAutoBody");
    if (body) body.innerHTML = '<div class="upg-auto keno-auto-card">' + kenoAutoSetupHTML() + "</div>";
    const go = document.getElementById("kenoAutoGo");
    if (go) {
        go.textContent = kenoAutoLabel();
        const off = !!(kenoAutoCfg && !kenoAutoCfg.enabled);
        go.classList.toggle("dim", off);
    }
}

function kenoAutoRefreshHints() {
    const sum = document.getElementById("knAutoSum");
    if (sum) sum.textContent = kenoAutoSummaryText();
    const warn = document.getElementById("knAutoWarn");
    if (warn) {
        const text = kenoAutoWarnText();
        warn.textContent = text;
        warn.hidden = !text;
    }
    const go = document.getElementById("kenoAutoGo");
    if (go) go.textContent = kenoAutoLabel();
}

function kenoAutoChanged(rerender) {
    kenoAutoSave();
    if (rerender) kenoAutoRenderModal();
    else kenoAutoRefreshHints();
}

function kenoAutoModalClick(e) {
    const s = kenoAutoSettings();
    const t = e.target;
    const rounds = t.closest("[data-kn-rounds]");
    if (rounds) {
        const n = parseInt(rounds.dataset.knRounds, 10);
        if (KENO_AUTO_ROUNDS.indexOf(n) >= 0) s.rounds = n;
        haptic("selection");
        kenoAutoChanged(true);
        return;
    }
    if (t.closest("[data-kn-toggle]")) {
        s.stopWin = !s.stopWin;
        haptic("selection");
        kenoAutoChanged(true);
        return;
    }
    const seg = t.closest("[data-kn-seg]");
    const segBtn = t.closest("[data-kn-val]");
    if (seg && segBtn) {
        const key = seg.dataset.knSeg;
        const val = segBtn.dataset.knVal;
        if (key === "picks" && (val === "mine" || val === "random")) s.picks = val;
        else if (key === "onLoss" && (val === "same" || val === "up")) s.onLoss = val;
        else if (key === "onWin" && (val === "same" || val === "reset" || val === "up")) s.onWin = val;
        else if (key === "speed" && KENO_AUTO_SPEEDS[val]) s.speed = val;
        else return;
        haptic("selection");
        kenoAutoChanged(true);
        return;
    }
    const pct = t.closest("[data-kn-pct]");
    if (pct) {
        const bits = pct.dataset.knPct.split(":");
        const n = kenoAutoClampPct(bits[1], null);
        if (n === null) return;
        if (bits[0] === "loss") s.lossPct = n;
        else s.winPct = n;
        haptic("selection");
        kenoAutoChanged(true);
    }
}

function kenoAutoModalInput(e) {
    const el = e.target;
    const s = kenoAutoSettings();
    const key = el.dataset && el.dataset.knIn;
    if (key && ["profit", "loss", "bigWin", "cap"].indexOf(key) >= 0) {
        const v = kenoAutoCleanNum(el.value);
        if (v !== el.value) el.value = v;
        s[key] = v;
        kenoAutoChanged(false);
        return;
    }
    const which = el.dataset && el.dataset.knPctin;
    if (which === "loss" || which === "win") {
        const n = kenoAutoClampPct(el.value, null);
        if (n === null) return;
        if (which === "loss") s.lossPct = n;
        else s.winPct = n;
        const body = document.getElementById("kenoAutoBody");
        if (body) body.querySelectorAll('[data-kn-pct^="' + which + ':"]').forEach(c => c.classList.toggle("on", parseInt(c.dataset.knPct.split(":")[1], 10) === n));
        kenoAutoChanged(false);
    }
}

function kenoAutoEnsureModal() {
    if (kenoAutoModalEl && document.body.contains(kenoAutoModalEl)) return kenoAutoModalEl;
    const el = document.createElement("div");
    el.className = "modal-overlay";
    el.id = "kenoAutoModal";
    el.innerHTML = '<div class="modal-card keno-auto-modal"><button class="modal-close" type="button" id="kenoAutoClose"><svg viewBox="0 0 24 24" fill="none"><path d="M6 6l12 12M18 6 6 18" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg></button>' + '<h3 class="modal-title">Авто-игра в Кено</h3>' + '<div id="kenoAutoBody"></div>' + '<button class="modal-ok keno-auto-go" type="button" id="kenoAutoGo">Запустить авто</button></div>';
    document.body.appendChild(el);
    el.addEventListener("click", e => {
        if (e.target === el || e.target.closest("#kenoAutoClose")) {
            el.classList.remove("active");
            return;
        }
        if (e.target.closest("#kenoAutoGo")) {
            kenoAutoStart();
            return;
        }
        kenoAutoModalClick(e);
    });
    el.addEventListener("input", kenoAutoModalInput);
    kenoAutoModalEl = el;
    return el;
}

function kenoAutoLoadCfg() {
    fetch("/api/keno/auto/config?uid=" + CURRENT_UID).then(r => r.json()).then(d => {
        if (!d || !d.ok) return;
        kenoAutoCfg = {
            enabled: !!d.enabled,
            maxRounds: d.maxRounds,
            minDelayMs: d.minDelayMs,
            maxBet: d.maxBet
        };
        const modal = document.getElementById("kenoAutoModal");
        if (modal && modal.classList.contains("active")) kenoAutoRenderModal();
    }).catch(() => {});
}

function openKenoAutoModal() {
    if (kenoAutoRun && kenoAutoRun.active) return;
    if (kenoBusy) return;
    const el = kenoAutoEnsureModal();
    kenoAutoRenderModal();
    el.classList.add("active");
    kenoAutoLoadCfg();
    haptic("selection");
}

function kenoAutoClose() {
    const el = document.getElementById("kenoAutoModal");
    if (el) el.classList.remove("active");
}

function kenoAutoParse() {
    const s = kenoAutoSettings();
    const out = {
        rounds: s.rounds,
        stopWin: s.stopWin,
        onLoss: s.onLoss,
        lossPct: s.lossPct,
        onWin: s.onWin,
        winPct: s.winPct,
        picks: s.picks,
        speed: s.speed
    };
    const labels = {
        profit: "Прибыль серии",
        loss: "Убыток серии",
        bigWin: "Выигрыш за раунд",
        cap: "Потолок ставки"
    };
    const keys = Object.keys(labels);
    for (let i = 0; i < keys.length; i++) {
        const n = kenoAutoNum(s[keys[i]]);
        if (n !== null && !(n > 0)) {
            showToast(labels[keys[i]] + ": введите число больше нуля или оставьте поле пустым", "error");
            return null;
        }
        out[keys[i]] = n;
    }
    return out;
}

function kenoAutoAlive(run) {
    return kenoAutoRun === run && run.active;
}

function kenoAutoLiveHTML() {
    const tile = (label, id) => '<div class="upgrade-stat"><span>' + label + '</span><b id="' + id + '">—</b></div>';
    return '<div class="upg-auto keno-auto-live-card"><div class="upg-live" id="knLive">' + '<div class="upg-live-top"><span class="upg-live-tag" id="knLiveTag">Авто-игра</span><span class="upg-live-round" id="knLiveRound"></span></div>' + '<div class="upg-live-bar"><i id="knLiveBar"></i></div>' + '<div class="upg-live-net-wrap"><span class="upg-live-net-cap">Итог серии</span><b class="upg-live-net" id="knLiveNet">0⭐️</b></div>' + '<div class="upg-live-stats">' + tile("Победы", "knLiveWins") + tile("Поражения", "knLiveLoss") + tile("Ставка", "knLiveBet") + "</div>" + '<div class="upg-live-dots" id="knLiveDots"></div>' + '<div class="upg-live-reason" id="knLiveReason" hidden></div>' + "</div></div>";
}

function kenoAutoPaintLive(newDot) {
    const run = kenoAutoRun;
    const roundEl = document.getElementById("knLiveRound");
    if (!run || !roundEl) return;
    const byId = id => document.getElementById(id);
    const net = Math.round((run.returned - run.staked) * 100) / 100;
    const total = run.total;
    roundEl.innerHTML = "Сыграно <b>" + run.round + "</b>" + (run.p.rounds ? " из " + total : " · ∞");
    byId("knLiveBar").style.width = Math.min(100, total ? run.round / total * 100 : 0).toFixed(1) + "%";
    const netEl = byId("knLiveNet");
    netEl.textContent = kenoAutoSigned(net);
    netEl.className = "upg-live-net" + (net > 0 ? " pos" : net < 0 ? " neg" : "");
    byId("knLiveWins").textContent = String(run.wins);
    byId("knLiveLoss").textContent = String(run.losses);
    byId("knLiveBet").textContent = fmtNum(run.bet) + "⭐️";
    byId("knLiveDots").innerHTML = run.dots.slice(-28).map((w, i, a) => '<i class="' + (w ? "w" : "l") + (newDot && i === a.length - 1 ? " new" : "") + '"></i>').join("");
    const live = byId("knLive");
    if (live) live.classList.toggle("done", !run.active);
    byId("knLiveTag").textContent = run.active ? "Авто-игра · " + KENO_AUTO_SPEEDS[run.p.speed].label.toLowerCase() : "Серия завершена";
    const reasonEl = byId("knLiveReason");
    reasonEl.hidden = run.active;
    if (!run.active) reasonEl.textContent = KENO_AUTO_REASONS[run.reason] || KENO_AUTO_REASONS.other;
}

function kenoAutoShowLive(show) {
    const box = document.getElementById("kenoAutoLive");
    if (!box) return;
    box.hidden = !show;
    if (show) box.innerHTML = kenoAutoLiveHTML();
}

function kenoAutoSyncButton() {
    const btn = document.getElementById("kenoStartBtn");
    if (!btn) return;
    const run = kenoAutoRun;
    const running = !!(run && run.active);
    btn.classList.toggle("keno-stop", running);
    if (running) {
        btn.textContent = run.stopRequested ? "Останавливаю…" : "Остановить";
        btn.classList.toggle("dim", !!run.stopRequested);
    }
}

function kenoAutoRandomPicks(count) {
    const pool = [];
    for (let n = 1; n <= KENO_BOARD_SIZE; n++) pool.push(n);
    for (let i = pool.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    return pool.slice(0, count).sort((a, b) => a - b);
}

function kenoAutoPaintPicks(picks) {
    resetKenoGrid();
    picks.forEach(n => {
        const cell = document.querySelector('#kenoGrid .gv-keno-cell[data-num="' + n + '"]');
        if (cell) cell.classList.add("selected");
    });
    updateKenoStatus();
}

function kenoAutoStart() {
    if (kenoBusy || kenoMode !== "select") {
        kenoAutoClose();
        return;
    }
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    if (kenoAutoCfg && !kenoAutoCfg.enabled) {
        showToast("Авто-игра сейчас отключена", "warning");
        return;
    }
    const s = kenoAutoSettings();
    const state = kenoReadyState();
    if (!state.hasBet) {
        showToast("Введите сумму ставки", "error");
        return;
    }
    if (!state.enoughBalance) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    if (state.underMin) {
        showToast("Минимальная ставка — " + fmtNum(betMin("keno")) + "⭐️", "error");
        return;
    }
    if (state.overMax) {
        showToast("Максимальная ставка — " + fmtNum(betMax("keno")) + "⭐️", "error");
        return;
    }
    let pickCount = kenoPicks.length;
    if (s.picks === "mine") {
        if (!state.validPicks) {
            showToast("Выберите от 1 до " + KENO_MAX_PICKS + " чисел или включите «Случайные»", "error");
            return;
        }
    } else {
        pickCount = pickCount >= 1 ? pickCount : 5;
    }
    const p = kenoAutoParse();
    if (!p) return;
    const cfg = kenoAutoCfg || {
        enabled: true,
        maxRounds: 100,
        minDelayMs: 450,
        maxBet: 0
    };
    if (cfg.maxBet > 0 && state.bet > cfg.maxBet + 1e-9) {
        showToast("В авто-игре ставка не больше " + fmtNum(cfg.maxBet) + "⭐️", "error");
        return;
    }
    if (p.cap && state.bet > p.cap + 1e-9) {
        showToast("Потолок ставки ниже вашей ставки", "error");
        return;
    }
    const run = {
        active: true,
        sid: null,
        p: p,
        cfg: cfg,
        total: p.rounds ? Math.min(p.rounds, cfg.maxRounds) : cfg.maxRounds,
        base: state.bet,
        bet: state.bet,
        pickCount: pickCount,
        fixedPicks: kenoPicks.slice(),
        round: 0,
        wins: 0,
        losses: 0,
        staked: 0,
        returned: 0,
        dots: [],
        stopReason: null,
        stopRequested: null,
        lastAt: 0,
        retry: 0,
        timer: null,
        inflight: false,
        revealing: false,
        finishPending: null,
        finishSent: false,
        reason: null,
        lastData: null,
        minDelay: cfg.minDelayMs + 40
    };
    kenoAutoRun = run;
    kenoAutoClose();
    kenoBusy = true;
    setKenoPanelLocked(true);
    const autoRow = document.getElementById("kenoAutoRow");
    if (autoRow) autoRow.style.display = "none";
    const resetRow = document.getElementById("kenoResetRow");
    if (resetRow) resetRow.style.display = "none";
    kenoAutoShowLive(true);
    kenoAutoPaintLive(false);
    kenoAutoSyncButton();
    haptic("impact", "medium");
    fetch("/api/keno/auto/start", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            params: {
                rounds: p.rounds,
                stopWin: p.stopWin,
                profit: p.profit,
                loss: p.loss,
                bigWin: p.bigWin,
                cap: p.cap,
                onLoss: p.onLoss,
                lossPct: p.lossPct,
                onWin: p.onWin,
                winPct: p.winPct,
                picks: p.picks,
                speed: p.speed,
                bet: state.bet,
                risk: kenoRisk
            }
        })
    }).then(r => r.json()).then(d => {
        if (!kenoAutoAlive(run)) return;
        if (!d || !d.ok) {
            kenoAutoStartFailed(run, d);
            return;
        }
        run.sid = d.sid;
        run.cfg = {
            enabled: true,
            maxRounds: d.maxRounds,
            minDelayMs: d.minDelayMs,
            maxBet: d.maxBet
        };
        kenoAutoCfg = run.cfg;
        run.minDelay = d.minDelayMs + 40;
        run.total = p.rounds ? Math.min(p.rounds, d.maxRounds) : d.maxRounds;
        if (d.maxBet > 0 && run.bet > d.maxBet + 1e-9) {
            kenoAutoStartFailed(run, {
                error: "В авто-игре ставка не больше " + fmtNum(d.maxBet) + "⭐️"
            });
            return;
        }
        kenoAutoPaintLive(false);
        kenoAutoStep(run);
    }).catch(() => {
        if (kenoAutoAlive(run)) kenoAutoStartFailed(run, null);
    });
}

function kenoAutoStartFailed(run, data) {
    run.active = false;
    kenoBusy = false;
    if (data && data.autoCode === "off" && kenoAutoCfg) kenoAutoCfg.enabled = false;
    kenoAutoShowLive(false);
    setKenoPanelLocked(false);
    kenoResetStartButton();
    const autoRow = document.getElementById("kenoAutoRow");
    if (autoRow) autoRow.style.display = "";
    updateKenoResetRow();
    updateKenoStartState();
    showToast(data && data.error || "Не удалось связаться с сервером", "error");
}

function kenoResetStartButton() {
    const btn = document.getElementById("kenoStartBtn");
    if (!btn) return;
    btn.classList.remove("keno-stop");
    setKenoStartBtn("play");
}

function kenoAutoClampBet(run) {
    let cap = betMax("keno");
    if (run.cfg.maxBet > 0) cap = Math.min(cap, run.cfg.maxBet);
    if (run.p.cap) cap = Math.min(cap, run.p.cap);
    return gvRound2(Math.min(Math.max(run.bet, betMin("keno")), cap));
}

function kenoAutoStep(run) {
    if (!kenoAutoAlive(run)) return;
    if (!document.getElementById("kenoGrid")) {
        kenoAutoAbort("user");
        return;
    }
    const reason = run.stopReason || run.stopRequested;
    if (reason) {
        kenoAutoFinish(run, reason);
        return;
    }
    const bet = kenoAutoClampBet(run);
    if (bet > currentUser.balance + 1e-9) {
        kenoAutoFinish(run, "balance");
        return;
    }
    run.bet = bet;
    kenoPicks = run.p.picks === "random" ? kenoAutoRandomPicks(run.pickCount) : run.fixedPicks.slice();
    kenoAutoPaintPicks(kenoPicks);
    const tableKey = kenoRisk + ":" + kenoPicks.length;
    if (run.tableKey !== tableKey) {
        run.tableKey = tableKey;
        fetchKenoTable().then(() => kenoAutoStep(run));
        return;
    }
    kenoAutoPaintLive(false);
    const wait = run.lastAt + run.minDelay - Date.now();
    if (wait > 0) run.timer = setTimeout(() => kenoAutoFire(run), wait);
    else kenoAutoFire(run);
}

function kenoAutoFire(run) {
    if (!kenoAutoAlive(run)) return;
    run.lastAt = Date.now();
    run.inflight = true;
    fetch("/api/keno/play", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            bet: run.bet,
            picks: kenoPicks,
            risk: kenoRisk,
            autoSid: run.sid
        })
    }).then(r => r.json()).then(data => {
        run.inflight = false;
        if (!kenoAutoAlive(run)) {
            if (data && data.ok && typeof data.balance === "number") applyBalance(data.balance);
            if (run.finishPending) kenoAutoSendFinish(run, run.finishPending);
            return;
        }
        if (!data || !data.ok) {
            kenoAutoFail(run, data);
            return;
        }
        kenoAutoResult(run, data);
    }).catch(() => {
        run.inflight = false;
        if (!kenoAutoAlive(run)) {
            if (run.finishPending) kenoAutoSendFinish(run, run.finishPending);
            return;
        }
        kenoAutoFinish(run, "error");
    });
}

function kenoAutoFail(run, data) {
    const code = data && data.autoCode;
    const msg = data && data.error || "Ошибка сервера";
    if (data && data.betsPaused) {
        kenoAutoFinish(run, "bets");
        return;
    }
    if (code === "fast" && run.retry < 3) {
        run.retry += 1;
        run.timer = setTimeout(() => kenoAutoFire(run), run.minDelay);
        return;
    }
    if (code === "limit") {
        kenoAutoFinish(run, "limit");
        return;
    }
    if (code === "off") {
        if (kenoAutoCfg) kenoAutoCfg.enabled = false;
        kenoAutoFinish(run, "off");
        return;
    }
    if (/Недостаточно средств/.test(msg)) {
        kenoAutoFinish(run, "balance");
        return;
    }
    showToast(msg, "error");
    kenoAutoFinish(run, code === "cap" ? "other" : "error");
}

function kenoAutoResult(run, data) {
    run.retry = 0;
    run.lastData = data;
    const speed = KENO_AUTO_SPEEDS[run.p.speed];
    kenoCurrentRoundInfo = {
        roundId: data.roundId,
        seedHash: data.seedHash,
        serverSeed: data.serverSeed,
        status: "finished",
        picks: data.picks,
        drawn: data.drawn,
        hits: data.hits,
        multiplier: data.multiplier
    };
    updateKenoRoundIdLabel();
    kenoDeferBalance(data, speed.reveal);
    run.revealing = true;
    kenoRevealResult(data, speed.reveal, () => {
        run.revealing = false;
        if (!kenoAutoAlive(run)) return;
        const win = !!data.win;
        const bet = Number(data.betAmount) || run.bet;
        const payout = win ? Number(data.winAmount) || 0 : 0;
        run.round += 1;
        run.staked += bet;
        run.returned += payout;
        if (win) run.wins += 1;
        else run.losses += 1;
        run.dots.push(win);
        updateKenoMultRow(data.hits);
        kenoAutoAfterRound(run, win, payout);
        kenoAutoPaintLive(true);
        if (run.round % 5 === 0) loadKenoHistory(null, true);
        run.timer = setTimeout(() => kenoAutoStep(run), speed.pause);
    });
}

function kenoAutoAfterRound(run, win, payout) {
    const p = run.p;
    if (win) {
        if (p.onWin === "reset") run.bet = run.base;
        else if (p.onWin === "up") run.bet = run.bet * (1 + p.winPct / 100);
    } else if (p.onLoss === "up") {
        run.bet = run.bet * (1 + p.lossPct / 100);
    }
    run.bet = gvRound2(run.bet);
    const net = run.returned - run.staked;
    let reason = null;
    if (p.stopWin && win) reason = "win";
    else if (p.profit && net >= p.profit - 1e-9) reason = "profit";
    else if (p.loss && -net >= p.loss - 1e-9) reason = "loss";
    else if (p.bigWin && win && payout >= p.bigWin - 1e-9) reason = "bigwin";
    else if (run.round >= run.total) reason = p.rounds ? "done" : "limit";
    run.stopReason = reason;
}

function kenoAutoRequestStop(reason) {
    const run = kenoAutoRun;
    if (!run || !run.active || run.stopRequested) return;
    run.stopRequested = reason;
    if (!run.inflight && !run.revealing) {
        clearTimeout(run.timer);
        kenoAutoFinish(run, run.stopReason || reason);
        return;
    }
    kenoAutoSyncButton();
}

function kenoAutoSendFinish(run, reason) {
    if (!run.sid || run.finishSent) return;
    run.finishSent = true;
    fetch("/api/keno/auto/finish", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        keepalive: true,
        body: JSON.stringify({
            uid: CURRENT_UID,
            sid: run.sid,
            reason: reason
        })
    }).catch(() => {});
}

function kenoAutoFinish(run, reason) {
    if (!kenoAutoAlive(run)) return;
    run.active = false;
    run.reason = reason;
    clearTimeout(run.timer);
    kenoBusy = false;
    kenoAutoSendFinish(run, reason);
    setKenoPanelLocked(false);
    const btn = document.getElementById("kenoStartBtn");
    if (btn) btn.classList.remove("keno-stop", "dim");
    if (run.lastData) {
        if (!document.querySelector("#kenoGrid .keno-ball")) {
            kenoAutoPaintPicks(run.lastData.picks || []);
            kenoRevealResult(run.lastData, 0, () => {});
        }
        kenoMode = "result";
        kenoLastResult = run.lastData;
        setKenoStartBtn("again");
        updateKenoStatus();
        updateKenoResetRow();
    } else {
        setKenoStartBtn("play");
        const autoRow = document.getElementById("kenoAutoRow");
        if (autoRow) autoRow.style.display = "";
        updateKenoResetRow();
        updateKenoStartState();
    }
    if (run.round) kenoAutoPaintLive(false);
    else kenoAutoShowLive(false);
    kenoAutoToast(run);
    loadKenoHistory(null, true);
}

function kenoAutoAbort(reason) {
    const run = kenoAutoRun;
    if (!run || !run.active) return;
    run.active = false;
    run.reason = reason;
    clearTimeout(run.timer);
    kenoBusy = false;
    kenoRevealSeq++;
    if (run.inflight) run.finishPending = reason;
    else kenoAutoSendFinish(run, reason);
}

function kenoAutoToast(run) {
    if (!run.round) return;
    const net = Math.round((run.returned - run.staked) * 100) / 100;
    if (net > 0) showGameWinToast(net, "Итог серии +", "⭐️");
    else if (net < 0) showGameLoseToast("Итог серии: −" + fmtNum(-net) + "⭐️");
    else showToast("Серия окончена: вы в нуле", "warning");
}

function kenoAutoReset() {
    kenoAutoAbort("user");
    kenoAutoRun = null;
}

document.addEventListener("visibilitychange", () => {
    if (document.hidden) kenoAutoRequestStop("hidden");
});

const PK_AUTO_STORE = "pickAutoCfg";

const PK_AUTO_ROUNDS = [5, 10, 25, 50, 100, 0];

const PK_AUTO_SPEEDS = {
    normal: {
        label: "Обычная",
        step: 230,
        pause: 650
    },
    fast: {
        label: "Быстрая",
        step: 100,
        pause: 300
    },
    turbo: {
        label: "Турбо",
        step: 0,
        pause: 0
    }
};

const PK_AUTO_REASONS = Object.assign({}, KENO_AUTO_REASONS, {
    broken: "Серия прервана"
});

const PK_AUTO_GAMES = {
    mines: {
        title: "Мины",
        limit: "mines",
        grid: "minesGrid",
        startBtn: "minesStartBtn",
        countKey: "minesCount",
        pathKey: "cells",
        unit: "клеток",
        count: () => minesCount,
        maxLen: () => 25 - minesCount,
        busy: () => minesBusy,
        active: () => minesActive,
        finished: () => minesFinishedInfo
    },
    ladder: {
        title: "Лесенка",
        limit: "ladder",
        grid: "ladderGrid",
        startBtn: "ladderStartBtn",
        countKey: "stonesCount",
        pathKey: "columns",
        unit: "уровней",
        count: () => ladderStones,
        maxLen: () => LADDER_LEVELS,
        busy: () => ladderBusy,
        active: () => ladderActive,
        finished: () => ladderFinishedInfo
    }
};

let pkAutoCfg = {};

let pkAutoSet = null;

let pkAutoSel = {
    mines: [],
    ladder: []
};

let pkAutoRun = null;

let pkAutoModalEl = null;

let pkAutoGame = "mines";

function pkAutoCleanNum(v) {
    let t = String(v == null ? "" : v).replace(",", ".").replace(/[^0-9.]/g, "");
    const i = t.indexOf(".");
    if (i >= 0) t = t.slice(0, i + 1) + t.slice(i + 1).replace(/\./g, "");
    return t.slice(0, 9);
}

function pkAutoNum(v) {
    const t = String(v == null ? "" : v).trim();
    if (!t) return null;
    const n = parseFloat(t);
    return isFinite(n) && n > 0 ? n : NaN;
}

function pkAutoClampPct(v, fallback) {
    const n = Math.round(Number(v));
    return isFinite(n) && n >= 1 && n <= 1000 ? n : fallback;
}

function pkAutoSettings(g) {
    if (!pkAutoSet) {
        let raw = null;
        try {
            raw = JSON.parse(localStorage.getItem(PK_AUTO_STORE) || "null");
        } catch (e) {}
        pkAutoSet = {};
        Object.keys(PK_AUTO_GAMES).forEach(key => {
            const d = {
                rounds: 10,
                stopWin: false,
                profit: "",
                loss: "",
                bigWin: "",
                onLoss: "same",
                lossPct: 100,
                onWin: "same",
                winPct: 50,
                cap: "",
                picks: "mine",
                speed: "normal",
                bet: ""
            };
            const r = raw && typeof raw === "object" ? raw[key] : null;
            if (r && typeof r === "object") {
                if (PK_AUTO_ROUNDS.indexOf(r.rounds) >= 0) d.rounds = r.rounds;
                d.stopWin = r.stopWin === true;
                ["profit", "loss", "bigWin", "cap", "bet"].forEach(k => {
                    d[k] = pkAutoCleanNum(r[k]);
                });
                if (r.onLoss === "up") d.onLoss = "up";
                if (r.onWin === "reset" || r.onWin === "up") d.onWin = r.onWin;
                d.lossPct = pkAutoClampPct(r.lossPct, d.lossPct);
                d.winPct = pkAutoClampPct(r.winPct, d.winPct);
                if (r.picks === "random") d.picks = "random";
                if (PK_AUTO_SPEEDS[r.speed]) d.speed = r.speed;
            }
            pkAutoSet[key] = d;
        });
    }
    return pkAutoSet[g];
}

function pkAutoSave() {
    try {
        localStorage.setItem(PK_AUTO_STORE, JSON.stringify(pkAutoSet));
    } catch (e) {}
}

function pkAutoServerCfg(g) {
    return pkAutoCfg[g] || {
        enabled: true,
        maxRounds: 100,
        minDelayMs: 450,
        maxBet: 0
    };
}

function pkAutoTotalRounds(g) {
    const max = pkAutoServerCfg(g).maxRounds;
    const r = pkAutoSettings(g).rounds;
    return r ? Math.min(r, max) : max;
}

function pkAutoLabel(g) {
    const r = pkAutoSettings(g).rounds;
    return "Запустить авто · " + (r ? r + " " + kenoAutoWord(r) : "∞");
}

function pkAutoTable(g) {
    return g === "mines" ? minesTable : ladderTable;
}

function pkAutoSummaryText(g) {
    const s = pkAutoSettings(g);
    const G = PK_AUTO_GAMES[g];
    const sel = pkAutoSel[g];
    const total = pkAutoTotalRounds(g);
    const parts = ["до " + total + " " + kenoAutoWord(total)];
    const bet = pkAutoNum(s.bet);
    const mult = pkAutoTable(g)[sel.length];
    if (bet > 0 && mult) parts.push("забираете x" + fmtCoef(mult) + " = " + fmtNum(Math.round(bet * mult * 100) / 100) + "⭐️");
    const stops = [];
    if (s.stopWin) stops.push("первый выигрыш");
    if (pkAutoNum(s.profit) > 0) stops.push("прибыль +" + s.profit + "⭐️");
    if (pkAutoNum(s.loss) > 0) stops.push("убыток −" + s.loss + "⭐️");
    if (pkAutoNum(s.bigWin) > 0) stops.push("выигрыш от " + s.bigWin + "⭐️");
    if (stops.length) parts.push("стоп: " + stops.join(", "));
    parts.push(s.picks === "random" ? "новые случайные " + G.unit + " каждый раунд" : "ваш выбор");
    if (s.onLoss === "up") parts.push("после проигрыша +" + s.lossPct + "%");
    if (s.onWin === "reset") parts.push("после выигрыша — начальная ставка");
    else if (s.onWin === "up") parts.push("после выигрыша +" + s.winPct + "%");
    if (pkAutoNum(s.cap) > 0) parts.push("потолок " + s.cap + "⭐️");
    parts.push(PK_AUTO_SPEEDS[s.speed].label.toLowerCase() + " скорость");
    return parts.join(" · ");
}

function pkAutoWarnText(g) {
    const s = pkAutoSettings(g);
    const hasLoss = pkAutoNum(s.loss) > 0;
    const hasCap = pkAutoNum(s.cap) > 0;
    if (s.onLoss === "up" && !hasLoss && !hasCap) return "Ставка растёт после каждого проигрыша — длинная серия поражений быстро её раздует. Задайте стоп-лосс или потолок ставки.";
    if (!s.rounds && !hasLoss && !(pkAutoNum(s.profit) > 0) && !s.stopWin) return "Без стоп-условий серия идёт до лимита раундов или пока хватает баланса.";
    return "";
}

function pkAutoSetupHTML(g) {
    const s = pkAutoSettings(g);
    const cfg = pkAutoServerCfg(g);
    const G = PK_AUTO_GAMES[g];
    if (!cfg.enabled) return '<div class="upg-auto-off">Авто-игра сейчас отключена администратором. Играйте вручную.</div>';
    const rounds = PK_AUTO_ROUNDS.map(n => '<button class="upg-chip' + (s.rounds === n ? " on" : "") + '" type="button" data-pk-rounds="' + n + '">' + (n ? n : "∞") + "</button>").join("");
    const field = (key, sign, name, ph) => '<label class="upg-field"><span class="upg-field-name">' + name + '</span><span class="upg-input"><em>' + sign + '</em><input type="text" inputmode="decimal" autocomplete="off" maxlength="9" data-pk-in="' + key + '" placeholder="' + ph + '" value="' + escapeHtml(s[key]) + '"><b>⭐️</b></span></label>';
    const seg = (key, items, cur) => '<div class="upg-seg" data-pk-seg="' + key + '">' + items.map(it => '<button class="upg-seg-btn' + (cur === it[0] ? " on" : "") + '" type="button" data-pk-val="' + it[0] + '">' + it[1] + "</button>").join("") + "</div>";
    const pct = which => {
        const mode = which === "loss" ? s.onLoss : s.onWin;
        if (mode !== "up") return "";
        const cur = which === "loss" ? s.lossPct : s.winPct;
        const chips = [25, 50, 100, 200].map(p => '<button class="upg-chip small' + (cur === p ? " on" : "") + '" type="button" data-pk-pct="' + which + ":" + p + '">+' + p + "%</button>").join("");
        return '<div class="upg-pct-row">' + chips + '<span class="upg-input mini"><em>+</em><input type="text" inputmode="numeric" autocomplete="off" maxlength="4" data-pk-pctin="' + which + '" value="' + cur + '"><b>%</b></span></div>';
    };
    const betChips = [
        ["min", "MIN"],
        ["half", "/2"],
        ["double", "x2"],
        ["max", "MAX"]
    ].map(c => '<button class="upg-chip small" type="button" data-pk-bet="' + c[0] + '">' + c[1] + "</button>").join("");
    const capHint = cfg.maxBet > 0 ? "до " + fmtNum(cfg.maxBet) : "выкл.";
    const warn = pkAutoWarnText(g);
    const sel = pkAutoSel[g];
    const picked = '<div class="pk-auto-picked">' + (G.title === "Мины" ? "Выбрано клеток: " : "Выбрано уровней: ") + "<b>" + sel.length + "</b> из " + G.maxLen() + "</div>";
    return '<div class="upg-auto-head"><span class="upg-auto-title">' + UPG_AUTO_ICON + 'Авто-игра</span><span class="upg-auto-limit">' + "до " + cfg.maxRounds + " " + kenoAutoWord(cfg.maxRounds) + " за серию</span></div>" + picked + '<div class="gv-label">Ставка в каждом раунде</div>' + '<label class="upg-field"><span class="upg-input"><em>⭐️</em><input type="text" inputmode="decimal" autocomplete="off" maxlength="9" data-pk-in="bet" placeholder="0" value="' + escapeHtml(s.bet) + '"><b>⭐️</b></span></label>' + '<div class="upg-pct-row">' + betChips + "</div>" + '<div class="gv-label">Количество раундов</div>' + '<div class="upg-chip-row">' + rounds + "</div>" + '<div class="gv-label">' + (g === "mines" ? "Клетки в каждом раунде" : "Путь в каждом раунде") + "</div>" + seg("picks", [
        ["mine", "Мой выбор"],
        ["random", "Случайный"]
    ], s.picks) + '<div class="gv-label">Остановить, если</div>' + '<div class="upg-stops">' + '<button class="upg-toggle' + (s.stopWin ? " on" : "") + '" type="button" data-pk-toggle="stopWin"><span>Выпал первый выигрыш</span><i class="upg-sw"></i></button>' + field("profit", "+", "Цель по прибыли", "выкл.") + field("loss", "−", "Стоп-лосс", "выкл.") + field("bigWin", "≥", "Крупный выигрыш", "выкл.") + "</div>" + '<div class="gv-label">Ставка после проигрыша</div>' + seg("onLoss", [
        ["same", "Не менять"],
        ["up", "Увеличить"]
    ], s.onLoss) + pct("loss") + '<div class="gv-label">Ставка после выигрыша</div>' + seg("onWin", [
        ["same", "Не менять"],
        ["reset", "Сбросить"],
        ["up", "Увеличить"]
    ], s.onWin) + pct("win") + '<div class="gv-label">Потолок ставки</div>' + field("cap", "≤", "Ставка не выше этой", capHint) + '<div class="gv-label">Скорость</div>' + seg("speed", [
        ["normal", "Обычная"],
        ["fast", "Быстрая"],
        ["turbo", "Турбо"]
    ], s.speed) + '<div class="upg-auto-warn" id="pkAutoWarn"' + (warn ? "" : " hidden") + ">" + escapeHtml(warn) + "</div>" + '<div class="upg-auto-sum" id="pkAutoSum">' + escapeHtml(pkAutoSummaryText(g)) + "</div>";
}

function pkAutoRenderModal() {
    const g = pkAutoGame;
    const body = document.getElementById("pkAutoBody");
    if (body) body.innerHTML = '<div class="upg-auto keno-auto-card">' + pkAutoSetupHTML(g) + "</div>";
    const title = document.getElementById("pkAutoTitle");
    if (title) title.textContent = "Авто-игра: " + PK_AUTO_GAMES[g].title;
    const go = document.getElementById("pkAutoGo");
    if (go) {
        go.textContent = pkAutoLabel(g);
        go.classList.toggle("dim", !pkAutoServerCfg(g).enabled);
    }
}

function pkAutoRefreshHints() {
    const g = pkAutoGame;
    const sum = document.getElementById("pkAutoSum");
    if (sum) sum.textContent = pkAutoSummaryText(g);
    const warn = document.getElementById("pkAutoWarn");
    if (warn) {
        const text = pkAutoWarnText(g);
        warn.textContent = text;
        warn.hidden = !text;
    }
    const go = document.getElementById("pkAutoGo");
    if (go) go.textContent = pkAutoLabel(g);
}

function pkAutoChanged(rerender) {
    pkAutoSave();
    if (rerender) pkAutoRenderModal();
    else pkAutoRefreshHints();
}

function pkAutoModalClick(e) {
    const g = pkAutoGame;
    const s = pkAutoSettings(g);
    const t = e.target;
    const rounds = t.closest("[data-pk-rounds]");
    if (rounds) {
        const n = parseInt(rounds.dataset.pkRounds, 10);
        if (PK_AUTO_ROUNDS.indexOf(n) >= 0) s.rounds = n;
        haptic("selection");
        pkAutoChanged(true);
        return;
    }
    if (t.closest("[data-pk-toggle]")) {
        s.stopWin = !s.stopWin;
        haptic("selection");
        pkAutoChanged(true);
        return;
    }
    const betChip = t.closest("[data-pk-bet]");
    if (betChip) {
        const cur = pkAutoNum(s.bet) || betMin(PK_AUTO_GAMES[g].limit);
        const kind = betChip.dataset.pkBet;
        let v = cur;
        if (kind === "min") v = betMin(PK_AUTO_GAMES[g].limit);
        else if (kind === "half") v = cur / 2;
        else if (kind === "double") v = cur * 2;
        else if (kind === "max") v = Math.min(betMax(PK_AUTO_GAMES[g].limit), Math.max(0, currentUser.balance));
        v = Math.max(betMin(PK_AUTO_GAMES[g].limit), Math.min(betMax(PK_AUTO_GAMES[g].limit), v));
        s.bet = String(Math.floor(v * 100) / 100);
        haptic("selection");
        pkAutoChanged(true);
        return;
    }
    const seg = t.closest("[data-pk-seg]");
    const segBtn = t.closest("[data-pk-val]");
    if (seg && segBtn) {
        const key = seg.dataset.pkSeg;
        const val = segBtn.dataset.pkVal;
        if (key === "picks" && (val === "mine" || val === "random")) s.picks = val;
        else if (key === "onLoss" && (val === "same" || val === "up")) s.onLoss = val;
        else if (key === "onWin" && (val === "same" || val === "reset" || val === "up")) s.onWin = val;
        else if (key === "speed" && PK_AUTO_SPEEDS[val]) s.speed = val;
        else return;
        haptic("selection");
        pkAutoChanged(true);
        return;
    }
    const pct = t.closest("[data-pk-pct]");
    if (pct) {
        const bits = pct.dataset.pkPct.split(":");
        const n = pkAutoClampPct(bits[1], null);
        if (n === null) return;
        if (bits[0] === "loss") s.lossPct = n;
        else s.winPct = n;
        haptic("selection");
        pkAutoChanged(true);
    }
}

function pkAutoModalInput(e) {
    const el = e.target;
    const g = pkAutoGame;
    const s = pkAutoSettings(g);
    const key = el.dataset && el.dataset.pkIn;
    if (key && ["bet", "profit", "loss", "bigWin", "cap"].indexOf(key) >= 0) {
        const v = pkAutoCleanNum(el.value);
        if (v !== el.value) el.value = v;
        s[key] = v;
        pkAutoChanged(false);
        return;
    }
    const which = el.dataset && el.dataset.pkPctin;
    if (which === "loss" || which === "win") {
        const n = pkAutoClampPct(el.value, null);
        if (n === null) return;
        if (which === "loss") s.lossPct = n;
        else s.winPct = n;
        const body = document.getElementById("pkAutoBody");
        if (body) body.querySelectorAll('[data-pk-pct^="' + which + ':"]').forEach(c => c.classList.toggle("on", parseInt(c.dataset.pkPct.split(":")[1], 10) === n));
        pkAutoChanged(false);
    }
}

function pkAutoEnsureModal() {
    if (pkAutoModalEl && document.body.contains(pkAutoModalEl)) return pkAutoModalEl;
    const el = document.createElement("div");
    el.className = "modal-overlay";
    el.id = "pkAutoModal";
    el.innerHTML = '<div class="modal-card keno-auto-modal"><button class="modal-close" type="button" id="pkAutoClose"><svg viewBox="0 0 24 24" fill="none"><path d="M6 6l12 12M18 6 6 18" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg></button>' + '<h3 class="modal-title" id="pkAutoTitle">Авто-игра</h3>' + '<div id="pkAutoBody"></div>' + '<button class="modal-ok keno-auto-go" type="button" id="pkAutoGo">Запустить авто</button></div>';
    document.body.appendChild(el);
    el.addEventListener("click", e => {
        if (e.target === el || e.target.closest("#pkAutoClose")) {
            el.classList.remove("active");
            return;
        }
        if (e.target.closest("#pkAutoGo")) {
            pkAutoStart();
            return;
        }
        pkAutoModalClick(e);
    });
    el.addEventListener("input", pkAutoModalInput);
    pkAutoModalEl = el;
    return el;
}

function pkAutoLoadCfg(g) {
    fetch("/api/" + g + "/auto/config?uid=" + CURRENT_UID).then(r => r.json()).then(d => {
        if (!d || !d.ok) return;
        pkAutoCfg[g] = {
            enabled: !!d.enabled,
            maxRounds: d.maxRounds,
            minDelayMs: d.minDelayMs,
            maxBet: d.maxBet
        };
        const modal = document.getElementById("pkAutoModal");
        if (modal && modal.classList.contains("active") && pkAutoGame === g) pkAutoRenderModal();
    }).catch(() => {});
}

function pkAutoIdle(g) {
    const G = PK_AUTO_GAMES[g];
    return !!document.getElementById(G.grid) && !G.active() && !G.busy() && !G.finished() && !(pkAutoRun && pkAutoRun.active);
}

function pkAutoOpen(g) {
    if (!pkAutoIdle(g)) return;
    if (!pkAutoSel[g].length) {
        showToast(g === "mines" ? "Сначала отметьте клетки на поле — они откроются по порядку" : "Сначала выберите столбец на каждом уровне, снизу вверх", "warning");
        return;
    }
    pkAutoGame = g;
    const s = pkAutoSettings(g);
    if (!pkAutoNum(s.bet)) {
        const have = gvInputBet();
        s.bet = String(have > 0 ? have : betMin(PK_AUTO_GAMES[g].limit));
    }
    const el = pkAutoEnsureModal();
    pkAutoRenderModal();
    el.classList.add("active");
    pkAutoLoadCfg(g);
    haptic("selection");
}

function pkAutoCloseModal() {
    const el = document.getElementById("pkAutoModal");
    if (el) el.classList.remove("active");
}

function pkAutoParse(g) {
    const s = pkAutoSettings(g);
    const out = {
        rounds: s.rounds,
        stopWin: s.stopWin,
        onLoss: s.onLoss,
        lossPct: s.lossPct,
        onWin: s.onWin,
        winPct: s.winPct,
        picks: s.picks,
        speed: s.speed
    };
    const labels = {
        profit: "Прибыль серии",
        loss: "Убыток серии",
        bigWin: "Выигрыш за раунд",
        cap: "Потолок ставки"
    };
    const keys = Object.keys(labels);
    for (let i = 0; i < keys.length; i++) {
        const n = pkAutoNum(s[keys[i]]);
        if (n !== null && !(n > 0)) {
            showToast(labels[keys[i]] + ": введите число больше нуля или оставьте поле пустым", "error");
            return null;
        }
        out[keys[i]] = n;
    }
    return out;
}

function pkAutoBoardHTML(g) {
    const G = PK_AUTO_GAMES[g];
    const lead = g === "mines" ? "Для авто-игры отметьте клетки на поле: они откроются по порядку, а после последней вы заберёте выигрыш." : "Для авто-игры выберите столбец на каждом уровне снизу вверх: раунд пройдёт по этому пути и заберёт выигрыш.";
    return '<div class="mines-auto-row keno-auto-row-sm" id="pkAutoRow" style="display:none;">' + '<button class="mines-auto-btn" type="button" id="pkAutoRandBtn"><span>' + (g === "mines" ? "Случайные клетки" : "Случайный путь") + "</span></button>" + '<button class="mines-auto-btn" type="button" id="pkAutoClearBtn"><span>Сбросить выбор</span></button>' + "</div>" + '<div class="pk-auto-hint" id="pkAutoHint" data-lead="' + escapeHtml(lead) + '"></div>';
}

function pkAutoLabelHTML(text, g) {
    return '<div class="gv-label keno-label-row"><span>' + text + '</span><button class="keno-auto-pill" type="button" id="pkAutoOpenBtn" data-pk-open="' + g + '">' + UPG_AUTO_ICON + "Авто-игра</button></div>";
}

function pkAutoLiveBoxHTML() {
    return '<div class="keno-auto-live" id="pkAutoLive" hidden></div>';
}

function pkAutoLiveHTML() {
    const tile = (label, id) => '<div class="upgrade-stat"><span>' + label + '</span><b id="' + id + '">—</b></div>';
    return '<div class="upg-auto keno-auto-live-card"><div class="upg-live" id="pkLive">' + '<div class="upg-live-top"><span class="upg-live-tag" id="pkLiveTag">Авто-игра</span><span class="upg-live-round" id="pkLiveRound"></span></div>' + '<div class="upg-live-bar"><i id="pkLiveBar"></i></div>' + '<div class="upg-live-net-wrap"><span class="upg-live-net-cap">Итог серии</span><b class="upg-live-net" id="pkLiveNet">0⭐️</b></div>' + '<div class="upg-live-stats">' + tile("Победы", "pkLiveWins") + tile("Поражения", "pkLiveLoss") + tile("Ставка", "pkLiveBet") + "</div>" + '<div class="upg-live-dots" id="pkLiveDots"></div>' + '<div class="upg-live-reason" id="pkLiveReason" hidden></div>' + "</div></div>";
}

function pkAutoPaintLive(newDot) {
    const run = pkAutoRun;
    const roundEl = document.getElementById("pkLiveRound");
    if (!run || !roundEl) return;
    const byId = id => document.getElementById(id);
    const net = Math.round((run.returned - run.staked) * 100) / 100;
    roundEl.innerHTML = "Сыграно <b>" + run.round + "</b>" + (run.p.rounds ? " из " + run.total : " · ∞");
    byId("pkLiveBar").style.width = Math.min(100, run.total ? run.round / run.total * 100 : 0).toFixed(1) + "%";
    const netEl = byId("pkLiveNet");
    netEl.textContent = kenoAutoSigned(net);
    netEl.className = "upg-live-net" + (net > 0 ? " pos" : net < 0 ? " neg" : "");
    byId("pkLiveWins").textContent = String(run.wins);
    byId("pkLiveLoss").textContent = String(run.losses);
    byId("pkLiveBet").textContent = fmtNum(run.bet) + "⭐️";
    byId("pkLiveDots").innerHTML = run.dots.slice(-28).map((w, i, a) => '<i class="' + (w ? "w" : "l") + (newDot && i === a.length - 1 ? " new" : "") + '"></i>').join("");
    const live = byId("pkLive");
    if (live) live.classList.toggle("done", !run.active);
    byId("pkLiveTag").textContent = run.active ? "Авто-игра · " + PK_AUTO_SPEEDS[run.p.speed].label.toLowerCase() : "Серия завершена";
    const reasonEl = byId("pkLiveReason");
    reasonEl.hidden = run.active;
    if (!run.active) reasonEl.textContent = PK_AUTO_REASONS[run.reason] || PK_AUTO_REASONS.other;
}

function pkAutoShowLive(show) {
    const box = document.getElementById("pkAutoLive");
    if (!box) return;
    box.hidden = !show;
    if (show) box.innerHTML = pkAutoLiveHTML();
}

function pkAutoSelClearBadges(g) {
    const grid = document.getElementById(PK_AUTO_GAMES[g].grid);
    if (!grid) return;
    grid.classList.remove("pk-pickable");
    grid.querySelectorAll(".pk-sel").forEach(c => c.classList.remove("pk-sel"));
    grid.querySelectorAll(".pk-ord").forEach(n => n.remove());
}

function pkAutoSelRender(g) {
    const grid = document.getElementById(PK_AUTO_GAMES[g].grid);
    if (!grid) return;
    pkAutoSelClearBadges(g);
    grid.classList.add("pk-pickable");
    const sel = pkAutoSel[g];
    sel.forEach((v, i) => {
        const c = g === "mines" ? grid.querySelector('.gv-mine-cell[data-idx="' + v + '"]') : grid.querySelector('.gv-ladder-cell[data-level="' + i + '"][data-col="' + v + '"]');
        if (!c) return;
        c.classList.add("pk-sel");
        const num = document.createElement("span");
        num.className = "pk-ord";
        num.textContent = String(i + 1);
        c.appendChild(num);
    });
}

function pkAutoHintText(g) {
    const hint = document.getElementById("pkAutoHint");
    const sel = pkAutoSel[g];
    const max = PK_AUTO_GAMES[g].maxLen();
    if (!sel.length) return hint ? hint.dataset.lead || "" : "";
    return (g === "mines" ? "Выбрано клеток: " : "Выбрано уровней: ") + sel.length + " из " + max + (g === "mines" ? " · откроются по порядку 1 → " + sel.length : "");
}

function pkAutoSync(g) {
    const G = PK_AUTO_GAMES[g];
    if (!document.getElementById(G.grid)) return;
    const run = pkAutoRun && pkAutoRun.active && pkAutoRun.g === g ? pkAutoRun : null;
    const idle = pkAutoIdle(g);
    const sel = pkAutoSel[g];
    if (sel.length > G.maxLen()) sel.length = G.maxLen();
    const row = document.getElementById("pkAutoRow");
    if (row) row.style.display = idle ? "flex" : "none";
    const hint = document.getElementById("pkAutoHint");
    if (hint) {
        hint.style.display = idle ? "" : "none";
        if (idle) hint.textContent = pkAutoHintText(g);
    }
    const pill = document.getElementById("pkAutoOpenBtn");
    if (pill) pill.classList.toggle("dim", !idle);
    const live = document.getElementById("pkAutoLive");
    if (idle && live && !live.hidden) live.hidden = true;
    if (idle) pkAutoSelRender(g);
    else if (!run) pkAutoSelClearBadges(g);
    const btn = document.getElementById(G.startBtn);
    if (btn) {
        btn.classList.toggle("pk-stop", !!run);
        if (run) {
            btn.textContent = run.stopRequested ? "Останавливаю…" : "Остановить";
            btn.classList.toggle("dim", !!run.stopRequested);
        }
    }
}

function pkAutoRandomPath(g, len) {
    if (g === "mines") {
        const pool = [];
        for (let i = 0; i < 25; i++) pool.push(i);
        for (let i = pool.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [pool[i], pool[j]] = [pool[j], pool[i]];
        }
        return pool.slice(0, len);
    }
    const out = [];
    for (let i = 0; i < len; i++) out.push(Math.floor(Math.random() * LADDER_COLUMNS));
    return out;
}

function pkAutoCellClick(e) {
    const mines = e.target.closest("#minesGrid .gv-mine-cell");
    const ladder = mines ? null : e.target.closest("#ladderGrid .gv-ladder-cell");
    const g = mines ? "mines" : ladder ? "ladder" : null;
    if (!g || !pkAutoIdle(g)) return;
    const sel = pkAutoSel[g];
    const max = PK_AUTO_GAMES[g].maxLen();
    if (g === "mines") {
        const idx = parseInt(mines.dataset.idx, 10);
        const at = sel.indexOf(idx);
        if (at >= 0) sel.splice(at, 1);
        else if (sel.length >= max) {
            showToast("На поле с " + minesCount + " минами можно выбрать не больше " + max + " клеток", "warning");
            return;
        } else sel.push(idx);
    } else {
        const level = parseInt(ladder.dataset.level, 10);
        const col = parseInt(ladder.dataset.col, 10);
        if (level > sel.length) {
            showToast("Выбирайте уровни по порядку, снизу вверх", "warning");
            return;
        }
        if (level === sel.length) sel.push(col);
        else if (sel[level] === col && level === sel.length - 1) sel.pop();
        else sel[level] = col;
    }
    haptic("selection");
    pkAutoSync(g);
}

function pkAutoRandClick(g) {
    if (!pkAutoIdle(g)) return;
    const max = PK_AUTO_GAMES[g].maxLen();
    const len = Math.min(max, pkAutoSel[g].length || 3);
    pkAutoSel[g] = pkAutoRandomPath(g, len);
    haptic("selection");
    pkAutoSync(g);
}

function pkAutoClearClick(g) {
    if (!pkAutoIdle(g)) return;
    pkAutoSel[g] = [];
    haptic("selection");
    pkAutoSync(g);
}

function pkAutoAlive(run) {
    return pkAutoRun === run && run.active;
}

function pkAutoLock(g, on) {
    if (g === "mines") {
        minesBusy = on;
        setMinesPanelLocked(on);
    } else {
        ladderBusy = on;
        setLadderPanelLocked(on);
    }
    const grid = document.getElementById(PK_AUTO_GAMES[g].grid);
    if (grid && grid.parentElement) grid.parentElement.classList.toggle("pk-running", on);
}

function pkAutoResetBoard(g) {
    if (g === "mines") resetMinesGrid();
    else resetLadderGrid();
}

function pkAutoStart() {
    const g = pkAutoGame;
    const G = PK_AUTO_GAMES[g];
    if (!pkAutoIdle(g)) {
        pkAutoCloseModal();
        return;
    }
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const cfg = pkAutoServerCfg(g);
    if (!cfg.enabled) {
        showToast("Авто-игра сейчас отключена", "warning");
        return;
    }
    const path = pkAutoSel[g].slice();
    if (!path.length) {
        showToast("Сначала выберите клетки на поле", "error");
        return;
    }
    if (path.length > G.maxLen()) {
        showToast("Выбрано больше клеток, чем безопасных на поле", "error");
        return;
    }
    const s = pkAutoSettings(g);
    const bet = pkAutoNum(s.bet);
    if (!(bet > 0)) {
        showToast("Введите сумму ставки", "error");
        return;
    }
    if (bet > currentUser.balance + 1e-9) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    if (bet < betMin(G.limit) - 1e-9) {
        showToast("Минимальная ставка — " + fmtNum(betMin(G.limit)) + "⭐️", "error");
        return;
    }
    if (bet > betMax(G.limit) + 1e-9) {
        showToast("Максимальная ставка — " + fmtNum(betMax(G.limit)) + "⭐️", "error");
        return;
    }
    const p = pkAutoParse(g);
    if (!p) return;
    if (cfg.maxBet > 0 && bet > cfg.maxBet + 1e-9) {
        showToast("В авто-игре ставка не больше " + fmtNum(cfg.maxBet) + "⭐️", "error");
        return;
    }
    if (p.cap && bet > p.cap + 1e-9) {
        showToast("Потолок ставки ниже вашей ставки", "error");
        return;
    }
    const run = {
        g: g,
        active: true,
        sid: null,
        p: p,
        cfg: cfg,
        total: p.rounds ? Math.min(p.rounds, cfg.maxRounds) : cfg.maxRounds,
        base: gvRound2(bet),
        bet: gvRound2(bet),
        count: G.count(),
        path: path,
        round: 0,
        wins: 0,
        losses: 0,
        staked: 0,
        returned: 0,
        dots: [],
        stopReason: null,
        stopRequested: null,
        lastAt: 0,
        retry: 0,
        timer: null,
        inflight: false,
        revealing: false,
        finishPending: null,
        finishSent: false,
        reason: null,
        lastData: null,
        pendingBalance: null,
        minDelay: cfg.minDelayMs + 40
    };
    pkAutoRun = run;
    pkAutoCloseModal();
    pkAutoLock(g, true);
    pkAutoShowLive(true);
    pkAutoPaintLive(false);
    pkAutoSync(g);
    haptic("impact", "medium");
    fetch("/api/" + g + "/auto/start", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            params: {
                rounds: p.rounds,
                stopWin: p.stopWin,
                profit: p.profit,
                loss: p.loss,
                bigWin: p.bigWin,
                cap: p.cap,
                onLoss: p.onLoss,
                lossPct: p.lossPct,
                onWin: p.onWin,
                winPct: p.winPct,
                picks: p.picks,
                speed: p.speed,
                bet: run.bet,
                count: run.count,
                len: path.length
            }
        })
    }).then(r => r.json()).then(d => {
        if (!pkAutoAlive(run)) return;
        if (!d || !d.ok) {
            pkAutoStartFailed(run, d);
            return;
        }
        run.sid = d.sid;
        run.cfg = {
            enabled: true,
            maxRounds: d.maxRounds,
            minDelayMs: d.minDelayMs,
            maxBet: d.maxBet
        };
        pkAutoCfg[g] = run.cfg;
        run.minDelay = d.minDelayMs + 40;
        run.total = p.rounds ? Math.min(p.rounds, d.maxRounds) : d.maxRounds;
        if (d.maxBet > 0 && run.bet > d.maxBet + 1e-9) {
            pkAutoStartFailed(run, {
                error: "В авто-игре ставка не больше " + fmtNum(d.maxBet) + "⭐️"
            });
            return;
        }
        pkAutoPaintLive(false);
        pkAutoStep(run);
    }).catch(() => {
        if (pkAutoAlive(run)) pkAutoStartFailed(run, null);
    });
}

function pkAutoStartFailed(run, data) {
    run.active = false;
    if (data && data.autoCode === "off" && pkAutoCfg[run.g]) pkAutoCfg[run.g].enabled = false;
    pkAutoLock(run.g, false);
    pkAutoShowLive(false);
    const btn = document.getElementById(PK_AUTO_GAMES[run.g].startBtn);
    if (btn) btn.classList.remove("pk-stop", "dim");
    if (run.g === "mines") {
        setMinesStartBtn("start");
        updateMinesStartState();
    } else {
        setLadderStartBtn("start");
        updateLadderStartState();
    }
    pkAutoSync(run.g);
    showToast(data && data.error || "Не удалось связаться с сервером", "error");
}

function pkAutoClampBet(run) {
    const G = PK_AUTO_GAMES[run.g];
    let cap = betMax(G.limit);
    if (run.cfg.maxBet > 0) cap = Math.min(cap, run.cfg.maxBet);
    if (run.p.cap) cap = Math.min(cap, run.p.cap);
    return gvRound2(Math.min(Math.max(run.bet, betMin(G.limit)), cap));
}

function pkAutoStep(run) {
    if (!pkAutoAlive(run)) return;
    if (!document.getElementById(PK_AUTO_GAMES[run.g].grid)) {
        pkAutoAbort("user");
        return;
    }
    const reason = run.stopReason || run.stopRequested;
    if (reason) {
        pkAutoFinish(run, reason);
        return;
    }
    const bet = pkAutoClampBet(run);
    if (bet > currentUser.balance + 1e-9) {
        pkAutoFinish(run, "balance");
        return;
    }
    run.bet = bet;
    pkAutoPaintLive(false);
    const wait = run.lastAt + run.minDelay - Date.now();
    if (wait > 0) run.timer = setTimeout(() => pkAutoFire(run), wait);
    else pkAutoFire(run);
}

function pkAutoFire(run) {
    if (!pkAutoAlive(run)) return;
    const g = run.g;
    const G = PK_AUTO_GAMES[g];
    run.lastAt = Date.now();
    run.inflight = true;
    const path = run.p.picks === "random" ? pkAutoRandomPath(g, run.path.length) : run.path.slice();
    run.curPath = path;
    pkAutoResetBoard(g);
    if (run.p.picks !== "random") pkAutoSelRender(g);
    const body = {
        uid: CURRENT_UID,
        bet: run.bet,
        autoSid: run.sid
    };
    body[G.countKey] = run.count;
    body[G.pathKey] = path;
    fetch("/api/" + g + "/auto/round", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify(body)
    }).then(r => r.json()).then(data => {
        run.inflight = false;
        if (!pkAutoAlive(run)) {
            if (data && data.ok && typeof data.balance === "number") applyBalance(data.balance);
            if (run.finishPending) pkAutoSendFinish(run, run.finishPending);
            return;
        }
        if (!data || !data.ok) {
            pkAutoFail(run, data);
            return;
        }
        pkAutoResult(run, data);
    }).catch(() => {
        run.inflight = false;
        if (!pkAutoAlive(run)) {
            if (run.finishPending) pkAutoSendFinish(run, run.finishPending);
            return;
        }
        pkAutoFinish(run, "error");
    });
}

function pkAutoFail(run, data) {
    const code = data && data.autoCode;
    const msg = data && data.error || "Ошибка сервера";
    if (data && data.betsPaused) {
        pkAutoFinish(run, "bets");
        return;
    }
    if (code === "fast" && run.retry < 3) {
        run.retry += 1;
        run.timer = setTimeout(() => pkAutoFire(run), run.minDelay);
        return;
    }
    if (code === "limit") {
        pkAutoFinish(run, "limit");
        return;
    }
    if (code === "off") {
        if (pkAutoCfg[run.g]) pkAutoCfg[run.g].enabled = false;
        pkAutoFinish(run, "off");
        return;
    }
    if (code === "session") {
        pkAutoFinish(run, "broken");
        return;
    }
    if (/Недостаточно средств/.test(msg)) {
        pkAutoFinish(run, "balance");
        return;
    }
    showToast(msg, "error");
    pkAutoFinish(run, code === "cap" ? "other" : "error");
}

function pkAutoAnimate(run, data, done) {
    const g = run.g;
    const speed = PK_AUTO_SPEEDS[run.p.speed];
    const path = data.path || [];
    const win = !!data.win;
    const steps = path.length;
    const paintStep = i => {
        const last = i === steps - 1;
        if (g === "mines") {
            setMinesGridCell(path[i], last && !win ? "hit" : "open");
            minesCellsOpened = last && !win ? i : i + 1;
        } else {
            setLadderCell(i, path[i], last && !win ? "hit" : "open");
            ladderLevel = last && !win ? i : i + 1;
        }
    };
    const finishBoard = () => {
        if (g === "mines") {
            const mines = data.minePositions || [];
            mines.forEach(p => {
                if (p !== data.hitIndex) setMinesGridCell(p, "bomb");
            });
            minesCellsOpened = data.cellsOpened;
        } else {
            ladderFullRevealGrid(data.stonePositions, data.hitPosition);
            ladderLevel = data.level;
        }
        done();
    };
    if (!speed.step) {
        for (let i = 0; i < steps; i++) paintStep(i);
        finishBoard();
        return;
    }
    let i = 0;
    const tick = () => {
        if (!pkAutoAlive(run)) {
            finishBoard();
            return;
        }
        if (i >= steps) {
            run.timer = setTimeout(finishBoard, speed.step);
            return;
        }
        paintStep(i);
        i += 1;
        run.timer = setTimeout(tick, speed.step);
    };
    tick();
}

function pkAutoFlushBalance(run) {
    if (run.pendingBalance !== null) {
        applyBalance(run.pendingBalance);
        run.pendingBalance = null;
    }
}

function pkAutoResult(run, data) {
    const g = run.g;
    run.retry = 0;
    run.lastData = data;
    run.pendingBalance = typeof data.balance === "number" ? data.balance : null;
    run.revealing = true;
    if (g === "mines") {
        minesCurrentRoundInfo = {
            roundId: data.roundId,
            seedHash: data.seedHash,
            serverSeed: data.serverSeed,
            minesCount: run.count,
            status: "finished"
        };
        updateMinesRoundIdLabel();
    } else {
        ladderCurrentRoundInfo = {
            roundId: data.roundId,
            seedHash: data.seedHash,
            serverSeed: data.serverSeed,
            stonesCount: run.count,
            status: "finished"
        };
        updateLadderRoundIdLabel();
    }
    pkAutoAnimate(run, data, () => {
        run.revealing = false;
        if (!pkAutoAlive(run)) {
            pkAutoFlushBalance(run);
            return;
        }
        const win = !!data.win;
        const bet = Number(data.betAmount) || run.bet;
        const payout = win ? Number(data.winAmount) || 0 : 0;
        pkAutoFlushBalance(run);
        run.round += 1;
        run.staked += bet;
        run.returned += payout;
        if (win) run.wins += 1;
        else run.losses += 1;
        run.dots.push(win);
        pkAutoAfterRound(run, win, payout);
        pkAutoPaintLive(true);
        if (run.round % 5 === 0) {
            if (run.g === "mines") loadMinesHistory();
            else loadLadderHistory();
        }
        const pause = PK_AUTO_SPEEDS[run.p.speed].pause;
        run.timer = setTimeout(() => pkAutoStep(run), pause);
    });
}

function pkAutoAfterRound(run, win, payout) {
    const p = run.p;
    if (win) {
        if (p.onWin === "reset") run.bet = run.base;
        else if (p.onWin === "up") run.bet = run.bet * (1 + p.winPct / 100);
    } else if (p.onLoss === "up") {
        run.bet = run.bet * (1 + p.lossPct / 100);
    }
    run.bet = gvRound2(run.bet);
    const net = run.returned - run.staked;
    let reason = null;
    if (p.stopWin && win) reason = "win";
    else if (p.profit && net >= p.profit - 1e-9) reason = "profit";
    else if (p.loss && -net >= p.loss - 1e-9) reason = "loss";
    else if (p.bigWin && win && payout >= p.bigWin - 1e-9) reason = "bigwin";
    else if (run.round >= run.total) reason = p.rounds ? "done" : "limit";
    run.stopReason = reason;
}

function pkAutoRequestStop(reason) {
    const run = pkAutoRun;
    if (!run || !run.active || run.stopRequested) return;
    run.stopRequested = reason;
    if (!run.inflight && !run.revealing) {
        clearTimeout(run.timer);
        pkAutoFinish(run, run.stopReason || reason);
        return;
    }
    pkAutoSync(run.g);
}

function pkAutoSendFinish(run, reason) {
    if (!run.sid || run.finishSent) return;
    run.finishSent = true;
    fetch("/api/" + run.g + "/auto/finish", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        keepalive: true,
        body: JSON.stringify({
            uid: CURRENT_UID,
            sid: run.sid,
            reason: reason
        })
    }).catch(() => {});
}

function pkAutoFinish(run, reason) {
    if (!pkAutoAlive(run)) return;
    const g = run.g;
    run.active = false;
    run.reason = reason;
    clearTimeout(run.timer);
    pkAutoFlushBalance(run);
    pkAutoSendFinish(run, reason);
    pkAutoLock(g, false);
    const btn = document.getElementById(PK_AUTO_GAMES[g].startBtn);
    if (btn) btn.classList.remove("pk-stop", "dim");
    const data = run.lastData;
    if (data) {
        const win = !!data.win;
        if (g === "mines") {
            minesBet = Number(data.betAmount) || run.bet;
            minesFinishedInfo = {
                win: win,
                winAmount: data.winAmount,
                mult: data.multiplier,
                hitIndex: data.hitIndex
            };
            minesCellsOpened = data.cellsOpened;
            updateMinesMultRow();
            setMinesStartBtn("again");
            updateMinesStatus();
            loadMinesHistory();
        } else {
            ladderBet = Number(data.betAmount) || run.bet;
            ladderFinishedInfo = {
                win: win,
                winAmount: data.winAmount,
                mult: data.multiplier
            };
            ladderLevel = data.level;
            updateLadderMultRow();
            setLadderStartBtn("again");
            refreshLadderGridLocks();
            updateLadderStatus();
            loadLadderHistory();
        }
    } else if (g === "mines") {
        setMinesStartBtn("start");
        updateMinesStartState();
    } else {
        setLadderStartBtn("start");
        updateLadderStartState();
    }
    pkAutoSync(g);
    if (run.round) pkAutoPaintLive(false);
    else pkAutoShowLive(false);
    pkAutoToast(run);
}

function pkAutoAbort(reason) {
    const run = pkAutoRun;
    if (!run || !run.active) return;
    run.active = false;
    run.reason = reason;
    clearTimeout(run.timer);
    pkAutoFlushBalance(run);
    pkAutoLock(run.g, false);
    if (run.inflight) run.finishPending = reason;
    else pkAutoSendFinish(run, reason);
}

function pkAutoToast(run) {
    if (!run.round) return;
    const net = Math.round((run.returned - run.staked) * 100) / 100;
    if (net > 0) showGameWinToast(net, "Итог серии +", "⭐️");
    else if (net < 0) showGameLoseToast("Итог серии: −" + fmtNum(-net) + "⭐️");
    else showToast("Серия окончена: вы в нуле", "warning");
}

function pkAutoReset() {
    pkAutoAbort("user");
    pkAutoRun = null;
}

document.addEventListener("click", e => {
    const open = e.target.closest("[data-pk-open]");
    if (open) {
        pkAutoOpen(open.dataset.pkOpen);
        return;
    }
    if (e.target.closest("#pkAutoRandBtn")) {
        pkAutoRandClick(document.getElementById("minesGrid") ? "mines" : "ladder");
        return;
    }
    if (e.target.closest("#pkAutoClearBtn")) {
        pkAutoClearClick(document.getElementById("minesGrid") ? "mines" : "ladder");
        return;
    }
    pkAutoCellClick(e);
});

document.addEventListener("visibilitychange", () => {
    if (document.hidden) pkAutoRequestStop("hidden");
});

let kenoPaytableModalRisk = "medium";

function updateKenoPaytableModalTabs() {
    const tabs = document.getElementById("kenoPaytableRiskTabs");
    if (tabs) tabs.querySelectorAll(".mines-bomb-btn").forEach(btn => btn.classList.toggle("selected", btn.dataset.kenoPaytableRisk === kenoPaytableModalRisk));
}

function renderKenoPaytableModalTable() {
    const picksCount = kenoPicks.length || 10;
    const label = document.getElementById("kenoPaytablePicksLabel");
    if (label) label.textContent = "Если выбрано " + picksCount + " " + (picksCount === 1 ? "число" : "чисел") + ":";
    const row = document.getElementById("kenoPaytableMultRow");
    if (!row) return;
    row.innerHTML = '<div class="gv-mult-chip now">Загрузка…</div>';
    fetch("/api/keno/paytable?risk=" + kenoPaytableModalRisk + "&picksCount=" + picksCount).then(r => r.json()).then(data => {
        if (!data || !data.ok) return;
        const table = data.table || {};
        let chips = "";
        for (let h = 0; h <= picksCount; h++) {
            const v = table[h];
            if (v === undefined) continue;
            chips += (h > 0 ? '<span class="gv-mult-arrow">›</span>' : "") + '<span class="gv-mult-chip">' + h + ": x" + fmtCoef(v) + "</span>";
        }
        row.innerHTML = chips || '<div class="gv-mult-chip now">—</div>';
    }).catch(() => {
        row.innerHTML = '<div class="gv-mult-chip now">Не удалось загрузить</div>';
    });
}

function selectKenoPaytableRisk(risk) {
    if (!KENO_RISK_LABELS[risk] || kenoPaytableModalRisk === risk) return;
    kenoPaytableModalRisk = risk;
    updateKenoPaytableModalTabs();
    renderKenoPaytableModalTable();
}

function openKenoPaytableModal() {
    const modal = document.getElementById("kenoPaytableModal");
    if (!modal) return;
    kenoPaytableModalRisk = kenoRisk;
    updateKenoPaytableModalTabs();
    renderKenoPaytableModalTable();
    setupKenoMultRowScroll("kenoPaytableMultRow");
    modal.classList.add("active");
}

function closeKenoPaytableModal() {
    const modal = document.getElementById("kenoPaytableModal");
    if (modal) modal.classList.remove("active");
}

const kenoPaytableModal = document.getElementById("kenoPaytableModal");

if (kenoPaytableModal) {
    document.getElementById("kenoPaytableClose").addEventListener("click", closeKenoPaytableModal);
    kenoPaytableModal.addEventListener("click", e => {
        if (e.target === kenoPaytableModal) closeKenoPaytableModal();
        const tabBtn = e.target.closest(".mines-bomb-btn[data-keno-paytable-risk]");
        if (tabBtn) selectKenoPaytableRisk(tabBtn.dataset.kenoPaytableRisk);
    });
}

function kenoHowtoExampleHTML() {
    const exPicks = [3, 7, 18, 25];
    const exDrawn = [3, 7, 12, 18, 21, 29, 33, 36, 39, 40];
    const exPickSet = new Set(exPicks);
    const exDrawnSet = new Set(exDrawn);
    let html = '<div class="gv-keno-grid keno-howto-example-grid">';
    for (let n = 1; n <= 40; n++) {
        let cls = "gv-keno-cell";
        if (exPickSet.has(n) && exDrawnSet.has(n)) cls += " hit";
        else if (exDrawnSet.has(n)) cls += " drawn";
        else if (exPickSet.has(n)) cls += " miss";
        html += '<div class="' + cls + '">' + n + "</div>";
    }
    html += "</div>";
    html += '<div class="blackjack-howto-example-total">Выбрано 4, выпало 10, совпало <b>2</b> (числа 3 и 7) — выигрыш считается по таблице коэффициентов для «выбрано 4»</div>';
    return html;
}

function openKenoHowto() {
    const modal = document.getElementById("kenoHowtoModal");
    if (!modal) return;
    const example = document.getElementById("kenoHowtoExample");
    if (example && !example.dataset.filled) {
        example.innerHTML = kenoHowtoExampleHTML();
        example.dataset.filled = "1";
    }
    modal.classList.add("active");
}

function closeKenoHowto() {
    const modal = document.getElementById("kenoHowtoModal");
    if (modal) modal.classList.remove("active");
}

const kenoHowtoModal = document.getElementById("kenoHowtoModal");

if (kenoHowtoModal) {
    document.getElementById("kenoHowtoClose").addEventListener("click", closeKenoHowto);
    document.getElementById("kenoHowtoOk").addEventListener("click", closeKenoHowto);
    kenoHowtoModal.addEventListener("click", e => {
        if (e.target === kenoHowtoModal) closeKenoHowto();
    });
}

let hiloActive = false;

let hiloBusy = false;

let hiloBet = 0;

let hiloCards = [];

let hiloMultiplier = 1.0;

let hiloChoiceMultipliers = {};

let hiloCanCashout = false;

let hiloCashoutAmount = 0;

let hiloHistoryScope = "all";

let hiloCurrentRoundInfo = null;

let hiloFinishedInfo = null;

const HILO_CHOICE_LABEL = {
    higher: "Больше",
    lower: "Меньше",
    same: "Так же"
};

function hiloCardWrapHTML(card, extraClass) {
    return '<span class="hilo-card-wrap' + (extraClass ? " " + extraClass : "") + '">' + blackjackCardImgHTML(card) + "</span>";
}

function hiloCardRowHTML() {
    if (!hiloCards.length) return '<span class="hilo-card-wrap hilo-card-placeholder">' + cardBackCrossHTML() + "</span>";
    return hiloCards.map((c, i) => hiloCardWrapHTML(c, i === hiloCards.length - 1 ? "hilo-card-current" : "hilo-card-past")).join("");
}

function updateHiloCardRow() {
    const row = document.getElementById("hiloCardRow");
    if (row) row.innerHTML = hiloCardRowHTML();
}

function hiloChoiceBtnHTML(choice) {
    const mult = hiloChoiceMultipliers[choice];
    const disabled = mult === null || mult === undefined;
    return '<button class="hilo-choice-btn' + (disabled ? " dim" : "") + '" type="button" data-hilo-choice="' + choice + '"' + (disabled ? " disabled" : "") + '><span class="hilo-choice-label">' + HILO_CHOICE_LABEL[choice] + "</span><span class=\"hilo-choice-mult\">" + (disabled ? "—" : "x" + fmtCoef(mult)) + "</span></button>";
}

function hiloChoicesHTML() {
    return '<div class="hilo-choices" id="hiloChoices">' + ["lower", "same", "higher"].map(hiloChoiceBtnHTML).join("") + "</div>";
}

function updateHiloChoices() {
    const wrap = document.getElementById("hiloChoices");
    if (!wrap) return;
    wrap.outerHTML = hiloChoicesHTML();
}

function hiloStatusHTML() {
    if (hiloActive) {
        return hiloCanCashout ? "Заберёте: <b>" + fmtNum(hiloCashoutAmount) + "⭐️</b> (x" + fmtCoef(hiloMultiplier) + ")" : "Угадайте первую карту, чтобы разблокировать «Забрать»";
    }
    if (hiloFinishedInfo) {
        return hiloFinishedInfo.win ? '<span class="gv-history-win">Выигрыш: ' + fmtNum(hiloFinishedInfo.winAmount) + "⭐️ (x" + fmtCoef(hiloFinishedInfo.multiplier) + ")</span>" : '<span class="gv-history-lose">Не угадали — ставка сгорела</span>';
    }
    return "";
}

function updateHiloStatus() {
    const el = document.getElementById("hiloStatus");
    if (!el) return;
    if (!hiloActive && !hiloFinishedInfo) {
        el.style.display = "none";
        return;
    }
    el.style.display = "";
    el.innerHTML = hiloStatusHTML();
}

function setHiloPanelLocked(locked) {
    const panel = document.getElementById("hiloPanel");
    if (panel) panel.classList.toggle("locked", locked);
}

function setHiloStartBtn(mode) {
    const btn = document.getElementById("hiloStartBtn");
    if (!btn) return;
    btn.classList.remove("dim");
    if (mode === "start") btn.textContent = "Начать игру";
    else if (mode === "active") btn.textContent = hiloCanCashout ? "Забрать " + fmtNum(hiloCashoutAmount) + "⭐️ (x" + fmtCoef(hiloMultiplier) + ")" : "Угадайте карту";
    else if (mode === "again") btn.textContent = "Создать новую игру";
}

function updateHiloCashoutBtn() {
    if (!hiloActive) return;
    const btn = document.getElementById("hiloStartBtn");
    if (!btn) return;
    btn.textContent = hiloCanCashout ? "Забрать " + fmtNum(hiloCashoutAmount) + "⭐️ (x" + fmtCoef(hiloMultiplier) + ")" : "Угадайте карту";
    btn.classList.toggle("dim", !hiloCanCashout || hiloBusy);
}

function updateHiloRoundIdLabel() {
    const el = document.getElementById("hiloRoundIdLabel");
    if (!el) return;
    const roundId = hiloCurrentRoundInfo && hiloCurrentRoundInfo.roundId;
    if (roundId) {
        el.textContent = roundId;
        el.classList.remove("text-skel");
    } else {
        el.textContent = "HXXXXXXXX";
        el.classList.add("text-skel");
    }
}

function hiloReadyState() {
    const betInput = gvBody.querySelector(".gv-bet-input");
    const bet = betInput ? parseFloat(betInput.value) : NaN;
    return {
        bet: bet,
        hasBet: bet > 0,
        enoughBalance: bet > 0 && bet <= currentUser.balance + 1e-6,
        overMax: bet > betMax("hilo"),
        underMin: bet > 0 && bet < betMin("hilo")
    };
}

function updateHiloStartState() {
    const btn = document.getElementById("hiloStartBtn");
    if (!btn || hiloActive) return;
    const state = hiloReadyState();
    const ready = !hiloBusy && betsAccepted && state.hasBet && state.enoughBalance && !state.overMax && !state.underMin;
    btn.classList.toggle("dim", !ready);
}

function applyHiloState(state) {
    hiloCards = state.cards || [];
    hiloMultiplier = state.multiplier || 1.0;
    hiloChoiceMultipliers = state.choiceMultipliers || {};
    hiloCanCashout = !!state.canCashout;
    hiloCashoutAmount = state.cashoutAmount || 0;
    hiloCurrentRoundInfo = {
        roundId: state.roundId,
        seedHash: state.seedHash,
        serverSeed: null,
        status: "active"
    };
    updateHiloRoundIdLabel();
    updateHiloCardRow();
    updateHiloChoices();
    updateHiloStatus();
    updateHiloCashoutBtn();
}

function resetHiloUI() {
    hiloActive = false;
    hiloBusy = false;
    hiloCards = [];
    hiloMultiplier = 1.0;
    hiloChoiceMultipliers = {};
    hiloCanCashout = false;
    hiloCashoutAmount = 0;
    hiloCurrentRoundInfo = null;
    hiloFinishedInfo = null;
    setHiloPanelLocked(false);
    setHiloStartBtn("start");
    updateHiloCardRow();
    const choicesWrap = document.getElementById("hiloChoices");
    if (choicesWrap) choicesWrap.style.display = "none";
    updateHiloStatus();
    updateHiloStartState();
    updateHiloRoundIdLabel();
}

function playHilo() {
    if (hiloBusy || hiloActive) return;
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const state = hiloReadyState();
    if (!state.hasBet) return;
    if (!state.enoughBalance) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    if (state.underMin) {
        showToast("Минимальная ставка — " + fmtNum(betMin("hilo")) + "⭐️", "error");
        return;
    }
    if (state.overMax) {
        showToast("Максимальная ставка — " + fmtNum(betMax("hilo")) + "⭐️", "error");
        return;
    }
    hiloBusy = true;
    hiloBet = state.bet;
    document.getElementById("hiloStartBtn").classList.add("dim");
    fetch("/api/hilo/start", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            bet: hiloBet
        })
    }).then(r => r.json()).then(data => {
        hiloBusy = false;
        if (!data || !data.ok) {
            showToast(data && data.error || "Ошибка сервера", "error");
            updateHiloStartState();
            return;
        }
        hiloActive = true;
        hiloFinishedInfo = null;
        if (typeof data.balance === "number") applyBalance(data.balance);
        applyHiloState(data);
        setHiloPanelLocked(true);
        setHiloStartBtn("active");
        const choicesWrap = document.getElementById("hiloChoices");
        if (choicesWrap) choicesWrap.style.display = "";
    }).catch(() => {
        hiloBusy = false;
        showToast("Не удалось связаться с сервером", "error");
        updateHiloStartState();
    });
}

function hiloFinish(data) {
    hiloActive = false;
    hiloFinishedInfo = {
        win: data.win,
        winAmount: data.winAmount,
        multiplier: data.multiplier,
        busted: data.busted
    };
    hiloCards = data.cards || hiloCards;
    hiloCurrentRoundInfo = {
        roundId: data.roundId,
        seedHash: data.seedHash,
        serverSeed: data.serverSeed,
        status: "finished",
        multiplier: data.multiplier
    };
    updateHiloRoundIdLabel();
    if (typeof data.balance === "number") applyBalance(data.balance);
    updateHiloCardRow();
    const choicesWrap = document.getElementById("hiloChoices");
    if (choicesWrap) choicesWrap.style.display = "none";
    setHiloPanelLocked(false);
    setHiloStartBtn("again");
    updateHiloStatus();
    if (data.win) showGameWinToast(data.winAmount, "Выигрыш ", "⭐️!");
    else showGameLoseToast("Не угадали — ставка сгорела");
    loadHiloHistory(null, true);
}

function guessHilo(choice) {
    if (hiloBusy || !hiloActive) return;
    if (hiloChoiceMultipliers[choice] === null || hiloChoiceMultipliers[choice] === undefined) return;
    hiloBusy = true;
    const wrap = document.getElementById("hiloChoices");
    if (wrap) wrap.classList.add("busy");
    fetch("/api/hilo/guess", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            choice: choice
        })
    }).then(r => r.json()).then(data => {
        hiloBusy = false;
        if (wrap) wrap.classList.remove("busy");
        if (!data || !data.ok) {
            showToast(data && data.error || "Ошибка сервера", "error");
            return;
        }
        if (data.active === false) {
            hiloFinish(data);
            return;
        }
        applyHiloState(data);
        haptic("selection");
    }).catch(() => {
        hiloBusy = false;
        if (wrap) wrap.classList.remove("busy");
        showToast("Не удалось связаться с сервером", "error");
    });
}

function cashoutHilo() {
    if (hiloBusy || !hiloActive || !hiloCanCashout) return;
    hiloBusy = true;
    document.getElementById("hiloStartBtn").classList.add("dim");
    fetch("/api/hilo/cashout", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID
        })
    }).then(r => r.json()).then(data => {
        hiloBusy = false;
        if (!data || !data.ok) {
            showToast(data && data.error || "Ошибка сервера", "error");
            updateHiloCashoutBtn();
            return;
        }
        hiloFinish(data);
    }).catch(() => {
        hiloBusy = false;
        showToast("Не удалось связаться с сервером", "error");
        updateHiloCashoutBtn();
    });
}

function renderHilo(data) {
    return '<div class="gv-mines-box blackjack-table-box hilo-table">' + '<div class="hilo-card-row" id="hiloCardRow">' + hiloCardRowHTML() + "</div>" + '<div class="mines-status" id="hiloStatus" style="display:none;"></div>' + hiloChoicesHTML() + '<div class="gv-mines-howto">' + '<div class="gv-fair" data-action="hilo-fair"><span class="gv-fair-icon">#</span><span id="hiloRoundIdLabel" class="text-skel">HXXXXXXXX</span></div>' + howtoHTML("position:static;") + "</div>" + "</div>" + '<div class="gv-panel" id="hiloPanel">' + '<div class="gv-label">Сумма ставки</div>' + betRowHTML() + "</div>" + '<button class="gv-start-btn dim" type="button" id="hiloStartBtn">Начать игру</button>' + '<div class="gv-history">' + '<div class="gv-history-head">' + '<h3 class="gv-history-title">' + lazyImgTag(liteAsset("/lottie/images/ОгоньЭмоджи.lottie"), "", "flame-gif") + " Последние игры</h3>" + '<div class="gv-history-tabs">' + '<button class="gv-history-tab active" type="button" data-hilo-scope="all">Все</button>' + '<button class="gv-history-tab" type="button" data-hilo-scope="mine">Мои</button>' + "</div>" + "</div>" + gvHistorySearchRowHTML("hiloHistorySearchInput") + '<div class="gv-history-list" id="hiloHistoryList"><div class="dice-history-empty">Загрузка…</div></div>' + "</div>";
}

function initHiloGame(data) {
    resetHiloUI();
    loadHiloHistory();
    gvHistoryWireSearch("hiloHistorySearchInput", () => loadHiloHistory(), value => {
        gvHistorySearch("hiloHistoryList", () => "/api/hilo/history?uid=" + CURRENT_UID + "&scope=" + hiloHistoryScope + "&q=" + encodeURIComponent(value), rows => {
            document.getElementById("hiloHistoryList").innerHTML = rows.map(hiloHistoryRowHTML).join("");
        });
    });
    fetch("/api/hilo/state?uid=" + CURRENT_UID).then(r => r.json()).then(st => {
        if (!st || !st.ok || hiloActive) return;
        if (typeof st.balance === "number") applyBalance(st.balance);
        if (!st.active) return;
        hiloActive = true;
        hiloBet = st.bet;
        applyHiloState(st);
        const betInput = gvBody.querySelector(".gv-bet-input");
        if (betInput) betInput.value = st.bet + "⭐️";
        setHiloPanelLocked(true);
        setHiloStartBtn("active");
        const choicesWrap = document.getElementById("hiloChoices");
        if (choicesWrap) choicesWrap.style.display = "";
    }).catch(() => {});
}

function hiloHistoryRowHTML(r) {
    let meta = {};
    try {
        meta = JSON.parse(r.meta || "{}");
    } catch (e) {}
    const isWin = r.result === "win";
    const isMe = r.user_id === CURRENT_UID;
    const botBadge = r.in_chat || meta.inChat ? '<span class="gv-history-bot-badge">Чат</span>' : meta.playedInBot ? '<span class="gv-history-bot-badge">Бот</span>' : "";
    const name = isMe ? currentUser.displayName || "Игрок" : r.username || "Игрок";
    const avatarUrl = isMe ? currentUser.avatarUrl : "/api/avatar/" + r.user_id;
    const steps = meta.cards ? meta.cards.length - 1 : "—";
    return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-avatar"><div class="skel-box"></div>' + lazyImgTag(avatarUrl, name) + "</div>" + '<div class="gv-history-mid">' + '<div class="gv-history-name"><span class="gv-history-name-text">' + escapeHtml(name) + "</span>" + botBadge + "</div>" + historyTimeHTML(r.created_at) + "</div>" + '<div class="gv-history-right">Сумма ставки: <b>' + fmtNum(r.bet) + "⭐️</b><br>" + '<span class="gv-history-outcome">Верных шагов: <b>' + steps + "</b></span><br>" + (isWin ? '<span class="gv-history-win">Выигрыш: ' + fmtNum(r.win_amount) + "⭐️ (x" + fmtCoef(meta.multiplier) + ")</span>" : '<span class="gv-history-lose">Проигрыш</span>') + "</div>" + "</div>" + (meta.roundId ? '<button class="crash-history-fair-btn" type="button" data-hilo-round="' + escapeHtml(meta.roundId) + '">' + fairCheckBtnIconHTML() + "Проверить честность</button>" : "") + "</div>";
}

function loadHiloHistory(scope, append) {
    if (scope) {
        hiloHistoryScope = scope;
        append = false;
    }
    gvHistoryLoad("hiloHistoryList", off => "/api/hilo/history?uid=" + CURRENT_UID + "&scope=" + hiloHistoryScope + "&offset=" + off, 20, (rows, append) => {
        const list = document.getElementById("hiloHistoryList");
        const html = rows.map(hiloHistoryRowHTML).join("");
        if (append) list.insertAdjacentHTML("beforeend", html);
        else list.innerHTML = html;
    }, GV_HISTORY_EMPTY_HTML, append);
}

GV_HISTORY_BY_GAME["hilo"] = {
    listId: "hiloHistoryList",
    load: () => loadHiloHistory(null, true)
};

function hiloFairFormulaHTML() {
    return '<p class="modal-text">Формула, которую можно пересчитать самостоятельно (пример на Python — hmac.new(seed.encode(), f"{uid}:{i}".encode(), hashlib.sha256)):</p>' + '<ol class="fair-formula-steps">' + "<li>Для карты на шаге i (0 - самая первая карта раунда) считаем H_i = HMAC-SHA256(секретный сид, \"UID раунда:i\")</li>" + "<li>Первые 8 hex-символов H_i → номер ранга (0..12) через остаток от деления на 13</li>" + "<li>Следующие 8 hex-символов H_i → номер масти (0..3) через остаток от деления на 4</li>" + "</ol>" + '<p class="modal-text">Последовательность карт обязана совпасть с картами раунда — если хэш выше совпадает с SHA-256(сид), а расчёт даёт другие карты, значит подменили сид или UID.</p>';
}

function openHiloFair() {
    const info = hiloCurrentRoundInfo;
    const roundId = info && info.roundId;
    if (roundId) {
        gvFairId.textContent = roundId;
        gvFairId.classList.remove("text-skel");
    } else {
        gvFairId.textContent = "HXXXXXXXX";
        gvFairId.classList.add("text-skel");
    }
    if (info && info.seedHash) setFairHashEl(gvFairHash, info.seedHash);
    else setFairHashSkeleton(gvFairHash);
    let resultHtml = '<div class="fair-block"><div class="fair-label">UID раунда</div><div class="fair-hash"' + (roundId ? ' data-copy="' + escapeHtml(roundId) + '">' + fairHashHTML(roundId) : ">" + fairHashSkeletonHTML()) + "</div></div>";
    if (info && info.status === "finished" && info.serverSeed) {
        resultHtml += '<div class="fair-block"><div class="fair-label">Секретный сид</div><div class="fair-hash" data-copy="' + escapeHtml(info.serverSeed) + '">' + fairHashHTML(info.serverSeed) + "</div></div>";
        gvFairNote.style.display = "";
        gvFairNote.innerHTML = hiloFairFormulaHTML();
    } else if (info && info.status === "active") {
        resultHtml += '<div class="fair-result-note">Раунд ещё не завершён — сид раскроется сразу после окончания игры.</div>';
        gvFairNote.style.display = "none";
    } else {
        resultHtml += '<div class="fair-result-note">Начните игру, чтобы получить UID и хэш текущего раунда.</div>';
        gvFairNote.style.display = "none";
    }
    gvFairResult.innerHTML = resultHtml;
    gvFairLink.style.display = "none";
    gvFairModal.classList.add("active");
}

const hiloRoundModal = document.getElementById("hiloRoundModal");

const hiloRoundBoard = document.getElementById("hiloRoundBoard");

const hiloRoundPlayerRow = document.getElementById("hiloRoundPlayerRow");

const hiloRoundFairBlock = document.getElementById("hiloRoundFairBlock");

let hiloRoundData = null;

function hiloRoundBoardHTML(detail) {
    const cards = detail.cards || [];
    const busted = !!detail.busted && detail.result !== "win";
    return cards.map((c, i) => hiloCardWrapHTML(c, i === 0 ? "" : busted && i === cards.length - 1 ? "hilo-card-bust" : "hilo-card-win")).join("");
}

function hiloRoundPlayerRowHTML(detail) {
    const isMe = detail.userId === CURRENT_UID;
    const name = isMe ? currentUser.displayName || "Игрок" : detail.username || "Игрок";
    const avatarUrl = isMe ? currentUser.avatarUrl : "/api/avatar/" + detail.userId;
    const isWin = detail.result === "win";
    const steps = (detail.cards || []).length - 1;
    return '<div class="crash-player-row' + (isMe ? " me" : "") + '">' + '<div class="crash-player-avatar"><img src="' + avatarUrl + '" alt="" loading="lazy"></div>' + '<div class="crash-player-mid">' + '<div class="crash-player-name"><span class="crash-player-name-text">' + escapeHtml(name) + "</span>" + (isMe ? ' <span class="lb-you-tag">Вы</span>' : "") + "</div>" + '<div class="crash-player-sub">Ставка: ' + fmtNum(detail.bet) + "⭐️ · Верных шагов: " + steps + "</div>" + "</div>" + (detail.multiplier != null ? '<div class="crash-player-mult">x' + fmtCoef(detail.multiplier) + "</div>" : "") + '<div class="crash-player-value">' + (isWin ? "+" + fmtNum(detail.winAmount) + "⭐️" : "Проигрыш") + "</div>" + "</div>";
}

function hiloRoundBoardSkeletonHTML() {
    return '<span class="hilo-card-wrap skel"></span><span class="hilo-card-wrap skel"></span><span class="hilo-card-wrap skel"></span>';
}

function openHiloRoundModal(publicId) {
    if (!publicId || !hiloRoundModal) return;
    hiloRoundData = null;
    hiloRoundFairBlock.style.display = "none";
    hiloRoundFairBlock.innerHTML = "";
    document.getElementById("hiloRoundFairBtn").textContent = "Проверить честность";
    document.getElementById("hiloRoundModalId").textContent = publicId;
    hiloRoundBoard.innerHTML = hiloRoundBoardSkeletonHTML();
    hiloRoundPlayerRow.innerHTML = minesRoundPlayerSkeletonHTML();
    hiloRoundModal.classList.add("active");
    fetch("/api/hilo/round?id=" + encodeURIComponent(publicId)).then(r => r.json()).then(data => {
        if (!hiloRoundModal.classList.contains("active")) return;
        if (!data || !data.ok) {
            hiloRoundPlayerRow.innerHTML = '<div class="crash-players-empty">Раунд не найден</div>';
            return;
        }
        hiloRoundData = data;
        hiloRoundBoard.innerHTML = hiloRoundBoardHTML(data);
        hiloRoundPlayerRow.innerHTML = hiloRoundPlayerRowHTML(data);
    }).catch(() => {
        hiloRoundPlayerRow.innerHTML = '<div class="crash-players-empty">Не удалось загрузить раунд</div>';
    });
}

function closeHiloRoundModal() {
    hiloRoundModal.classList.remove("active");
}

if (hiloRoundModal) {
    document.getElementById("hiloRoundClose").addEventListener("click", closeHiloRoundModal);
    hiloRoundModal.addEventListener("click", e => {
        if (e.target === hiloRoundModal) closeHiloRoundModal();
    });
    document.getElementById("hiloRoundFairBtn").addEventListener("click", () => {
        const data = hiloRoundData;
        if (!data) return;
        const isHidden = hiloRoundFairBlock.style.display === "none";
        if (isHidden) {
            hiloRoundFairBlock.innerHTML = '<div class="fair-block"><div class="fair-label">UID раунда</div><div class="fair-hash" data-copy="' + escapeHtml(data.roundId) + '">' + fairHashHTML(data.roundId) + "</div></div>" + '<div class="fair-block"><div class="fair-label">SHA-256 hash</div><div class="fair-hash" data-copy="' + escapeHtml(data.seedHash || "") + '">' + fairHashHTML(data.seedHash || "—") + "</div></div>" + '<div class="fair-block"><div class="fair-label">Секретный сид</div><div class="fair-hash" data-copy="' + escapeHtml(data.serverSeed || "") + '">' + fairHashHTML(data.serverSeed || "—") + "</div></div>" + hiloFairFormulaHTML();
            hiloRoundFairBlock.style.display = "";
            document.getElementById("hiloRoundFairBtn").textContent = "Скрыть информацию";
        } else {
            hiloRoundFairBlock.style.display = "none";
            document.getElementById("hiloRoundFairBtn").textContent = "Проверить честность";
        }
    });
}

function hiloHowtoExampleHTML() {
    const exCards = [{
        rank: "8",
        suit: "H"
    }, {
        rank: "K",
        suit: "S"
    }];
    return '<div class="hilo-card-row hilo-howto-example-row">' + exCards.map((c, i) => hiloCardWrapHTML(c, i === 1 ? "hilo-card-current" : "")).join("") + "</div>" + '<div class="blackjack-howto-example-total">Была 8 — выпал Король: угадали «Больше» → множитель применяется к ставке</div>';
}

function openHiloHowto() {
    const modal = document.getElementById("hiloHowtoModal");
    if (!modal) return;
    const example = document.getElementById("hiloHowtoExample");
    if (example && !example.dataset.filled) {
        example.innerHTML = hiloHowtoExampleHTML();
        example.dataset.filled = "1";
    }
    modal.classList.add("active");
}

function closeHiloHowto() {
    const modal = document.getElementById("hiloHowtoModal");
    if (modal) modal.classList.remove("active");
}

const hiloHowtoModal = document.getElementById("hiloHowtoModal");

if (hiloHowtoModal) {
    document.getElementById("hiloHowtoClose").addEventListener("click", closeHiloHowto);
    document.getElementById("hiloHowtoOk").addEventListener("click", closeHiloHowto);
    hiloHowtoModal.addEventListener("click", e => {
        if (e.target === hiloHowtoModal) closeHiloHowto();
    });
}

let rbActive = false;

let rbBusy = false;

let rbBet = 0;

let rbCards = [];

let rbChoices = [];

let rbMultiplier = 1.0;

let rbChoiceMultipliers = {};

let rbCanCashout = false;

let rbCashoutAmount = 0;

let rbHistoryScope = "all";

let rbCurrentRoundInfo = null;

let rbFinishedInfo = null;

let rbMultChain = [1];

const RB_COLOR_LABEL = {
    red: "Красное",
    black: "Чёрное"
};

const RB_SUITS = ["S", "H", "D", "C"];

const RB_SUIT_SYMBOL = {
    C: "♣",
    D: "♦",
    H: "♥",
    S: "♠"
};

const RB_SUIT_ICON = {
    C: "/lottie/ИграRadOrBlack/Трефы.png",
    D: "/lottie/ИграRadOrBlack/Бубны.png",
    H: "/lottie/ИграRadOrBlack/Черви.png",
    S: "/lottie/ИграRadOrBlack/Пики.png"
};

const RB_SUIT_NAME = {
    C: "Трефы",
    D: "Бубны",
    H: "Черви",
    S: "Пики"
};

const RB_SUIT_COLOR = {
    C: "black",
    S: "black",
    D: "red",
    H: "red"
};

function rbCardWrapHTML(card, extraClass) {
    return '<span class="hilo-card-wrap' + (extraClass ? " " + extraClass : "") + '">' + blackjackCardImgHTML(card) + "</span>";
}

function rbCardRowHTML() {
    if (!rbCards.length) return '<span class="hilo-card-wrap hilo-card-placeholder">' + cardBackCrossHTML() + "</span>";
    return rbCards.map((c, i) => rbCardWrapHTML(c, i === rbCards.length - 1 ? "hilo-card-current" : "hilo-card-past")).join("");
}

function rbMultRowHTML() {
    let chips = "";
    rbMultChain.forEach((v, i) => {
        chips += (i > 0 ? '<span class="gv-mult-arrow">›</span>' : "") + '<span class="gv-mult-chip' + (i === rbMultChain.length - 1 ? " now" : "") + '">x' + fmtCoef(v) + "</span>";
    });
    return chips || '<div class="gv-mult-chip now">x1</div>';
}

function updateRbMultRow() {
    const row = document.getElementById("rbMultRow");
    if (!row) return;
    row.innerHTML = rbMultRowHTML();
    const now = row.querySelector(".gv-mult-chip.now");
    if (now) now.scrollIntoView({
        block: "nearest",
        inline: "center"
    });
}

function updateRbCardRow() {
    const row = document.getElementById("rbCardRow");
    if (row) row.innerHTML = rbCardRowHTML();
}

function rbColorBtnHTML(color) {
    const mult = rbChoiceMultipliers.color;
    const disabled = mult === null || mult === undefined;
    return '<button class="rb-color-btn rb-color-' + color + (disabled ? " dim" : "") + '" type="button" data-rb-color="' + color + '"' + (disabled ? " disabled" : "") + '><span class="rb-choice-label">' + RB_COLOR_LABEL[color] + "</span><span class=\"rb-choice-mult\">" + (disabled ? "—" : "x" + fmtCoef(mult)) + "</span></button>";
}

function rbSuitBtnHTML(suit) {
    const mult = rbChoiceMultipliers.suit;
    const disabled = mult === null || mult === undefined;
    return '<button class="rb-suit-btn rb-suit-' + RB_SUIT_COLOR[suit] + (disabled ? " dim" : "") + '" type="button" data-rb-suit="' + suit + '"' + (disabled ? " disabled" : "") + '><img class="rb-suit-icon-img" src="' + RB_SUIT_ICON[suit] + '" alt="' + RB_SUIT_NAME[suit] + '"><span class="rb-choice-mult">' + (disabled ? "—" : "x" + fmtCoef(mult)) + "</span></button>";
}

function rbChoicesHTML() {
    return '<div class="rb-choices" id="rbChoices">' + '<div class="rb-color-row">' + ["red", "black"].map(rbColorBtnHTML).join("") + "</div>" + '<div class="rb-suit-row">' + RB_SUITS.map(rbSuitBtnHTML).join("") + "</div>" + "</div>";
}

function updateRbChoices() {
    const wrap = document.getElementById("rbChoices");
    if (!wrap) return;
    wrap.outerHTML = rbChoicesHTML();
}

function rbStatusHTML() {
    if (rbActive) {
        return rbCanCashout ? "Заберёте: <b>" + fmtNum(rbCashoutAmount) + "⭐️</b> (x" + fmtCoef(rbMultiplier) + ")" : "Сделайте первый прогноз, чтобы разблокировать «Забрать»";
    }
    if (rbFinishedInfo) {
        return rbFinishedInfo.win ? '<span class="gv-history-win">Выигрыш: ' + fmtNum(rbFinishedInfo.winAmount) + "⭐️ (x" + fmtCoef(rbFinishedInfo.multiplier) + ")</span>" : '<span class="gv-history-lose">Не угадали — ставка сгорела</span>';
    }
    return "";
}

function updateRbStatus() {
    const el = document.getElementById("rbStatus");
    if (!el) return;
    if (!rbActive && !rbFinishedInfo) {
        el.style.display = "none";
        return;
    }
    el.style.display = "";
    el.innerHTML = rbStatusHTML();
}

function setRbPanelLocked(locked) {
    const panel = document.getElementById("rbPanel");
    if (panel) panel.classList.toggle("locked", locked);
}

function setRbStartBtn(mode) {
    const btn = document.getElementById("redblackStartBtn");
    if (!btn) return;
    btn.classList.remove("dim");
    if (mode === "start") btn.textContent = "Начать игру";
    else if (mode === "active") btn.textContent = rbCanCashout ? "Забрать " + fmtNum(rbCashoutAmount) + "⭐️ (x" + fmtCoef(rbMultiplier) + ")" : "Сделайте прогноз";
    else if (mode === "again") btn.textContent = "Создать новую игру";
}

function updateRbCashoutBtn() {
    if (!rbActive) return;
    const btn = document.getElementById("redblackStartBtn");
    if (!btn) return;
    btn.textContent = rbCanCashout ? "Забрать " + fmtNum(rbCashoutAmount) + "⭐️ (x" + fmtCoef(rbMultiplier) + ")" : "Сделайте прогноз";
    btn.classList.toggle("dim", !rbCanCashout || rbBusy);
}

function updateRbRoundIdLabel() {
    const el = document.getElementById("redblackRoundIdLabel");
    if (!el) return;
    const roundId = rbCurrentRoundInfo && rbCurrentRoundInfo.roundId;
    if (roundId) {
        el.textContent = roundId;
        el.classList.remove("text-skel");
    } else {
        el.textContent = "RBXXXXXXXX";
        el.classList.add("text-skel");
    }
}

function rbReadyState() {
    const betInput = gvBody.querySelector(".gv-bet-input");
    const bet = betInput ? parseFloat(betInput.value) : NaN;
    return {
        bet: bet,
        hasBet: bet > 0,
        enoughBalance: bet > 0 && bet <= currentUser.balance + 1e-6,
        overMax: bet > betMax("redblack"),
        underMin: bet > 0 && bet < betMin("redblack")
    };
}

function updateRbStartState() {
    const btn = document.getElementById("redblackStartBtn");
    if (!btn || rbActive) return;
    const state = rbReadyState();
    const ready = !rbBusy && betsAccepted && state.hasBet && state.enoughBalance && !state.overMax && !state.underMin;
    btn.classList.toggle("dim", !ready);
}

function applyRbState(state) {
    rbCards = state.cards || [];
    rbMultiplier = state.multiplier || 1.0;
    rbChoiceMultipliers = state.choiceMultipliers || {};
    rbCanCashout = !!state.canCashout;
    rbCashoutAmount = state.cashoutAmount || 0;
    rbCurrentRoundInfo = {
        roundId: state.roundId,
        seedHash: state.seedHash,
        serverSeed: null,
        status: "active"
    };
    if (state.step === 0) {
        rbMultChain = [1];
    } else if (rbMultChain.length === state.step) {
        rbMultChain.push(state.multiplier);
    } else if (rbMultChain.length !== state.step + 1) {
        rbMultChain = [1, state.multiplier];
    }
    updateRbRoundIdLabel();
    updateRbCardRow();
    updateRbChoices();
    updateRbStatus();
    updateRbCashoutBtn();
    updateRbMultRow();
}

function resetRedBlackUI() {
    rbActive = false;
    rbBusy = false;
    rbCards = [];
    rbChoices = [];
    rbMultiplier = 1.0;
    rbChoiceMultipliers = {};
    rbCanCashout = false;
    rbCashoutAmount = 0;
    rbCurrentRoundInfo = null;
    rbFinishedInfo = null;
    rbMultChain = [1];
    setRbPanelLocked(false);
    setRbStartBtn("start");
    updateRbCardRow();
    const choicesWrap = document.getElementById("rbChoices");
    if (choicesWrap) choicesWrap.style.display = "none";
    updateRbStatus();
    updateRbStartState();
    updateRbRoundIdLabel();
    updateRbMultRow();
}

function playRedBlack() {
    if (rbBusy || rbActive) return;
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const state = rbReadyState();
    if (!state.hasBet) return;
    if (!state.enoughBalance) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    if (state.underMin) {
        showToast("Минимальная ставка — " + fmtNum(betMin("redblack")) + "⭐️", "error");
        return;
    }
    if (state.overMax) {
        showToast("Максимальная ставка — " + fmtNum(betMax("redblack")) + "⭐️", "error");
        return;
    }
    rbBusy = true;
    rbBet = state.bet;
    document.getElementById("redblackStartBtn").classList.add("dim");
    fetch("/api/redblack/start", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            bet: rbBet
        })
    }).then(r => r.json()).then(data => {
        rbBusy = false;
        if (!data || !data.ok) {
            showToast(data && data.error || "Ошибка сервера", "error");
            updateRbStartState();
            return;
        }
        rbActive = true;
        rbFinishedInfo = null;
        if (typeof data.balance === "number") applyBalance(data.balance);
        applyRbState(data);
        setRbPanelLocked(true);
        setRbStartBtn("active");
        const choicesWrap = document.getElementById("rbChoices");
        if (choicesWrap) choicesWrap.style.display = "";
    }).catch(() => {
        rbBusy = false;
        showToast("Не удалось связаться с сервером", "error");
        updateRbStartState();
    });
}

function rbFinish(data) {
    rbActive = false;
    rbFinishedInfo = {
        win: data.win,
        winAmount: data.winAmount,
        multiplier: data.multiplier,
        busted: data.busted
    };
    rbCards = data.cards || rbCards;
    rbCurrentRoundInfo = {
        roundId: data.roundId,
        seedHash: data.seedHash,
        serverSeed: data.serverSeed,
        status: "finished",
        multiplier: data.multiplier
    };
    updateRbRoundIdLabel();
    if (typeof data.balance === "number") applyBalance(data.balance);
    updateRbCardRow();
    const choicesWrap = document.getElementById("rbChoices");
    if (choicesWrap) choicesWrap.style.display = "none";
    setRbPanelLocked(false);
    setRbStartBtn("again");
    updateRbStatus();
    if (data.win) showGameWinToast(data.winAmount, "Выигрыш ", "⭐️!");
    else showGameLoseToast("Не угадали — ставка сгорела");
    loadRedBlackHistory(null, true);
}

function guessRedBlack(choiceType, choiceValue) {
    if (rbBusy || !rbActive) return;
    const mult = choiceType === "color" ? rbChoiceMultipliers.color : rbChoiceMultipliers.suit;
    if (mult === null || mult === undefined) return;
    rbBusy = true;
    const wrap = document.getElementById("rbChoices");
    if (wrap) wrap.classList.add("busy");
    fetch("/api/redblack/guess", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            choiceType: choiceType,
            choiceValue: choiceValue
        })
    }).then(r => r.json()).then(data => {
        rbBusy = false;
        if (wrap) wrap.classList.remove("busy");
        if (!data || !data.ok) {
            showToast(data && data.error || "Ошибка сервера", "error");
            return;
        }
        if (data.active === false) {
            rbFinish(data);
            return;
        }
        applyRbState(data);
        haptic("selection");
    }).catch(() => {
        rbBusy = false;
        if (wrap) wrap.classList.remove("busy");
        showToast("Не удалось связаться с сервером", "error");
    });
}

function cashoutRedBlack() {
    if (rbBusy || !rbActive || !rbCanCashout) return;
    rbBusy = true;
    document.getElementById("redblackStartBtn").classList.add("dim");
    fetch("/api/redblack/cashout", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID
        })
    }).then(r => r.json()).then(data => {
        rbBusy = false;
        if (!data || !data.ok) {
            showToast(data && data.error || "Ошибка сервера", "error");
            updateRbCashoutBtn();
            return;
        }
        rbFinish(data);
    }).catch(() => {
        rbBusy = false;
        showToast("Не удалось связаться с сервером", "error");
        updateRbCashoutBtn();
    });
}

function renderRedBlack(data) {
    return '<div class="gv-mines-box blackjack-table-box rb-table">' + '<div class="gv-mult-row" id="rbMultRow" data-action="redblack-paytable-info">' + rbMultRowHTML() + "</div>" + '<div class="hilo-card-row" id="rbCardRow">' + rbCardRowHTML() + "</div>" + '<div class="mines-status" id="rbStatus" style="display:none;"></div>' + rbChoicesHTML() + '<div class="gv-mines-howto">' + '<div class="gv-fair" data-action="redblack-fair"><span class="gv-fair-icon">#</span><span id="redblackRoundIdLabel" class="text-skel">RBXXXXXXXX</span></div>' + howtoHTML("position:static;") + "</div>" + "</div>" + '<div class="gv-panel" id="rbPanel">' + '<div class="gv-label">Сумма ставки</div>' + betRowHTML() + "</div>" + '<button class="gv-start-btn dim" type="button" id="redblackStartBtn">Начать игру</button>' + '<div class="gv-history">' + '<div class="gv-history-head">' + '<h3 class="gv-history-title">' + lazyImgTag(liteAsset("/lottie/images/ОгоньЭмоджи.lottie"), "", "flame-gif") + " Последние игры</h3>" + '<div class="gv-history-tabs">' + '<button class="gv-history-tab active" type="button" data-redblack-scope="all">Все</button>' + '<button class="gv-history-tab" type="button" data-redblack-scope="mine">Мои</button>' + "</div>" + "</div>" + gvHistorySearchRowHTML("redblackHistorySearchInput") + '<div class="gv-history-list" id="redblackHistoryList"><div class="dice-history-empty">Загрузка…</div></div>' + "</div>";
}

function initRedBlackGame(data) {
    resetRedBlackUI();
    loadRedBlackHistory();
    gvHistoryWireSearch("redblackHistorySearchInput", () => loadRedBlackHistory(), value => {
        gvHistorySearch("redblackHistoryList", () => "/api/redblack/history?uid=" + CURRENT_UID + "&scope=" + rbHistoryScope + "&q=" + encodeURIComponent(value), rows => {
            document.getElementById("redblackHistoryList").innerHTML = rows.map(rbHistoryRowHTML).join("");
        });
    });
    fetch("/api/redblack/state?uid=" + CURRENT_UID).then(r => r.json()).then(st => {
        if (!st || !st.ok || rbActive) return;
        if (typeof st.balance === "number") applyBalance(st.balance);
        if (!st.active) return;
        rbActive = true;
        rbBet = st.bet;
        applyRbState(st);
        const betInput = gvBody.querySelector(".gv-bet-input");
        if (betInput) betInput.value = st.bet + "⭐️";
        setRbPanelLocked(true);
        setRbStartBtn("active");
        const choicesWrap = document.getElementById("rbChoices");
        if (choicesWrap) choicesWrap.style.display = "";
    }).catch(() => {});
}

function rbChoiceLabel(choice) {
    if (!choice) return "—";
    return choice.type === "color" ? RB_COLOR_LABEL[choice.value] : RB_SUIT_SYMBOL[choice.value];
}

function rbHistoryRowHTML(r) {
    let meta = {};
    try {
        meta = JSON.parse(r.meta || "{}");
    } catch (e) {}
    const isWin = r.result === "win";
    const isMe = r.user_id === CURRENT_UID;
    const botBadge = r.in_chat || meta.inChat ? '<span class="gv-history-bot-badge">Чат</span>' : meta.playedInBot ? '<span class="gv-history-bot-badge">Бот</span>' : "";
    const name = isMe ? currentUser.displayName || "Игрок" : r.username || "Игрок";
    const avatarUrl = isMe ? currentUser.avatarUrl : "/api/avatar/" + r.user_id;
    const steps = meta.cards ? meta.cards.length - 1 : "—";
    return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-avatar"><div class="skel-box"></div>' + lazyImgTag(avatarUrl, name) + "</div>" + '<div class="gv-history-mid">' + '<div class="gv-history-name"><span class="gv-history-name-text">' + escapeHtml(name) + "</span>" + botBadge + "</div>" + historyTimeHTML(r.created_at) + "</div>" + '<div class="gv-history-right">Сумма ставки: <b>' + fmtNum(r.bet) + "⭐️</b><br>" + '<span class="gv-history-outcome">Верных шагов: <b>' + steps + "</b></span><br>" + (isWin ? '<span class="gv-history-win">Выигрыш: ' + fmtNum(r.win_amount) + "⭐️ (x" + fmtCoef(meta.multiplier) + ")</span>" : '<span class="gv-history-lose">Проигрыш</span>') + "</div>" + "</div>" + (meta.roundId ? '<button class="crash-history-fair-btn" type="button" data-redblack-round="' + escapeHtml(meta.roundId) + '">' + fairCheckBtnIconHTML() + "Проверить честность</button>" : "") + "</div>";
}

function loadRedBlackHistory(scope, append) {
    if (scope) {
        rbHistoryScope = scope;
        append = false;
    }
    gvHistoryLoad("redblackHistoryList", off => "/api/redblack/history?uid=" + CURRENT_UID + "&scope=" + rbHistoryScope + "&offset=" + off, 20, (rows, append) => {
        const list = document.getElementById("redblackHistoryList");
        const html = rows.map(rbHistoryRowHTML).join("");
        if (append) list.insertAdjacentHTML("beforeend", html);
        else list.innerHTML = html;
    }, GV_HISTORY_EMPTY_HTML, append);
}

GV_HISTORY_BY_GAME["redblack"] = {
    listId: "redblackHistoryList",
    load: () => loadRedBlackHistory(null, true)
};

function rbFairFormulaHTML() {
    return '<p class="modal-text">Формула, которую можно пересчитать самостоятельно (пример на Python — hmac.new(seed.encode(), f"{uid}:{i}".encode(), hashlib.sha256)):</p>' + '<ol class="fair-formula-steps">' + "<li>Для карты на шаге i (0 - самая первая карта раунда) считаем H_i = HMAC-SHA256(секретный сид, \"UID раунда:i\")</li>" + "<li>Первые 8 hex-символов H_i → номер ранга (0..12) через остаток от деления на 13 (косметика)</li>" + "<li>Следующие 8 hex-символов H_i → номер масти (0..3) через остаток от деления на 4 — вот она и решает исход</li>" + "</ol>" + '<p class="modal-text">Последовательность карт обязана совпасть с картами раунда — если хэш выше совпадает с SHA-256(сид), а расчёт даёт другие карты, значит подменили сид или UID.</p>';
}

function openRedBlackFair() {
    const info = rbCurrentRoundInfo;
    const roundId = info && info.roundId;
    if (roundId) {
        gvFairId.textContent = roundId;
        gvFairId.classList.remove("text-skel");
    } else {
        gvFairId.textContent = "RBXXXXXXXX";
        gvFairId.classList.add("text-skel");
    }
    if (info && info.seedHash) setFairHashEl(gvFairHash, info.seedHash);
    else setFairHashSkeleton(gvFairHash);
    let resultHtml = '<div class="fair-block"><div class="fair-label">UID раунда</div><div class="fair-hash"' + (roundId ? ' data-copy="' + escapeHtml(roundId) + '">' + fairHashHTML(roundId) : ">" + fairHashSkeletonHTML()) + "</div></div>";
    if (info && info.status === "finished" && info.serverSeed) {
        resultHtml += '<div class="fair-block"><div class="fair-label">Секретный сид</div><div class="fair-hash" data-copy="' + escapeHtml(info.serverSeed) + '">' + fairHashHTML(info.serverSeed) + "</div></div>";
        gvFairNote.style.display = "";
        gvFairNote.innerHTML = rbFairFormulaHTML();
    } else if (info && info.status === "active") {
        resultHtml += '<div class="fair-result-note">Раунд ещё не завершён — сид раскроется сразу после окончания игры.</div>';
        gvFairNote.style.display = "none";
    } else {
        resultHtml += '<div class="fair-result-note">Начните игру, чтобы получить UID и хэш текущего раунда.</div>';
        gvFairNote.style.display = "none";
    }
    gvFairResult.innerHTML = resultHtml;
    gvFairLink.style.display = "none";
    gvFairModal.classList.add("active");
}

const redblackRoundModal = document.getElementById("redblackRoundModal");

const redblackRoundBoard = document.getElementById("redblackRoundBoard");

const redblackRoundPlayerRow = document.getElementById("redblackRoundPlayerRow");

const redblackRoundFairBlock = document.getElementById("redblackRoundFairBlock");

let redblackRoundData = null;

function rbRoundBoardHTML(detail) {
    const cards = detail.cards || [];
    const busted = !!detail.busted && detail.result !== "win";
    return cards.map((c, i) => rbCardWrapHTML(c, i === 0 ? "" : busted && i === cards.length - 1 ? "hilo-card-bust" : "hilo-card-win")).join("");
}

function rbRoundPlayerRowHTML(detail) {
    const isMe = detail.userId === CURRENT_UID;
    const name = isMe ? currentUser.displayName || "Игрок" : detail.username || "Игрок";
    const avatarUrl = isMe ? currentUser.avatarUrl : "/api/avatar/" + detail.userId;
    const isWin = detail.result === "win";
    const steps = (detail.cards || []).length - 1;
    return '<div class="crash-player-row' + (isMe ? " me" : "") + '">' + '<div class="crash-player-avatar"><img src="' + avatarUrl + '" alt="" loading="lazy"></div>' + '<div class="crash-player-mid">' + '<div class="crash-player-name"><span class="crash-player-name-text">' + escapeHtml(name) + "</span>" + (isMe ? ' <span class="lb-you-tag">Вы</span>' : "") + "</div>" + '<div class="crash-player-sub">Ставка: ' + fmtNum(detail.bet) + "⭐️ · Верных шагов: " + steps + "</div>" + "</div>" + (detail.multiplier != null ? '<div class="crash-player-mult">x' + fmtCoef(detail.multiplier) + "</div>" : "") + '<div class="crash-player-value">' + (isWin ? "+" + fmtNum(detail.winAmount) + "⭐️" : "Проигрыш") + "</div>" + "</div>";
}

function rbRoundBoardSkeletonHTML() {
    return '<span class="hilo-card-wrap skel"></span><span class="hilo-card-wrap skel"></span><span class="hilo-card-wrap skel"></span>';
}

function openRedBlackRoundModal(publicId) {
    if (!publicId || !redblackRoundModal) return;
    redblackRoundData = null;
    redblackRoundFairBlock.style.display = "none";
    redblackRoundFairBlock.innerHTML = "";
    document.getElementById("redblackRoundFairBtn").textContent = "Проверить честность";
    document.getElementById("redblackRoundModalId").textContent = publicId;
    redblackRoundBoard.innerHTML = rbRoundBoardSkeletonHTML();
    redblackRoundPlayerRow.innerHTML = minesRoundPlayerSkeletonHTML();
    redblackRoundModal.classList.add("active");
    fetch("/api/redblack/round?id=" + encodeURIComponent(publicId)).then(r => r.json()).then(data => {
        if (!redblackRoundModal.classList.contains("active")) return;
        if (!data || !data.ok) {
            redblackRoundPlayerRow.innerHTML = '<div class="crash-players-empty">Раунд не найден</div>';
            return;
        }
        redblackRoundData = data;
        redblackRoundBoard.innerHTML = rbRoundBoardHTML(data);
        redblackRoundPlayerRow.innerHTML = rbRoundPlayerRowHTML(data);
    }).catch(() => {
        redblackRoundPlayerRow.innerHTML = '<div class="crash-players-empty">Не удалось загрузить раунд</div>';
    });
}

function closeRedBlackRoundModal() {
    redblackRoundModal.classList.remove("active");
}

if (redblackRoundModal) {
    document.getElementById("redblackRoundClose").addEventListener("click", closeRedBlackRoundModal);
    redblackRoundModal.addEventListener("click", e => {
        if (e.target === redblackRoundModal) closeRedBlackRoundModal();
    });
    document.getElementById("redblackRoundFairBtn").addEventListener("click", () => {
        const data = redblackRoundData;
        if (!data) return;
        const isHidden = redblackRoundFairBlock.style.display === "none";
        if (isHidden) {
            redblackRoundFairBlock.innerHTML = '<div class="fair-block"><div class="fair-label">UID раунда</div><div class="fair-hash" data-copy="' + escapeHtml(data.roundId) + '">' + fairHashHTML(data.roundId) + "</div></div>" + '<div class="fair-block"><div class="fair-label">SHA-256 hash</div><div class="fair-hash" data-copy="' + escapeHtml(data.seedHash || "") + '">' + fairHashHTML(data.seedHash || "—") + "</div></div>" + '<div class="fair-block"><div class="fair-label">Секретный сид</div><div class="fair-hash" data-copy="' + escapeHtml(data.serverSeed || "") + '">' + fairHashHTML(data.serverSeed || "—") + "</div></div>" + rbFairFormulaHTML();
            redblackRoundFairBlock.style.display = "";
            document.getElementById("redblackRoundFairBtn").textContent = "Скрыть информацию";
        } else {
            redblackRoundFairBlock.style.display = "none";
            document.getElementById("redblackRoundFairBtn").textContent = "Проверить честность";
        }
    });
}

