function initBlackjackHouseBody() {
    blackjackBusy = false;
    blackjackActive = false;
    blackjackPlayerCards = [];
    blackjackDealerCards = [];
    blackjackPlayerTotal = 0;
    blackjackDealerTotal = 0;
    blackjackDoubled = false;
    blackjackHands = [];
    blackjackActiveHand = 0;
    blackjackCanDouble = false;
    blackjackCanSplit = false;
    blackjackCurrentRoundInfo = null;
    blackjackFinishedInfo = null;
    setBlackjackPanelLocked(false);
    setBlackjackStartBtn("start");
    updateBlackjackTable();
    updateBlackjackStatus();
    updateBlackjackStartState();
    updateBlackjackRoundIdLabel();
    loadBlackjackHistory("all");
    gvHistoryWireSearch("blackjackHistorySearchInput", () => loadBlackjackHistory(), value => {
        gvHistorySearch("blackjackHistoryList", () => "/api/blackjack/history?uid=" + CURRENT_UID + "&scope=" + blackjackHistoryScope + "&q=" + encodeURIComponent(value), rows => {
            document.getElementById("blackjackHistoryList").innerHTML = rows.map(blackjackHistoryRowHTML).join("");
        });
    });
    fetch("/api/blackjack/state?uid=" + CURRENT_UID).then(r => r.json()).then(st => {
        if (!st || !st.ok || blackjackActive) return;
        if (typeof st.balance === "number") applyBalance(st.balance);
        if (!st.active) return;
        blackjackBet = st.bet;
        blackjackActive = true;
        blackjackApplyActiveState(st);
        blackjackDealerCards = st.dealerCards;
        blackjackCurrentRoundInfo = {
            roundId: st.roundId,
            seedHash: st.seedHash,
            serverSeed: null,
            status: "active"
        };
        updateBlackjackRoundIdLabel();
        setBlackjackPanelLocked(true);
        setBlackjackStartBtn("hidden");
        updateBlackjackTable();
        updateBlackjackStatus();
    }).catch(() => {});
}

