const UPG_SPEED_STORE = "upgSpeed";

const UPG_SPEED_ITEMS = [
    ["normal", "Обычная"],
    ["fast", "Быстрая"],
    ["turbo", "Турбо"]
];

let upgradeSpeed = (() => {
    try {
        const v = localStorage.getItem(UPG_SPEED_STORE);
        if (v === "fast" || v === "turbo") return v;
    } catch (e) {}
    return "normal";
})();

function upgradeSpinProfile() {
    if (upgradeSpeed === "fast") return UPG_AUTO_SPEEDS.fast.spin;
    if (upgradeSpeed === "turbo") return UPG_AUTO_SPEEDS.turbo.spin;
    return UPGRADE_SPIN;
}

function upgradeSpeedRowHTML() {
    return '<div class="upg-speed-row" id="upgradeSpeedRow"><div class="gv-label">Скорость</div><div class="upg-seg">' + UPG_SPEED_ITEMS.map(it => '<button class="upg-seg-btn' + (upgradeSpeed === it[0] ? " on" : "") + '" type="button" data-upg-speed="' + it[0] + '">' + it[1] + "</button>").join("") + "</div></div>";
}

function upgradeSetSpeed(val) {
    if (UPG_SPEED_ITEMS.every(it => it[0] !== val) || val === upgradeSpeed) return;
    upgradeSpeed = val;
    try {
        localStorage.setItem(UPG_SPEED_STORE, val);
    } catch (e) {}
    const row = document.getElementById("upgradeSpeedRow");
    if (row) row.querySelectorAll("[data-upg-speed]").forEach(b => b.classList.toggle("on", b.dataset.upgSpeed === val));
    haptic("selection");
}

const UPG_AUTO_REASONS = {
    done: "Все раунды сыграны",
    win: "Выпал первый выигрыш",
    profit: "Цель по прибыли достигнута",
    loss: "Сработал стоп-лосс",
    bigwin: "Крупный выигрыш",
    balance: "Не хватило баланса на следующую ставку",
    user: "Остановлено вами",
    error: "Потеряна связь с сервером",
    hidden: "Приложение было свёрнуто",
    limit: "Достигнут лимит раундов серии",
    off: "Авто-игру отключили",
    bets: "Ставки приостановлены",
    other: "Серия остановлена"
};

const UPG_AUTO_STORE = "upgAutoCfg";

const UPG_AUTO_ICON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M17 2l4 4-4 4"/><path d="M3 11V9a3 3 0 0 1 3-3h15"/><path d="M7 22l-4-4 4-4"/><path d="M21 13v2a3 3 0 0 1-3 3H3"/></svg>';

let upgradeMode = "manual";

let upgradeAutoCfg = null;

let upgradeAutoCfgLoading = false;

let upgradeAutoView = "setup";

let upgradeAutoRun = null;

function upgradeAutoClampPct(v, fallback) {
    const n = Math.round(Number(v));
    return isFinite(n) && n >= 1 && n <= 1000 ? n : fallback;
}

function upgradeAutoCleanNum(v) {
    let t = String(v == null ? "" : v).replace(",", ".").replace(/[^0-9.]/g, "");
    const i = t.indexOf(".");
    if (i >= 0) t = t.slice(0, i + 1) + t.slice(i + 1).replace(/\./g, "");
    return t.slice(0, 9);
}

function upgradeAutoNum(v) {
    const t = String(v == null ? "" : v).trim();
    if (!t) return null;
    const n = parseFloat(t);
    return isFinite(n) && n > 0 ? n : NaN;
}

function upgradeAutoLoadSettings() {
    const d = {
        rounds: 10,
        stopWin: false,
        profit: "",
        loss: "",
        bigWin: "",
        onLoss: "same",
        lossPct: 100,
        onWin: "same",
        winPct: 50,
        cap: "",
        speed: "normal"
    };
    try {
        const raw = JSON.parse(localStorage.getItem(UPG_AUTO_STORE) || "null");
        if (raw && typeof raw === "object") {
            if (UPG_AUTO_ROUNDS.indexOf(raw.rounds) >= 0) d.rounds = raw.rounds;
            d.stopWin = raw.stopWin === true;
            ["profit", "loss", "bigWin", "cap"].forEach(k => {
                d[k] = upgradeAutoCleanNum(raw[k]);
            });
            if (raw.onLoss === "up") d.onLoss = "up";
            if (raw.onWin === "reset" || raw.onWin === "up") d.onWin = raw.onWin;
            d.lossPct = upgradeAutoClampPct(raw.lossPct, d.lossPct);
            d.winPct = upgradeAutoClampPct(raw.winPct, d.winPct);
            if (["normal", "fast", "turbo"].indexOf(raw.speed) >= 0) d.speed = raw.speed;
        }
    } catch (e) {}
    return d;
}

let upgradeAutoSet = upgradeAutoLoadSettings();

function upgradeAutoSave() {
    try {
        localStorage.setItem(UPG_AUTO_STORE, JSON.stringify(upgradeAutoSet));
    } catch (e) {}
}

function upgradeAutoRoundsWord(n) {
    const m10 = n % 10;
    const m100 = n % 100;
    if (m10 === 1 && m100 !== 11) return "раунд";
    if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return "раунда";
    return "раундов";
}

function upgradeAutoSigned(n) {
    const v = Math.round(n * 100) / 100;
    return (v > 0 ? "+" : v < 0 ? "−" : "") + fmtNum(Math.abs(v)) + "⭐️";
}

function upgradeInfoSvg() {
    return '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.6" fill="none" stroke="currentColor" stroke-width="2"/><path d="M12 11v5.2" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/><circle cx="12" cy="7.9" r="1.3" fill="currentColor"/></svg>';
}

function upgradeInfoCardHTML() {
    return '<div class="rc-info upgrade-info" id="upgradeInfo"><div class="rc-info-in">' + '<div class="upgrade-stats">' + '<div class="upgrade-stat"><span>Шанс</span><b id="upgradeStatChance">' + upgradeChance.toFixed(1) + '%</b></div>' + '<div class="upgrade-stat"><span>Множитель</span><b id="upgradeStatMult">x' + fmtCoef(upgradeMultiplier(upgradeChance)) + '</b></div>' + '<div class="upgrade-stat win"><span>Выигрыш</span><b id="upgradeStatWin">—</b></div>' + "</div>" + '<div class="rc-info-note">Считается по сумме из поля ставки</div>' + "</div></div>";
}

function upgradeModeRowHTML() {
    return '<div class="upg-mode" id="upgradeModeRow" data-mode="manual">' + '<i class="upg-mode-thumb"></i>' + '<button class="upg-mode-btn on" type="button" data-upg-mode="manual">Вручную</button>' + '<button class="upg-mode-btn" type="button" data-upg-mode="auto">' + UPG_AUTO_ICON + "Авто</button>" + "</div>";
}

function upgradeAutoCardHTML() {
    return '<div class="upg-auto" id="upgradeAutoCard" hidden></div>';
}

let upgradeAutoModalEl = null;

function upgradeAutoCompactHTML() {
    const cfg = upgradeAutoCfg;
    if (cfg && !cfg.enabled) return '<div class="upg-auto-off">Авто-игра сейчас отключена администратором. Играйте вручную.</div>';
    const warn = upgradeAutoWarnText();
    return '<div class="upg-auto-compact"><div class="upg-auto-compact-head"><span class="upg-auto-title">' + UPG_AUTO_ICON + 'Авто-игра</span><button class="keno-auto-pill" type="button" data-upg-act="settings">Настроить</button></div>' + '<div class="upg-auto-sum" id="upgAutoSumCard">' + escapeHtml(upgradeAutoSummaryText()) + "</div>" + '<div class="upg-auto-warn" id="upgAutoWarnCard"' + (warn ? "" : " hidden") + ">" + escapeHtml(warn) + "</div></div>";
}

function upgradeAutoRenderModal() {
    const body = document.getElementById("upgradeAutoBody");
    if (!body) return;
    body.innerHTML = '<div class="upg-auto keno-auto-card">' + upgradeAutoSetupHTML() + "</div>";
    const go = document.getElementById("upgradeAutoGo");
    if (go) {
        go.textContent = upgradeAutoStartLabel();
        go.classList.toggle("dim", !!(upgradeAutoCfg && !upgradeAutoCfg.enabled));
    }
}

function upgradeAutoEnsureModal() {
    if (upgradeAutoModalEl && document.body.contains(upgradeAutoModalEl)) return upgradeAutoModalEl;
    const el = document.createElement("div");
    el.className = "modal-overlay";
    el.id = "upgradeAutoModal";
    el.innerHTML = '<div class="modal-card keno-auto-modal"><button class="modal-close" type="button" id="upgradeAutoClose"><svg viewBox="0 0 24 24" fill="none"><path d="M6 6l12 12M18 6 6 18" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg></button>' + '<h3 class="modal-title">Авто-игра в Upgrader</h3>' + '<div id="upgradeAutoBody"></div>' + '<button class="modal-ok keno-auto-go" type="button" id="upgradeAutoGo">Запустить авто</button></div>';
    document.body.appendChild(el);
    el.addEventListener("click", e => {
        if (e.target === el || e.target.closest("#upgradeAutoClose")) {
            el.classList.remove("active");
            return;
        }
        if (e.target.closest("#upgradeAutoGo")) {
            upgradeAutoStart();
            return;
        }
        upgradeAutoCardClick(e);
    });
    el.addEventListener("input", upgradeAutoCardInput);
    upgradeAutoModalEl = el;
    return el;
}

function openUpgradeAutoModal() {
    if (upgradeAutoRun && upgradeAutoRun.active) return;
    if (upgradeBusy) return;
    const el = upgradeAutoEnsureModal();
    upgradeAutoRenderModal();
    el.classList.add("active");
    upgradeAutoLoadCfg();
    haptic("selection");
}

function upgradeAutoCloseModal() {
    const el = document.getElementById("upgradeAutoModal");
    if (el) el.classList.remove("active");
}

function upgradeStartLabel() {
    return upgradeMode === "auto" ? upgradeAutoStartLabel() : "Начать игру";
}

function upgradeAutoStartLabel() {
    if (upgradeAutoView === "done") return "Запустить снова";
    const r = upgradeAutoSet.rounds;
    return "Запустить авто · " + (r ? r + " " + upgradeAutoRoundsWord(r) : "∞");
}

function upgradeAutoTotalRounds() {
    const max = upgradeAutoCfg ? upgradeAutoCfg.maxRounds : 100;
    return upgradeAutoSet.rounds ? Math.min(upgradeAutoSet.rounds, max) : max;
}

function upgradeAutoSummaryText() {
    const s = upgradeAutoSet;
    const total = upgradeAutoTotalRounds();
    const parts = ["до " + total + " " + upgradeAutoRoundsWord(total)];
    const stops = [];
    if (s.stopWin) stops.push("первый выигрыш");
    if (upgradeAutoNum(s.profit) > 0) stops.push("прибыль +" + s.profit + "⭐️");
    if (upgradeAutoNum(s.loss) > 0) stops.push("убыток −" + s.loss + "⭐️");
    if (upgradeAutoNum(s.bigWin) > 0) stops.push("выигрыш от " + s.bigWin + "⭐️");
    if (stops.length) parts.push("стоп: " + stops.join(", "));
    if (s.onLoss === "up") parts.push("после проигрыша +" + s.lossPct + "%");
    if (s.onWin === "reset") parts.push("после выигрыша — начальная ставка");
    else if (s.onWin === "up") parts.push("после выигрыша +" + s.winPct + "%");
    if (upgradeAutoNum(s.cap) > 0) parts.push("потолок " + s.cap + "⭐️");
    parts.push(UPG_AUTO_SPEEDS[s.speed].label.toLowerCase() + " скорость");
    return parts.join(" · ");
}

function upgradeAutoWarnText() {
    const s = upgradeAutoSet;
    const hasLoss = upgradeAutoNum(s.loss) > 0;
    const hasCap = upgradeAutoNum(s.cap) > 0;
    if (s.onLoss === "up" && !hasLoss && !hasCap) return "Ставка растёт после каждого проигрыша — длинная серия поражений быстро её раздует. Задайте стоп-лосс или потолок ставки.";
    if (!s.rounds && !hasLoss && !(upgradeAutoNum(s.profit) > 0) && !s.stopWin) return "Без стоп-условий серия идёт до лимита раундов или пока хватает баланса.";
    return "";
}

function upgradeAutoRefreshHints() {
    const text = upgradeAutoWarnText();
    ["upgAutoSum", "upgAutoSumCard"].forEach(id => {
        const sum = document.getElementById(id);
        if (sum) sum.textContent = upgradeAutoSummaryText();
    });
    ["upgAutoWarn", "upgAutoWarnCard"].forEach(id => {
        const warn = document.getElementById(id);
        if (warn) {
            warn.textContent = text;
            warn.hidden = !text;
        }
    });
    const go = document.getElementById("upgradeAutoGo");
    if (go) go.textContent = upgradeAutoStartLabel();
}

function upgradeAutoSetupHTML() {
    const s = upgradeAutoSet;
    const cfg = upgradeAutoCfg;
    if (cfg && !cfg.enabled) return '<div class="upg-auto-off">Авто-игра сейчас отключена администратором. Играйте вручную.</div>';
    const rounds = UPG_AUTO_ROUNDS.map(n => '<button class="upg-chip' + (s.rounds === n ? " on" : "") + '" type="button" data-upg-rounds="' + n + '">' + (n ? n : "∞") + "</button>").join("");
    const field = (key, sign, name, ph) => '<label class="upg-field"><span class="upg-field-name">' + name + '</span><span class="upg-input"><em>' + sign + '</em><input type="text" inputmode="decimal" autocomplete="off" maxlength="9" data-upg-in="' + key + '" placeholder="' + ph + '" value="' + escapeHtml(s[key]) + '"><b>⭐️</b></span></label>';
    const seg = (key, items, cur) => '<div class="upg-seg" data-upg-seg="' + key + '">' + items.map(it => '<button class="upg-seg-btn' + (cur === it[0] ? " on" : "") + '" type="button" data-upg-val="' + it[0] + '">' + it[1] + "</button>").join("") + "</div>";
    const pct = which => {
        const mode = which === "loss" ? s.onLoss : s.onWin;
        if (mode !== "up") return "";
        const cur = which === "loss" ? s.lossPct : s.winPct;
        const chips = [25, 50, 100, 200].map(p => '<button class="upg-chip small' + (cur === p ? " on" : "") + '" type="button" data-upg-pct="' + which + ":" + p + '">+' + p + "%</button>").join("");
        return '<div class="upg-pct-row">' + chips + '<span class="upg-input mini"><em>+</em><input type="text" inputmode="numeric" autocomplete="off" maxlength="4" data-upg-pctin="' + which + '" value="' + cur + '"><b>%</b></span></div>';
    };
    const capHint = cfg && cfg.maxBet > 0 ? "до " + fmtNum(cfg.maxBet) : "выкл.";
    const warn = upgradeAutoWarnText();
    return '<div class="upg-auto-head"><span class="upg-auto-title">' + UPG_AUTO_ICON + 'Авто-игра</span><span class="upg-auto-limit">' + (cfg ? "до " + cfg.maxRounds + " " + upgradeAutoRoundsWord(cfg.maxRounds) + " за серию" : "") + "</span></div>" + '<div class="gv-label">Количество раундов</div>' + '<div class="upg-chip-row">' + rounds + "</div>" + '<div class="gv-label">Остановить, если</div>' + '<div class="upg-stops">' + '<button class="upg-toggle' + (s.stopWin ? " on" : "") + '" type="button" data-upg-toggle="stopWin"><span>Выпал первый выигрыш</span><i class="upg-sw"></i></button>' + field("profit", "+", "Цель по прибыли", "выкл.") + field("loss", "−", "Стоп-лосс", "выкл.") + field("bigWin", "≥", "Крупный выигрыш", "выкл.") + "</div>" + '<div class="gv-label">Ставка после проигрыша</div>' + seg("onLoss", [
        ["same", "Не менять"],
        ["up", "Увеличить"]
    ], s.onLoss) + pct("loss") + '<div class="gv-label">Ставка после выигрыша</div>' + seg("onWin", [
        ["same", "Не менять"],
        ["reset", "Сбросить"],
        ["up", "Увеличить"]
    ], s.onWin) + pct("win") + '<div class="gv-label">Потолок ставки</div>' + field("cap", "≤", "Ставка не выше этой", capHint) + '<div class="gv-label">Скорость</div>' + seg("speed", [
        ["normal", "Обычная"],
        ["fast", "Быстрая"],
        ["turbo", "Турбо"]
    ], s.speed) + '<div class="upg-auto-warn" id="upgAutoWarn"' + (warn ? "" : " hidden") + ">" + escapeHtml(warn) + "</div>" + '<div class="upg-auto-sum" id="upgAutoSum">' + escapeHtml(upgradeAutoSummaryText()) + "</div>";
}

function upgradeAutoLiveHTML() {
    const tile = (label, id) => '<div class="upgrade-stat"><span>' + label + '</span><b id="' + id + '">—</b></div>';
    return '<div class="upg-live" id="upgAutoLive">' + '<div class="upg-live-top"><span class="upg-live-tag" id="upgLiveTag">Авто-игра</span><span class="upg-live-round" id="upgLiveRound"></span></div>' + '<div class="upg-live-bar"><i id="upgLiveBar"></i></div>' + '<div class="upg-live-net-wrap"><span class="upg-live-net-cap">Итог серии</span><b class="upg-live-net" id="upgLiveNet">0⭐️</b></div>' + '<div class="upg-live-stats">' + tile("Победы", "upgLiveWins") + tile("Поражения", "upgLiveLoss") + tile("Ставка", "upgLiveBet") + "</div>" + '<div class="upg-live-dots" id="upgLiveDots"></div>' + '<div class="upg-live-reason" id="upgLiveReason" hidden></div>' + '<div class="upg-live-actions" id="upgLiveActions" hidden><button class="upg-ghost" type="button" data-upg-act="setup">Изменить настройки</button></div>' + "</div>";
}

function upgradeAutoRenderCard() {
    const speedRow = document.getElementById("upgradeSpeedRow");
    if (speedRow) speedRow.hidden = upgradeMode === "auto";
    const card = document.getElementById("upgradeAutoCard");
    if (!card) return;
    card.hidden = upgradeMode !== "auto";
    if (upgradeMode !== "auto") return;
    if (upgradeAutoView === "setup") {
        card.innerHTML = upgradeAutoCompactHTML();
    } else {
        card.innerHTML = upgradeAutoLiveHTML();
        upgradeAutoPaintLive(false);
    }
    upgradeAutoSyncButton();
}

function upgradeAutoSyncButton() {
    const btn = document.getElementById("upgradeStartBtn");
    if (!btn) return;
    const run = upgradeAutoRun;
    const running = !!(run && run.active);
    btn.classList.toggle("upg-stop", running);
    if (upgradeMode !== "auto") return;
    if (running) {
        btn.textContent = run.stopRequested ? "Останавливаю…" : "Остановить";
        btn.classList.toggle("dim", !!run.stopRequested);
        return;
    }
    btn.textContent = upgradeAutoStartLabel();
    const state = upgradeReadyState();
    const ready = betsAccepted && state.hasBet && state.enoughBalance && !state.overMax && !state.underMin && !(upgradeAutoCfg && !upgradeAutoCfg.enabled);
    btn.classList.toggle("dim", !ready);
}

function upgradeAutoPaintLive(newDot) {
    const run = upgradeAutoRun;
    const roundEl = document.getElementById("upgLiveRound");
    if (!run || !roundEl) return;
    const byId = id => document.getElementById(id);
    const net = Math.round((run.returned - run.staked) * 100) / 100;
    const total = run.total || upgradeAutoTotalRounds();
    roundEl.innerHTML = "Сыграно <b>" + run.round + "</b>" + (run.p.rounds ? " из " + total : " · ∞");
    byId("upgLiveBar").style.width = Math.min(100, total ? run.round / total * 100 : 0).toFixed(1) + "%";
    const netEl = byId("upgLiveNet");
    netEl.textContent = upgradeAutoSigned(net);
    netEl.className = "upg-live-net" + (net > 0 ? " pos" : net < 0 ? " neg" : "");
    byId("upgLiveWins").textContent = String(run.wins);
    byId("upgLiveLoss").textContent = String(run.losses);
    byId("upgLiveBet").textContent = fmtNum(run.bet) + "⭐️";
    byId("upgLiveDots").innerHTML = run.dots.slice(-28).map((w, i, a) => '<i class="' + (w ? "w" : "l") + (newDot && i === a.length - 1 ? " new" : "") + '"></i>').join("");
    const live = byId("upgAutoLive");
    if (live) live.classList.toggle("done", !run.active);
    byId("upgLiveTag").textContent = run.active ? "Авто-игра · " + UPG_AUTO_SPEEDS[run.p.speed].label.toLowerCase() : "Серия завершена";
    const reasonEl = byId("upgLiveReason");
    reasonEl.hidden = run.active;
    if (!run.active) reasonEl.textContent = UPG_AUTO_REASONS[run.reason] || UPG_AUTO_REASONS.other;
    byId("upgLiveActions").hidden = run.active;
}

function upgradeSetMode(mode) {
    if (upgradeBusy || mode === upgradeMode) return;
    upgradeMode = mode;
    const row = document.getElementById("upgradeModeRow");
    if (row) {
        row.dataset.mode = mode;
        row.querySelectorAll(".upg-mode-btn").forEach(b => b.classList.toggle("on", b.dataset.upgMode === mode));
    }
    haptic("selection");
    if (mode === "auto") upgradeAutoLoadCfg();
    else upgradeAutoView = "setup";
    upgradeNewGame();
    upgradeAutoRenderCard();
}

function upgradeAutoLoadCfg() {
    if (upgradeAutoCfgLoading) return;
    upgradeAutoCfgLoading = true;
    fetch("/api/upgrade/auto/config?uid=" + CURRENT_UID).then(r => r.json()).then(d => {
        upgradeAutoCfgLoading = false;
        if (!d || !d.ok) return;
        upgradeAutoCfg = {
            enabled: !!d.enabled,
            maxRounds: d.maxRounds,
            minDelayMs: d.minDelayMs,
            maxBet: d.maxBet
        };
        if (upgradeMode === "auto" && upgradeAutoView === "setup" && !(upgradeAutoRun && upgradeAutoRun.active)) {
            upgradeAutoRenderCard();
            updateUpgradeStartState();
        }
        const upgradeModal = document.getElementById("upgradeAutoModal");
        if (upgradeModal && upgradeModal.classList.contains("active")) upgradeAutoRenderModal();
    }).catch(() => {
        upgradeAutoCfgLoading = false;
    });
}

function upgradeAutoChanged(rerender) {
    upgradeAutoSave();
    if (rerender) {
        upgradeAutoRenderCard();
        upgradeAutoRenderModal();
    } else {
        upgradeAutoRefreshHints();
    }
    upgradeAutoSyncButton();
}

function upgradeAutoCardClick(e) {
    const s = upgradeAutoSet;
    const t = e.target;
    const rounds = t.closest("[data-upg-rounds]");
    if (rounds) {
        const n = parseInt(rounds.dataset.upgRounds, 10);
        if (UPG_AUTO_ROUNDS.indexOf(n) >= 0) s.rounds = n;
        haptic("selection");
        upgradeAutoChanged(true);
        return;
    }
    if (t.closest("[data-upg-toggle]")) {
        s.stopWin = !s.stopWin;
        haptic("selection");
        upgradeAutoChanged(true);
        return;
    }
    const seg = t.closest("[data-upg-seg]");
    const segBtn = t.closest("[data-upg-val]");
    if (seg && segBtn) {
        const key = seg.dataset.upgSeg;
        const val = segBtn.dataset.upgVal;
        if (key === "onLoss" && (val === "same" || val === "up")) s.onLoss = val;
        else if (key === "onWin" && (val === "same" || val === "reset" || val === "up")) s.onWin = val;
        else if (key === "speed" && UPG_AUTO_SPEEDS[val] && ["normal", "fast", "turbo"].indexOf(val) >= 0) s.speed = val;
        else return;
        haptic("selection");
        upgradeAutoChanged(true);
        return;
    }
    const pct = t.closest("[data-upg-pct]");
    if (pct) {
        const bits = pct.dataset.upgPct.split(":");
        const n = upgradeAutoClampPct(bits[1], null);
        if (n === null) return;
        if (bits[0] === "loss") s.lossPct = n;
        else s.winPct = n;
        haptic("selection");
        upgradeAutoChanged(true);
        return;
    }
    const act = t.closest("[data-upg-act]");
    if (act && act.dataset.upgAct === "settings") {
        openUpgradeAutoModal();
        return;
    }
    if (act && act.dataset.upgAct === "setup" && !(upgradeAutoRun && upgradeAutoRun.active)) {
        upgradeAutoView = "setup";
        upgradeAutoRenderCard();
    }
}

function upgradeAutoCardInput(e) {
    const el = e.target;
    const s = upgradeAutoSet;
    const key = el.dataset && el.dataset.upgIn;
    if (key && ["profit", "loss", "bigWin", "cap"].indexOf(key) >= 0) {
        const v = upgradeAutoCleanNum(el.value);
        if (v !== el.value) el.value = v;
        s[key] = v;
        upgradeAutoChanged(false);
        return;
    }
    const which = el.dataset && el.dataset.upgPctin;
    if (which === "loss" || which === "win") {
        const n = upgradeAutoClampPct(el.value, null);
        if (n === null) return;
        if (which === "loss") s.lossPct = n;
        else s.winPct = n;
        const card = document.getElementById("upgradeAutoCard");
        if (card) card.querySelectorAll('[data-upg-pct^="' + which + ':"]').forEach(c => c.classList.toggle("on", parseInt(c.dataset.upgPct.split(":")[1], 10) === n));
        upgradeAutoChanged(false);
    }
}

function upgradeAutoWire() {
    const card = document.getElementById("upgradeAutoCard");
    if (card && !card.dataset.wired) {
        card.dataset.wired = "1";
        card.addEventListener("click", upgradeAutoCardClick);
        card.addEventListener("input", upgradeAutoCardInput);
    }
    const row = document.getElementById("upgradeModeRow");
    if (row && !row.dataset.wired) {
        row.dataset.wired = "1";
        row.addEventListener("click", e => {
            const b = e.target.closest("[data-upg-mode]");
            if (b) upgradeSetMode(b.dataset.upgMode);
        });
    }
    const speed = document.getElementById("upgradeSpeedRow");
    if (speed && !speed.dataset.wired) {
        speed.dataset.wired = "1";
        speed.addEventListener("click", e => {
            const b = e.target.closest("[data-upg-speed]");
            if (b) upgradeSetSpeed(b.dataset.upgSpeed);
        });
    }
}

function upgradeAutoAlive(run) {
    return upgradeAutoRun === run && run.active;
}

function upgradeAutoParse() {
    const s = upgradeAutoSet;
    const out = {
        rounds: s.rounds,
        stopWin: s.stopWin,
        onLoss: s.onLoss,
        lossPct: s.lossPct,
        onWin: s.onWin,
        winPct: s.winPct,
        speed: s.speed
    };
    const labels = {
        profit: "Прибыль серии",
        loss: "Убыток серии",
        bigWin: "Выигрыш за раунд",
        cap: "Потолок ставки"
    };
    const keys = Object.keys(labels);
    for (let i = 0; i < keys.length; i++) {
        const n = upgradeAutoNum(s[keys[i]]);
        if (n !== null && !(n > 0)) {
            showToast(labels[keys[i]] + ": введите число больше нуля или оставьте поле пустым", "error");
            return null;
        }
        out[keys[i]] = n;
    }
    return out;
}

function upgradeAutoClickMain() {
    const run = upgradeAutoRun;
    if (run && run.active) {
        upgradeAutoRequestStop("user");
        return;
    }
    upgradeAutoStart();
}

function upgradeAutoStartFailed(run, data) {
    run.active = false;
    upgradeBusy = false;
    upgradeAutoView = "setup";
    if (data && data.autoCode === "off" && upgradeAutoCfg) upgradeAutoCfg.enabled = false;
    setUpgradePanelLocked(false);
    upgradeAutoRenderCard();
    updateUpgradeStartState();
    showToast(data && data.error || "Не удалось связаться с сервером", "error");
}

function upgradeAutoStart() {
    if (upgradeBusy) return;
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    if (upgradeAutoCfg && !upgradeAutoCfg.enabled) {
        showToast("Авто-игра сейчас отключена", "warning");
        return;
    }
    const state = upgradeReadyState();
    if (!state.hasBet) return;
    if (!state.enoughBalance) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    if (state.underMin) {
        showToast("Минимальная ставка — " + fmtNum(betMin("upgrade")) + "⭐️", "error");
        return;
    }
    if (state.overMax) {
        showToast("Максимальная ставка — " + fmtNum(betMax("upgrade")) + "⭐️", "error");
        return;
    }
    const p = upgradeAutoParse();
    if (!p) return;
    const cfg = upgradeAutoCfg || {
        enabled: true,
        maxRounds: 100,
        minDelayMs: 450,
        maxBet: 0
    };
    if (cfg.maxBet > 0 && state.bet > cfg.maxBet + 1e-9) {
        showToast("В авто-игре ставка не больше " + fmtNum(cfg.maxBet) + "⭐️", "error");
        return;
    }
    if (p.cap && state.bet > p.cap + 1e-9) {
        showToast("Потолок ставки ниже вашей ставки", "error");
        return;
    }
    const run = {
        active: true,
        sid: null,
        p: p,
        cfg: cfg,
        total: p.rounds ? Math.min(p.rounds, cfg.maxRounds) : cfg.maxRounds,
        base: state.bet,
        bet: state.bet,
        round: 0,
        wins: 0,
        losses: 0,
        staked: 0,
        returned: 0,
        dots: [],
        stopReason: null,
        stopRequested: null,
        lastAt: 0,
        retry: 0,
        timer: null,
        inflight: false,
        spinning: false,
        finishPending: null,
        finishSent: false,
        reason: null,
        minDelay: cfg.minDelayMs + 40
    };
    upgradeAutoCloseModal();
    upgradeAutoRun = run;
    upgradeBusy = true;
    upgradeLastBet = state.bet;
    upgradeAutoView = "live";
    setUpgradePanelLocked(true);
    upgradeAutoRenderCard();
    haptic("impact", "medium");
    fetch("/api/upgrade/auto/start", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            params: {
                rounds: p.rounds,
                stopWin: p.stopWin,
                profit: p.profit,
                loss: p.loss,
                bigWin: p.bigWin,
                cap: p.cap,
                onLoss: p.onLoss,
                lossPct: p.lossPct,
                onWin: p.onWin,
                winPct: p.winPct,
                speed: p.speed,
                bet: state.bet,
                chance: upgradeChance
            }
        })
    }).then(r => r.json()).then(d => {
        if (!upgradeAutoAlive(run)) return;
        if (!d || !d.ok) {
            upgradeAutoStartFailed(run, d);
            return;
        }
        run.sid = d.sid;
        run.cfg = {
            enabled: true,
            maxRounds: d.maxRounds,
            minDelayMs: d.minDelayMs,
            maxBet: d.maxBet
        };
        upgradeAutoCfg = run.cfg;
        run.minDelay = d.minDelayMs + 40;
        run.total = p.rounds ? Math.min(p.rounds, d.maxRounds) : d.maxRounds;
        if (d.maxBet > 0 && run.bet > d.maxBet + 1e-9) {
            upgradeAutoStartFailed(run, {
                error: "В авто-игре ставка не больше " + fmtNum(d.maxBet) + "⭐️"
            });
            return;
        }
        upgradeAutoPaintLive(false);
        upgradeAutoStep(run);
    }).catch(() => {
        if (upgradeAutoAlive(run)) upgradeAutoStartFailed(run, null);
    });
}

function upgradeAutoClampBet(run) {
    let cap = betMax("upgrade");
    if (run.cfg.maxBet > 0) cap = Math.min(cap, run.cfg.maxBet);
    if (run.p.cap) cap = Math.min(cap, run.p.cap);
    return gvRound2(Math.min(Math.max(run.bet, betMin("upgrade")), cap));
}

function upgradeAutoStep(run) {
    if (!upgradeAutoAlive(run)) return;
    if (!document.getElementById("upgradeStartBtn") || currentGame !== "upgrader") {
        upgradeAutoAbort("user");
        return;
    }
    const reason = run.stopReason || run.stopRequested;
    if (reason) {
        upgradeAutoFinish(run, reason);
        return;
    }
    const bet = upgradeAutoClampBet(run);
    if (bet > currentUser.balance + 1e-9) {
        upgradeAutoFinish(run, "balance");
        return;
    }
    run.bet = bet;
    upgradeAutoPaintLive(false);
    const wait = run.lastAt + run.minDelay - Date.now();
    if (wait > 0) run.timer = setTimeout(() => upgradeAutoFire(run), wait);
    else upgradeAutoFire(run);
}

function upgradeAutoFire(run) {
    if (!upgradeAutoAlive(run)) return;
    run.lastAt = Date.now();
    run.inflight = true;
    upgradeWheelLabel(document.getElementById("upgradeRingBox"), "idle");
    fetch("/api/upgrade/play", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            bet: run.bet,
            chance: upgradeChance,
            autoSid: run.sid
        })
    }).then(r => r.json()).then(data => {
        run.inflight = false;
        if (data && data.ok && typeof data.balance === "number") applyBalance(data.balance);
        if (!upgradeAutoAlive(run)) {
            if (run.finishPending) upgradeAutoSendFinish(run, run.finishPending);
            return;
        }
        if (!data || !data.ok) {
            upgradeAutoFail(run, data);
            return;
        }
        upgradeAutoSpin(run, data);
    }).catch(() => {
        run.inflight = false;
        if (!upgradeAutoAlive(run)) {
            if (run.finishPending) upgradeAutoSendFinish(run, run.finishPending);
            return;
        }
        upgradeAutoFinish(run, "error");
    });
}

function upgradeAutoFail(run, data) {
    const code = data && data.autoCode;
    const msg = data && data.error || "Ошибка сервера";
    if (data && data.betsPaused) {
        upgradeAutoFinish(run, "bets");
        return;
    }
    if (code === "fast" && run.retry < 3) {
        run.retry += 1;
        run.timer = setTimeout(() => upgradeAutoFire(run), run.minDelay);
        return;
    }
    if (code === "limit") {
        upgradeAutoFinish(run, "limit");
        return;
    }
    if (code === "off") {
        if (upgradeAutoCfg) upgradeAutoCfg.enabled = false;
        upgradeAutoFinish(run, "off");
        return;
    }
    if (/Недостаточно средств/.test(msg)) {
        upgradeAutoFinish(run, "balance");
        return;
    }
    showToast(msg, "error");
    upgradeAutoFinish(run, code === "cap" ? "other" : "error");
}

function upgradeAutoSpin(run, data) {
    run.retry = 0;
    const speed = UPG_AUTO_SPEEDS[run.p.speed];
    const win = !!data.win;
    const roll = Number(data.roll);
    const chance = Number(data.chance);
    upgradeCurrentRoundInfo = {
        roundId: data.roundId,
        seedHash: data.seedHash,
        serverSeed: data.serverSeed,
        chance: data.chance,
        status: "finished"
    };
    updateUpgradeRoundIdLabel();
    const box = document.getElementById("upgradeRingBox");
    run.spinning = true;
    const done = () => {
        run.spinning = false;
        if (!upgradeAutoAlive(run)) return;
        const bet = Number(data.betAmount) || run.bet;
        const payout = win ? Number(data.winAmount) || 0 : 0;
        run.round += 1;
        run.staked += bet;
        run.returned += payout;
        if (win) run.wins += 1;
        else run.losses += 1;
        run.dots.push(win);
        const liveBox = document.getElementById("upgradeRingBox");
        if (liveBox) {
            liveBox.classList.remove("spinning");
            upgradeWheelLabel(liveBox, win ? "win" : "loss", roll);
        }
        haptic("impact", win ? "medium" : "light");
        upgradeAutoAfterRound(run, win, payout);
        upgradeAutoPaintLive(true);
        if (run.round % 5 === 0) loadUpgradeHistory();
        run.timer = setTimeout(() => upgradeAutoStep(run), speed.pause);
    };
    if (!box || !box.querySelector(".upg-arrow") || !isFinite(roll) || !isFinite(chance)) {
        done();
        return;
    }
    upgradeWheelSetChance(box, chance, "main");
    box.classList.add("spinning");
    upgradeSpinArrow(box, upgradeArrowTarget(chance, roll), () => setTimeout(done, speed.spin.reveal), speed.spin);
}

function upgradeAutoAfterRound(run, win, payout) {
    const p = run.p;
    if (win) {
        if (p.onWin === "reset") run.bet = run.base;
        else if (p.onWin === "up") run.bet = run.bet * (1 + p.winPct / 100);
    } else if (p.onLoss === "up") {
        run.bet = run.bet * (1 + p.lossPct / 100);
    }
    run.bet = gvRound2(run.bet);
    const net = run.returned - run.staked;
    let reason = null;
    if (p.stopWin && win) reason = "win";
    else if (p.profit && net >= p.profit - 1e-9) reason = "profit";
    else if (p.loss && -net >= p.loss - 1e-9) reason = "loss";
    else if (p.bigWin && win && payout >= p.bigWin - 1e-9) reason = "bigwin";
    else if (run.round >= run.total) reason = p.rounds ? "done" : "limit";
    run.stopReason = reason;
}

function upgradeAutoRequestStop(reason) {
    const run = upgradeAutoRun;
    if (!run || !run.active || run.stopRequested) return;
    run.stopRequested = reason;
    if (!run.inflight && !run.spinning) {
        clearTimeout(run.timer);
        upgradeAutoFinish(run, run.stopReason || reason);
        return;
    }
    upgradeAutoSyncButton();
}

function upgradeAutoSendFinish(run, reason) {
    if (!run.sid || run.finishSent) return;
    run.finishSent = true;
    fetch("/api/upgrade/auto/finish", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        keepalive: true,
        body: JSON.stringify({
            uid: CURRENT_UID,
            sid: run.sid,
            reason: reason
        })
    }).catch(() => {});
}

function upgradeAutoFinish(run, reason) {
    if (!upgradeAutoAlive(run)) return;
    run.active = false;
    run.reason = reason;
    clearTimeout(run.timer);
    upgradeBusy = false;
    upgradeAutoView = "done";
    const box = document.getElementById("upgradeRingBox");
    if (box) box.classList.remove("spinning");
    setUpgradePanelLocked(false);
    upgradeAutoSendFinish(run, reason);
    upgradeAutoRenderCard();
    upgradeAutoToast(run);
    loadUpgradeHistory();
    updateUpgradeStartState();
}

function upgradeAutoAbort(reason) {
    const run = upgradeAutoRun;
    if (!run || !run.active) return;
    run.active = false;
    run.reason = reason;
    clearTimeout(run.timer);
    upgradeBusy = false;
    const box = document.getElementById("upgradeRingBox");
    if (box) upgradeStopSpin(box);
    if (run.inflight) run.finishPending = reason;
    else upgradeAutoSendFinish(run, reason);
}

function upgradeAutoToast(run) {
    if (!run.round) return;
    const net = Math.round((run.returned - run.staked) * 100) / 100;
    if (net > 0) showGameWinToast(net, "Итог серии +", "⭐️");
    else if (net < 0) showGameLoseToast("Итог серии: −" + fmtNum(-net) + "⭐️");
    else showToast("Серия окончена: вы в нуле", "warning");
}

function upgradeAutoReset() {
    upgradeAutoCloseModal();
    upgradeAutoAbort("user");
    upgradeAutoRun = null;
    upgradeMode = "manual";
    upgradeAutoView = "setup";
    upgradeAutoWire();
}

document.addEventListener("visibilitychange", () => {
    if (document.hidden) upgradeAutoRequestStop("hidden");
});

function playUpgrade() {
    if (upgradeBusy) return;
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const state = upgradeReadyState();
    if (!state.hasBet) return;
    if (!state.enoughBalance) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    if (state.underMin) {
        showToast("Минимальная ставка — " + fmtNum(betMin("upgrade")) + "⭐️", "error");
        return;
    }
    if (state.overMax) {
        showToast("Максимальная ставка — " + fmtNum(betMax("upgrade")) + "⭐️", "error");
        return;
    }
    upgradeBusy = true;
    upgradeLastBet = state.bet;
    setUpgradePanelLocked(true);
    const btn = document.getElementById("upgradeStartBtn");
    if (btn) {
        btn.classList.add("dim");
        btn.textContent = "Крутится…";
    }
    const startBox = document.getElementById("upgradeRingBox");
    upgradeWheelLabel(startBox, "idle");
    upgradeResetArrow(startBox);
    fetch("/api/upgrade/play", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            bet: state.bet,
            chance: upgradeChance
        })
    }).then(r => r.json()).then(data => {
        if (!data || !data.ok) {
            upgradeBusy = false;
            setUpgradePanelLocked(false);
            if (btn) btn.textContent = "Начать игру";
            updateUpgradeStartState();
            showToast(data && data.error || "Ошибка сервера", "error");
            return;
        }
        spinUpgradeRing(data);
    }).catch(() => {
        upgradeBusy = false;
        setUpgradePanelLocked(false);
        if (btn) btn.textContent = "Начать игру";
        updateUpgradeStartState();
        showToast("Не удалось связаться с сервером", "error");
    });
}

function upgradeFairFormulaHTML() {
    return '<p class="modal-text">Формула, которую можно пересчитать самостоятельно (пример на Python — hmac.new(seed.encode(), uid.encode(), hashlib.sha256)):</p>' + '<ol class="fair-formula-steps">' + "<li>H = HMAC-SHA256(секретный сид, UID раунда как обычный UTF-8 текст)</li>" + "<li>R = первые 13 hex-символов H, переведённые в число по основанию 16</li>" + "<li>roll = R / 16^13 × 100 — число от 0.0000 до 99.9999…</li>" + "<li>Победа, если " + UPGRADE_MIN_ROLL.toFixed(4) + " ≤ roll ≤ выбранный шанс (%)</li>" + "</ol>" + '<p class="modal-text">Результат обязан совпасть с показанным roll — если хэш выше совпадает с SHA-256(сид), а расчёт даёт другое число, значит подменили сид или UID.</p>';
}

function openUpgradeFair() {
    const info = upgradeCurrentRoundInfo;
    const roundId = info && info.roundId;
    if (roundId) {
        gvFairId.textContent = roundId;
        gvFairId.classList.remove("text-skel");
    } else {
        gvFairId.textContent = "UXXXXXXXX";
        gvFairId.classList.add("text-skel");
    }
    if (info && info.seedHash) setFairHashEl(gvFairHash, info.seedHash);
    else setFairHashSkeleton(gvFairHash);
    let resultHtml = '<div class="fair-block"><div class="fair-label">UID раунда</div><div class="fair-hash"' + (roundId ? ' data-copy="' + escapeHtml(roundId) + '">' + fairHashHTML(roundId) : ">" + fairHashSkeletonHTML()) + "</div></div>";
    if (info && info.serverSeed) {
        resultHtml += '<div class="fair-block"><div class="fair-label">Секретный сид</div><div class="fair-hash" data-copy="' + escapeHtml(info.serverSeed) + '">' + fairHashHTML(info.serverSeed) + "</div></div>";
        gvFairNote.style.display = "";
        gvFairNote.innerHTML = upgradeFairFormulaHTML();
    } else {
        resultHtml += '<div class="fair-result-note">Сыграйте раунд, чтобы получить UID и хэш.</div>';
        gvFairNote.style.display = "none";
    }
    gvFairResult.innerHTML = resultHtml;
    gvFairLink.style.display = "none";
    gvFairModal.classList.add("active");
}

function upgradeHistoryRowHTML(r) {
    let meta = {};
    try {
        meta = JSON.parse(r.meta || "{}");
    } catch (e) {}
    const isWin = r.result === "win";
    const isMe = r.user_id === CURRENT_UID;
    const botBadge = r.in_chat || meta.inChat ? '<span class="gv-history-bot-badge">Чат</span>' : meta.playedInBot ? '<span class="gv-history-bot-badge">Бот</span>' : "";
    const name = isMe ? currentUser.displayName || "Игрок" : r.username || "Игрок";
    const avatarUrl = isMe ? currentUser.avatarUrl : "/api/avatar/" + r.user_id;
    const chance = meta.chance != null ? fmtCoef(meta.chance) : "—";
    const roll = meta.roll != null ? fmtCoef(meta.roll) : "—";
    return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-avatar"><div class="skel-box"></div>' + lazyImgTag(avatarUrl, name) + "</div>" + '<div class="gv-history-mid">' + '<div class="gv-history-name"><span class="gv-history-name-text">' + escapeHtml(name) + "</span>" + (meta.auto ? '<span class="upg-auto-tag">АВТО</span>' : "") + botBadge + "</div>" + historyTimeHTML(r.created_at) + "</div>" + '<div class="gv-history-right">Сумма ставки: <b>' + fmtNum(r.bet) + "⭐️</b><br>" + '<span class="gv-history-outcome">Шанс: <b>' + chance + "%</b> · Roll: <b>" + roll + "</b></span><br>" + (isWin ? '<span class="gv-history-win">Выигрыш: ' + fmtNum(r.win_amount) + "⭐️ (x" + fmtCoef(meta.multiplier) + ")</span>" : '<span class="gv-history-lose">Проигрыш</span>') + "</div>" + "</div>" + (meta.roundId ? '<button class="crash-history-fair-btn" type="button" data-upgrade-round="' + escapeHtml(meta.roundId) + '">' + fairCheckBtnIconHTML() + "Проверить честность</button>" : "") + "</div>";
}

function loadUpgradeHistory(scope, append) {
    if (scope) {
        upgradeHistoryScope = scope;
        append = false;
    }
    gvHistoryLoad("upgradeHistoryList", off => "/api/upgrade/history?uid=" + CURRENT_UID + "&scope=" + upgradeHistoryScope + "&offset=" + off, 20, (rows, append) => {
        const list = document.getElementById("upgradeHistoryList");
        const html = rows.map(upgradeHistoryRowHTML).join("");
        if (append) list.insertAdjacentHTML("beforeend", html);
        else list.innerHTML = html;
    }, GV_HISTORY_EMPTY_HTML, append);
}

GV_HISTORY_BY_GAME["upgrader"] = {
    listId: "upgradeHistoryList",
    load: () => loadUpgradeHistory(null, true)
};

const upgradeRoundModal = document.getElementById("upgradeRoundModal");

const upgradeRoundRing = document.getElementById("upgradeRoundRing");

const upgradeRoundPlayerRow = document.getElementById("upgradeRoundPlayerRow");

const upgradeRoundFairBlock = document.getElementById("upgradeRoundFairBlock");

let upgradeRoundData = null;

function upgradeRoundRingHTML(detail) {
    return upgradeWheelSVG("round", Number(detail.chance) || 0, UPGRADE_IDLE_ANGLE);
}

function playUpgradeRoundReplay(detail) {
    const ring = upgradeRoundRing;
    if (!ring || !ring.querySelector(".upg-arrow")) return;
    const chance = Number(detail.chance) || 0;
    const roll = Number(detail.roll) || 0;
    ring._upgAngle = UPGRADE_IDLE_ANGLE;
    upgradeWheelLabel(ring, "idle");
    ring.classList.add("spinning");
    upgradeSpinArrow(ring, upgradeArrowTarget(chance, roll), tok => {
        setTimeout(() => {
            if (ring._upgTok !== tok) return;
            ring.classList.remove("spinning");
            upgradeWheelLabel(ring, detail.result === "win" ? "win" : "loss", roll);
        }, UPGRADE_SPIN.reveal);
    });
}

function upgradeRoundPlayerRowHTML(detail) {
    const isMe = detail.userId === CURRENT_UID;
    const name = isMe ? currentUser.displayName || "Игрок" : detail.username || "Игрок";
    const avatarUrl = isMe ? currentUser.avatarUrl : "/api/avatar/" + detail.userId;
    const isWin = detail.result === "win";
    return '<div class="crash-player-row' + (isMe ? " me" : "") + '">' + '<div class="crash-player-avatar"><img src="' + avatarUrl + '" alt="" loading="lazy"></div>' + '<div class="crash-player-mid">' + '<div class="crash-player-name"><span class="crash-player-name-text">' + escapeHtml(name) + "</span>" + (isMe ? ' <span class="lb-you-tag">Вы</span>' : "") + "</div>" + '<div class="crash-player-sub">Ставка: ' + fmtNum(detail.bet) + "⭐️" + (detail.chance != null ? " · Шанс: " + fmtCoef(detail.chance) + "%" : "") + "</div>" + "</div>" + (detail.multiplier != null ? '<div class="crash-player-mult">x' + fmtCoef(detail.multiplier) + "</div>" : "") + '<div class="crash-player-value">' + (isWin ? "+" + fmtNum(detail.winAmount) + "⭐️" : "Проигрыш") + "</div>" + "</div>";
}

function openUpgradeRoundModal(publicId) {
    if (!publicId) return;
    upgradeRoundData = null;
    upgradeRoundFairBlock.style.display = "none";
    upgradeRoundFairBlock.innerHTML = "";
    document.getElementById("upgradeRoundFairBtn").textContent = "Проверить честность";
    document.getElementById("upgradeRoundModalId").textContent = publicId;
    upgradeStopSpin(upgradeRoundRing);
    upgradeRoundRing.innerHTML = '<div class="skel-box" style="position:absolute; inset:0; border-radius:50%;"></div>';
    upgradeRoundRing.classList.remove("won", "lost", "spinning");
    upgradeRoundPlayerRow.innerHTML = minesRoundPlayerSkeletonHTML();
    upgradeRoundModal.classList.add("active");
    fetch("/api/upgrade/round?id=" + encodeURIComponent(publicId)).then(r => r.json()).then(data => {
        if (!upgradeRoundModal.classList.contains("active")) return;
        if (!data || !data.ok) {
            upgradeRoundPlayerRow.innerHTML = '<div class="crash-players-empty">Раунд не найден</div>';
            return;
        }
        upgradeRoundData = data;
        upgradeRoundRing.innerHTML = upgradeRoundRingHTML(data);
        upgradeRoundPlayerRow.innerHTML = upgradeRoundPlayerRowHTML(data);
        playUpgradeRoundReplay(data);
    }).catch(() => {
        upgradeRoundPlayerRow.innerHTML = '<div class="crash-players-empty">Не удалось загрузить раунд</div>';
    });
}

function closeUpgradeRoundModal() {
    upgradeRoundModal.classList.remove("active");
}

document.getElementById("upgradeRoundClose").addEventListener("click", closeUpgradeRoundModal);

upgradeRoundModal.addEventListener("click", e => {
    if (e.target === upgradeRoundModal) closeUpgradeRoundModal();
});

document.getElementById("upgradeRoundFairBtn").addEventListener("click", () => {
    const data = upgradeRoundData;
    if (!data) return;
    const isHidden = upgradeRoundFairBlock.style.display === "none";
    if (isHidden) {
        upgradeRoundFairBlock.innerHTML = '<div class="fair-block"><div class="fair-label">UID раунда</div><div class="fair-hash" data-copy="' + escapeHtml(data.roundId) + '">' + fairHashHTML(data.roundId) + "</div></div>" + '<div class="fair-block"><div class="fair-label">SHA-256 hash</div><div class="fair-hash" data-copy="' + escapeHtml(data.seedHash || "") + '">' + fairHashHTML(data.seedHash || "—") + "</div></div>" + '<div class="fair-block"><div class="fair-label">Секретный сид</div><div class="fair-hash" data-copy="' + escapeHtml(data.serverSeed || "") + '">' + fairHashHTML(data.serverSeed || "—") + "</div></div>" + upgradeFairFormulaHTML();
        upgradeRoundFairBlock.style.display = "";
        document.getElementById("upgradeRoundFairBtn").textContent = "Скрыть информацию";
    } else {
        upgradeRoundFairBlock.style.display = "none";
        document.getElementById("upgradeRoundFairBtn").textContent = "Проверить честность";
    }
});

function setNavActive(name) {
    const items = Array.from(document.querySelectorAll(".nav-item"));
    const nav = document.querySelector(".bottom-nav");
    let idx = -1;
    items.forEach((i, n) => {
        const on = i.dataset.nav === name;
        i.classList.toggle("active", on);
        if (on) idx = n;
    });
    if (!nav || idx < 0) return;
    nav.style.setProperty("--nav-i", idx);
    const playIcon = document.querySelector('.nav-item[data-nav="играть"] .nav-icon');
    if (playIcon) {
        const wantStatic = name === "играть" || currentUser.liteUiEnabled;
        const isStatic = !!playIcon.querySelector("img");
        if (wantStatic && !isStatic) {
            playIcon.innerHTML = '<img src="images/РазделИграть.png" alt="">';
        } else if (!wantStatic && isStatic) {
            playIcon.innerHTML = '<canvas class="lottie-canvas" width="96" height="96" data-lottie-src="/lottie/NavBar/РазделИграть.lottie"></canvas>';
        }
    }
    if (nav.dataset.active !== name) {
        nav.dataset.active = name;
        const icon = items[idx].querySelector("canvas.lottie-canvas");
        if (icon) replayLottie(icon);
    }
}

