const gameSwitchOff = new Set(["doghouse"]);

window.gameSwitchOff = gameSwitchOff;

let gameSwitchOrder = [];

let gameSwitchVer = -1;

let gameSwitchBusy = false;

function gameNameClosed(name) {
    const ids = GAME_NAME_IDS[name];
    return !!ids && ids.every(id => gameSwitchOff.has(id));
}

function gameClosedByAdmin(name) {
    const closed = gameNameClosed(name);
    if (closed) showToast("Игра временно недоступна", "warning");
    return closed;
}

function applyGameSwitchStyle() {
    let el = document.getElementById("gameSwitchStyle");
    if (!el) {
        el = document.createElement("style");
        el.id = "gameSwitchStyle";
        document.head.appendChild(el);
    }
    const hidden = [];
    GAME_SWITCH_TILES.forEach(rule => {
        const off = rule.anyOff ? rule.ids.some(id => gameSwitchOff.has(id)) : rule.ids.every(id => gameSwitchOff.has(id));
        if (off) rule.sel.forEach(s => hidden.push(s));
    });
    el.textContent = hidden.length ? hidden.join(",") + "{display:none !important}" : "";
    syncCardsRow();
}

function syncCardsRow() {
    const row = document.getElementById("cardGamesRow");
    if (!row) return;
    const shown = Array.prototype.filter.call(row.children, s => getComputedStyle(s).display !== "none");
    row.classList.toggle("fc-solo", shown.length === 1);
}

function applyGameOrder() {
    const pos = {};
    gameSwitchOrder.forEach((id, i) => {
        pos[id] = i;
    });
    document.querySelectorAll("#gamesGrid .game-card, #exclusiveScroll .game-card").forEach(card => {
        const id = GAME_CARD_IDS[card.dataset.name];
        if (id in pos) card.style.order = String(pos[id]);
    });
    document.querySelectorAll("#pvpGamesGrid .game-card").forEach(card => {
        const id = GAME_PVP_CARD_IDS[card.dataset.name];
        if (id in pos) card.style.order = String(pos[id]);
    });
}

function updateGameOffBanner() {
    const host = document.getElementById("gvBody");
    if (!host || !host.parentNode) return;
    let banner = document.getElementById("gvOffBanner");
    const closed = gameView.classList.contains("active") && !!currentGame && gameNameClosed(currentGame);
    if (!closed) {
        if (banner) banner.remove();
        return;
    }
    if (!banner) {
        banner = document.createElement("div");
        banner.id = "gvOffBanner";
        banner.className = "gv-off-banner";
        banner.textContent = "Игра временно недоступна — новые ставки не принимаются. Уже начатый раунд можно доиграть.";
        host.parentNode.insertBefore(banner, host);
    }
}

function applyGameSwitches(data) {
    if (!data || !data.ok) return;
    const before = Array.from(gameSwitchOff).sort().join(",");
    gameSwitchOff.clear();
    gameSwitchOff.add("doghouse");
    (data.off || []).forEach(id => gameSwitchOff.add(id));
    gameSwitchOrder = data.order || [];
    gameSwitchVer = typeof data.ver === "number" ? data.ver : gameSwitchVer;
    if (window.GameNames) window.GameNames.set(data.names || {});
    applyGameSwitchStyle();
    applyGameOrder();
    updateGameOffBanner();
    if (before !== Array.from(gameSwitchOff).sort().join(",") && typeof loadPopularGames === "function") loadPopularGames();
}

function loadGameSwitches() {
    if (gameSwitchBusy) return;
    gameSwitchBusy = true;
    fetch("/api/games/off", {
        cache: "no-store"
    }).then(r => r.json()).then(applyGameSwitches).catch(function() {}).then(function() {
        gameSwitchBusy = false;
    });
}

function gameSwitchSeen(ver) {
    if (typeof ver === "number" && ver !== gameSwitchVer) loadGameSwitches();
}

loadGameSwitches();

document.addEventListener("visibilitychange", function() {
    if (!document.hidden) loadGameSwitches();
});

const CF_LOTTIE = {
    heads: "/lottie/ИграОрелРешка/Орел.lottie",
    tails: "/lottie/ИграОрелРешка/Решка.lottie"
};

const CF_PNG = {
    heads: "/lottie/ИграОрелРешка/Орел.png",
    tails: "/lottie/ИграОрелРешка/Решка.png"
};

const CF_SIDE_RU = {
    heads: "Орёл",
    tails: "Решка"
};

const CF_SIDE_LETTER = {
    heads: "О",
    tails: "Р"
};

const CF_ICON = {
    ok: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.4 12.7l3.7 3.7 7.5-7.9" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>',
    bad: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 7l10 10M17 7L7 17" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/></svg>',
    dash: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 12h10" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/></svg>'
};

let cfCfg = null;

let cfCommit = null;

let cfReady = false;

let cfBusy = false;

let cfRound = null;

let cfPhase = "idle";

let cfScope = "all";

let cfRunToken = 0;

let cfFinishTimer = 0;

let cfActTimer = 0;

let cfActAt = 0;

let cfFlipStart = 0;

let cfMountToken = 0;

let cfLastRoundId = "";

let cfRecent = [];

let cfPlayer = null;

let cfPendingBalance = null;

function cfStepMult() {
    if (cfRound && cfRound.stepMult) return cfRound.stepMult;
    return cfCfg ? cfCfg.stepMult || cfCfg.multiplier : 1.95;
}

function cfMaxSteps() {
    return cfRound && cfRound.maxSteps || cfCfg && cfCfg.maxSteps || 15;
}

function cfIsLite() {
    return currentUser.liteUiEnabled === true;
}

function cfById(id) {
    return document.getElementById(id);
}

function cfMoney(v) {
    return fmtNum(v) + "⭐️";
}

function cfNow() {
    return typeof performance !== "undefined" ? performance.now() : Date.now();
}

function cfChipHTML(side, extra) {
    return '<span class="cf-chip ' + side + (extra ? " " + extra : "") + '">' + CF_SIDE_LETTER[side] + "</span>";
}

function cfPlayerHTML(id) {
    if (cfIsLite()) return '<img class="cf-coin-png on" id="' + id + 'Png" src="' + CF_PNG.heads + '" alt="">';
    return '<canvas class="cf-coin on" id="' + id + 'Heads" width="512" height="512"></canvas><canvas class="cf-coin" id="' + id + 'Tails" width="512" height="512"></canvas>';
}

function cfCreatePlayer(id, alive) {
    const lite = cfIsLite();
    const player = {
        id: id,
        lite: lite,
        side: "heads",
        dl: {
            heads: null,
            tails: null
        },
        onComplete: null
    };
    if (lite) return Promise.resolve(player);
    const load = side => {
        const canvas = cfById(id + (side === "heads" ? "Heads" : "Tails"));
        if (!canvas) return Promise.resolve(null);
        return loadDotLottie().then(DotLottie => new Promise(resolve => {
            if (!alive() || !canvas.isConnected) {
                resolve(null);
                return;
            }
            const dl = new DotLottie({
                canvas: canvas,
                src: CF_LOTTIE[side],
                loop: false,
                autoplay: false,
                renderConfig: {
                    autoResize: true,
                    devicePixelRatio: lottieDprFor(canvas),
                    freezeOnOffscreen: false
                }
            });
            dl.addEventListener("load", () => {
                if (!alive()) {
                    try {
                        dl.destroy();
                    } catch (e) {}
                    resolve(null);
                    return;
                }
                try {
                    dl.setFrame(0);
                } catch (e) {}
                player.dl[side] = dl;
                _lottieLive.add(dl);
                dl.addEventListener("complete", () => {
                    if (player.onComplete) player.onComplete(side);
                });
                resolve(dl);
            });
            dl.addEventListener("loadError", () => resolve(null));
        })).catch(() => null);
    };
    return Promise.all([load("heads"), load("tails")]).then(() => player);
}

function cfDestroyPlayer(player) {
    if (!player) return;
    player.onComplete = null;
    ["heads", "tails"].forEach(side => {
        const dl = player.dl[side];
        player.dl[side] = null;
        if (!dl) return;
        _lottieLive.delete(dl);
        try {
            dl.destroy();
        } catch (e) {}
    });
}

function cfPlayerShow(player, side) {
    if (!player) return;
    player.side = side;
    if (player.lite) {
        const img = cfById(player.id + "Png");
        if (img) {
            img.classList.remove("flipping");
            const src = CF_PNG[side];
            if (img.getAttribute("src") !== src) img.setAttribute("src", src);
        }
        return;
    }
    const heads = cfById(player.id + "Heads");
    const tails = cfById(player.id + "Tails");
    if (heads) heads.classList.toggle("on", side === "heads");
    if (tails) tails.classList.toggle("on", side === "tails");
}

function cfPlayerFrame(player, side, last) {
    if (!player || player.lite) return;
    const dl = player.dl[side];
    if (!dl) return;
    try {
        dl.stop();
        dl.setFrame(last ? Math.max(0, (dl.totalFrames || 90) - 1) : 0);
    } catch (e) {}
}

function cfPlayerFly(player, side, elapsed, flipSec, speed) {
    if (!player) return;
    if (player.lite) {
        cfPlayerShow(player, "heads");
        const img = cfById(player.id + "Png");
        if (img) img.classList.add("flipping");
        return;
    }
    cfPlayerShow(player, side);
    const dl = player.dl[side];
    if (!dl) return;
    try {
        dl.stop();
        if (elapsed > 0.05) dl.setFrame(Math.floor((dl.totalFrames || 90) * Math.min(.97, elapsed / flipSec)));
        if (speed && dl.setSpeed) dl.setSpeed(speed);
        dl.play();
    } catch (e) {}
}

function cfPlayerLand(player, side) {
    if (!player) return;
    cfPlayerShow(player, side);
    cfPlayerFrame(player, side, true);
}

function cfPlayerRest(player) {
    if (!player) return;
    cfPlayerShow(player, "heads");
    cfPlayerFrame(player, "heads", false);
    cfPlayerFrame(player, "tails", false);
}

function cfSideTilesHTML() {
    return ["heads", "tails"].map(side => '<button class="gv-outcome cf-side" type="button" data-coin="' + side + '"><span class="cf-side-name">' + CF_SIDE_RU[side] + '</span><span class="cf-side-mult" data-cf-mult>x' + fmtCoef(cfStepMult()) + "</span></button>").join("");
}

function cfChipsSkeletonHTML() {
    let html = "";
    for (let i = 0; i < 10; i++) html += '<span class="cf-chip skel"></span>';
    return html;
}

function renderCoinflip(data) {
    return '<div class="gv-mines-box cf-box">' + '<div class="gv-mult-row cf-mult-row"><div class="gv-mult-chip now" id="cfMultChip">Шанс 50% · выплата x' + fmtCoef(cfStepMult()) + "</div></div>" + '<div class="cf-stage" id="cfStage" data-phase="idle">' + '<div class="cf-glow"></div>' + '<div class="cf-coin-wrap" id="cfCoinWrap">' + cfPlayerHTML("cfCoin") + "</div>" + "</div>" + '<div class="cf-result" id="cfResult"></div>' + '<div class="cf-chips" id="cfChips">' + cfChipsSkeletonHTML() + "</div>" + '<div class="gv-mines-howto">' + '<div class="gv-fair" data-action="coinflip-fair"><span class="gv-fair-icon">#</span><span id="cfRoundIdLabel" class="text-skel">CXXXXXXXX</span></div>' + howtoHTML("position:static;") + "</div>" + "</div>" + '<div class="gv-panel" id="cfPanel">' + '<div class="gv-label" id="cfPanelLabel">Сторона монеты</div>' + '<div class="gv-outcomes cf-outcomes" id="cfOutcomes">' + cfSideTilesHTML() + "</div>" + '<div class="gv-label cf-bet-label" style="margin-top:18px;">Сумма ставки</div>' + betRowHTML() + "</div>" + '<button class="gv-start-btn dim" type="button" id="cfStartBtn">Загрузка…</button>' + '<div class="gv-history">' + '<div class="gv-history-head">' + '<h3 class="gv-history-title">' + lazyImgTag(liteAsset("/lottie/images/ОгоньЭмоджи.lottie"), "", "flame-gif") + " Последние игры</h3>" + '<div class="gv-history-tabs">' + '<button class="gv-history-tab active" type="button" data-coinflip-scope="all">Все</button>' + '<button class="gv-history-tab" type="button" data-coinflip-scope="mine">Мои</button>' + "</div>" + "</div>" + gvHistorySearchRowHTML("coinflipHistorySearchInput") + '<div class="gv-history-list" id="coinflipHistoryList"><div class="dice-history-empty">Загрузка…</div></div>' + "</div>";
}

function cfPick() {
    const el = gvBody.querySelector("#cfOutcomes .gv-outcome.selected");
    return el ? el.dataset.coin : "";
}

function cfClearPick() {
    gvBody.querySelectorAll("#cfOutcomes .gv-outcome").forEach(b => b.classList.remove("selected"));
}

function cfActive() {
    return cfPhase === "flip" || cfPhase === "decide";
}

function cfCanAct() {
    return cfPhase === "decide" && cfNow() >= cfActAt && !cfBusy;
}

function cfReadyState() {
    const input = gvBody.querySelector(".gv-bet-input");
    const bet = input ? parseFloat(input.value) : NaN;
    return {
        bet: bet,
        hasBet: bet > 0,
        enoughBalance: bet > 0 && bet <= currentUser.balance + 1e-6,
        overMax: bet > betMax("coinflip"),
        underMin: bet > 0 && bet < betMin("coinflip")
    };
}

function cfCashoutText() {
    return "Забрать " + cfMoney(cfRound ? cfRound.cashoutAmount : 0) + " (x" + fmtCoef(cfRound ? cfRound.multiplier : 1) + ")";
}

function cfUpdateStart() {
    const btn = cfById("cfStartBtn");
    if (!btn) return;
    const st = cfReadyState();
    let text = "Играть";
    let ready = false;
    if (!cfReady) text = "Загрузка…";
    else if (cfBusy) text = "…";
    else if (cfPhase === "flip") text = "Монета в воздухе…";
    else if (cfPhase === "decide") {
        text = cfRound && cfRound.canCashout ? cfCashoutText() : "Выберите сторону";
        ready = cfCanAct() && !!(cfRound && cfRound.canCashout);
    } else if (!betsAccepted) text = "Ставки приостановлены";
    else if (!cfPick()) text = "Выберите сторону";
    else ready = st.hasBet && st.enoughBalance && !st.overMax && !st.underMin && cfNow() >= cfActAt;
    if (btn.textContent !== text) btn.textContent = text;
    btn.classList.toggle("dim", !ready);
    const panel = cfById("cfPanel");
    if (panel) {
        panel.classList.toggle("cf-locked", cfBusy || cfPhase === "flip" || cfPhase === "decide" && !cfCanAct());
        panel.classList.toggle("cf-streak", cfActive());
    }
    const label = cfById("cfPanelLabel");
    if (label) {
        const text2 = cfActive() ? "Следующий бросок — выберите сторону" : "Сторона монеты";
        if (label.textContent !== text2) label.textContent = text2;
    }
    const betLabel = gvBody.querySelector(".cf-bet-label");
    if (betLabel) betLabel.classList.toggle("cf-dim", cfActive());
    document.querySelectorAll("[data-cf-mult]").forEach(el => {
        el.textContent = "x" + fmtCoef(cfStepMult());
    });
}

function cfUpdateChip() {
    const chip = cfById("cfMultChip");
    if (!chip || !cfRound && cfPhase !== "idle" && cfPhase !== "end") return;
    let text;
    if (cfActive() && cfRound) {
        const wins = cfRound.steps.filter(s => s.win).length;
        text = "Серия " + wins + " из " + cfMaxSteps() + " · x" + fmtCoef(cfRound.multiplier) + " → x" + fmtCoef(cfRound.nextMultiplier);
    } else if (cfPhase === "end" && cfRound && cfRound.status === "won") {
        text = "Серия " + cfRound.steps.length + " · итог x" + fmtCoef(cfRound.multiplier);
    } else {
        text = "Шанс 50% · выплата x" + fmtCoef(cfStepMult()) + " за бросок";
    }
    if (chip.textContent !== text) chip.textContent = text;
}

function cfUpdateRoundLabel() {
    const el = cfById("cfRoundIdLabel");
    if (!el) return;
    const id = cfRound && cfActive() ? cfRound.roundId : cfCommit ? cfCommit.roundId : "";
    if (id) {
        el.textContent = id;
        el.classList.remove("text-skel");
    } else {
        el.textContent = "CXXXXXXXX";
        el.classList.add("text-skel");
    }
}

function cfApplyConfig(c) {
    if (!c) return;
    cfCfg = c;
    cfUpdateChip();
    cfUpdateStart();
}

function cfSetPhase(phase) {
    const stage = cfById("cfStage");
    if (stage) stage.setAttribute("data-phase", phase);
}

function cfSetResult(cls, html) {
    const res = cfById("cfResult");
    if (!res) return;
    if (!html) {
        res.className = "cf-result";
        res.innerHTML = "";
        return;
    }
    res.className = "cf-result on" + (cls ? " " + cls : "");
    res.innerHTML = html;
}

function cfLastStep() {
    return cfRound && cfRound.steps.length ? cfRound.steps[cfRound.steps.length - 1] : null;
}

function cfLiveChips(round, includeLast) {
    const list = [];
    round.steps.forEach((s, i) => {
        if (i === round.steps.length - 1 && !includeLast) return;
        list.unshift({
            roundId: round.roundId,
            side: s.side,
            win: s.win,
            n: s.n,
            live: round.status === "active"
        });
    });
    return list;
}

function cfRenderChips() {
    const box = cfById("cfChips");
    if (!box) return;
    if (!cfRecent.length) {
        box.innerHTML = '<span class="cf-chips-empty">Результаты появятся после первых бросков</span>';
        return;
    }
    box.innerHTML = cfRecent.map(r => r.live ? '<span class="cf-chip-btn live" title="' + CF_SIDE_RU[r.side] + '">' + cfChipHTML(r.side) + "</span>" : '<button class="cf-chip-btn" type="button" data-coinflip-round="' + escapeHtml(r.roundId) + '" title="' + CF_SIDE_RU[r.side] + '">' + cfChipHTML(r.side) + "</button>").join("");
}

function cfPushChip(round, step) {
    cfRecent = cfRecent.filter(r => !(r.roundId === round.roundId && r.n === step.n));
    cfRecent.unshift({
        roundId: round.roundId,
        side: step.side,
        win: step.win,
        n: step.n,
        live: round.status === "active"
    });
    cfRecent = cfRecent.slice(0, 12);
    cfRenderChips();
}

function cfSealChips(roundId) {
    cfRecent.forEach(r => {
        if (r.roundId === roundId) r.live = false;
    });
    cfRenderChips();
}

function cfDecideHTML() {
    const last = cfLastStep();
    return "<b>" + CF_SIDE_RU[last.side] + "!</b><span>Заберёте " + cfMoney(cfRound.cashoutAmount) + " (x" + fmtCoef(cfRound.multiplier) + ") · дальше x" + fmtCoef(cfRound.nextMultiplier) + "</span>";
}

function cfClearTimers(all) {
    clearTimeout(cfFinishTimer);
    cfFinishTimer = 0;
    if (all) {
        clearTimeout(cfActTimer);
        cfActTimer = 0;
    }
}

function cfResetToIdle() {
    cfClearTimers();
    cfRunToken++;
    cfPhase = "idle";
    cfRound = null;
    cfSetPhase("idle");
    cfSetResult("", "");
    cfPlayerRest(cfPlayer);
    cfUpdateChip();
    cfUpdateRoundLabel();
    cfUpdateStart();
}

function cfScheduleAct(waitMs) {
    clearTimeout(cfActTimer);
    cfActAt = cfNow() + Math.max(0, waitMs);
    cfActTimer = setTimeout(() => {
        cfActTimer = 0;
        cfUpdateStart();
    }, Math.max(0, waitMs) + 30);
}

function cfBeginFlip(round, elapsed) {
    cfRound = round;
    cfPhase = "flip";
    cfSetPhase("flip");
    const step = cfLastStep();
    cfSetResult("", '<span class="cf-flip-note">Бросок №' + step.n + "…</span>");
    cfFlipStart = cfNow() - (elapsed || 0) * 1000;
    cfPlayerFly(cfPlayer, step.side, elapsed || 0, round.flipSec || 3, 0);
    cfUpdateChip();
    cfUpdateRoundLabel();
    const token = ++cfRunToken;
    clearTimeout(cfFinishTimer);
    const total = Math.max(0, round.finishIn || 0) * 1000;
    const flipMs = Math.max(0, ((round.flipSec || 3) - (elapsed || 0)) * 1000);
    const actWait = total + 120;
    cfScheduleAct(actWait);
    if (cfPlayer) cfPlayer.onComplete = () => {
        if (token === cfRunToken && cfPhase === "flip") cfReveal(token);
    };
    cfFinishTimer = setTimeout(() => cfReveal(token), flipMs + (cfIsLite() ? 80 : 700));
    cfUpdateStart();
}

function cfReveal(token) {
    if (token !== cfRunToken || cfPhase !== "flip") return;
    clearTimeout(cfFinishTimer);
    cfFinishTimer = 0;
    const round = cfRound;
    const step = cfLastStep();
    if (!round || !step) return;
    cfPlayerLand(cfPlayer, step.side);
    cfPushChip(round, step);
    if (round.status === "active") {
        round.flipping = false;
        round.canCashout = round.multiplier > 1;
        round.canGuess = round.steps.length < cfMaxSteps();
        cfPhase = "decide";
        cfSetPhase("win");
        cfSetResult("win", cfDecideHTML());
        haptic("notification", "success");
        cfClearPick();
        cfUpdateChip();
        cfUpdateStart();
        return;
    }
    cfSettle(round);
}

function cfSettle(round) {
    cfClearTimers();
    cfPhase = "end";
    cfBusy = false;
    const win = round.status === "won";
    const last = round.steps[round.steps.length - 1];
    cfLastRoundId = round.roundId;
    cfSetPhase(win ? "win" : "lose");
    if (win) cfSetResult("win", "<b>Выигрыш +" + cfMoney(round.payout) + "</b><span>Серия " + round.steps.length + " · итог x" + fmtCoef(round.multiplier) + "</span>");
    else cfSetResult("lose", "<b>" + CF_SIDE_RU[last.side] + "</b><span>Не угадали — ставка сгорела" + (round.steps.length > 1 ? " (серия " + (round.steps.length - 1) + ")" : "") + "</span>");
    if (cfPendingBalance !== null) {
        applyBalance(cfPendingBalance);
        cfPendingBalance = null;
    }
    if (win) showGameWinToast(round.payout, "Выигрыш ", "⭐️!");
    else showGameLoseToast("Не угадали — ставка сгорела");
    haptic("notification", win ? "success" : "warning");
    cfSealChips(round.roundId);
    cfClearPick();
    cfUpdateChip();
    cfUpdateRoundLabel();
    cfUpdateStart();
    loadCoinflipHistory();
    const historyWait = cfActAt - cfNow();
    if (historyWait > 0) setTimeout(() => {
        if (currentGame === "coinflip") loadCoinflipHistory();
    }, historyWait + 400);
}

function cfAfterServer(data) {
    const round = data.round;
    if (data.next) cfCommit = {
        roundId: data.next.roundId,
        seedHash: data.next.seedHash
    };
    cfPendingBalance = typeof data.balance === "number" ? data.balance : null;
    if (typeof data.balanceVisible === "number") applyBalance(data.balanceVisible);
    cfRound = round;
    if (round.flipping) {
        cfBeginFlip(round, 0);
        return;
    }
    if (round.status === "active") {
        cfPhase = "decide";
        cfSetPhase("win");
        cfSetResult("win", cfDecideHTML());
        cfUpdateChip();
        cfUpdateStart();
        return;
    }
    cfSettle(round);
}

function cfPost(path, body) {
    return fetch(path, {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify(body)
    }).then(r => r.json());
}

function cfFail(data) {
    cfBusy = false;
    showToast(data && data.error || "Ошибка сервера", "error");
    cfUpdateStart();
    if (data && (data.code === "no active game" || data.code === "game already active" || data.code === "flip in progress")) loadCoinflipState(cfMountToken, true);
}

function cfStartRound() {
    if (!cfReady || cfBusy || cfPhase === "flip" || cfPhase === "decide" || cfNow() < cfActAt) return;
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const pick = cfPick();
    if (!pick) {
        showToast("Выберите сторону монеты — Орёл или Решка", "warning");
        return;
    }
    const st = cfReadyState();
    if (!st.hasBet) {
        showToast("Введите сумму ставки", "warning");
        return;
    }
    if (!st.enoughBalance) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    if (st.underMin) {
        showToast("Минимальная ставка — " + fmtNum(betMin("coinflip")) + "⭐️", "error");
        return;
    }
    if (st.overMax) {
        showToast("Максимальная ставка — " + fmtNum(betMax("coinflip")) + "⭐️", "error");
        return;
    }
    cfBusy = true;
    cfResetBoard();
    cfUpdateStart();
    cfPost("/api/coinflip/start", {
        uid: CURRENT_UID,
        bet: st.bet,
        pick: pick
    }).then(data => {
        if (!data || !data.ok) {
            cfFail(data);
            return;
        }
        cfBusy = false;
        cfClearPick();
        cfAfterServer(data);
    }).catch(() => {
        cfBusy = false;
        showToast("Не удалось связаться с сервером", "error");
        cfUpdateStart();
    });
}

function cfResetBoard() {
    cfClearTimers();
    cfRunToken++;
    cfSetPhase("idle");
    cfSetResult("", "");
    cfPlayerRest(cfPlayer);
}

function cfGuessSide(pick) {
    if (!cfCanAct() || !cfRound || !cfRound.canGuess) return;
    cfBusy = true;
    cfPlayerRest(cfPlayer);
    cfSetResult("", "");
    cfUpdateStart();
    cfPost("/api/coinflip/guess", {
        uid: CURRENT_UID,
        pick: pick
    }).then(data => {
        if (!data || !data.ok) {
            cfFail(data);
            return;
        }
        cfBusy = false;
        cfAfterServer(data);
    }).catch(() => {
        cfBusy = false;
        showToast("Не удалось связаться с сервером", "error");
        cfUpdateStart();
    });
}

function cfCashoutRound() {
    if (!cfCanAct() || !cfRound || !cfRound.canCashout) return;
    cfBusy = true;
    cfUpdateStart();
    cfPost("/api/coinflip/cashout", {
        uid: CURRENT_UID
    }).then(data => {
        if (!data || !data.ok) {
            cfFail(data);
            return;
        }
        cfBusy = false;
        cfAfterServer(data);
    }).catch(() => {
        cfBusy = false;
        showToast("Не удалось связаться с сервером", "error");
        cfUpdateStart();
    });
}

function playCoinflip() {
    if (cfPhase === "decide") {
        if (cfCanAct()) cfCashoutRound();
        return;
    }
    cfStartRound();
}

function cfTileClick(tile) {
    const side = tile.dataset.coin;
    if (cfBusy || cfPhase === "flip") return;
    if (cfPhase === "decide") {
        cfGuessSide(side);
        return;
    }
    if (cfPhase === "end") {
        cfResetToIdle();
    }
    cfClearPick();
    tile.classList.add("selected");
    cfUpdateStart();
}

function loadCoinflipState(token, force) {
    fetch("/api/coinflip/state?uid=" + CURRENT_UID, {
        cache: "no-store"
    }).then(r => r.json()).then(d => {
        if (token !== cfMountToken || !d || !d.ok) return;
        if (!force && (cfBusy || cfPhase === "flip" || cfPhase === "decide")) return;
        cfApplyConfig(d.config);
        cfRecent = d.recent || [];
        if (d.commit) cfCommit = d.commit;
        cfReady = true;
        cfBusy = false;
        if (typeof d.balance === "number") applyBalance(d.balance);
        if (d.active && d.round) {
            const round = d.round;
            cfPendingBalance = null;
            cfRound = round;
            cfLiveChips(round, !round.flipping).forEach(c => cfRecent.unshift(c));
            cfRecent = cfRecent.slice(0, 12);
            cfRenderChips();
            if (round.flipping) {
                cfBeginFlip(round, round.elapsed || 0);
                return;
            }
            if (round.status === "active") {
                cfPhase = "decide";
                cfActAt = 0;
                cfSetPhase("win");
                cfPlayerLand(cfPlayer, cfLastStep().side);
                cfSetResult("win", cfDecideHTML());
                cfClearPick();
            } else {
                cfPhase = "idle";
                cfRound = null;
            }
        } else {
            cfRound = null;
            cfPhase = "idle";
            cfSetPhase("idle");
            cfSetResult("", "");
            cfPlayerRest(cfPlayer);
        }
        cfRenderChips();
        cfUpdateChip();
        cfUpdateRoundLabel();
        cfUpdateStart();
    }).catch(() => {
        if (token !== cfMountToken) return;
        cfReady = true;
        cfUpdateStart();
    });
}

function cfMountCoins(token) {
    cfCreatePlayer("cfCoin", () => token === cfMountToken).then(player => {
        if (token !== cfMountToken) {
            cfDestroyPlayer(player);
            return;
        }
        cfPlayer = player;
        if (cfPhase === "flip" && cfRound) {
            const step = cfLastStep();
            const elapsedNow = Math.max(0, (cfNow() - cfFlipStart) / 1000);
            cfPlayerFly(player, step.side, Math.min(elapsedNow, cfRound.flipSec || 3), cfRound.flipSec || 3, 0);
            const run = cfRunToken;
            player.onComplete = () => {
                if (run === cfRunToken && cfPhase === "flip") cfReveal(run);
            };
        } else if (cfPhase === "decide" || cfPhase === "end") {
            const step = cfLastStep();
            if (step) cfPlayerLand(player, step.side);
        } else cfPlayerRest(player);
    });
}

function initCoinflipGame(data) {
    stopCoinflip();
    const token = ++cfMountToken;
    cfReady = false;
    cfBusy = false;
    cfPhase = "idle";
    cfRound = null;
    cfScope = "all";
    cfPendingBalance = null;
    cfUpdateStart();
    cfUpdateRoundLabel();
    cfMountCoins(token);
    loadCoinflipState(token);
    loadCoinflipHistory("all");
    gvHistoryWireSearch("coinflipHistorySearchInput", () => loadCoinflipHistory(), value => {
        gvHistorySearch("coinflipHistoryList", () => "/api/coinflip/history?uid=" + CURRENT_UID + "&scope=" + cfScope + "&q=" + encodeURIComponent(value), rows => {
            cfById("coinflipHistoryList").innerHTML = rows.map(coinflipHistoryRowHTML).join("");
        });
    });
}

function stopCoinflip() {
    cfMountToken++;
    cfRunToken++;
    cfBusy = false;
    cfPhase = "idle";
    cfRound = null;
    cfClearTimers(true);
    cfDestroyPlayer(cfPlayer);
    cfPlayer = null;
}

document.addEventListener("input", e => {
    if (currentGame !== "coinflip") return;
    if (e.target && e.target.classList && e.target.classList.contains("gv-bet-input")) cfUpdateStart();
});

document.addEventListener("click", e => {
    if (currentGame !== "coinflip") return;
    if (e.target.closest(".gv-bet-row .gv-chip")) setTimeout(cfUpdateStart, 0);
});

function cfRowSteps(meta) {
    if (meta && Array.isArray(meta.steps) && meta.steps.length) return meta.steps;
    if (meta && meta.pick && meta.side) return [{
        n: 1,
        pick: meta.pick,
        side: meta.side,
        win: meta.pick === meta.side
    }];
    return [];
}

function cfStepChipsHTML(steps, size) {
    return steps.map(s => cfChipHTML(s.side, (size || "mini") + (s.win ? " ok" : " bad"))).join("");
}

function coinflipHistoryRowHTML(r) {
    let meta = {};
    try {
        meta = JSON.parse(r.meta || "{}");
    } catch (e) {}
    const win = r.result === "win";
    const isMe = r.user_id == null || r.user_id === CURRENT_UID;
    const name = isMe ? currentUser.displayName || "Игрок" : r.username || "Игрок";
    const avatar = isMe ? lazyImgTag(currentUser.avatarUrl, name) : r.anon ? "?" : lazyImgTag("/api/avatar/" + r.user_id, name);
    const rid = meta.roundId || r.public_id || "";
    const steps = cfRowSteps(meta);
    const wins = steps.filter(s => s.win).length;
    const mult = meta.multiplier || (steps.length ? steps[steps.length - 1].total : 0) || cfStepMult();
    return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-avatar">' + (isMe || !r.anon ? '<div class="skel-box"></div>' : "") + avatar + "</div>" + '<div class="gv-history-mid">' + '<div class="gv-history-name"><span class="gv-history-name-text">' + escapeHtml(name) + "</span></div>" + historyTimeHTML(r.created_at) + "</div>" + '<div class="gv-history-right">Сумма ставки: <b>' + cfMoney(r.bet) + '</b><br><span class="gv-history-outcome cf-hist-line">' + (steps.length > 1 ? "Серия " + wins + ": " : "Бросок: ") + cfStepChipsHTML(steps) + "</span><br>" + (win ? '<span class="gv-history-win">Выигрыш: ' + cfMoney(r.win_amount) + " (x" + fmtCoef(mult) + ")</span>" : '<span class="gv-history-lose">Проигрыш</span>') + "</div>" + "</div>" + (rid ? '<button class="crash-history-fair-btn" type="button" data-coinflip-round="' + escapeHtml(rid) + '">' + fairCheckBtnIconHTML() + "Проверить честность</button>" : "") + "</div>";
}

function loadCoinflipHistory(scope, append) {
    if (scope) {
        cfScope = scope;
        append = false;
    }
    gvHistoryLoad("coinflipHistoryList", off => "/api/coinflip/history?uid=" + CURRENT_UID + "&scope=" + cfScope + "&offset=" + off, 20, (rows, app) => {
        const list = cfById("coinflipHistoryList");
        if (!list) return;
        const html = rows.map(coinflipHistoryRowHTML).join("");
        if (app) list.insertAdjacentHTML("beforeend", html);
        else list.innerHTML = html;
    }, GV_HISTORY_EMPTY_HTML, append);
}

GV_HISTORY_BY_GAME["coinflip"] = {
    listId: "coinflipHistoryList",
    load: () => loadCoinflipHistory(null, true)
};

function cfFormulaHTML() {
    return '<p class="modal-text">Секретный сид раунда скрыт, пока серия идёт, а его SHA-256-хэш публикуется ещё ДО ставки — поэтому стороны монеты нельзя подогнать под вашу ставку или выбор. Сид раскрывается, когда раунд закончен.</p>' + '<ol class="fair-formula-steps">' + "<li>H = HMAC-SHA256(секретный сид, «UID раунда:coin:N»), где N — номер броска в серии (1, 2, 3…)</li>" + "<li>R = первые 13 hex-символов H как число по основанию 16, делённое на 2<sup>52</sup> — получается число от 0 до 1</li>" + "<li>R меньше 0.5 — выпал <b>Орёл</b>, иначе <b>Решка</b>. Монета честная: шанс 50% на каждую сторону</li>" + "<li>Угадали сторону — множитель серии умножается на коэффициент броска (1 − комиссия) × 2, сейчас <b>x" + fmtCoef(cfStepMult()) + "</b>. Выплата = ставка × множитель серии</li>" + "<li>Не угадали — вся ставка сгорает. «Забрать» доступно после первого верного броска</li>" + "</ol>";
}

function openCoinflipFair() {
    let id = "";
    let hash = "";
    let html = "";
    gvFairNote.style.display = "none";
    if (cfRound && (cfPhase === "flip" || cfPhase === "decide")) {
        id = cfRound.roundId;
        hash = cfRound.seedHash || "";
        html = '<div class="fair-block"><div class="fair-label">UID раунда</div><div class="fair-hash" data-copy="' + escapeHtml(id) + '">' + fairHashHTML(id) + '</div></div><div class="fair-result-note">Серия идёт — секретный сид раскроется сразу после её окончания, проверить раунд можно будет в «Последних играх».</div>';
        gvFairNote.style.display = "";
        gvFairNote.innerHTML = cfFormulaHTML();
    } else if (cfCommit) {
        id = cfCommit.roundId;
        hash = cfCommit.seedHash;
        html = '<div class="fair-block"><div class="fair-label">UID следующего раунда</div><div class="fair-hash" data-copy="' + escapeHtml(id) + '">' + fairHashHTML(id) + '</div></div><div class="fair-result-note">Хэш секретного сида следующего раунда опубликован ещё до ставки. Когда раунд закончится, сид раскроется — проверьте его в «Последних играх» или здесь.</div>';
        if (cfLastRoundId) html += '<button class="ah-res-more cf-fair-last" type="button" data-coinflip-round="' + escapeHtml(cfLastRoundId) + '">Проверить предыдущий раунд</button>';
        gvFairNote.style.display = "";
        gvFairNote.innerHTML = cfFormulaHTML();
    }
    if (id) {
        gvFairId.textContent = id;
        gvFairId.classList.remove("text-skel");
        if (hash) setFairHashEl(gvFairHash, hash);
        else setFairHashSkeleton(gvFairHash);
    } else {
        gvFairId.textContent = "CXXXXXXXX";
        gvFairId.classList.add("text-skel");
        setFairHashSkeleton(gvFairHash);
        html = '<div class="fair-result-note">Загрузка…</div>';
    }
    gvFairResult.innerHTML = html;
    gvFairLink.style.display = "none";
    gvFairModal.classList.add("active");
}

function cfHex(buf) {
    return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, "0")).join("");
}

function cfSha256(text) {
    return crypto.subtle.digest("SHA-256", new TextEncoder().encode(text)).then(cfHex);
}

function cfHmac(key, msg) {
    return crypto.subtle.importKey("raw", new TextEncoder().encode(key), {
        name: "HMAC",
        hash: "SHA-256"
    }, false, ["sign"]).then(k => crypto.subtle.sign("HMAC", k, new TextEncoder().encode(msg))).then(cfHex);
}

function cfThrows(n) {
    return n + (n % 10 === 1 && n % 100 !== 11 ? " броска" : " бросков");
}

function cfRound4(v) {
    return Math.round(v * 10000) / 10000;
}

function cfRunChecks(d) {
    if (!d.serverSeed) return Promise.resolve([{
        label: "Хэш коммита",
        passed: null,
        detail: "Сид ещё не раскрыт"
    }]);
    const steps = d.steps || [];
    return Promise.all([cfSha256(d.serverSeed)].concat(steps.map(s => cfHmac(d.serverSeed, d.roundId + ":coin:" + s.n)))).then(res => {
        const hash = res[0];
        const units = res.slice(1).map(h => parseInt(h.slice(0, 13), 16) / 4503599627370496);
        const sides = units.map(u => u < .5 ? "heads" : "tails");
        const list = [];
        list.push({
            label: "Хэш коммита",
            passed: hash === d.seedHash,
            detail: "SHA-256 раскрытого сида (" + hash.slice(0, 12) + "…) совпал с хэшем, опубликованным до ставки"
        });
        list.push({
            label: "Стороны монеты (" + steps.length + ")",
            passed: steps.length > 0 && steps.every((s, i) => s.side === sides[i]),
            detail: steps.slice(0, 5).map((s, i) => "№" + s.n + ": " + units[i].toFixed(4) + (units[i] < .5 ? " < " : " ≥ ") + "0.5 → " + CF_SIDE_RU[sides[i]]).join("; ") + (steps.length > 5 ? "; …" : "")
        });
        list.push({
            label: "Угадал или нет",
            passed: steps.every((s, i) => (sides[i] === s.pick) === !!s.win),
            detail: steps.slice(0, 5).map((s, i) => "№" + s.n + ": выбрано " + CF_SIDE_RU[s.pick] + ", выпало " + CF_SIDE_RU[sides[i]] + " → " + (sides[i] === s.pick ? "верно" : "мимо")).join("; ") + (steps.length > 5 ? "; …" : "")
        });
        const lastLost = steps.length > 0 && !steps[steps.length - 1].win;
        const onlyLastLost = steps.every((s, i) => i === steps.length - 1 || s.win);
        list.push({
            label: "Ход серии",
            passed: onlyLastLost && (d.result === "win" ? !lastLost : lastLost),
            detail: d.result === "win" ? "серия из " + cfThrows(steps.length) + " без промаха — выигрыш забран" : "серия оборвалась на броске №" + steps.length + " — ставка сгорела"
        });
        let total = 1;
        let totalOk = true;
        steps.forEach(s => {
            if (!s.win) return;
            total = cfRound4(total * s.mult);
            if (Math.abs(total - s.total) > 1e-9) totalOk = false;
        });
        list.push({
            label: "Множитель серии",
            passed: totalOk && Math.abs(total - d.multiplier) < 1e-9,
            detail: steps.filter(s => s.win).length ? "x" + steps.filter(s => s.win).map(s => fmtCoef(s.mult)).join(" × x") + " = x" + fmtCoef(total) : "верных бросков нет — множитель x1"
        });
        const pay = d.result === "win" ? Math.round((d.bet * d.multiplier + 1e-9) * 100) / 100 : 0;
        list.push({
            label: "Выплата",
            passed: Math.abs(pay - d.winAmount) < .0051,
            detail: d.result === "win" ? "ставка " + cfMoney(d.bet) + " × " + fmtCoef(d.multiplier) + " = " + cfMoney(pay) : "серия проиграна — выплата 0⭐️"
        });
        if (d.startedAt && d.finishAt && d.flipSec) {
            list.push({
                label: "Сид раскрыт после раунда",
                passed: d.finishAt - d.startedAt >= d.flipSec * 1000 * steps.length - 1,
                detail: "старт " + mskClock(d.startedAt) + " → раскрытие " + mskClock(d.finishAt)
            });
        }
        return list;
    });
}

function cfChecksHTML(list) {
    const failed = list.filter(c => c.passed === false).length;
    const head = failed ? '<div class="ah-verdict bad"><i>' + CF_ICON.bad + "</i><div><b>Найдено расхождение</b><span>Не прошло проверок: " + failed + "</span></div></div>" : '<div class="ah-verdict ok"><i>' + CF_ICON.ok + "</i><div><b>Раунд честный</b><span>Все проверки выполнены в вашем браузере</span></div></div>";
    const rows = list.map((c, i) => {
        const cls = c.passed === true ? "pass" : c.passed === false ? "fail" : "skip";
        const icon = c.passed === true ? CF_ICON.ok : c.passed === false ? CF_ICON.bad : CF_ICON.dash;
        return '<div class="ah-check ' + cls + '" style="--i:' + i + '"><i>' + icon + "</i><div><b>" + escapeHtml(c.label) + "</b><span>" + escapeHtml(c.detail) + "</span></div></div>";
    }).join("");
    return head + '<div class="ah-checklist">' + rows + "</div>";
}

const coinflipRoundModal = document.getElementById("coinflipRoundModal");

const coinflipRoundBoard = document.getElementById("coinflipRoundBoard");

const coinflipRoundPlayerRow = document.getElementById("coinflipRoundPlayerRow");

const coinflipRoundFairBlock = document.getElementById("coinflipRoundFairBlock");

let coinflipRoundData = null;

let coinflipRoundPlayer = null;

let coinflipRoundToken = 0;

let coinflipReplayToken = 0;

function cfDestroyRoundCoin() {
    coinflipReplayToken++;
    const player = coinflipRoundPlayer;
    coinflipRoundPlayer = null;
    cfDestroyPlayer(player);
}

function cfRoundStepsHTML(d) {
    return '<div class="cf-rb-steps" id="cfRbSteps">' + d.steps.map((s, i) => '<div class="cf-rb-step ' + (s.win ? "ok" : "bad") + '" data-i="' + i + '"><span class="cf-rb-n">№' + s.n + '</span><span class="cf-rb-pair">' + cfChipHTML(s.pick, "mini") + "<i>→</i>" + cfChipHTML(s.side, "mini") + '</span><span class="cf-rb-res">' + (s.win ? "x" + fmtCoef(s.total) : "мимо") + "</span></div>").join("") + "</div>";
}

function cfRoundBoardHTML(d) {
    return '<div class="cf-rb"><div class="cf-rb-stage" data-win="' + (d.result === "win" ? "1" : "0") + '">' + cfPlayerHTML("cfRb") + "</div>" + cfRoundStepsHTML(d) + (cfIsLite() ? "" : '<button class="ah-res-more cf-replay" type="button" id="coinflipReplayBtn">Повторить ' + (d.steps.length > 1 ? "серию" : "бросок") + "</button>") + "</div>";
}

function cfRoundPlayerRowHTML(d) {
    const isMe = d.userId === CURRENT_UID;
    const name = isMe ? currentUser.displayName || "Игрок" : d.username || "Игрок";
    const avatarUrl = isMe ? currentUser.avatarUrl : "/api/avatar/" + d.userId;
    const win = d.result === "win";
    return '<div class="crash-player-row' + (isMe ? " me" : "") + '">' + '<div class="crash-player-avatar">' + (!isMe && d.anon ? "?" : '<img src="' + avatarUrl + '" alt="" loading="lazy">') + "</div>" + '<div class="crash-player-mid">' + '<div class="crash-player-name"><span class="crash-player-name-text">' + escapeHtml(name) + "</span>" + (isMe ? ' <span class="lb-you-tag">Вы</span>' : "") + "</div>" + '<div class="crash-player-sub">Ставка: ' + fmtNum(d.bet) + "⭐️ · серия " + d.steps.filter(s => s.win).length + "</div>" + "</div>" + (win ? '<div class="crash-player-mult">x' + fmtCoef(d.multiplier) + "</div>" : "") + '<div class="crash-player-value">' + (win ? "+" + fmtNum(d.winAmount) + "⭐️" : "Проигрыш") + "</div>" + "</div>";
}

function cfMountRoundCoin(d, token) {
    cfCreatePlayer("cfRb", () => token === coinflipRoundToken).then(player => {
        if (token !== coinflipRoundToken) {
            cfDestroyPlayer(player);
            return;
        }
        coinflipRoundPlayer = player;
        cfPlayerLand(player, d.steps[d.steps.length - 1].side);
    });
}

function cfMarkReplayStep(i) {
    document.querySelectorAll("#cfRbSteps .cf-rb-step").forEach((el, idx) => {
        el.classList.toggle("cur", idx === i);
        el.classList.toggle("done", i < 0 || idx < i);
    });
}

function cfReplay() {
    const d = coinflipRoundData;
    const player = coinflipRoundPlayer;
    if (!d || !player || player.lite) return;
    const token = ++coinflipReplayToken;
    const speed = 2;
    const stepMs = (d.flipSec || 3) / speed * 1000 + 250;
    const btn = cfById("coinflipReplayBtn");
    if (btn) btn.disabled = true;
    let i = 0;
    const next = () => {
        if (token !== coinflipReplayToken) return;
        if (i >= d.steps.length) {
            player.onComplete = null;
            cfMarkReplayStep(-1);
            cfPlayerLand(player, d.steps[d.steps.length - 1].side);
            if (btn) btn.disabled = false;
            return;
        }
        const step = d.steps[i];
        cfMarkReplayStep(i);
        cfPlayerRest(player);
        cfPlayerFly(player, step.side, 0, d.flipSec || 3, speed);
        const at = i;
        let moved = false;
        const go = () => {
            if (moved || token !== coinflipReplayToken || at !== i) return;
            moved = true;
            cfPlayerLand(player, step.side);
            i++;
            setTimeout(next, 450);
        };
        player.onComplete = go;
        setTimeout(go, stepMs + 300);
    };
    cfMarkReplayStep(-1);
    next();
}

function openCoinflipRoundModal(publicId) {
    if (!publicId || !coinflipRoundModal) return;
    gvFairModal.classList.remove("active");
    coinflipRoundData = null;
    const token = ++coinflipRoundToken;
    cfDestroyRoundCoin();
    coinflipRoundFairBlock.style.display = "none";
    coinflipRoundFairBlock.innerHTML = "";
    cfById("coinflipRoundFairBtn").textContent = "Проверить честность";
    cfById("coinflipRoundModalId").textContent = publicId;
    coinflipRoundBoard.innerHTML = '<div class="cf-rb"><div class="cf-rb-stage"><span class="skel-box" style="position:absolute;inset:0;border-radius:24px;"></span></div></div>';
    coinflipRoundPlayerRow.innerHTML = minesRoundPlayerSkeletonHTML();
    coinflipRoundModal.classList.add("active");
    fetch("/api/coinflip/round?id=" + encodeURIComponent(publicId)).then(r => r.json()).then(d => {
        if (token !== coinflipRoundToken || !coinflipRoundModal.classList.contains("active")) return;
        if (!d || !d.ok) {
            coinflipRoundBoard.innerHTML = "";
            coinflipRoundPlayerRow.innerHTML = '<div class="crash-players-empty">Раунд не найден</div>';
            return;
        }
        if (d.status !== "finished") {
            coinflipRoundBoard.innerHTML = "";
            coinflipRoundPlayerRow.innerHTML = '<div class="crash-players-empty">Раунд ещё идёт — результат и сид откроются сразу после его завершения</div>';
            return;
        }
        coinflipRoundData = d;
        coinflipRoundBoard.innerHTML = cfRoundBoardHTML(d);
        coinflipRoundPlayerRow.innerHTML = cfRoundPlayerRowHTML(d);
        cfMountRoundCoin(d, token);
    }).catch(() => {
        coinflipRoundPlayerRow.innerHTML = '<div class="crash-players-empty">Не удалось загрузить раунд</div>';
    });
}

function closeCoinflipRoundModal() {
    coinflipRoundToken++;
    cfDestroyRoundCoin();
    coinflipRoundModal.classList.remove("active");
}

function cfFillRoundFair(d) {
    const hashBlock = (label, value) => '<div class="fair-block"><div class="fair-label">' + label + '</div><div class="fair-hash" data-copy="' + escapeHtml(value) + '">' + fairHashHTML(value || "—") + "</div></div>";
    coinflipRoundFairBlock.innerHTML = hashBlock("UID раунда", d.roundId) + hashBlock("SHA-256 hash", d.seedHash) + hashBlock("Секретный сид", d.serverSeed) + '<div class="cf-checks" id="cfChecks"><div class="ah-checks-loading"><span class="skel-box"></span><span class="skel-box"></span><span class="skel-box"></span></div></div>' + cfFormulaHTML();
    if (!window.crypto || !crypto.subtle) {
        cfById("cfChecks").innerHTML = '<div class="fair-result-note">Проверка в браузере недоступна — пересчитайте формулу вручную</div>';
        return;
    }
    cfRunChecks(d).then(list => {
        const box = cfById("cfChecks");
        if (box) box.innerHTML = cfChecksHTML(list);
    }).catch(() => {
        const box = cfById("cfChecks");
        if (box) box.innerHTML = '<div class="fair-result-note">Проверка в браузере недоступна</div>';
    });
}

if (coinflipRoundModal) {
    cfById("coinflipRoundClose").addEventListener("click", closeCoinflipRoundModal);
    coinflipRoundModal.addEventListener("click", e => {
        if (e.target === coinflipRoundModal) {
            closeCoinflipRoundModal();
            return;
        }
        if (e.target.closest("#coinflipReplayBtn")) cfReplay();
    });
    cfById("coinflipRoundFairBtn").addEventListener("click", () => {
        const d = coinflipRoundData;
        if (!d) return;
        const hidden = coinflipRoundFairBlock.style.display === "none";
        if (hidden) {
            cfFillRoundFair(d);
            coinflipRoundFairBlock.style.display = "";
            cfById("coinflipRoundFairBtn").textContent = "Скрыть информацию";
        } else {
            coinflipRoundFairBlock.style.display = "none";
            cfById("coinflipRoundFairBtn").textContent = "Проверить честность";
        }
    });
}

