function clawLoadInto(ctx, src, loop, slow) {
    const token = ctx.token();
    if (clawIsLite()) return Promise.resolve(null);
    const target = ctx.players[ctx.active] ? 1 - ctx.active : ctx.active;
    const canvas = clawEl(ctx.pre + target);
    if (!canvas) return Promise.resolve(null);
    clawDestroySlot(ctx, target);
    return loadDotLottie().then(DotLottie => new Promise(resolve => {
        if (token !== ctx.token() || !canvas.isConnected) {
            resolve(null);
            return;
        }
        const dl = new DotLottie({
            canvas: canvas,
            src: src,
            loop: !!loop,
            autoplay: false,
            renderConfig: {
                autoResize: true,
                devicePixelRatio: lottieDprFor(canvas),
                freezeOnOffscreen: false
            }
        });
        dl.addEventListener("load", () => {
            if (token !== ctx.token() || !canvas.isConnected) {
                try {
                    dl.destroy();
                } catch (e) {}
                resolve(null);
                return;
            }
            ctx.players[target] = dl;
            _lottieLive.add(dl);
            try {
                dl.setFrame(0);
            } catch (e) {}
            const other = 1 - target;
            const otherCanvas = clawEl(ctx.pre + other);
            const dur = slow ? ".6s" : "";
            canvas.style.transitionDuration = dur;
            if (otherCanvas) otherCanvas.style.transitionDuration = dur;
            canvas.classList.add("on");
            if (otherCanvas) otherCanvas.classList.remove("on");
            ctx.active = target;
            setTimeout(() => {
                if (token === ctx.token() && ctx.active === target) clawDestroySlot(ctx, other);
            }, slow ? 700 : 160);
            resolve(dl);
        });
        dl.addEventListener("loadError", () => resolve(null));
    }));
}

function clawSetStage(phase) {
    const stage = clawEl("clawStage");
    if (stage) stage.setAttribute("data-phase", phase);
}

function clawPlayIdle(ctx, slow) {
    const token = ctx.token();
    return clawLoadInto(ctx, CLAW_DIR + "Начало.lottie", true, slow).then(dl => {
        if (!dl || token !== ctx.token()) return;
        try {
            dl.play();
        } catch (e) {}
    });
}

function clawShowIdle() {
    clawSetStage("idle");
    if (clawIsLite()) {
        const img = clawEl("clawPng");
        if (img) img.src = CLAW_DIR + "Начало.png";
        const pop = clawEl("clawPop");
        if (pop) pop.remove();
        return;
    }
    clawPlayIdle(clawMain, false);
}

function clawPrefetch(key) {
    const names = CLAW_ANIM[key];
    if (!names || clawIsLite()) return;
    [names.win, names.lose].forEach(n => {
        fetch(CLAW_DIR + n + ".lottie", {
            cache: "force-cache"
        }).catch(() => {});
    });
}

function clawPlayOn(ctx, win, key, done) {
    const names = CLAW_ANIM[key];
    const token = ctx.token();
    let finished = false;
    let timer = 0;
    const end = () => {
        if (finished) return;
        finished = true;
        clearTimeout(timer);
        done();
    };
    if (!names || clawIsLite()) {
        timer = setTimeout(end, 900);
        return;
    }
    timer = setTimeout(end, 5200);
    clawLoadInto(ctx, CLAW_DIR + (win ? names.win : names.lose) + ".lottie", false, false).then(dl => {
        if (token !== ctx.token()) return;
        if (!dl) {
            end();
            return;
        }
        dl.addEventListener("complete", () => {
            if (token === ctx.token()) end();
        });
        try {
            dl.setFrame(0);
            dl.play();
        } catch (e) {
            end();
        }
    });
}

function clawLoopPlayer(ctx, dl, token) {
    if (!dl) return;
    const alive = () => token === ctx.token() && ctx.players[ctx.active] === dl;
    const again = () => {
        if (!alive() || dl.isPlaying) return;
        try {
            dl.setFrame(0);
            dl.play();
        } catch (e) {}
    };
    dl.addEventListener("complete", () => {
        if (alive()) setTimeout(again, 1300);
    });
    setTimeout(again, 1300);
}

function clawPlayOutcome(win, key, done) {
    clawSetStage("play");
    clawPlayOn(clawMain, win, key, done);
}

function clawSetResult(cls, html) {
    const res = clawEl("clawResult");
    if (!res) return;
    if (!html) {
        res.className = "cf-result";
        res.innerHTML = "";
        return;
    }
    res.className = "cf-result on " + cls;
    res.innerHTML = html;
}

function clawSetPanelLocked(locked) {
    const panel = clawEl("clawPanel");
    if (panel) panel.classList.toggle("claw-locked", locked);
}

function clawReadyState() {
    const input = gvBody.querySelector(".gv-bet-input");
    const bet = input ? parseFloat(input.value) : NaN;
    return {
        bet: bet,
        hasBet: bet > 0,
        enoughBalance: bet > 0 && bet <= currentUser.balance + 1e-6,
        overMax: bet > betMax("claw"),
        underMin: bet > 0 && bet < betMin("claw")
    };
}

function clawUpdateChip() {
    const chip = clawEl("clawChip");
    if (!chip) return;
    const t = clawToyByKey(clawSel);
    const text = t ? t.label + " · шанс " + fmtCoef(t.chance) + "% · выплата x" + fmtCoef(t.multiplier) : "Выберите игрушку";
    if (chip.textContent !== text) chip.textContent = text;
}

function clawRefreshStats() {
    const chEl = clawEl("clawStatChance");
    if (!chEl) return;
    const t = clawToyByKey(clawSel);
    chEl.textContent = t ? fmtCoef(t.chance) + "%" : "—";
    const mEl = clawEl("clawStatMult");
    if (mEl) mEl.textContent = t ? "x" + fmtCoef(t.multiplier) : "—";
    const winEl = clawEl("clawStatWin");
    if (winEl) {
        const input = gvBody.querySelector(".gv-bet-input");
        const bet = input ? parseFloat(input.value) : NaN;
        winEl.textContent = t && bet > 0 ? "+" + fmtNum(Math.round(bet * t.multiplier * 100) / 100) + "⭐️" : "—";
    }
}

function clawUpdateStart() {
    clawRefreshStats();
    const btn = clawEl("clawStartBtn");
    if (!btn || clawBusy) return;
    if (gvIsNewGameBtn(btn)) {
        btn.classList.remove("dim");
        return;
    }
    const st = clawReadyState();
    let text = "Играть";
    let ready = false;
    if (!clawReady) text = "Загрузка…";
    else if (!betsAccepted) text = "Ставки приостановлены";
    else if (!clawVisibleToys().length) text = "Игра недоступна";
    else if (!clawSel) text = "Выберите игрушку";
    else ready = st.hasBet && st.enoughBalance && !st.overMax && !st.underMin;
    if (btn.textContent !== text) btn.textContent = text;
    btn.classList.toggle("dim", !ready);
}

function clawUpdateRoundLabel() {
    const el = clawEl("clawRoundIdLabel");
    if (!el) return;
    const id = clawCommit && clawCommit.roundId;
    if (id) {
        el.textContent = id;
        el.classList.remove("text-skel");
    } else {
        el.textContent = "AXXXXXXXX";
        el.classList.add("text-skel");
    }
}

function clawRenderToys() {
    const box = clawEl("clawToys");
    if (!box) return;
    if (clawSel && !clawVisibleToys().some(t => t.key === clawSel)) clawSel = "";
    box.innerHTML = clawTilesHTML();
}

function clawApplyConfig(c) {
    if (!c || !Array.isArray(c.toys)) return;
    clawToys = c.toys.map(t => ({
        key: t.key,
        label: t.label,
        multiplier: Number(t.multiplier),
        chance: Number(t.chance),
        enabled: t.enabled !== false
    }));
    if (c.commit) clawCommit = c.commit;
    clawReady = true;
    clawRenderToys();
    clawUpdateChip();
    clawUpdateRoundLabel();
    clawUpdateStart();
}

function loadClawConfig(force) {
    const token = clawMountToken;
    fetch("/api/claw/state?uid=" + CURRENT_UID, {
        cache: "no-store"
    }).then(r => r.json()).then(d => {
        if (token !== clawMountToken || !d || !d.ok) return;
        if (clawBusy && !force) return;
        clawApplyConfig(d);
    }).catch(() => {
        if (token === clawMountToken && !clawReady) {
            clawReady = true;
            clawUpdateStart();
        }
    });
}

function clawOnOutcomeChange() {
    if (clawBusy) return;
    clawRenderToys();
    clawUpdateChip();
    clawUpdateStart();
}

function clawTileClick(tile) {
    if (clawBusy) return;
    const btn = clawEl("clawStartBtn");
    if (gvIsNewGameBtn(btn)) clawNewGame();
    clawSel = tile.dataset.toy;
    gvBody.querySelectorAll("#clawToys .claw-toy").forEach(b => b.classList.toggle("selected", b === tile));
    clawPrefetch(clawSel);
    clawUpdateChip();
    clawUpdateStart();
}

function clawNewGame() {
    clawSetResult("", "");
    clawSetPanelLocked(false);
    const btn = clawEl("clawStartBtn");
    if (btn) btn.textContent = "Играть";
    clawShowIdle();
    clawUpdateStart();
}

function clawUserEditedBet() {
    if (!clawBusy && gvIsNewGameBtn(clawEl("clawStartBtn"))) {
        clawNewGame();
        return;
    }
    clawUpdateStart();
}

function initClawGame() {
    clawMountToken++;
    clawDestroyAll(clawMain);
    clawMain.active = 0;
    clawBusy = false;
    clawReady = false;
    clawRound = null;
    clawCommit = null;
    clawSel = "";
    clawScope = "all";
    clawUpdateChip();
    clawUpdateRoundLabel();
    clawUpdateStart();
    clawShowIdle();
    loadClawConfig(true);
    clearInterval(clawCfgTimer);
    clawCfgTimer = setInterval(() => loadClawConfig(false), 30000);
    loadClawHistory();
    gvHistoryWireSearch("clawHistorySearchInput", () => loadClawHistory(), value => {
        gvHistorySearch("clawHistoryList", () => "/api/claw/history?uid=" + CURRENT_UID + "&scope=" + clawScope + "&q=" + encodeURIComponent(value), rows => {
            clawEl("clawHistoryList").innerHTML = rows.map(clawHistoryRowHTML).join("");
        });
    });
}

function stopClaw() {
    clawMountToken++;
    clearInterval(clawCfgTimer);
    clawCfgTimer = 0;
    clawDestroyAll(clawMain);
    clawBusy = false;
}

function clawFail(token, data) {
    clawBusy = false;
    if (token !== clawMountToken) return;
    clawSetPanelLocked(false);
    const btn = clawEl("clawStartBtn");
    if (btn) btn.textContent = "Играть";
    clawSetStage("idle");
    if (data && data.config) clawApplyConfig(data.config);
    if (data && (data.outcomeOff || data.stale)) {
        loadClawConfig(true);
        ocLoad();
    }
    clawUpdateStart();
}

function clawFinish(token, data) {
    clawBusy = false;
    if (typeof data.balance === "number") applyBalance(data.balance);
    if (data.win) showGameWinToast(data.winAmount, "Выигрыш +", "⭐️ (x" + fmtCoef(data.multiplier) + ")");
    else showGameLoseToast("Не повезло — игрушка выскользнула");
    if (token !== clawMountToken) return;
    clawSetStage(data.win ? "win" : "lose");
    clawSetResult(data.win ? "win" : "lose", data.win ? "<b>Достал: " + escapeHtml(data.toyLabel) + "!</b><span>Выигрыш +" + fmtNum(data.winAmount) + "⭐️ (x" + fmtCoef(data.multiplier) + ")</span>" : "<b>Не достал</b><span>" + escapeHtml(data.toyLabel) + " выскользнула — ставка сгорела</span>");
    if (clawIsLite()) {
        const wrap = clawEl("clawWrap");
        const old = clawEl("clawPop");
        if (old) old.remove();
        if (wrap) wrap.insertAdjacentHTML("beforeend", '<img class="claw-pop ' + (data.win ? "win" : "lose") + '" id="clawPop" src="' + clawToyImg(data.toy) + '" alt="">');
    }
    const btn = clawEl("clawStartBtn");
    if (btn) {
        btn.textContent = GV_NEW_GAME_TEXT;
        btn.classList.remove("dim");
    }
    clawSetPanelLocked(false);
    clawUpdateRoundLabel();
    loadClawHistory();
    if (!clawIsLite()) clawLoopPlayer(clawMain, clawMain.players[clawMain.active], token);
}

function playClaw() {
    if (clawBusy) return;
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const toy = clawToyByKey(clawSel);
    if (!toy) {
        showToast("Выберите игрушку", "error");
        return;
    }
    const state = clawReadyState();
    if (!state.hasBet) return;
    if (!state.enoughBalance) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    if (state.underMin) {
        showToast("Минимальная ставка — " + fmtNum(betMin("claw")) + "⭐️", "error");
        return;
    }
    if (state.overMax) {
        showToast("Максимальная ставка — " + fmtNum(betMax("claw")) + "⭐️", "error");
        return;
    }
    clawBusy = true;
    clawLastBet = state.bet;
    clawSetPanelLocked(true);
    clawSetResult("", "");
    const btn = clawEl("clawStartBtn");
    if (btn) {
        btn.classList.add("dim");
        btn.textContent = "Идёт игра…";
    }
    const token = clawMountToken;
    fetch("/api/claw/play", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            toy: toy.key,
            bet: state.bet,
            chance: toy.chance,
            multiplier: toy.multiplier
        })
    }).then(r => r.json()).then(data => {
        if (!data || !data.ok) {
            clawFail(token, data);
            showToast(data && data.error || "Ошибка сервера", "error");
            return;
        }
        clawRound = {
            roundId: data.roundId,
            seedHash: data.seedHash,
            serverSeed: data.serverSeed,
            chance: data.chance,
            toy: data.toy
        };
        if (data.nextCommit) clawCommit = data.nextCommit;
        if (token !== clawMountToken) {
            clawFinish(token, data);
            return;
        }
        clawPlayOutcome(!!data.win, data.toy, () => clawFinish(token, data));
    }).catch(() => {
        clawFail(token, null);
        showToast("Не удалось связаться с сервером", "error");
    });
}

function clawFairFormulaHTML() {
    return '<p class="modal-text">Хэш секретного сида раунда (SHA-256) публикуется ДО вашей ставки, а сам сид раскрывается после раунда — подогнать результат под ставку или выбор игрушки нельзя. Формула (пример на Python — hmac.new(seed.encode(), uid.encode(), hashlib.sha256)):</p>' + '<ol class="fair-formula-steps">' + "<li>H = HMAC-SHA256(секретный сид, UID раунда как обычный UTF-8 текст)</li>" + "<li>R = первые 13 hex-символов H, переведённые в число по основанию 16</li>" + "<li>roll = R / 16^13 × 100 — число от 0.0000 до 99.9999…</li>" + "<li>Игрушка достаётся, если roll меньше её шанса (%)</li>" + "</ol>" + '<p class="modal-text">Если SHA-256 раскрытого сида не равен хэшу, который вы видели до ставки, или пересчёт даёт другой roll — раунд подменили.</p>';
}

function openClawFair() {
    const info = clawRound;
    const pre = clawCommit;
    const roundId = pre && pre.roundId || "";
    if (roundId) {
        gvFairId.textContent = roundId;
        gvFairId.classList.remove("text-skel");
    } else {
        gvFairId.textContent = "AXXXXXXXX";
        gvFairId.classList.add("text-skel");
    }
    if (pre && pre.seedHash) setFairHashEl(gvFairHash, pre.seedHash);
    else setFairHashSkeleton(gvFairHash);
    let resultHtml = '<div class="fair-block"><div class="fair-label">UID следующего раунда</div><div class="fair-hash"' + (roundId ? ' data-copy="' + escapeHtml(roundId) + '">' + fairHashHTML(roundId) : ">" + fairHashSkeletonHTML()) + "</div></div>";
    if (info && info.serverSeed) {
        resultHtml += '<div class="fair-block"><div class="fair-label">Прошлый раунд ' + escapeHtml(info.roundId) + ": секретный сид</div>" + '<div class="fair-hash" data-copy="' + escapeHtml(info.serverSeed) + '">' + fairHashHTML(info.serverSeed) + "</div></div>";
    }
    gvFairNote.style.display = "";
    gvFairNote.innerHTML = clawFairFormulaHTML();
    gvFairResult.innerHTML = resultHtml;
    gvFairLink.style.display = "none";
    gvFairModal.classList.add("active");
}

function clawHistoryRowHTML(r) {
    let meta = {};
    try {
        meta = JSON.parse(r.meta || "{}");
    } catch (e) {}
    const isWin = r.result === "win";
    const isMe = r.user_id == null || r.user_id === CURRENT_UID;
    const name = isMe ? currentUser.displayName || "Игрок" : r.username || "Игрок";
    const avatarUrl = isMe ? currentUser.avatarUrl : "/api/avatar/" + r.user_id;
    const chance = meta.chance != null ? fmtCoef(meta.chance) : "—";
    const toyLabel = meta.toyLabel || (clawToyByKey(meta.toy) || {}).label || "—";
    const toyImg = meta.toy ? '<img class="claw-hist-toy" src="' + clawToyImg(meta.toy) + '" alt="">' : "";
    return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-avatar"><div class="skel-box"></div>' + lazyImgTag(avatarUrl, name) + "</div>" + '<div class="gv-history-mid">' + '<div class="gv-history-name">' + escapeHtml(name) + "</div>" + historyTimeHTML(r.created_at) + "</div>" + '<div class="gv-history-right">Сумма ставки: <b>' + fmtNum(r.bet) + "⭐️</b><br>" + '<span class="gv-history-outcome">' + toyImg + "<b>" + escapeHtml(toyLabel) + "</b> · шанс <b>" + chance + "%</b></span><br>" + (isWin ? '<span class="gv-history-win">Выигрыш: ' + fmtNum(r.win_amount) + "⭐️ (x" + fmtCoef(meta.multiplier) + ")</span>" : '<span class="gv-history-lose">Проигрыш</span>') + "</div>" + "</div>" + (meta.roundId ? '<button class="crash-history-fair-btn" type="button" data-claw-round="' + escapeHtml(meta.roundId) + '">' + fairCheckBtnIconHTML() + "Проверить честность</button>" : "") + "</div>";
}

function loadClawHistory(scope, append) {
    if (scope) {
        clawScope = scope;
        append = false;
    }
    gvHistoryLoad("clawHistoryList", off => "/api/claw/history?uid=" + CURRENT_UID + "&scope=" + clawScope + "&offset=" + off, 20, (rows, app) => {
        const list = clawEl("clawHistoryList");
        if (!list) return;
        const html = rows.map(clawHistoryRowHTML).join("");
        if (app) list.insertAdjacentHTML("beforeend", html);
        else list.innerHTML = html;
    }, GV_HISTORY_EMPTY_HTML, append);
}

GV_HISTORY_BY_GAME["claw"] = {
    listId: "clawHistoryList",
    load: () => loadClawHistory(null, true)
};

const clawRoundModal = document.getElementById("clawRoundModal");

const clawRoundBoard = document.getElementById("clawRoundBoard");

const clawRoundPlayerRow = document.getElementById("clawRoundPlayerRow");

const clawRoundFairBlock = document.getElementById("clawRoundFairBlock");

function clawRoundStageHTML() {
    if (clawIsLite()) return '<img class="claw-png" id="clawRbPng" src="' + CLAW_DIR + 'Начало.png" alt="">';
    return '<canvas class="claw-canvas on" id="clawRbCanvas0" width="512" height="512"></canvas><canvas class="claw-canvas" id="clawRbCanvas1" width="512" height="512"></canvas>';
}

function clawModalPlay(d) {
    const token = clawRoundToken;
    clawDestroyAll(clawModal);
    clawModal.active = 0;
    if (clawIsLite()) {
        const wrap = clawEl("clawRbStage");
        const old = clawEl("clawRbPop");
        if (old) old.remove();
        if (wrap) wrap.insertAdjacentHTML("beforeend", '<img class="claw-pop ' + (d.result === "win" ? "win" : "lose") + '" id="clawRbPop" src="' + clawToyImg(d.toy) + '" alt="">');
        return;
    }
    clawPlayOn(clawModal, d.result === "win", d.toy, () => {
        if (token !== clawRoundToken) return;
        clawLoopPlayer(clawModal, clawModal.players[clawModal.active], token);
    });
}

function clawRoundBoardHTML(d) {
    const win = d.result === "win";
    const label = d.toyLabel || (clawToyByKey(d.toy) || {}).label || "";
    return '<div class="claw-rb-stage" id="clawRbStage">' + clawRoundStageHTML() + "</div>" + '<div class="claw-rb">' + '<img class="claw-rb-toy" src="' + clawToyImg(d.toy) + '" alt="">' + '<div class="claw-rb-text">' + '<b class="' + (win ? "win" : "lose") + '">' + (win ? "Достал игрушку" : "Игрушка выскользнула") + "</b>" + "<span>" + escapeHtml(label) + " · шанс " + fmtCoef(d.chance) + "% · x" + fmtCoef(d.multiplier) + "</span>" + "<span>Roll " + Number(d.roll).toFixed(4) + (win ? " < " : " ≥ ") + fmtCoef(d.chance) + "</span>" + "</div>" + "</div>";
}

function openClawRoundModal(publicId) {
    if (!publicId || !clawRoundModal) return;
    gvFairModal.classList.remove("active");
    clawRoundData = null;
    const token = ++clawRoundToken;
    clawRoundFairBlock.style.display = "none";
    clawRoundFairBlock.innerHTML = "";
    clawEl("clawRoundFairBtn").textContent = "Проверить честность";
    clawEl("clawRoundModalId").textContent = publicId;
    clawDestroyAll(clawModal);
    clawModal.active = 0;
    clawRoundBoard.innerHTML = '<div class="claw-rb"><span class="skel-box claw-rb-skel"></span></div>';
    clawRoundPlayerRow.innerHTML = minesRoundPlayerSkeletonHTML();
    clawRoundModal.classList.add("active");
    fetch("/api/claw/round?id=" + encodeURIComponent(publicId)).then(r => r.json()).then(d => {
        if (token !== clawRoundToken || !clawRoundModal.classList.contains("active")) return;
        if (!d || !d.ok) {
            clawRoundBoard.innerHTML = "";
            clawRoundPlayerRow.innerHTML = '<div class="crash-players-empty">Раунд не найден</div>';
            return;
        }
        clawRoundData = d;
        clawRoundBoard.innerHTML = clawRoundBoardHTML(d);
        clawRoundPlayerRow.innerHTML = upgradeRoundPlayerRowHTML(d);
        clawModalPlay(d);
    }).catch(() => {
        clawRoundPlayerRow.innerHTML = '<div class="crash-players-empty">Не удалось загрузить раунд</div>';
    });
}

function closeClawRoundModal() {
    clawRoundToken++;
    clawDestroyAll(clawModal);
    clawRoundModal.classList.remove("active");
}

function clawRunChecks(d) {
    if (!d.serverSeed) return Promise.resolve([{
        label: "Хэш коммита",
        passed: null,
        detail: "Сид ещё не раскрыт"
    }]);
    return Promise.all([cfSha256(d.serverSeed), cfHmac(d.serverSeed, d.roundId)]).then(res => {
        const roll = Math.round(parseInt(res[1].slice(0, 13), 16) / Math.pow(16, 13) * 1e6) / 1e4;
        const win = roll < Number(d.chance);
        return [{
            label: "Хэш коммита",
            passed: res[0] === d.seedHash,
            detail: "SHA-256 раскрытого сида (" + res[0].slice(0, 12) + "…) совпал с хэшем раунда, опубликованным до ставки"
        }, {
            label: "Roll раунда",
            passed: Math.abs(roll - Number(d.roll)) < .00011,
            detail: "HMAC-SHA256(сид, " + d.roundId + ") даёт roll " + roll.toFixed(4) + ", в раунде записано " + Number(d.roll).toFixed(4)
        }, {
            label: "Достал или нет",
            passed: win === (d.result === "win"),
            detail: "roll " + roll.toFixed(4) + (win ? " < " : " ≥ ") + fmtCoef(d.chance) + "% → " + (win ? "игрушка достаётся" : "игрушка выскальзывает")
        }];
    });
}

function clawFillRoundFair(d) {
    const hashBlock = (label, value) => '<div class="fair-block"><div class="fair-label">' + label + '</div><div class="fair-hash" data-copy="' + escapeHtml(value) + '">' + fairHashHTML(value || "—") + "</div></div>";
    clawRoundFairBlock.innerHTML = hashBlock("UID раунда", d.roundId) + hashBlock("SHA-256 hash", d.seedHash) + hashBlock("Секретный сид", d.serverSeed) + '<div class="cf-checks" id="clawChecks"><div class="ah-checks-loading"><span class="skel-box"></span><span class="skel-box"></span></div></div>' + clawFairFormulaHTML();
    if (!window.crypto || !crypto.subtle) {
        clawEl("clawChecks").innerHTML = '<div class="fair-result-note">Проверка в браузере недоступна — пересчитайте формулу вручную</div>';
        return;
    }
    clawRunChecks(d).then(list => {
        const box = clawEl("clawChecks");
        if (box) box.innerHTML = cfChecksHTML(list);
    }).catch(() => {
        const box = clawEl("clawChecks");
        if (box) box.innerHTML = '<div class="fair-result-note">Проверка в браузере недоступна</div>';
    });
}

