let _supportPromise = null;

function loadSupport() {
    if (window.SUP) return Promise.resolve(window.SUP);
    if (_supportPromise) return _supportPromise;
    let v = "";
    try {
        v = new URL(__APP_SCRIPT_EL.src, location.href).searchParams.get("v") || "";
    } catch (e) {}
    _supportPromise = new Promise((resolve, reject) => {
        const l = document.createElement("link");
        l.rel = "stylesheet";
        l.href = "/support.css?v=" + v;
        document.head.appendChild(l);
        const s = document.createElement("script");
        s.src = "/support.js?v=" + v;
        s.onload = () => resolve(window.SUP);
        s.onerror = () => {
            _supportPromise = null;
            reject(new Error("support"));
        };
        document.body.appendChild(s);
    });
    return _supportPromise;
}

function openHelp() {
    showScreen("help");
    setNavActive("помощь");
    loadSupport().then(S => S.open()).catch(() => showToast("Не удалось загрузить поддержку. Попробуйте ещё раз.", "error"));
}

function supportBadgeSet(n) {
    const item = document.querySelector('.nav-item[data-nav="помощь"]');
    if (!item) return;
    let b = item.querySelector(".sup-nav-badge");
    if (!n) {
        if (b) b.remove();
        return;
    }
    if (!b) {
        b = document.createElement("span");
        b.className = "sup-nav-badge";
        item.appendChild(b);
    }
    b.textContent = n > 9 ? "9+" : String(n);
}

function supportBadgePoll() {
    if (document.hidden) return;
    fetch("/api/support/unread", {
        credentials: "same-origin"
    }).then(r => r.json()).then(d => {
        if (d && d.ok) supportBadgeSet(d.unread);
    }).catch(() => {});
}

