function profileStatRowHTML(icon, label, value, mode) {
    let iconHtml;
    if (mode === "gif") {
        iconHtml = '<span class="profile-stat-icon gif"><span class="skel-box"></span>' + lazyImgTag(icon, "", "") + "</span>";
    } else if (mode === "img") {
        iconHtml = '<span class="profile-stat-icon img"><img src="' + icon + '" alt=""></span>';
    } else {
        iconHtml = '<span class="profile-stat-icon">' + icon + "</span>";
    }
    return '<div class="profile-stat-row">' + '<div class="profile-stat-label">' + iconHtml + "<span>" + label + "</span></div>" + '<span class="profile-stat-leader"></span>' + '<div class="profile-stat-value">' + value + "</div>" + "</div>";
}

function psNum(to, kind, text) {
    return '<span class="cs-num" data-to="' + to + '" data-kind="' + kind + '">' + text + "</span>";
}

function csFormatFor(kind) {
    if (kind === "int") return checksStatInt;
    if (kind === "pct") return v => fmtCoef(Math.round(v * 10) / 10) + "%";
    if (kind === "profit") return v => (v > 0 ? "+" : v < 0 ? "−" : "") + checksStatMoney(Math.abs(v));
    return checksStatMoney;
}

function csAnimateNums(root) {
    root.querySelectorAll(".cs-num").forEach((el, i) => {
        checksCountUp(el, parseFloat(el.dataset.to) || 0, 1100, 100 + (i % 6) * 60, csFormatFor(el.dataset.kind));
    });
}

function profileStatsRowsHTML(s) {
    return profileStatRowHTML(liteAsset("/lottie/images/Баланс.lottie"), "Баланс", psNum(s.balance, "money", fmtNum(s.balance) + "⭐️"), "gif") + profileStatRowHTML(liteAsset("/lottie/images/ОборотБаланса.lottie"), "Оборот", psNum(s.turnover, "money", fmtNum(s.turnover) + "⭐️"), "gif") + profileStatRowHTML(liteAsset("/lottie/images/ПроцентПобед.lottie"), "Процент побед", psNum(s.winPercent, "pct", fmtCoef(s.winPercent) + "%"), "gif") + profileStatRowHTML(liteAsset("/lottie/images/ДатаРегистрации.lottie"), "Дата регистрации", formatDate(s.registrationDate), "gif") + profileStatRowHTML(liteAsset("/lottie/images/Депозиты.lottie"), "Депозитов", psNum(s.deposits, "money", fmtNum(s.deposits) + "⭐️"), "gif") + profileStatRowHTML(liteAsset("/lottie/images/Выводы.lottie"), "Выводов", psNum(s.cashouts, "money", fmtNum(s.cashouts) + "⭐️"), "gif") + profileStatRowHTML(liteAsset("/lottie/РазделБонусы/bonus_icon.png"), "Бонусы", psNum(s.bonuses || 0, "money", fmtNum(s.bonuses || 0) + "⭐️"), "gif") + profileStatRowHTML(liteAsset("/lottie/images/ВыСНами.lottie"), "Вы с нами", s.daysWithUs + " " + s.daysWithUsLabel, "gif");
}

const PS_VIEW_KEY = "eternaProfileStatsView";

let profileStatsData = null;

let profileStatsView = "list";

try {
    if (localStorage.getItem(PS_VIEW_KEY) === "chart") profileStatsView = "chart";
} catch (e) {}

const PS_DAY_MILESTONES = [7, 30, 60, 100, 180, 365, 500, 730, 1e3, 1500, 2e3, 3e3];

function profileStatsSwitchHTML(view) {
    return '<div class="ps-head"><div class="ps-switch" role="tablist" data-view="' + view + '">' + '<button type="button" class="ps-tab ps-tab-list" role="tab" data-ps-view="list">Список</button>' + '<button type="button" class="ps-tab ps-tab-chart" role="tab" data-ps-view="chart">Диаграмма</button>' + "</div></div>";
}

function profileStatsChartHTML(s) {
    const win = Math.max(0, Math.min(100, s.winPercent || 0));
    const dep = s.deposits || 0;
    const cash = s.cashouts || 0;
    const bonus = s.bonuses || 0;
    const flowMax = Math.max(dep, cash, bonus);
    const days = s.daysWithUs || 1;
    const next = PS_DAY_MILESTONES.find(m => m > days);
    const prev = next ? PS_DAY_MILESTONES[PS_DAY_MILESTONES.indexOf(next) - 1] || 0 : days;
    const dpct = next ? Math.max(3, Math.min(100, (days - prev) / (next - prev) * 100)) : 100;

    function tile(src, label, cls, to) {
        return '<div class="cs-tile"><span class="cs-tile-ic ' + cls + '"><span class="skel-box"></span>' + lazyImgTag(src, "", "checks-icon-img") + '</span><div class="cs-tile-text"><small>' + label + '</small><b class="cs-num" data-to="' + to + '" data-kind="money">0⭐️</b></div></div>';
    }
    let html = '<div class="cs-stats ps-stats">';
    html += '<div class="cs-card cs-donut-card ps-donut-card"><div class="cs-donut wl" id="psDonut"' + csRingAttr([
        [win, "green"],
        [win > 0 ? 100 - win : 0, "lose"]
    ]) + '><canvas class="cs-ring"></canvas><div class="cs-donut-in"><b class="cs-num" data-to="' + win + '" data-kind="pct">0%</b><small>побед</small></div></div>' + '<div class="cs-legend"><div class="cs-cap">Процент побед</div>' + '<div class="cs-leg"><i class="win"></i><span>Побед</span><b class="cs-num" data-to="' + win + '" data-kind="pct">0%</b></div>' + '<div class="cs-leg"><i class="lose"></i><span>Поражений</span><b class="cs-num" data-to="' + (win > 0 ? 100 - win : 0) + '" data-kind="pct">0%</b></div>' + '<div class="cs-leg-note">' + (win > 0 ? "По всем сыгранным ставкам" : "Пока нет выигранных ставок") + "</div></div></div>";
    html += '<div class="cs-tiles">' + tile("/lottie/images/Баланс.png", "Баланс", "gold", s.balance || 0) + tile("/lottie/images/ОборотБаланса.png", "Оборот", "gold", s.turnover || 0) + tile("/lottie/images/Депозиты.png", "Депозитов", "green", dep) + tile("/lottie/images/Выводы.png", "Выводов", "gold", cash) + tile("/lottie/РазделБонусы/bonus_icon.png", "Бонусы", "green", s.bonuses || 0) + "</div>";
    const net = dep - cash;
    html += '<div class="cs-card ps-flat"><div class="cs-cap">Ввод и вывод средств</div><div class="cs-group">' + checksBarRow("Депозитов", "green", dep, flowMax, 150) + checksBarRow("Выводов", "gold", cash, flowMax, 260) + checksBarRow("Бонусы", "green", bonus, flowMax, 370) + "</div>" + '<div class="cs-profit ' + (net >= 0 ? "pos" : "neg") + '"><span>Внесено − выведено</span><b><i class="cs-arrow"></i><span class="cs-num" data-to="' + net + '" data-kind="profit">0⭐️</span></b></div></div>';
    html += '<div class="cs-card ps-flat ps-days"><div class="ps-days-top"><div class="cs-cap">Вы с нами</div><span class="ps-days-date">с ' + escapeHtml(formatDate(s.registrationDate)) + "</span></div>" + '<div class="ps-days-big"><b class="cs-num" data-to="' + days + '" data-kind="int">0</b><small>' + escapeHtml(s.daysWithUsLabel || "дней") + "</small></div>" + '<div class="cs-track"><i class="cs-fill gold" style="--w:' + dpct.toFixed(1) + '%; transition-delay:300ms"></i></div>' + '<div class="ps-days-note">' + (next ? "До отметки в " + next + " дн. — ещё " + (next - days) : "Вы с нами дольше всех отметок — спасибо!") + "</div></div>";
    return html + "</div>";
}

function profileStatsRunChart(root) {
    if (!root) return;
    const st = root.querySelector(".cs-stats");
    csAnimateNums(root);
    const donut = root.querySelector("#psDonut");
    if (donut) checksAnimateDonut(donut, parseFloat(donut.dataset.pct) || 0, 1200, 120);
    requestAnimationFrame(() => requestAnimationFrame(() => {
        if (st && st.isConnected) st.classList.add("go");
    }));
}

function profileStatsApplyView(card, view) {
    const sw = card.querySelector(".ps-switch");
    if (sw) sw.dataset.view = view;
    card.querySelectorAll(".ps-tab").forEach(t => t.setAttribute("aria-selected", t.dataset.psView === view ? "true" : "false"));
    const listEl = card.querySelector(".ps-list");
    const chartEl = card.querySelector(".ps-chart");
    if (!profileStatsData || !listEl || !chartEl) return;
    const pop = el => {
        el.classList.remove("ps-in");
        void el.offsetWidth;
        el.classList.add("ps-in");
    };
    if (view === "chart") {
        chartEl.innerHTML = profileStatsChartHTML(profileStatsData);
        listEl.hidden = true;
        chartEl.hidden = false;
        pop(chartEl);
        profileStatsRunChart(chartEl);
    } else {
        chartEl.hidden = true;
        listEl.hidden = false;
        pop(listEl);
        csAnimateNums(listEl);
    }
}

function profileStatsRender(card) {
    if (!profileStatsData) return;
    card.innerHTML = profileStatsSwitchHTML(profileStatsView) + '<div class="ps-view ps-list">' + profileStatsRowsHTML(profileStatsData) + '</div><div class="ps-view ps-chart" hidden></div>';
    profileStatsApplyView(card, profileStatsView);
}

function profileStatsSetView(view) {
    profileStatsView = view;
    try {
        localStorage.setItem(PS_VIEW_KEY, view);
    } catch (e) {}
    const card = document.getElementById("profileStatsCard");
    if (card) profileStatsApplyView(card, view);
}

document.addEventListener("click", e => {
    const tab = e.target.closest && e.target.closest(".ps-tab");
    if (!tab) return;
    if (tab.closest("#refStatsBody")) {
        if (tab.dataset.psView === refStatsView) return;
        haptic("selection");
        refStatsSetView(tab.dataset.psView);
        return;
    }
    if (tab.dataset.psView === profileStatsView) return;
    haptic("selection");
    profileStatsSetView(tab.dataset.psView);
});

function tagPlural(n, one, few, many) {
    n = Math.abs(Math.floor(n));
    if (n % 10 === 1 && n % 100 !== 11) return one;
    if (n % 10 >= 2 && n % 10 <= 4 && !(n % 100 >= 12 && n % 100 <= 14)) return few;
    return many;
}

function tagTimeText(sec) {
    sec = Math.max(0, Math.floor(sec));
    const d = Math.floor(sec / 86400);
    const h = Math.floor(sec % 86400 / 3600);
    const m = Math.floor(sec % 3600 / 60);
    if (d > 0) return d + " д" + (h > 0 ? " " + h + " ч" : "");
    if (h > 0) return h + " ч" + (m > 0 ? " " + m + " мин" : "");
    return Math.max(1, m) + " мин";
}

function tagHoursLabel(h) {
    h = Number(h);
    if (h >= 24 && Math.abs(h / 24 - Math.round(h / 24)) < 1e-9) {
        const d = Math.round(h / 24);
        return d + " " + tagPlural(d, "день", "дня", "дней");
    }
    return fmtCoef(h) + " ч";
}

function tagGamesWord(n) {
    return tagPlural(n, "игру", "игры", "игр");
}

function tagFlameTexts(t) {
    const g = t.games;
    const bot = escapeHtml(t.bot || "бот");
    const left = Math.max(0, g.need - g.today);
    if (!t.tag) return ["Огонька нет", "Добавьте @" + bot + " в имя профиля и играйте по " + g.need + " " + tagGamesWord(g.need) + " в день — огонёк будет расти"];
    if (g.state === "dead") return ["Огонёк потух", "Серия " + g.deadDays + " " + tagPlural(g.deadDays, "день", "дня", "дней") + " сгорела. Сыграйте " + g.need + " " + tagGamesWord(g.need) + " сегодня, чтобы зажечь снова"];
    if (g.state === "new") return ["Зажгите огонёк", "Сыграйте " + g.need + " " + tagGamesWord(g.need) + " сегодня — серия начнётся" + (g.today > 0 ? " (осталось " + left + ")" : "")];
    const days = g.days + " " + tagPlural(g.days, "день", "дня", "дней");
    if (g.state === "lit") return [days, "Норма на сегодня сыграна · завтра сыграйте ещё " + g.need + " " + tagGamesWord(g.need) + ", чтобы огонёк продолжал гореть" + (t.percent > 0 ? " · +" + fmtCoef(t.percent) + "% к бонусу" : "")];
    if (g.state === "alert") return [days, "Огонёк тревожится! Сыграйте ещё " + left + " " + tagGamesWord(left) + " — до конца дня " + tagTimeText(g.secondsLeft)];
    return [days, "Сегодня " + g.today + " из " + g.need + " · сыграйте ещё " + left + " " + tagGamesWord(left) + ", чтобы огонёк не погас · до конца дня " + tagTimeText(g.secondsLeft)];
}

function tagFlameBarHTML(t) {
    const g = t.games;
    if (!t.tag) return "";
    const pct = Math.min(100, Math.round(g.today / Math.max(1, g.need) * 100));
    return '<div class="tag-games-line"><span>Игр сегодня</span><b>' + Math.min(g.today, g.need) + " / " + g.need + (g.todayDone ? " ✓" : "") + '</b></div><div class="tag-games-bar' + (g.todayDone ? " done" : "") + '"><i style="width:' + pct + '%"></i></div>' + (g.best > 0 ? '<div class="tag-games-best">Рекорд: ' + g.best + " " + tagPlural(g.best, "день", "дня", "дней") + "</div>" : "");
}

function tagStreakTexts(t) {
    if (t.games && t.streakOn) return tagFlameTexts(t);
    const bot = escapeHtml(t.bot || "бот");
    if (t.streakOn) {
        if (!t.tag) return ["Серии нет", "Добавьте @" + bot + " в имя профиля: каждый день +" + fmtCoef(t.perDay) + "% к бонусу за выигрыш, до +" + fmtCoef(t.maxPercent) + "%"];
        const days = t.days + " " + tagPlural(t.days, "день", "дня", "дней");
        if (t.capped) return [days, "Максимум: серия на потолке +" + fmtCoef(t.maxPercent) + "% к бонусу"];
        if (t.days > 0) return [days, "+" + fmtCoef(t.percent) + "% к бонусу за выигрыш · следующий день через " + tagTimeText(t.nextDay)];
        return ["Серия началась", "Первая надбавка +" + fmtCoef(t.perDay) + "% через " + tagTimeText(t.nextDay || 86400)];
    }
    if (!t.tag) return ["Приписки нет", "Добавьте @" + bot + " в имя профиля: чем дольше она стоит, тем больше бонус к выигрышу"];
    if (t.step > 0) return ["Ступень " + t.step + " из " + t.steps.length, "+" + fmtCoef(t.total) + "% к каждому выигрышу"];
    const first = t.steps[0];
    return ["Приписка стоит", first ? "Первая ступень +" + fmtCoef(first.percent) + "% откроется через " + tagTimeText(first.left) : "Бонус откроется позже"];
}

function tagStreakBlockHTML(t) {
    if (!t || !t.enabled) return "";
    const texts = tagStreakTexts(t);
    const flame = !!(t.games && t.streakOn);
    const fireSrc = flame ? "/lottie/Серийчики/" + (t.tag ? t.games.skin : "streak_dead") + ".lottie" : "/lottie/images/FireBonus.lottie";
    const bar = t.streakOn && t.tag && t.maxPercent > 0 ? '<div class="tag-streak-bar"><i style="width:' + Math.min(100, Math.round(t.percent / t.maxPercent * 100)) + '%"></i></div>' + '<div class="tag-streak-cap"><span>+0%</span><span>потолок +' + fmtCoef(t.maxPercent) + "%</span></div>" : "";
    const steps = t.ladderOn && t.steps.length ? '<div class="tag-steps">' + t.steps.map(st => '<div class="tag-step' + (st.reached ? " on" : "") + '"><b>+' + fmtCoef(st.percent) + "%</b><i>от " + tagHoursLabel(st.hours) + "</i></div>").join("") + "</div>" : "";
    const note = t.tag && t.total > 0 ? '<div class="tag-streak-note">Сейчас к каждому выигрышу добавляется <b>+' + fmtCoef(t.total) + "%</b></div>" : "";
    const gamesBar = flame ? tagFlameBarHTML(t) : "";
    return '<div class="ref-block tag-streak' + (t.tag ? "" : " off") + (flame ? " flame flame-" + (t.tag ? t.games.state : "off") : "") + '">' + '<div class="ref-block-title">' + (flame ? "Огонёк серии" : t.streakOn ? "Серия приписки" : "Лесенка приписки") + "</div>" + '<div class="tag-streak-main">' + '<div class="tag-streak-fire"><span class="skel-box"></span>' + lazyImgTag(liteAsset(fireSrc), "", "") + "</div>" + '<div class="tag-streak-text"><b class="tag-streak-days">' + texts[0] + "</b><span>" + texts[1] + "</span></div></div>" + gamesBar + bar + steps + note + '<div class="tag-streak-act"><button class="ref-action-btn tag-streak-btn" type="button" data-action="tag-profile-check">Проверить приписку</button></div></div>';
}

function renderTagStreakSlot(t) {
    const slot = document.getElementById("tagStreakSlot");
    if (slot) slot.innerHTML = tagStreakBlockHTML(t);
}

function tagProfileCheck(btn) {
    if (btn.classList.contains("busy")) return;
    btn.classList.add("busy");
    fetch("/api/bonuses/tagpromo/check", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID
        })
    }).then(r => r.json()).then(data => {
        if (!data || !data.ok) throw new Error("bad response");
        const tp = data.state && data.state.tagPromo;
        const found = !!(tp && tp.tag && tp.tag.name);
        showToast(found ? "Приписка найдена" : "Приписка не найдена: добавьте @" + (tp && tp.bot ? tp.bot : "бот") + " в имя", found ? "success" : "warning");
        return fetch("/api/profile/stats?uid=" + CURRENT_UID).then(r => r.json()).then(stats => {
            if (stats && stats.ok) renderTagStreakSlot(stats.tagStreak);
        });
    }).catch(() => {
        showToast("Нет соединения, попробуйте ещё раз", "error");
    }).finally(() => {
        const again = document.querySelector('[data-action="tag-profile-check"]');
        if (again) again.classList.remove("busy");
    });
}

function profileStatsSkeletonHTML() {
    let rows = "";
    for (let i = 0; i < 7; i++) {
        rows += '<div class="profile-stat-row"><div class="profile-stat-label">' + '<span class="skel-box" style="width:18px;height:18px;border-radius:6px;flex-shrink:0;"></span>' + '<span class="text-skel" style="width:100px;">Баланс</span></div>' + '<div class="profile-stat-value text-skel" style="width:60px;">100⭐️</div></div>';
    }
    return '<div class="profile-stats-card" id="profileStatsCard">' + profileStatsSwitchHTML(profileStatsView) + '<div class="ps-view ps-list">' + rows + "</div></div>";
}

function loadProfileStats() {
    fetch("/api/profile/stats?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (!data || !data.ok) throw new Error("bad response");
        profileStatsData = data;
        const card = document.getElementById("profileStatsCard");
        if (card) profileStatsRender(card);
        renderTagStreakSlot(data.tagStreak);
    }).catch(() => {
        if (document.getElementById("profileStatsCard")) setTimeout(loadProfileStats, 4e3);
    });
}

function refLinkDisplayHTML(link) {
    const m = /^(https?:\/\/)(.*)$/i.exec(link || "");
    if (!m) return escapeHtml(link || "");
    return '<span class="ref-link-proto">' + escapeHtml(m[1]) + "</span>" + escapeHtml(m[2]);
}

function refBlockHTML() {
    const linkHtml = refDataLoaded ? refLinkDisplayHTML(currentUser.refLink) : '<span class="text-skel" style="display:inline-block; width:100%;">https://t.me/mjrstarsbot?start=xxxxxxxx</span>';
    const countHtml = refDataLoaded ? currentUser.refCount : '<span class="text-skel" style="display:inline-block; width:24px;">0</span>';
    const earnHtml = refDataLoaded ? fmtNum(currentUser.refEarnings) + "⭐️" : '<span class="text-skel" style="display:inline-block; width:48px;">0⭐️</span>';
    return '<div class="ref-block">' + '<div class="ref-block-title"><span class="ref-title-icon"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/РефСистема.lottie"), "", "") + "</span>Реф. Система</div>" + '<div class="ref-link-wrap">' + '<div class="ref-copied-badge" id="refCopiedBadge">Скопировано!</div>' + '<div class="ref-link-row">' + '<span class="ref-link-text" id="profileRefLink">' + linkHtml + "</span>" + '<button class="fair-copy-btn" type="button" id="profileCopyBtn" title="Скопировать">' + fairCopyIconHTML() + "</button>" + "</div>" + '<button class="ref-share-btn" type="button" data-action="ref-share-link">' + lazyImgTag(liteAsset(CHECKS_DIR + "СоздатьИнлайн.lottie"), "", "ref-share-btn-icon") + "<span>Поделиться ссылкой</span>" + "</button>" + "</div>" + '<div class="ref-summary-row">' + '<div class="ref-summary-item"><span class="ref-summary-label">Приглашено друзей</span><span class="ref-summary-value" id="refSummaryCount">' + countHtml + "</span></div>" + '<div class="ref-summary-item"><span class="ref-summary-label">Заработано с рефералов</span><span class="ref-summary-value" id="refSummaryEarnings">' + earnHtml + "</span></div>" + "</div>" + '<div class="ref-percents">' + '<div class="ref-percents-title"><span class="ref-title-icon"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/РеферальноеНачисление.lottie"), "", "") + "</span>Реферальные начисления:</div>" + '<div class="ref-percents-line text-skel" id="refPercentDeposit">• Доля от депозитов: загрузка…</div>' + '<div class="ref-percents-line text-skel" id="refPercentGame">• Бонус за приглашение: загрузка…</div>' + "</div>" + '<div class="ref-btn-grid">' + '<button class="ref-action-btn" type="button" data-action="ref-open-list">Мои рефералы</button>' + '<button class="ref-action-btn" type="button" data-action="ref-open-history">История начислений</button>' + '<button class="ref-action-btn" type="button" data-action="ref-open-stats">Подробная статистика</button>' + '<button class="ref-action-btn" type="button" data-action="ref-open-top">Топ 5 рефоводов</button>' + '<button class="ref-action-btn" type="button" data-action="ref-withdraw">Перевести на основной баланс</button>' + "</div>" + '<div class="ref-notif-row">' + '<div class="ref-notif-text">' + '<b id="refNotifStatus" class="text-skel">Уведомления: ···</b>' + "<span>Получайте уведомления о новых рефералах и начислениях</span>" + "</div>" + '<button class="gv-toggle" type="button" id="refNotifToggle"><span class="gv-toggle-knob"></span></button>' + "</div>" + "</div>";
}

function loadReferralHeaderExtras() {
    fetchWithRetry("/api/referral/stats?uid=" + CURRENT_UID, data => {
        refDataLoaded = true;
        currentUser.refCount = data.refCount;
        currentUser.refEarnings = data.totalEarnings;
        const depEl = document.getElementById("refPercentDeposit");
        if (depEl) {
            depEl.textContent = "• " + fmtCoef(data.depositPercent) + "% от депозитов ваших рефералов";
            depEl.classList.remove("text-skel");
        }
        const gameEl = document.getElementById("refPercentGame");
        if (gameEl) {
            gameEl.textContent = "• За приглашение: " + fmtNum(data.signupBase) + " Stars, с Telegram Premium — " + fmtNum(data.signupPremium) + " Stars";
            gameEl.classList.remove("text-skel");
        }
        const countEl = document.getElementById("refSummaryCount");
        if (countEl) {
            countEl.textContent = data.refCount;
            countEl.classList.remove("text-skel");
        }
        const earnEl = document.getElementById("refSummaryEarnings");
        if (earnEl) {
            earnEl.textContent = fmtNum(data.totalEarnings) + "⭐️";
            earnEl.classList.remove("text-skel");
        }
    });
    fetchWithRetry("/api/referral/notifications?uid=" + CURRENT_UID, data => {
        refNotifLoaded = true;
        setRefNotifUI(data.enabled);
    });
}

function fetchWithRetry(url, onOk) {
    fetch(url).then(r => r.json()).then(data => {
        if (!data || !data.ok) throw new Error("bad response");
        onOk(data);
    }).catch(() => {
        setTimeout(() => fetchWithRetry(url, onOk), 4e3);
    });
}

function setRefNotifUI(enabled) {
    const toggle = document.getElementById("refNotifToggle");
    const status = document.getElementById("refNotifStatus");
    if (toggle) toggle.classList.toggle("on", enabled);
    if (status) {
        status.textContent = "Уведомления: " + (enabled ? "Включены" : "Выключены");
        status.classList.remove("text-skel");
    }
}

function liteUiBlockHTML() {
    return '<div class="ref-block">' + '<div class="ref-block-title"><span class="ref-title-icon"><span class="skel-box"></span>' + lazyImgTag("/lottie/LiteUi.png", "", "") + "</span>Lite UI</div>" + '<div class="ref-notif-row">' + '<div class="ref-notif-text">' + '<b id="liteUiStatus">Lite UI: ' + (currentUser.liteUiEnabled ? "Включено" : "Выключено") + "</b>" + "<span>Анимации станут статичными картинками — меньше нагрузки на устройство</span>" + "</div>" + '<button class="gv-toggle' + (currentUser.liteUiEnabled ? " on" : "") + '" type="button" id="liteUiToggle"><span class="gv-toggle-knob"></span></button>' + "</div>" + '<div class="ref-notif-row">' + '<div class="ref-notif-text">' + '<b id="tgBgStatus">Фон как в Telegram: ' + (currentUser.tgBgEnabled ? "Включено" : "Выключено") + "</b>" + "<span>Узор из значков на фоне всех экранов, загрузки и нижнего меню</span>" + "</div>" + '<button class="gv-toggle' + (currentUser.tgBgEnabled ? " on" : "") + '" type="button" id="tgBgToggle"><span class="gv-toggle-knob"></span></button>' + "</div>" + "</div>";
}

function fullscreenBlockHTML() {
    return '<div class="ref-block">' + '<div class="ref-block-title"><span class="ref-title-icon"><span class="skel-box"></span>' + lazyImgTag("/lottie/WebAppFullScreen.png", "", "") + "</span>WebApp View</div>" + '<div class="ref-notif-row">' + '<div class="ref-notif-text">' + '<b id="fullscreenStatus">WebApp View: ' + (currentUser.fullscreenEnabled ? "Fullscreen" : "Fullsize") + "</b>" + "<span>Растянуть мини-апп на весь экран телефона, по умолчанию FullScreen</span>" + "</div>" + '<button class="gv-toggle' + (currentUser.fullscreenEnabled ? " on" : "") + '" type="button" id="fullscreenToggle"><span class="gv-toggle-knob"></span></button>' + "</div>" + "</div>";
}

function renderProfileBody() {
    const body = document.getElementById("profileBody");
    if (!body) return;
    body.innerHTML = profileStatsSkeletonHTML() + '<div id="tagStreakSlot"></div>' + refBlockHTML() + liteUiBlockHTML() + fullscreenBlockHTML();
    loadProfileStats();
    loadReferralHeaderExtras();
}

const profileBodyEl = document.getElementById("profileBody");

if (profileBodyEl) {
    profileBodyEl.addEventListener("click", e => {
        const referralShare = e.target.closest('[data-action="ref-share-link"]');
        if (referralShare) {
            if (!currentUser.refLink) return;
            const link = "https://t.me/share/url?url=" + encodeURIComponent(currentUser.refLink);
            if (tgWebApp && tgWebApp.openTelegramLink) tgWebApp.openTelegramLink(link);
            else window.open(link, "_blank", "noopener");
            return;
        }
        const referralWithdraw = e.target.closest('[data-action="ref-withdraw"]');
        if (referralWithdraw) {
            if (referralWithdraw.disabled) return;
            referralWithdraw.disabled = true;
            fetch("/api/referral/withdraw", {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({uid: CURRENT_UID})}).then(response => response.json()).then(data => {
                if (!data || !data.ok) throw new Error(data && data.error || "Не удалось перевести средства");
                applyBalance(data.balance);
                loadReferralHeaderExtras();
                showToast("Переведено " + fmtNum(data.creditedAmount) + " Stars", "success");
            }).catch(error => showToast(error.message, "error")).finally(() => referralWithdraw.disabled = false);
            return;
        }
        const tagCheckBtn = e.target.closest('[data-action="tag-profile-check"]');
        if (tagCheckBtn) {
            tagProfileCheck(tagCheckBtn);
            return;
        }
        const shareBtn = e.target.closest('[data-action="checks-create-inline"]');
        if (shareBtn) {
            checksOpenInlineChatPicker();
            return;
        }
        const copyRow = e.target.closest(".ref-link-row");
        if (copyRow) {
            const copyBtn = document.getElementById("profileCopyBtn");
            if (navigator.clipboard) navigator.clipboard.writeText(currentUser.refLink).catch(() => {});
            if (copyBtn) flashCopyIcon(copyBtn);
            const linkEl = document.getElementById("profileRefLink");
            const badgeEl = document.getElementById("refCopiedBadge");
            if (linkEl && !linkEl.dataset.copyFlashing) {
                linkEl.dataset.copyFlashing = "1";
                if (badgeEl) badgeEl.classList.add("show");
                try {
                    const range = document.createRange();
                    range.selectNodeContents(linkEl);
                    const sel = window.getSelection();
                    sel.removeAllRanges();
                    sel.addRange(range);
                } catch (err) {}
                setTimeout(() => {
                    if (badgeEl) badgeEl.classList.remove("show");
                    delete linkEl.dataset.copyFlashing;
                    const sel = window.getSelection();
                    if (sel) sel.removeAllRanges();
                }, 1500);
            }
            return;
        }
        const notifToggle = e.target.closest("#refNotifToggle");
        if (notifToggle) {
            const newState = !notifToggle.classList.contains("on");
            setRefNotifUI(newState);
            fetch("/api/referral/notifications", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    uid: CURRENT_UID,
                    enabled: newState
                })
            }).catch(() => {});
            return;
        }
        const liteUiToggle = e.target.closest("#liteUiToggle");
        if (liteUiToggle) {
            currentUser.liteUiEnabled = !currentUser.liteUiEnabled;
            applyLiteUiUI();
            fetch("/api/settings/lite_ui", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    uid: CURRENT_UID,
                    enabled: currentUser.liteUiEnabled
                })
            }).catch(() => {});
            return;
        }
        const tgBgToggle = e.target.closest("#tgBgToggle");
        if (tgBgToggle) {
            currentUser.tgBgEnabled = !currentUser.tgBgEnabled;
            applyTgBg();
            fetch("/api/settings/tg_bg", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    uid: CURRENT_UID,
                    enabled: currentUser.tgBgEnabled
                })
            }).catch(() => {});
            return;
        }
        const fullscreenToggle = e.target.closest("#fullscreenToggle");
        if (fullscreenToggle) {
            currentUser.fullscreenEnabled = !currentUser.fullscreenEnabled;
            applyFullscreenUI();
            fetch("/api/settings/fullscreen", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    uid: CURRENT_UID,
                    enabled: currentUser.fullscreenEnabled
                })
            }).catch(() => {});
            return;
        }
        const listBtn = e.target.closest('[data-action="ref-open-list"]');
        if (listBtn) {
            openRefListModal();
            return;
        }
        const histBtn = e.target.closest('[data-action="ref-open-history"]');
        if (histBtn) {
            openRefHistoryModal();
            return;
        }
        const statsBtn = e.target.closest('[data-action="ref-open-stats"]');
        if (statsBtn) {
            openRefStatsModal();
            return;
        }
        const topBtn = e.target.closest('[data-action="ref-open-top"]');
        if (topBtn) {
            openRefTopModal();
            return;
        }
    });
}

const PRIVACY_MODE_LABELS = {
    username: "Telegram Username",
    hidden: "Анонимно",
    blank: "Пустой ник",
    game_id: "Игровой ID",
    nickname: "Псевдоним"
};

let privacyData = null;

let privacyScreen = "main";

let privacyActivateOnSave = false;

let privacyBusy = false;

function openPrivacyModal() {
    document.getElementById("privacyModal").classList.add("active");
    privacyScreen = "main";
    document.getElementById("privacyModalBody").innerHTML = privacySkeletonHTML();
    loadPrivacyData();
}

function closePrivacyModal() {
    document.getElementById("privacyModal").classList.remove("active");
}

document.getElementById("privacyClose").addEventListener("click", closePrivacyModal);

document.getElementById("privacyModal").addEventListener("click", e => {
    if (e.target.id === "privacyModal") closePrivacyModal();
});

document.getElementById("profilePrivacyBtn").addEventListener("click", openPrivacyModal);

document.querySelector(".brand").addEventListener("click", openPrivacyModal);

function updateHapticsToggleUI() {
    const icon = document.getElementById("hapticsToggleIcon");
    if (!icon) return;
    const src = "/lottie/images/" + (currentUser.hapticsEnabled ? "ВыбрацияВключено.png" : "ВыбрацияВыключено.png");
    if (icon.getAttribute("src") === src) return;
    icon.classList.remove("loaded");
    icon.setAttribute("src", src);
}

const hapticsToggleBtn = document.getElementById("hapticsToggleBtn");

if (hapticsToggleBtn) {
    hapticsToggleBtn.addEventListener("click", () => {
        currentUser.hapticsEnabled = !currentUser.hapticsEnabled;
        updateHapticsToggleUI();
        fetch("/api/settings/haptics", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                uid: CURRENT_UID,
                enabled: currentUser.hapticsEnabled
            })
        }).catch(() => {});
    });
}

const hapticsInfoBtn = document.getElementById("hapticsInfoBtn");

const hapticsInfoModal = document.getElementById("hapticsInfoModal");

const hapticsInfoClose = document.getElementById("hapticsInfoClose");

if (hapticsInfoBtn && hapticsInfoModal) {
    hapticsInfoBtn.addEventListener("click", () => hapticsInfoModal.classList.add("active"));
    if (hapticsInfoClose) hapticsInfoClose.addEventListener("click", () => hapticsInfoModal.classList.remove("active"));
    hapticsInfoModal.addEventListener("click", e => {
        if (e.target === hapticsInfoModal) hapticsInfoModal.classList.remove("active");
    });
}

function privacySkeletonHTML() {
    let btns = "";
    for (let i = 0; i < 5; i++) btns += '<span class="skel-box" style="height:44px;border-radius:12px;"></span>';
    return '<div class="privacy-desc"><span class="text-skel" style="width:90%;">line</span><span class="text-skel" style="width:70%;">line</span></div>' + '<div class="privacy-mode-grid">' + btns + "</div>";
}

function loadPrivacyData() {
    fetch("/api/privacy?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (!data || !data.ok) return;
        privacyData = data;
        renderPrivacyScreen();
    }).catch(() => {});
}

function privacyModeLabel(data) {
    if (data.privacyMode === "nickname" && data.displayName) return "Псевдоним (" + escapeHtml(data.displayName) + ")";
    return PRIVACY_MODE_LABELS[data.privacyMode] || "Telegram Username";
}

function renderPrivacyScreen() {
    if (!privacyData) return;
    const body = document.getElementById("privacyModalBody");
    const title = document.getElementById("privacyModalTitle");
    if (privacyScreen === "settings") {
        title.textContent = "Настройки приватности";
        body.innerHTML = privacySettingsHTML(privacyData);
        return;
    }
    if (privacyScreen === "nickname") {
        title.textContent = "Псевдоним";
        body.innerHTML = privacyNicknameHTML(privacyData);
        return;
    }
    title.innerHTML = '<span class="privacy-modal-title-icon"><span class="skel-box"></span>' + lazyImgTag("/lottie/images/Приватность.png", "", "") + "</span>Приватность";
    body.innerHTML = privacyMainHTML(privacyData);
}

function privacyMainHTML(data) {
    const gameUid = data.gameUid || "—";
    const modeLabel = privacyModeLabel(data);
    const nicknameHint = data.privacyMode === "nickname" && data.displayName ? '<div class="privacy-hint">Изменить псевдоним можно в настройках.</div>' : "";

    function modeBtn(mode, label, wide) {
        const active = data.privacyMode === mode ? " active" : "";
        return '<button class="privacy-mode-btn' + (wide ? " wide" : "") + active + '" type="button" data-privacy-mode="' + mode + '">' + label + "</button>";
    }
    return '<div class="privacy-desc">' + '<div class="privacy-desc-line">— Игровые ставки в игровом канале</div>' + '<div class="privacy-desc-line">— Топ игроков по обороту и балансу</div>' + '<div class="privacy-desc-line">— Ставки в чатах</div>' + "</div>" + '<div class="privacy-current">Сейчас отображается <b>' + modeLabel + "</b></div>" + nicknameHint + '<div class="privacy-mode-grid">' + modeBtn("username", "Telegram Username") + modeBtn("hidden", "Анонимно") + modeBtn("blank", "Пустой ник") + modeBtn("game_id", "Игрок #" + escapeHtml(String(gameUid))) + modeBtn("nickname", "Псевдоним", true) + "</div>" + '<button class="privacy-settings-btn" type="button" data-action="privacy-open-settings"><span class="privacy-btn-icon"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/НастройкиПриватности.lottie"), "", "") + "</span>Настройки</button>";
}

function privacySettingsHTML(data) {
    const hideOn = !!data.hideFromLeaderboard;
    const clickOn = !!data.clickableProfile;
    const nickStatus = data.displayName ? escapeHtml(data.displayName) : "Не указан";
    return '<button class="privacy-back-btn" type="button" data-action="privacy-back">‹ Назад</button>' + '<div class="privacy-toggle-row">' + '<div class="privacy-toggle-text"><b>Не показывать меня в рейтингах</b><span>Статус: ' + (hideOn ? "Да" : "Нет") + "</span></div>" + '<button class="gv-toggle' + (hideOn ? " on" : "") + '" type="button" data-privacy-toggle="hide"><span class="gv-toggle-knob"></span></button>' + "</div>" + '<div class="privacy-toggle-row">' + '<div class="privacy-toggle-text"><b>Псевдоним</b><span>' + nickStatus + "</span></div>" + '<button class="privacy-nickname-btn" type="button" data-action="privacy-open-nickname"><span class="privacy-btn-icon"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/ДатаРегистрации.lottie"), "", "") + "</span>" + (data.displayName ? "Изменить" : "Установить") + "</button>" + "</div>" + (data.displayName ? '<button class="privacy-delete-btn" type="button" data-action="privacy-delete-nickname"><span class="privacy-btn-icon"><span class="skel-box"></span>' + lazyImgTag("/lottie/images/УдалитьПсевдоним.lottie", "", "") + "</span>Удалить псевдоним</button>" : "") + '<div class="privacy-toggle-row">' + '<div class="privacy-toggle-text"><b>Кликабельный профиль</b><span>Статус: ' + (clickOn ? "Да" : "Нет") + "</span></div>" + '<button class="gv-toggle' + (clickOn ? " on" : "") + '" type="button" data-privacy-toggle="clickable"><span class="gv-toggle-knob"></span></button>' + "</div>";
}

function privacyNicknameHTML(data) {
    const hasName = !!data.displayName;
    const backAction = privacyActivateOnSave ? "privacy-back" : "privacy-back-settings";
    return '<button class="privacy-back-btn" type="button" data-action="' + backAction + '">‹ Назад</button>' + '<div class="privacy-nickname-desc">' + (hasName ? "Текущее отображаемое имя: <b>" + escapeHtml(data.displayName) + "</b>. Отправьте новое, чтобы сменить его за ⭐️" + fmtNum(1) + "." : "Установите отображаемое имя (3-20 символов: буквы, цифры и _), чтобы оно показывалось в канале при публикации ваших ставок.") + "</div>" + '<input class="privacy-nickname-input" type="text" id="privacyNicknameInput" maxlength="20" placeholder="Введите имя">' + '<div class="privacy-nickname-cost">Стоимость: ⭐️1.00 · Баланс: ' + fmtNum(currentUser.balance || 0) + "⭐️</div>" + '<button class="ref-action-btn" type="button" data-action="privacy-nickname-confirm"><span class="privacy-btn-icon"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/КнопкаПодтвердить.lottie"), "", "") + "</span>Подтвердить</button>" + (hasName ? '<button class="privacy-delete-btn" type="button" data-action="privacy-delete-nickname"><span class="privacy-btn-icon"><span class="skel-box"></span>' + lazyImgTag("/lottie/images/УдалитьПсевдоним.lottie", "", "") + "</span>Удалить псевдоним</button>" : "");
}

document.getElementById("privacyModalBody").addEventListener("click", e => {
    if (privacyBusy) return;
    const modeBtn = e.target.closest("[data-privacy-mode]");
    if (modeBtn) {
        const mode = modeBtn.dataset.privacyMode;
        if (mode === "nickname" && !(privacyData && privacyData.displayName)) {
            privacyActivateOnSave = true;
            privacyScreen = "nickname";
            renderPrivacyScreen();
            return;
        }
        privacySetMode(mode);
        return;
    }
    const settingsBtn = e.target.closest('[data-action="privacy-open-settings"]');
    if (settingsBtn) {
        privacyScreen = "settings";
        renderPrivacyScreen();
        return;
    }
    const backBtn = e.target.closest('[data-action="privacy-back"]');
    if (backBtn) {
        privacyActivateOnSave = false;
        privacyScreen = "main";
        renderPrivacyScreen();
        return;
    }
    const backSettingsBtn = e.target.closest('[data-action="privacy-back-settings"]');
    if (backSettingsBtn) {
        privacyScreen = "settings";
        renderPrivacyScreen();
        return;
    }
    const openNickBtn = e.target.closest('[data-action="privacy-open-nickname"]');
    if (openNickBtn) {
        privacyActivateOnSave = false;
        privacyScreen = "nickname";
        renderPrivacyScreen();
        return;
    }
    const toggleBtn = e.target.closest("[data-privacy-toggle]");
    if (toggleBtn) {
        privacyToggle(toggleBtn.dataset.privacyToggle);
        return;
    }
    const confirmBtn = e.target.closest('[data-action="privacy-nickname-confirm"]');
    if (confirmBtn) {
        privacyConfirmNickname();
        return;
    }
    const deleteBtn = e.target.closest('[data-action="privacy-delete-nickname"]');
    if (deleteBtn) {
        privacyDeleteNickname();
        return;
    }
});

function privacySetMode(mode) {
    privacyBusy = true;
    fetch("/api/privacy/mode", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            mode: mode
        })
    }).then(r => r.json()).then(data => {
        privacyBusy = false;
        if (!data || !data.ok) {
            showToast(data && data.error === "nickname_required" ? "Сначала установите псевдоним" : data && data.error || "Ошибка");
            return;
        }
        privacyData = data;
        privacyScreen = "main";
        renderPrivacyScreen();
        showToast("Режим отображения обновлён!", "success");
    }).catch(() => {
        privacyBusy = false;
    });
}

function privacyToggle(field) {
    privacyBusy = true;
    fetch("/api/privacy/toggle", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            field: field
        })
    }).then(r => r.json()).then(data => {
        privacyBusy = false;
        if (!data || !data.ok) return;
        privacyData = data;
        renderPrivacyScreen();
    }).catch(() => {
        privacyBusy = false;
    });
}

function privacyConfirmNickname() {
    const input = document.getElementById("privacyNicknameInput");
    const name = (input ? input.value : "").trim().replace(/^@/, "");
    if (!name) {
        showToast("Введите имя");
        return;
    }
    privacyBusy = true;
    fetch("/api/privacy/nickname", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            name: name,
            activate: privacyActivateOnSave
        })
    }).then(r => r.json()).then(data => {
        privacyBusy = false;
        if (!data || !data.ok) {
            showToast(data && data.error || "Ошибка");
            return;
        }
        privacyData = data;
        if (typeof data.balance === "number") {
            currentUser.balance = cleanBalance(data.balance);
            applyUserToUI();
        }
        privacyActivateOnSave = false;
        privacyScreen = privacyData.privacyMode === "nickname" ? "main" : "settings";
        renderPrivacyScreen();
        showToast("Отображаемое имя установлено: " + name, "success");
    }).catch(() => {
        privacyBusy = false;
    });
}

function privacyDeleteNickname() {
    privacyBusy = true;
    fetch("/api/privacy/nickname/delete", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID
        })
    }).then(r => r.json()).then(data => {
        privacyBusy = false;
        if (!data || !data.ok) return;
        privacyData = data;
        privacyScreen = "settings";
        renderPrivacyScreen();
        showToast("Псевдоним удалён", "success");
    }).catch(() => {
        privacyBusy = false;
    });
}

function refRowsSkeletonHTML(n, cols) {
    let html = "";
    for (let i = 0; i < n; i++) {
        html += '<div class="ref-list-row">' + '<span class="skel-box" style="width:34px;height:34px;border-radius:50%;flex-shrink:0;"></span>' + '<span class="text-skel" style="width:100px;">Игрок</span>' + '<span class="text-skel" style="width:70px;margin-left:auto;">28.08.2026</span>' + "</div>";
    }
    return html;
}

let refListPage = 1,
    refListTotalPages = 1,
    refListQuery = "",
    refListReq = 0,
    refListSearchTimer = null;

function refSearchNormalize(value) {
    return String(value || "").replace(/\s+/g, " ").trim().toLowerCase().slice(0, 64);
}

function refHitHTML(text, q) {
    const s = String(text == null ? "" : text);
    if (!q) return escapeHtml(s);
    const low = s.toLowerCase();
    if (low.length !== s.length) return escapeHtml(s);
    let out = "",
        pos = 0,
        idx;
    while ((idx = low.indexOf(q, pos)) !== -1) {
        out += escapeHtml(s.slice(pos, idx)) + '<mark class="my-games-search-hit">' + escapeHtml(s.slice(idx, idx + q.length)) + "</mark>";
        pos = idx + q.length;
    }
    return out + escapeHtml(s.slice(pos));
}

function refDateHitHTML(sqlDate, q) {
    const shown = formatDate(sqlDate);
    if (!q) return escapeHtml(shown);
    const dq = q.replace(/[.\/\\ ]+/g, "-");
    if (dq && shown.indexOf(dq) !== -1) return refHitHTML(shown, dq);
    if (dq && String(sqlDate || "").slice(0, 10).indexOf(dq) !== -1) return '<mark class="my-games-search-hit">' + escapeHtml(shown) + "</mark>";
    return escapeHtml(shown);
}

function refListRowHTML(r, q) {
    const name = r.name || r.username || "ID" + r.id;
    const handleQ = q.replace(/^@+/, "");
    const viaHandle = q && handleQ && name.toLowerCase().indexOf(q) === -1 && r.username && r.username.toLowerCase().indexOf(handleQ) !== -1;
    const nameHTML = '<div class="ref-list-name">' + refHitHTML(name, q) + "</div>";
    const nameCol = viaHandle ? '<div class="ref-list-namecol">' + nameHTML + '<div class="ref-list-sub">@' + refHitHTML(r.username, handleQ) + "</div></div>" : nameHTML;
    return '<div class="ref-list-row">' + '<div class="ref-list-avatar"><img src="/api/avatar/' + r.id + '" alt="" loading="lazy"></div>' + nameCol + '<div class="ref-list-date">' + refDateHitHTML(r.join_date, q) + "</div>" + "</div>";
}

function refListEmptyHTML(q) {
    if (q) return gvHistorySearchEmptyHTML();
    return '<div class="ref-empty">У вас пока нет рефералов</div>';
}

function loadRefList(keepRows) {
    const bodyEl = document.getElementById("refListBody");
    if (!bodyEl) return;
    const req = ++refListReq;
    const q = refListQuery;
    if (keepRows && bodyEl.querySelector(".ref-list-row")) bodyEl.classList.add("is-loading");
    else bodyEl.innerHTML = refRowsSkeletonHTML(4);
    fetch("/api/referral/list?uid=" + CURRENT_UID + "&page=" + refListPage + (q ? "&q=" + encodeURIComponent(q) : "")).then(r => r.json()).then(data => {
        if (req !== refListReq) return;
        if (!data || !data.ok) throw new Error("bad response");
        refListPage = data.page || 1;
        refListTotalPages = data.totalPages || 1;
        const rows = data.rows || [];
        bodyEl.classList.remove("is-loading");
        bodyEl.innerHTML = rows.length ? rows.map(r => refListRowHTML(r, q)).join("") : refListEmptyHTML(q);
        bodyEl.scrollTop = 0;
        const label = document.getElementById("refListPageLabel");
        if (label) label.textContent = refListPage + " из " + refListTotalPages;
        const countEl = document.getElementById("refListSearchCount");
        if (countEl) {
            countEl.hidden = !q || !rows.length;
            if (q && rows.length) countEl.textContent = "Найдено: " + (data.totalCount || rows.length);
        }
        const rowEl = document.getElementById("refListSearchRow");
        if (rowEl) rowEl.hidden = !q && !(data.allCount > 0);
    }).catch(() => {
        if (req === refListReq && document.getElementById("refListModal").classList.contains("active")) setTimeout(() => {
            if (req === refListReq) loadRefList(keepRows);
        }, 4e3);
    });
}

function refListApplySearch(value) {
    const next = refSearchNormalize(value);
    const clearBtn = document.getElementById("refListSearchClear");
    if (clearBtn) clearBtn.hidden = !String(value || "").length;
    if (next === refListQuery) return;
    refListQuery = next;
    refListPage = 1;
    loadRefList(true);
}

function openRefListModal() {
    refListPage = 1;
    refListQuery = "";
    clearTimeout(refListSearchTimer);
    const input = document.getElementById("refListSearchInput");
    if (input) input.value = "";
    const clearBtn = document.getElementById("refListSearchClear");
    if (clearBtn) clearBtn.hidden = true;
    const countEl = document.getElementById("refListSearchCount");
    if (countEl) countEl.hidden = true;
    const rowEl = document.getElementById("refListSearchRow");
    if (rowEl) rowEl.hidden = false;
    document.getElementById("refListModal").classList.add("active");
    loadRefList();
}

function closeRefListModal() {
    clearTimeout(refListSearchTimer);
    refListReq++;
    document.getElementById("refListModal").classList.remove("active");
}

document.getElementById("refListClose").addEventListener("click", closeRefListModal);

document.getElementById("refListModal").addEventListener("click", e => {
    if (e.target.id === "refListModal") closeRefListModal();
});

document.getElementById("refListPrev").addEventListener("click", () => {
    refListPage = refListPage > 1 ? refListPage - 1 : refListTotalPages;
    loadRefList(true);
});

document.getElementById("refListNext").addEventListener("click", () => {
    refListPage = refListPage < refListTotalPages ? refListPage + 1 : 1;
    loadRefList(true);
});

document.getElementById("refListSearchInput").addEventListener("input", e => {
    const value = e.target.value;
    const clearBtn = document.getElementById("refListSearchClear");
    if (clearBtn) clearBtn.hidden = !value.length;
    clearTimeout(refListSearchTimer);
    refListSearchTimer = setTimeout(() => refListApplySearch(value), 280);
});

document.getElementById("refListSearchInput").addEventListener("keydown", e => {
    if (e.key === "Enter") {
        e.preventDefault();
        clearTimeout(refListSearchTimer);
        refListApplySearch(e.target.value);
        e.target.blur();
    }
});

document.getElementById("refListSearchClear").addEventListener("click", () => {
    const input = document.getElementById("refListSearchInput");
    input.value = "";
    clearTimeout(refListSearchTimer);
    refListApplySearch("");
    input.focus();
});

let refHistoryPeriod = "all",
    refHistoryPage = 1,
    refHistoryTotalPages = 1;

function refHistoryRowHTML(r) {
    const isDeposit = r.type === "deposit";
    const isSignup = r.type === "signup";
    const name = escapeHtml(r.referral_name || r.referral_username || "ID" + r.referral_id);
    return '<div class="ref-history-row">' + '<span class="ref-history-icon ' + (isDeposit ? "in" : "out") + '">' + (isDeposit ? lazyImgTag("/images/СпособПополнения.png", "", "") : lazyImgTag("/lottie/images/ИсторияНачисленияРеф.lottie", "", "")) + "</span>" + '<div class="ref-history-mid">' + "<b>" + (isSignup ? "За приглашение" : "От депозита") + (isSignup ? "" : " (" + fmtCoef(r.percent) + "%)") + "</b>" + '<span class="ref-history-name">' + name + "</span>" + historyTimeHTML(r.date) + "</div>" + '<div class="ref-history-amount">+' + fmtNum(r.amount) + "⭐️</div>" + "</div>";
}

function refHistorySkeletonHTML() {
    let html = "";
    for (let i = 0; i < 4; i++) {
        html += '<div class="ref-history-row">' + '<span class="skel-box" style="width:30px;height:30px;border-radius:50%;flex-shrink:0;"></span>' + '<div class="ref-history-mid"><span class="text-skel" style="width:120px;">От депозита</span><span class="text-skel" style="width:80px;">Игрок</span></div>' + '<div class="ref-history-amount text-skel" style="width:40px;">10⭐️</div>' + "</div>";
    }
    return html;
}

function loadRefHistory() {
    const bodyEl = document.getElementById("refHistoryBody");
    if (!bodyEl) return;
    bodyEl.innerHTML = refHistorySkeletonHTML();
    fetch("/api/referral/history?uid=" + CURRENT_UID + "&period=" + refHistoryPeriod + "&page=" + refHistoryPage).then(r => r.json()).then(data => {
        if (!data || !data.ok) throw new Error("bad response");
        refHistoryPage = data.page || 1;
        refHistoryTotalPages = data.totalPages || 1;
        const rows = data.rows || [];
        bodyEl.innerHTML = rows.length ? rows.map(refHistoryRowHTML).join("") : '<div class="ref-empty">У вас пока нет реферальных начислений</div>';
        const label = document.getElementById("refHistoryPageLabel");
        if (label) label.textContent = refHistoryPage + " из " + refHistoryTotalPages;
    }).catch(() => {
        if (document.getElementById("refHistoryBody") === bodyEl) setTimeout(loadRefHistory, 4e3);
    });
}

function openRefHistoryModal() {
    refHistoryPeriod = "all";
    refHistoryPage = 1;
    document.querySelectorAll("#refHistoryPeriodTabs .ref-period-tab").forEach(t => t.classList.toggle("active", t.dataset.refPeriod === "all"));
    document.getElementById("refHistoryModal").classList.add("active");
    loadRefHistory();
}

function closeRefHistoryModal() {
    document.getElementById("refHistoryModal").classList.remove("active");
}

document.getElementById("refHistoryClose").addEventListener("click", closeRefHistoryModal);

document.getElementById("refHistoryModal").addEventListener("click", e => {
    if (e.target.id === "refHistoryModal") closeRefHistoryModal();
});

document.getElementById("refHistoryPeriodTabs").addEventListener("click", e => {
    const tab = e.target.closest(".ref-period-tab");
    if (!tab) return;
    refHistoryPeriod = tab.dataset.refPeriod;
    refHistoryPage = 1;
    document.querySelectorAll("#refHistoryPeriodTabs .ref-period-tab").forEach(t => t.classList.toggle("active", t === tab));
    loadRefHistory();
});

document.getElementById("refHistoryPrev").addEventListener("click", () => {
    refHistoryPage = refHistoryPage > 1 ? refHistoryPage - 1 : refHistoryTotalPages;
    loadRefHistory();
});

document.getElementById("refHistoryNext").addEventListener("click", () => {
    refHistoryPage = refHistoryPage < refHistoryTotalPages ? refHistoryPage + 1 : 1;
    loadRefHistory();
});

function refStatsSectionHTML(title, lines) {
    return '<div class="ref-stats-section"><div class="ref-stats-title">' + title + "</div>" + lines.join("") + "</div>";
}

function refStatsLine(label, value) {
    return '<div class="ref-stats-line">' + label + ": <b>" + value + "</b></div>";
}

function refStatsBodyHTML(s) {
    const icon = name => '<span class="ref-title-icon"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/" + name + ".lottie"), "", "") + "</span>";
    const money = v => psNum(v, "money", fmtNum(v) + "⭐️");
    return refStatsSectionHTML(icon("ДатаРегистрации") + "Основная статистика", [refStatsLine("Количество рефералов", psNum(s.refCount, "int", s.refCount)), refStatsLine("Общий заработок", money(s.totalEarnings)), refStatsLine("С депозитов (" + fmtCoef(s.depositPercent) + "%)", money(s.depositEarnings)), refStatsLine("За приглашения", money(s.signupEarnings))]) + refStatsSectionHTML(icon("ПроцентПобед") + "Недельная статистика", [refStatsLine("Заработок за 7 дней", money(s.weekEarnings))]) + refStatsSectionHTML(icon("ОборотБаланса") + "Детальная статистика", [refStatsLine("Количество начислений", psNum(s.totalCount, "int", s.totalCount)), refStatsLine("От депозитов", psNum(s.depositCount, "int", s.depositCount)), refStatsLine("За приглашения", psNum(s.signupCount, "int", s.signupCount))]) + refStatsSectionHTML(icon("РеферальноеНачисление") + "Размер начислений", [refStatsLine("Среднее от депозита", money(s.avgDeposit)), refStatsLine("Среднее за приглашение", money(s.avgSignup)), refStatsLine("Максимальное от депозита", money(s.maxDeposit)), refStatsLine("Максимальное за приглашение", money(s.maxSignup))]);
}

function psBarRow(label, cls, value, max, delay, kind) {
    const w = max > 0 ? Math.max(value > 0 ? 3 : 0, value / max * 100) : 0;
    return '<div class="cs-bar-row"><div class="cs-bar-top"><span>' + label + '</span><b class="cs-num" data-to="' + value + '" data-kind="' + kind + '">' + (kind === "int" ? "0" : "0⭐️") + '</b></div><div class="cs-track"><i class="cs-fill ' + cls + '" style="--w:' + w.toFixed(2) + "%; transition-delay:" + delay + 'ms"></i></div></div>';
}

function refStatsChartHTML(s) {
    const dep = s.depositEarnings || 0;
    const game = s.signupEarnings || 0;
    const sum = dep + game;
    const pct = sum > 0 ? dep / sum * 100 : 0;
    const total = s.totalEarnings || 0;
    const totalText = checksStatMoney(total);
    const fs = totalText.length <= 6 ? 18 : totalText.length <= 8 ? 15 : totalText.length <= 10 ? 13 : 11;

    function tile(icon, label, cls, to, kind) {
        return '<div class="cs-tile"><span class="cs-tile-ic ' + cls + '"><span class="skel-box"></span>' + lazyImgTag("/lottie/images/" + icon + ".png", "", "checks-icon-img") + '</span><div class="cs-tile-text"><small>' + label + '</small><b class="cs-num" data-to="' + to + '" data-kind="' + kind + '">' + (kind === "int" ? "0" : "0⭐️") + "</b></div></div>";
    }
    let html = '<div class="cs-stats ps-stats">';
    html += '<div class="cs-card cs-donut-card ps-donut-card"><div class="cs-donut" id="rsDonut"' + csRingAttr([
        [dep, "gold"],
        [game, "green"]
    ]) + '><canvas class="cs-ring"></canvas><div class="cs-donut-in"><b class="cs-num" style="font-size:' + fs + 'px" data-to="' + total + '" data-kind="money">0⭐️</b><small>заработок</small></div></div>' + '<div class="cs-legend"><div class="cs-cap">Источники дохода</div>' + '<div class="cs-leg"><i class="gold"></i><span>Депозит</span><b class="cs-num" data-to="' + dep + '" data-kind="money">0⭐️</b></div>' + '<div class="cs-leg"><i class="green"></i><span>Приглашения</span><b class="cs-num" data-to="' + game + '" data-kind="money">0⭐️</b></div>' + '<div class="cs-leg-note">' + fmtCoef(s.depositPercent) + "% с депозитов и бонусы за приглашения</div></div></div>";
    html += '<div class="cs-tiles">' + tile("РефСистема", "Рефералов", "green", s.refCount || 0, "int") + tile("РеферальноеНачисление", "Общий заработок", "gold", total, "money") + tile("ПроцентПобед", "За 7 дней", "green", s.weekEarnings || 0, "money") + tile("ОборотБаланса", "Начислений", "gold", s.totalCount || 0, "int") + "</div>";
    const cntMax = Math.max(s.depositCount || 0, s.signupCount || 0);
    html += '<div class="cs-card ps-flat"><div class="cs-cap">Количество начислений</div><div class="cs-group">' + psBarRow("От депозитов", "gold", s.depositCount || 0, cntMax, 150, "int") + psBarRow("За приглашения", "green", s.signupCount || 0, cntMax, 260, "int") + "</div>" + '<div class="cs-profit pos"><span>Всего начислений</span><b><i class="cs-arrow"></i><span class="cs-num" data-to="' + (s.totalCount || 0) + '" data-kind="int">0</span></b></div></div>';
    const avgMax = Math.max(s.avgDeposit || 0, s.avgSignup || 0);
    const maxMax = Math.max(s.maxDeposit || 0, s.maxSignup || 0);
    html += '<div class="cs-card ps-flat"><div class="cs-cap">Размер начислений</div>' + '<div class="cs-group"><div class="cs-group-cap">Среднее</div>' + psBarRow("От депозита", "gold", s.avgDeposit || 0, avgMax, 380, "money") + psBarRow("За приглашение", "green", s.avgSignup || 0, avgMax, 490, "money") + "</div>" + '<div class="cs-group"><div class="cs-group-cap">Максимальное</div>' + psBarRow("От депозита", "gold", s.maxDeposit || 0, maxMax, 600, "money") + psBarRow("За приглашение", "green", s.maxSignup || 0, maxMax, 710, "money") + "</div></div>";
    return html + "</div>";
}

const RS_VIEW_KEY = "eternaRefStatsView";

let refStatsData = null;

let refStatsView = "list";

try {
    if (localStorage.getItem(RS_VIEW_KEY) === "chart") refStatsView = "chart";
} catch (e) {}

function refStatsApplyView(body, view) {
    const sw = body.querySelector(".ps-switch");
    if (sw) sw.dataset.view = view;
    body.querySelectorAll(".ps-tab").forEach(t => t.setAttribute("aria-selected", t.dataset.psView === view ? "true" : "false"));
    const listEl = body.querySelector(".ps-list");
    const chartEl = body.querySelector(".ps-chart");
    if (!refStatsData || !listEl || !chartEl) return;
    const pop = el => {
        el.classList.remove("ps-in");
        void el.offsetWidth;
        el.classList.add("ps-in");
    };
    if (view === "chart") {
        chartEl.innerHTML = refStatsChartHTML(refStatsData);
        listEl.hidden = true;
        chartEl.hidden = false;
        pop(chartEl);
        csAnimateNums(chartEl);
        const donut = chartEl.querySelector("#rsDonut");
        if (donut) checksAnimateDonut(donut, parseFloat(donut.dataset.pct) || 0, 1200, 120);
        const st = chartEl.querySelector(".cs-stats");
        requestAnimationFrame(() => requestAnimationFrame(() => {
            if (st && st.isConnected) st.classList.add("go");
        }));
    } else {
        chartEl.hidden = true;
        listEl.hidden = false;
        pop(listEl);
        csAnimateNums(listEl);
    }
}

function refStatsRender(body) {
    if (!refStatsData) return;
    body.innerHTML = profileStatsSwitchHTML(refStatsView) + '<div class="ps-view ps-list">' + refStatsBodyHTML(refStatsData) + '</div><div class="ps-view ps-chart" hidden></div>';
    refStatsApplyView(body, refStatsView);
}

function refStatsSetView(view) {
    refStatsView = view;
    try {
        localStorage.setItem(RS_VIEW_KEY, view);
    } catch (e) {}
    const body = document.getElementById("refStatsBody");
    if (body) refStatsApplyView(body, view);
}

function refStatsSkeletonHTML() {
    let html = profileStatsSwitchHTML(refStatsView);
    for (let i = 0; i < 4; i++) {
        html += '<div class="ref-stats-section"><div class="text-skel" style="width:140px;height:14px;margin-bottom:8px;">Раздел</div>' + '<div class="text-skel" style="width:100%;height:12px;margin-bottom:6px;">строка</div>' + '<div class="text-skel" style="width:80%;height:12px;">строка</div></div>';
    }
    return html;
}

function openRefStatsModal() {
    const bodyEl = document.getElementById("refStatsBody");
    bodyEl.innerHTML = refStatsSkeletonHTML();
    document.getElementById("refStatsModal").classList.add("active");
    fetch("/api/referral/stats?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (!data || !data.ok) throw new Error("bad response");
        refStatsData = data;
        refStatsRender(bodyEl);
    }).catch(() => {
        if (document.getElementById("refStatsBody") === bodyEl) setTimeout(openRefStatsModal, 4e3);
    });
}

function closeRefStatsModal() {
    document.getElementById("refStatsModal").classList.remove("active");
}

document.getElementById("refStatsClose").addEventListener("click", closeRefStatsModal);

document.getElementById("refStatsModal").addEventListener("click", e => {
    if (e.target.id === "refStatsModal") closeRefStatsModal();
});

function refTopRowHTML(r, idx) {
    const name = escapeHtml(r.name || r.username || "ID" + r.id);
    return '<div class="ref-list-row">' + '<div class="ref-top-rank">#' + (idx + 1) + "</div>" + '<div class="ref-list-avatar"><img src="/api/avatar/' + r.id + '" alt="" loading="lazy"></div>' + '<div class="ref-list-name">' + name + "</div>" + '<div class="ref-top-count">' + r.c + " реф.</div>" + "</div>";
}

function openRefTopModal() {
    const bodyEl = document.getElementById("refTopBody");
    bodyEl.innerHTML = refRowsSkeletonHTML(5);
    document.getElementById("refTopModal").classList.add("active");
    fetch("/api/referral/top").then(r => r.json()).then(data => {
        if (!data || !data.ok) throw new Error("bad response");
        const rows = data.rows || [];
        bodyEl.innerHTML = rows.length ? rows.map(refTopRowHTML).join("") : '<div class="ref-empty">Пока никто не пригласил рефералов</div>';
    }).catch(() => {
        if (document.getElementById("refTopBody") === bodyEl) setTimeout(openRefTopModal, 4e3);
    });
}

function closeRefTopModal() {
    document.getElementById("refTopModal").classList.remove("active");
}

document.getElementById("refTopClose").addEventListener("click", closeRefTopModal);

document.getElementById("refTopModal").addEventListener("click", e => {
    if (e.target.id === "refTopModal") closeRefTopModal();
});

let walletHistoryFilter = "all";

let walletHistoryPage = 1;

let walletHistoryTotalPages = 1;

const WALLET_ICON_DEPOSIT = "data:image/png;base64,";

const WALLET_ICON_WITHDRAW = "data:image/png;base64,";

function walletMethodDisplay(method) {
    if (!method) return "Неизвестно";
    if (method.indexOf("CryptoBot") !== -1) return "CryptoBot";
    if (method.indexOf("xRocket") !== -1) return "xRocket";
    if (method.indexOf("Stars") !== -1) return "Telegram Stars";
    if (method.indexOf("Tonkeeper") !== -1) {
        if (method.indexOf("USDT") !== -1) return "Tonkeeper (USDT)";
        if (method.indexOf("TON") !== -1 || method.indexOf("GRAM") !== -1) return "Tonkeeper (GRAM)";
        return "Tonkeeper";
    }
    return method;
}

function backPillHTML(action) {
    return '<button class="back-pill" data-action="' + action + '">' + '<svg viewBox="0 0 24 24" fill="none"><path d="M15 6l-6 6 6 6" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"/></svg>' + "Обратно</button>";
}

function walletBalancePillHTML() {
    const amountHtml = balanceAmountHTML(currentUser.balance, !userDataLoaded);
    return '<div class="balance-pill"><span class="amount' + (userDataLoaded ? "" : " text-skel") + '">' + amountHtml + '</span><div class="coin-toggle">' + (sourceCoinToggle ? sourceCoinToggle.innerHTML : "") + "</div></div>";
}

function walletTxRowHTML(r) {
    const isOut = r.type === "withdrawal";
    const d = mskParts((r.created_at || 0) * 1e3);
    const pad = n => String(n).padStart(2, "0");
    const dateStr = pad(d.d) + "." + pad(d.mo) + "." + d.y;
    const timeStr = pad(d.h) + ":" + pad(d.mi);
    return '<div class="wv-table-row">' + '<div class="wv-tx-type">' + '<span class="wv-tx-icon ' + (isOut ? "out" : "in") + '"><img src="' + (isOut ? WALLET_ICON_WITHDRAW : WALLET_ICON_DEPOSIT) + '" alt=""></span>' + '<span class="wv-tx-type-text"><b>' + (isOut ? "Вывод" : "Пополнение") + '</b><span class="wv-tx-method">' + escapeHtml(walletMethodDisplay(r.description)) + "</span></span>" + "</div>" + '<div class="wv-tx-time">' + dateStr + "<br>" + timeStr + "</div>" + walletStatusHTML(r) + walletAmountHTML(r, isOut) + "</div>";
}

function walletHistorySkeletonHTML() {
    let html = "";
    for (let i = 0; i < 4; i++) {
        html += '<div class="wv-table-row">' + '<div class="wv-tx-type"><span class="skel-box" style="width:26px;height:26px;border-radius:50%;flex-shrink:0;"></span>' + '<span class="wv-tx-type-text"><span class="text-skel" style="width:70px;">Пополнение</span><span class="text-skel" style="width:50px;">CryptoBot</span></span></div>' + '<div class="text-skel" style="width:56px;">28.08.2026</div>' + '<div class="text-skel" style="width:56px;">Успешно</div>' + '<div class="wv-amount text-skel" style="width:40px; margin-left:auto;">100⭐️</div>' + "</div>";
    }
    return html;
}

function loadWalletHistory() {
    const body = document.getElementById("wvHistoryBody");
    if (!body) return;
    body.innerHTML = walletHistorySkeletonHTML();
    fetch("/api/wallet/transactions?uid=" + CURRENT_UID + "&filter=" + walletHistoryFilter + "&page=" + walletHistoryPage).then(r => r.json()).then(data => {
        if (!data || !data.ok) throw new Error("bad response");
        walletHistoryPage = data.page || 1;
        walletHistoryTotalPages = data.totalPages || 1;
        const rows = data.rows || [];
        body.innerHTML = rows.length ? rows.map(walletTxRowHTML).join("") : '<div class="wv-history-empty">Транзакций пока нет</div>';
        const pageLabel = document.getElementById("wvPageLabel");
        if (pageLabel) pageLabel.textContent = walletHistoryPage + " из " + walletHistoryTotalPages;
        const prevBtn = document.getElementById("wvPagePrev");
        const nextBtn = document.getElementById("wvPageNext");
        if (prevBtn) prevBtn.classList.toggle("dim", walletHistoryTotalPages <= 1);
        if (nextBtn) nextBtn.classList.toggle("dim", walletHistoryTotalPages <= 1);
    }).catch(() => {
        if (document.getElementById("wvHistoryBody") === body) {
            setTimeout(loadWalletHistory, 4e3);
        }
    });
}

let walletPromoPrefill = "";

let walletPromoBusy = false;

let walletInfoToken = 0;

let walletFrozenOpen = false;

function walletDateText(ts) {
    const d = mskParts(ts * 1e3);
    const pad = n => String(n).padStart(2, "0");
    return pad(d.d) + "." + pad(d.mo) + " " + pad(d.h) + ":" + pad(d.mi);
}

function walletPromoHTML() {
    return '<div class="wv-promo" id="wvPromo"><div class="wv-promo-head"><span class="wv-promo-ic"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/ВыСНами.lottie"), "", "") + "</span><b>Ввести промокод</b></div>" + '<div class="wv-promo-row"><input class="wv-promo-input" id="wvPromoInput" type="text" maxlength="32" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="Промокод" value="' + escapeHtml(walletPromoPrefill) + '">' + '<button class="wv-promo-btn" type="button" id="wvPromoBtn" data-action="wallet-promo-activate">Активировать</button></div><div id="wvPromoInfo"></div></div>';
}

function walletPromoCardHTML(d) {
    let h = '<div class="wv-promo-card"><div class="wv-promo-code">' + escapeHtml(d.code) + '</div><div class="wv-promo-reward">' + escapeHtml(d.reward) + "</div>";
    const extra = [];
    if (d.kind === "balance" && d.wagerMult > 0) extra.push("вейджер x" + fmtCoef(d.wagerMult));
    if (d.kind === "deposit") {
        if (d.minDeposit > 0) extra.push("пополнение от " + fmtCoef(d.minDeposit) + "⭐️");
        if (d.maxBonus > 0) extra.push("бонус до " + fmtCoef(d.maxBonus) + "⭐️");
        if (d.wagerMult > 0) extra.push("вейджер x" + fmtCoef(d.wagerMult));
        if (d.validHours > 0) extra.push("награда ждёт пополнения " + fmtCoef(d.validHours) + " ч");
    }
    if (d.expiresAt > 0) extra.push("действует до " + walletDateText(d.expiresAt));
    if (d.left != null) extra.push("осталось активаций: " + d.left);
    if (extra.length) h += '<div class="wv-promo-meta">' + extra.map(escapeHtml).join(" · ") + "</div>";
    if (d.conditions && d.conditions.length) h += '<div class="wv-promo-conds">' + d.conditions.map(c => "<span>" + escapeHtml(c) + "</span>").join("") + "</div>";
    if (d.used) h += '<div class="wv-promo-msg warn">Вы уже активировали этот промокод</div>';
    else if (d.status !== "active") h += '<div class="wv-promo-msg bad">' + escapeHtml(d.statusLabel) + "</div>";
    else if (d.missing && d.missing.length) h += '<div class="wv-promo-msg warn"><b>Чего не хватает:</b><br>' + d.missing.map(escapeHtml).join("<br>") + "</div>";
    else h += '<div class="wv-promo-msg ok">Условия выполнены — нажмите «Активировать»</div>';
    return h + "</div>";
}

function walletPromoPreview(code) {
    fetch("/api/wallet/promo/preview?code=" + encodeURIComponent(code)).then(r => r.json()).then(d => {
        const box = document.getElementById("wvPromoInfo");
        if (!box) return;
        box.dataset.kind = "preview";
        if (!d || !d.ok) {
            box.innerHTML = '<div class="wv-promo-msg bad">' + escapeHtml((d && d.message) || "Не удалось проверить промокод") + "</div>";
            return;
        }
        box.innerHTML = walletPromoCardHTML(d);
    }).catch(() => {});
}

function walletPromoInit() {
    const input = document.getElementById("wvPromoInput");
    if (!input) return;
    if (walletPromoPrefill) {
        const code = walletPromoPrefill;
        walletPromoPrefill = "";
        walletPromoPreview(code);
        setTimeout(() => {
            const box = document.getElementById("wvPromo");
            if (box && box.scrollIntoView) box.scrollIntoView({
                behavior: "smooth",
                block: "center"
            });
        }, 450);
    }
    input.addEventListener("keydown", e => {
        if (e.key === "Enter") {
            e.preventDefault();
            walletPromoActivate();
        }
    });
    input.addEventListener("input", () => {
        const box = document.getElementById("wvPromoInfo");
        if (box && box.dataset.kind) {
            box.dataset.kind = "";
            box.innerHTML = "";
        }
    });
}

function walletPromoSuccessHTML(d) {
    let sub = "";
    if (d.kind === "deposit") {
        sub = "Бонус придёт сам при следующем пополнении" + (d.minDeposit > 0 ? " от " + fmtCoef(d.minDeposit) + "⭐️" : "") + (d.expiresAt > 0 ? ", награда ждёт до " + walletDateText(d.expiresAt) : "") + (d.maxBonus > 0 ? ". Бонус до " + fmtCoef(d.maxBonus) + "⭐️" : "");
    } else if (d.wagerRequired > 0) {
        sub = "Для вывода отыграйте " + fmtCoef(d.wagerRequired) + "⭐️ (x" + fmtCoef(d.wagerMult) + ")";
    } else {
        sub = "Деньги уже на балансе";
    }
    return '<div class="wv-promo-ok">' + lazyImgTag(liteAsset("/lottie/images/УспешноДляУведомлений.lottie"), "", "wv-promo-ok-ic") + "<div><b>" + escapeHtml(d.text) + "</b><span>" + escapeHtml(sub) + "</span></div></div>";
}

function walletPromoActivate() {
    if (walletPromoBusy) return;
    const input = document.getElementById("wvPromoInput");
    const btn = document.getElementById("wvPromoBtn");
    if (!input || !btn) return;
    const code = input.value.trim();
    if (!code) {
        showToast("Введите промокод", "warning");
        return;
    }
    walletPromoBusy = true;
    btn.classList.add("busy");
    btn.disabled = true;
    fetch("/api/wallet/promo/activate", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            code: code
        })
    }).then(r => r.json()).then(d => {
        const box = document.getElementById("wvPromoInfo");
        if (d && d.ok) {
            input.value = "";
            if (typeof d.balance === "number") applyBalance(d.balance);
            if (box) {
                box.dataset.kind = "result";
                box.innerHTML = walletPromoSuccessHTML(d);
            }
            showToast(d.text, "success");
            haptic("notification", "success");
            loadWalletInfo();
            return;
        }
        const text = (d && d.message) || "Не удалось активировать промокод";
        const conditions = !!(d && d.code === "conditions");
        if (box) {
            box.dataset.kind = "result";
            box.innerHTML = '<div class="wv-promo-msg ' + (conditions ? "warn" : "bad") + '"><b>' + escapeHtml(text) + "</b>" + (d && d.lines && d.lines.length ? "<br>" + d.lines.map(escapeHtml).join("<br>") : "") + "</div>";
        }
        showToast(text, conditions ? "warning" : "error");
        haptic("notification", "error");
    }).catch(() => {
        showToast("Нет соединения, попробуйте ещё раз", "error");
    }).finally(() => {
        walletPromoBusy = false;
        const again = document.getElementById("wvPromoBtn");
        if (again) {
            again.classList.remove("busy");
            again.disabled = false;
        }
    });
}

function walletBoostsHTML(list) {
    if (!list || !list.length) return "";
    return '<div class="wv-boosts">' + list.map(b => '<div class="wv-boost"><b>' + escapeHtml(b.text) + "</b><span>" + (b.kind === "win" ? "сработает на первом выигрыше" : "сработает на следующем пополнении" + (b.minDeposit > 0 ? " от " + fmtCoef(b.minDeposit) + "⭐️" : "")) + (b.expiresAt > 0 ? " · до " + walletDateText(b.expiresAt) : " · без срока") + (b.maxBonus > 0 ? " · бонус до " + fmtCoef(b.maxBonus) + "⭐️" : "") + "</span></div>").join("") + "</div>";
}

function walletFrozenDetailsHTML(f) {
    let h = "";
    f.withdrawals.forEach(w => {
        h += '<div class="wv-fz-item"><span class="wv-fz-ic"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/Выводы.lottie"), "", "") + '</span><div class="wv-fz-t"><b>Заявка на вывод №' + w.id + '</b><span>' + escapeHtml(w.method) + " · " + escapeHtml(w.statusText) + " · " + walletDateText(w.createdAt) + '</span></div><div class="wv-fz-a">' + fmtNum(w.amount) + " ⭐️</div></div>";
    });
    f.checks.forEach(c => {
        h += '<div class="wv-fz-item"><span class="wv-fz-ic"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/ПредупреждениеОшибка.lottie"), "", "") + '</span><div class="wv-fz-t"><b>Чек ' + escapeHtml(c.code) + '</b><span>Заблокирован администрацией' + (c.multi ? " · активаций осталось " + c.left : "") + '</span></div><div class="wv-fz-a">' + fmtNum(c.amount) + " ⭐️</div></div>";
    });
    f.wagers.forEach(w => {
        h += '<div class="wv-fz-wager"><div class="wv-fz-wh"><span class="wv-fz-ic"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/ОборотБаланса.lottie"), "", "") + '</span><div class="wv-fz-t"><b>' + escapeHtml(w.title) + "</b><span>" + escapeHtml(w.reason) + '</span></div><div class="wv-fz-a">' + fmtNum(w.left) + ' ⭐️</div></div><div class="wv-fz-bar"><i style="width:' + w.pct + '%"></i></div><div class="wv-fz-cap"><span>Отыграно ' + fmtNum(w.done) + " из " + fmtNum(w.required) + " ⭐️</span><span>осталось " + fmtNum(w.left) + " ⭐️</span></div>" + (w.gamesRequired > 0 ? '<div class="wv-fz-cap"><span>Игр: ' + w.gamesDone + " из " + w.gamesRequired + "</span><span>осталось " + w.gamesLeft + "</span></div>" : "") + "</div>";
    });
    return h;
}

function walletFrozenHTML(f) {
    if (!f || !f.enabled) return "";
    const sum = f.total > 0 ? fmtNum(f.total) + " ⭐️" : "Отыграть " + fmtNum(f.wagerLeft) + " ⭐️";
    return '<div class="wv-frozen' + (walletFrozenOpen ? " open" : "") + '" id="wvFrozen"><div class="wv-frozen-head"><span class="wv-frozen-ic"><span class="skel-box"></span>' + lazyImgTag(liteAsset("/lottie/images/Баланс.lottie"), "", "") + "</span><b>Замороженный счёт:</b></div>" + '<button class="wv-frozen-row" type="button" data-action="wallet-frozen-toggle"><span class="wv-frozen-sum">' + sum + '</span><span class="wv-frozen-more">Подробнее <i>›</i></span>' + (f.total > 0 && f.wagerLeft > 0 ? '<span class="wv-frozen-sub">и ещё отыграть ' + fmtNum(f.wagerLeft) + " ⭐️</span>" : "") + "</button>" + '<div class="wv-frozen-body">' + walletFrozenDetailsHTML(f) + "</div></div>";
}

function loadWalletInfo() {
    if (!document.getElementById("wvFrozenSlot")) return;
    const token = ++walletInfoToken;
    fetch("/api/wallet/info?uid=" + CURRENT_UID).then(r => r.json()).then(d => {
        if (token !== walletInfoToken) return;
        const slot = document.getElementById("wvFrozenSlot");
        if (!slot || !d || !d.ok) return;
        slot.innerHTML = walletBoostsHTML(d.boosts) + walletFrozenHTML(d.frozen);
    }).catch(() => {});
}

function walletStatusHTML(r) {
    const s = r.status || "success";
    if (s === "pending" || s === "processing" || s === "active" || s === "creating") return '<div class="wv-status pending">⏳ ' + escapeHtml(r.statusText || "На рассмотрении") + "</div>";
    if (s === "rejected" || s === "failed" || s === "cancelled" || s === "expired") return '<div class="wv-status failed" title="' + escapeHtml(r.reason || "") + '">✕ ' + escapeHtml(r.statusText || "Отклонена") + "</div>";
    return '<div class="wv-status success">✓ Успешно</div>';
}

function walletAmountHTML(r, isOut) {
    const s = r.status || "success";
    if (s === "rejected" || s === "failed" || s === "cancelled" || s === "expired") return '<div class="wv-amount struck">' + fmtNum(r.amount) + "⭐️" + (r.refunded ? '<small>возвращено</small>' : "") + "</div>";
    return '<div class="wv-amount' + (s === "pending" || s === "processing" || s === "active" || s === "creating" ? " waiting" : "") + '">' + (isOut ? "−" : "+") + fmtNum(r.amount) + "⭐️</div>";
}

function renderWalletMain() {
    return '<div class="wv-topbar-brand">' + backPillHTML("wallet-exit") + '<div class="brand"><span class="brand-name text-skel" id="wvBrandName">Игрок</span><div class="brand-mark" id="wvBrandMark"><div class="skel-box"></div></div></div>' + "</div>" + '<h2 class="wv-title">Кошелек</h2>' + '<div class="wallet-balance-card">' + '<div class="wallet-balance-label">Баланс:</div>' + '<div class="wallet-balance-amount' + (userDataLoaded ? "" : " text-skel") + '">' + balanceAmountHTML(currentUser.balance, !userDataLoaded) + "</div>" + '<div class="wallet-balance-icon">' + (sourceCoinToggle && sourceCoinToggle.querySelector("img") ? '<img src="' + sourceCoinToggle.querySelector("img").src + '" alt="">' : "") + "</div>" + '<div class="wallet-brand-row"><div class="wallet-brand-mark" id="wvBalanceBrandMark"><div class="skel-box"></div></div><span class="text-skel" id="wvBalanceBrandName">Игрок</span></div>' + '<div class="wallet-actions">' + '<button class="wallet-action-btn" type="button" data-action="wallet-deposit">Пополнить</button>' + '<button class="wallet-action-btn" type="button" data-action="wallet-withdraw">Вывести</button>' + "</div>" + "</div>" + walletPromoHTML() + '<div id="wvFrozenSlot"></div>' + '<h3 class="wv-history-title">История транзакций</h3>' + '<div class="wv-filter-tabs" id="wvFilterTabs">' + '<button class="wv-filter-tab' + (walletHistoryFilter === "all" ? " active" : "") + '" type="button" data-wv-filter="all">Все</button>' + '<button class="wv-filter-tab' + (walletHistoryFilter === "deposit" ? " active" : "") + '" type="button" data-wv-filter="deposit">Депозиты</button>' + '<button class="wv-filter-tab' + (walletHistoryFilter === "withdrawal" ? " active" : "") + '" type="button" data-wv-filter="withdrawal">Выводы</button>' + "</div>" + '<div class="wv-table">' + '<div class="wv-table-head"><div>Тип транзакции</div><div>Дата</div><div>Статус</div><div style="text-align:right;">Сумма</div></div>' + '<div class="wv-table-body" id="wvHistoryBody">' + walletHistorySkeletonHTML() + "</div>" + "</div>" + '<div class="wv-pagination">' + '<button class="wv-page-btn" type="button" id="wvPagePrev">‹</button>' + '<button class="wv-page-label wv-page-label-btn" type="button" id="wvPageLabel">1 из 1</button>' + '<button class="wv-page-btn" type="button" id="wvPageNext">›</button>' + "</div>";
}

function renderWallet() {
    if (bottomNav) bottomNav.style.display = "";
    const appEl = document.querySelector(".app");
    if (appEl) appEl.classList.remove("no-nav");
    wvBody.innerHTML = renderWalletMain();
    applyUserToUI();
    walletHistoryPage = 1;
    loadWalletHistory();
    walletPromoInit();
    loadWalletInfo();
    window.scrollTo({
        top: 0,
        behavior: "instant"
    });
}

