let depositState = depositFreshState();

function depositStopPolling() {
    if (depositState.pollTimer) {
        clearInterval(depositState.pollTimer);
        depositState.pollTimer = null;
    }
    if (depositState.tickTimer) {
        clearInterval(depositState.tickTimer);
        depositState.tickTimer = null;
    }
    if (depositState.resumeHandler) {
        document.removeEventListener("visibilitychange", depositState.resumeHandler);
        depositState.resumeHandler = null;
    }
    depositState.sbpRequestId = null;
}

function depositOpenPayLink(url) {
    if (!url) return;
    const isTelegramLink = /^https?:\/\/(www\.)?t\.me\//i.test(url);
    if (tgWebApp && isTelegramLink && tgWebApp.openTelegramLink) {
        tgWebApp.openTelegramLink(url);
        return;
    }
    if (tgWebApp && tgWebApp.openLink) {
        tgWebApp.openLink(url, {
            try_instant_view: false
        });
        return;
    }
    window.open(url, "_blank");
}

function depositCopyText(text) {
    const done = () => {
        showToast("Скопировано", "success");
        haptic("notification", "success");
    };
    const fallback = () => {
        try {
            const ta = document.createElement("textarea");
            ta.value = text;
            ta.style.position = "fixed";
            ta.style.opacity = "0";
            document.body.appendChild(ta);
            ta.focus();
            ta.select();
            document.execCommand("copy");
            document.body.removeChild(ta);
            done();
        } catch (e) {
            showToast("Не удалось скопировать", "error");
        }
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(done).catch(fallback);
    } else {
        fallback();
    }
}

function depositFmt4(v) {
    const n = Math.round(Number(v) * 1e4) / 1e4;
    const parts = String(Math.abs(n)).split(".");
    return (n < 0 ? "-" : "") + parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".") + (parts[1] ? "." + parts[1] : "");
}

function depositCoinName(code) {
    const c = String(code || "").toUpperCase();
    return c === "TON" || c === "TONCOIN" ? "GRAM" : c;
}

function depositCoinList(coins) {
    return (coins || []).map(depositCoinName).join(", ");
}

function depositPromoCoin(code) {
    const c = String(code || "").toUpperCase();
    return c === "TONCOIN" || c === "GRAM" ? "TON" : c;
}

function depositPromoMethodInfo(method) {
    const p = depositState.promo;
    if (!p || !p.active) return null;
    return (p.methods || []).find(m => m.client === method) || null;
}

function depositPromoBonus(amount) {
    const p = depositState.promo;
    const dep = Number(amount) || 0;
    if (!p || !p.active || !(p.percent > 0) || !(dep > 0)) return null;
    if (p.minDeposit > 0 && dep + 1e-9 < p.minDeposit) return {
        below: true,
        min: p.minDeposit
    };
    let bonus = Math.round(dep * p.percent / 100 * 1e4) / 1e4;
    let capped = false;
    if (p.maxBonus > 0 && bonus > p.maxBonus) {
        bonus = Math.round(p.maxBonus * 1e4) / 1e4;
        capped = true;
    }
    if (!(bonus > 0)) return null;
    const total = Math.round((dep + bonus) * 1e4) / 1e4;
    return {
        bonus: bonus,
        total: total,
        capped: capped,
        wager: p.wagerMult > 0 ? total * p.wagerMult : 0
    };
}

function depositPromoTermsText(m) {
    const p = depositState.promo;
    const parts = [];
    if (m && m.coins && m.coins.length) parts.push("монеты: " + depositCoinList(m.coins));
    if (p.minDeposit > 0) parts.push("от " + depositFmt4(p.minDeposit) + "⭐️");
    if (p.maxBonus > 0) parts.push("бонус не больше " + depositFmt4(p.maxBonus) + "⭐️");
    if (p.wagerMult > 0) parts.push("вейджер ×" + depositFmt4(p.wagerMult) + " от суммы с бонусом");
    return parts.join(" · ");
}

function depositTagMethodInfo(method) {
    const t = depositState.tagPromo;
    if (!t) return null;
    return (t.methods || []).find(m => m.client === method) || null;
}

function depositTagBonus(amount) {
    const t = depositState.tagPromo;
    const dep = Number(amount) || 0;
    if (!t || !(t.percent > 0) || !(dep > 0)) return null;
    if (t.minDeposit > 0 && dep + 1e-9 < t.minDeposit) return {
        below: true,
        min: t.minDeposit
    };
    let bonus = Math.round(dep * t.percent / 100 * 1e4) / 1e4;
    let capped = false;
    if (t.maxBonus > 0 && bonus > t.maxBonus) {
        bonus = Math.round(t.maxBonus * 1e4) / 1e4;
        capped = true;
    }
    if (!(bonus > 0)) return null;
    const total = Math.round((dep + bonus) * 1e4) / 1e4;
    return {
        bonus: bonus,
        total: total,
        capped: capped,
        wager: t.wagerMult > 0 ? total * t.wagerMult : 0
    };
}

function depositTagTermsText() {
    const t = depositState.tagPromo;
    const parts = [];
    if (t.wagerMult > 0) parts.push("вейджер ×" + depositFmt4(t.wagerMult) + " от суммы с бонусом");
    if (t.minDeposit > 0) parts.push("от " + depositFmt4(t.minDeposit) + "⭐️");
    if (t.maxBonus > 0) parts.push("бонус не больше " + depositFmt4(t.maxBonus) + "⭐️");
    return parts.join(" · ");
}

function depositTagBannerHTML() {
    const t = depositState.tagPromo;
    if (!t) return "";
    const names = (t.methods || []).filter(m => m.client).map(m => m.label).join(", ");
    const terms = depositTagTermsText();
    let state = "";
    if (t.ok === true) state = '<div class="deposit-promo-text">Приписка у вас стоит — бонус начислится сам.</div>';
    else if (t.ok === false) state = '<div class="deposit-promo-text">Условия: ' + escapeHtml(t.conditions || "приписка в имени") + (t.reasons && t.reasons.length ? "<br>Чего не хватает: " + t.reasons.map(escapeHtml).join("; ") : "") + "</div>";
    return '<div class="deposit-promo deposit-promo-tag"><div class="deposit-promo-title">' + depositPromoIcon() + "<span>С припиской @" + escapeHtml(t.bot) + " +" + depositFmt4(t.percent) + "% к депозитам!</span></div>" + (names ? '<div class="deposit-promo-text">· ' + escapeHtml(names) + "</div>" : "") + (terms ? '<div class="deposit-promo-text">' + escapeHtml(terms) + "</div>" : "") + state + "</div>";
}

function depositTagPreviewInfo(amount) {
    const r = depositTagBonus(amount);
    if (!r) return null;
    if (r.below) return {
        text: "С припиской — от " + depositFmt4(r.min) + "⭐️",
        off: true
    };
    return {
        text: "С припиской +" + depositFmt4(r.bonus) + "⭐️ · на баланс " + depositFmt4(r.total) + "⭐️" + (r.capped ? " (максимальный бонус)" : ""),
        off: false
    };
}

function depositTagPreviewHTML(amount) {
    if (!depositState.tagPromo) return "";
    const info = depositTagPreviewInfo(amount);
    return '<div class="deposit-promo-bonus' + (info ? "" : " hidden") + (info && info.off ? " off" : "") + '" id="depositTagBonus">' + depositPromoIcon() + '<span id="depositTagBonusText">' + (info ? escapeHtml(info.text) : "") + "</span></div>";
}

function depositTagWaitingHTML() {
    const m = depositTagMethodInfo(depositState.method);
    if (!m) return "";
    const r = depositTagBonus(depositState.amount);
    if (!r || r.below) return "";
    const t = depositState.tagPromo;
    const both = !!depositPromoWaitingHTML();
    return '<div class="deposit-invoice-promo">' + depositPromoIcon() + "<span>С припиской +" + depositFmt4(t.percent) + "%: +" + depositFmt4(r.bonus) + "⭐️ · на баланс " + depositFmt4(r.total) + "⭐️" + (r.wager > 0 ? " · вейджер ×" + depositFmt4(t.wagerMult) : "") + (both ? " · начисляется один бонус, выгоднее" : "") + "</span></div>";
}

