function renderDepositStep() {
    const body = document.getElementById("depositPageBody");
    if (!body) return;
    if (depositState.step === "main") {
        body.innerHTML = depositMainStepHTML();
        setTimeout(() => {
            const el = document.getElementById("depositAmountInput");
            if (el) el.focus();
        }, 50);
    } else if (depositState.step === "currency") {
        body.innerHTML = depositCurrencyStepHTML();
    } else if (depositState.step === "tonkeeper") {
        body.innerHTML = depositTonkeeperStepHTML();
    } else if (depositState.step === "waiting") {
        body.innerHTML = depositWaitingStepHTML();
    } else if (depositState.step === "sbpFail") {
        body.innerHTML = depositSbpFailStepHTML();
    } else if (depositState.step === "cancelConfirm") {
        body.innerHTML = depositCancelConfirmStepHTML();
    } else if (depositState.step === "success") {
        body.innerHTML = depositSuccessStepHTML();
    }
}

