function depositWagerNoteHTML() {
    const w = depositState.wager;
    if (!w || !(w.mult > 0) || !(w.amount > 0)) return "";
    return '<div class="deposit-success-wager">Вейджер ×' + fmtNum(w.mult) + ": отыграйте " + fmtNum(w.amount) + "⭐️ ставками, чтобы выводить средства</div>";
}

function depositStartPolling(checkFn) {
    depositStopPolling();
    let finishing = false;
    const handle = (data, last) => {
        if (data && data.ok && data.paid) {
            depositStopPolling();
            depositState.creditedAmount = data.amount != null ? data.amount : depositState.amount;
            depositState.wager = data.wager || null;
            depositState.creditPromo = data.promo || null;
            if (typeof data.balance === "number") applyBalance(data.balance);
            haptic("notification", "success");
            depositState.step = "success";
            renderDepositStep();
            return;
        }
        if (data && data.ok && data.status === "credit_failed") {
            depositSbpFail("credit_failed");
            return;
        }
        if (data && data.ok && data.status === "error") {
            depositSbpFail("error", data.error);
            return;
        }
        if (data && data.ok && (data.status === "expired" || data.status === "cancelled") || last) depositInvoiceExpired();
    };
    const tick = () => {
        if (finishing) return;
        checkFn().then(data => handle(data, false)).catch(() => {});
    };
    const deadline = depositState.invoiceDeadline;
    if (deadline) {
        depositState.tickTimer = setInterval(() => {
            const el = document.getElementById("depositInvoiceTimer");
            if (el) el.textContent = depositInvoiceTimerText();
            if (!finishing && Date.now() >= deadline) {
                finishing = true;
                setTimeout(() => {
                    checkFn().then(data => handle(data, true)).catch(() => depositInvoiceExpired());
                }, 2500);
            }
        }, 1e3);
    }
    depositState.pollTimer = setInterval(tick, 4e3);
    depositState.resumeHandler = () => {
        if (!document.hidden) tick();
    };
    document.addEventListener("visibilitychange", depositState.resumeHandler);
}

function depositSbpFail(kind, message) {
    depositStopPolling();
    const base = DEPOSIT_SBP_FAIL_TEXTS[kind] || DEPOSIT_SBP_FAIL_TEXTS.error;
    depositState.sbpFail = {
        title: base.title,
        text: kind === "error" && message ? message : base.text
    };
    depositState.step = "sbpFail";
    haptic("notification", "error");
    renderDepositStep();
}

function depositSbpApply(data) {
    if (!data || !data.ok) {
        depositSbpFail("error", data && data.error);
        return;
    }
    if (data.state === "creating") return;
    if (data.state === "paid") {
        depositStopPolling();
        depositState.creditedAmount = data.amount != null ? data.amount : depositState.amount;
        depositState.wager = data.wager || null;
        depositState.creditPromo = data.promo || null;
        if (typeof data.balance === "number") applyBalance(data.balance);
        haptic("notification", "success");
        depositState.step = "success";
        renderDepositStep();
        return;
    }
    if (data.state === "pending" || data.state === "processing") {
        const prev = depositState.sbpInvoice;
        depositState.sbpInvoice = data;
        depositState.sbpDeadline = Date.now() + (data.expiresIn || 0) * 1e3;
        if (!prev || prev.state !== data.state) {
            renderDepositStep();
            if (!depositState.tickTimer) {
                depositState.tickTimer = setInterval(() => {
                    const el = document.getElementById("depositSbpTimer");
                    if (el) el.textContent = depositSbpTimerText();
                }, 1e3);
            }
        }
        return;
    }
    depositSbpFail(data.state, data.error);
}

function depositSbpStartPolling(requestId) {
    depositStopPolling();
    depositState.sbpRequestId = requestId;
    let busy = false;
    depositState.pollTimer = setInterval(() => {
        if (busy) return;
        busy = true;
        fetch("/api/deposit/sbp/status?uid=" + CURRENT_UID + "&requestId=" + requestId).then(r => r.json()).then(data => {
            if (depositState.sbpRequestId === requestId) depositSbpApply(data);
        }).catch(() => {}).then(() => {
            busy = false;
        });
    }, 2e3);
}

function depositCreateSbp() {
    depositState.sbpInvoice = null;
    depositState.sbpFail = null;
    depositState.step = "waiting";
    renderDepositStep();
    fetch("/api/deposit/sbp/create", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            amount: depositState.amount
        })
    }).then(r => r.json()).then(data => {
        if (depositState.method !== "sbp" || depositState.step !== "waiting") return;
        if (!data || !data.ok) {
            showToast(data && data.error || "Не удалось создать счёт", "error");
            depositState.step = "main";
            renderDepositStep();
            return;
        }
        depositSbpStartPolling(data.requestId);
    }).catch(() => {
        if (depositState.method !== "sbp" || depositState.step !== "waiting") return;
        showToast("Ошибка сети", "error");
        depositState.step = "main";
        renderDepositStep();
    });
}

