function depositCreateStars() {
    fetch("/api/deposit/stars/create", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            amount: depositState.amount
        })
    }).then(r => r.json()).then(data => {
        if (!data || !data.ok) {
            showToast(data && data.error || "Не удалось создать счёт", "error");
            depositState.step = "main";
            renderDepositStep();
            return;
        }
        const link = data.invoiceLink;
        depositState.invoiceId = data.invoiceId;
        depositState.invoiceDeadline = Date.now() + data.expiresIn * 1000;
        const check = () => fetch("/api/deposit/stars/status?invoiceId=" + encodeURIComponent(data.invoiceId)).then(r => r.json());
        depositStartPolling(check);
        depositState.step = "waiting";
        renderDepositStep();
        if (tgWebApp && tgWebApp.openInvoice) {
            tgWebApp.openInvoice(link, status => {
                if (status === "paid") {
                    check().then(result => {
                        if (result && result.ok && result.paid) {
                            depositState.creditedAmount = result.creditedAmount;
                            depositState.step = "success";
                            depositStopPolling();
                            renderDepositStep();
                            loadUserState();
                        }
                    }).catch(() => {});
                } else if (status === "cancelled" || status === "failed") {
                    depositState.step = "main";
                    renderDepositStep();
                }
            });
        } else {
            depositOpenPayLink(link);
        }
    }).catch(() => {
        showToast("Ошибка сети", "error");
        depositState.step = "main";
        renderDepositStep();
    });
}

function depositShowTonkeeper() {
    depositState.step = "tonkeeper";
    renderDepositStep();
    fetch("/api/deposit/tonkeeper/info?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (data && data.ok) {
            depositState.tonkeeperInfo = data;
            if (depositState.step === "tonkeeper") renderDepositStep();
        } else {
            showToast(data && data.error || "Не удалось загрузить данные", "error");
        }
    }).catch(() => showToast("Ошибка сети", "error"));
}

function depositConfirmCancel() {
    const method = depositState.method;
    const invoiceId = depositState.invoiceId;
    depositStopPolling();
    const finish = () => {
        haptic("notification", "warning");
        showToast("Счёт отменён", "error");
        depositState.invoiceId = null;
        depositState.payUrl = null;
        depositState.step = method === "xrocket" ? "currency" : method === "tonkeeper" ? "tonkeeper" : "main";
        renderDepositStep();
    };
    if ((method === "cryptobot" || method === "xrocket") && invoiceId) {
        fetch("/api/deposit/" + method + "/cancel", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                uid: CURRENT_UID,
                invoiceId: invoiceId
            })
        }).then(response => response.json()).then(data => {
            if (!data || !data.ok) throw new Error(data && data.error || "Не удалось отменить счёт");
            if (data.paid) {
                depositState.creditedAmount = data.creditedAmount;
                depositState.step = "success";
                renderDepositStep();
                loadUserState();
            } else finish();
        }).catch(error => {
            showToast(error.message || "Проверьте статус оплаты", "error");
            depositStartPolling(() => fetch("/api/deposit/" + method + "/status?invoiceId=" + encodeURIComponent(invoiceId)).then(response => response.json()));
        });
    } else if (method === "laveshka" && invoiceId) {
        fetch("/api/deposit/laveshka/cancel", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                paymentId: invoiceId
            })
        }).then(r => r.json()).then(data => {
            if (data && data.status === "paid") {
                showToast("Платёж уже оплачен, зачисляем…", "success");
                depositState.step = "waiting";
                renderDepositStep();
                depositStartPolling(depositLavePollFn());
                return;
            }
            if (data && data.ok === false && data.error) {
                showToast(data.error, "error");
                depositState.step = "waiting";
                renderDepositStep();
                depositStartPolling(depositLavePollFn());
                return;
            }
            finish();
        }).catch(finish);
    } else if (method === "xrocket" && invoiceId) {
        fetch("/api/deposit/xrocket/cancel", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                uid: CURRENT_UID,
                invoiceId: invoiceId
            })
        }).then(finish).catch(finish);
    } else {
        finish();
    }
}

