    const n = c.networks.find(x => x.network === wdState.network);
    return '<div class="deposit-hint center">Вывод ' + escapeHtml(c.display) + " · " + escapeHtml(n.display) + '</div><div class="deposit-warning">Внимательно проверьте адрес! Если он неверный или относится к другой сети — средства будут потеряны безвозвратно. Комиссия сети ' + wdNum(n.fee, 8) + " " + escapeHtml(c.display) + " вычитается из указанной суммы.</div>" + '<div class="wd-field-label">Адрес кошелька</div><input class="wd-input" id="wdAddressInput" type="text" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Адрес в сети ' + escapeHtml(n.display) + '" value="' + escapeHtml(wdState.addressRaw) + '"><div class="wd-field-label">Сумма списания в ' + escapeHtml(c.display) + '</div><div class="deposit-amount-row"><input class="deposit-amount-input wd-amount-sm" id="wdAmountInput" type="text" inputmode="decimal" placeholder="0" autocomplete="off" value="' + escapeHtml(wdState.amountRaw) + "\"></div>" + wdAmountRangeHTML(n.min, n.max, c.decimals, c.display) + '<div class="wd-approx" id="wdApprox"></div><div class="deposit-error" id="wdError"></div><div class="wd-quick"><button class="deposit-quick-btn" type="button" data-wd="fill-min">Минимум</button><button class="deposit-quick-btn" type="button" data-wd="fill-max">Максимум</button></div><button class="gv-start-btn" type="button" data-wd="quote">Продолжить</button>';
