function openFair() {
    const roundIdAtOpen = currentRoundId;
    gvFairId.textContent = currentRoundId;
    gvFairId.classList.remove("text-skel");
    gvFairResult.textContent = currentPlayed ? currentSeed : "Игра не завершена";
    if (currentPlayed) {
        gvFairNote.style.display = "";
        gvFairLink.style.display = "";
        gvFairLink.href = "https://emn178.github.io/online-tools/sha256.html?input=" + encodeURIComponent(currentSeed);
    } else {
        gvFairNote.style.display = "none";
        gvFairLink.style.display = "none";
    }
    gvFairHash.textContent = currentHash || "Вычисление…";
    if (!currentHash) {
        sha256Hex(currentSeed).then(h => {
            if (roundIdAtOpen !== currentRoundId) return;
            currentHash = h;
            gvFairHash.textContent = h;
        });
    }
    gvFairModal.classList.add("active");
}

(function watchFairState() {
    const modal = document.getElementById("gvFairModal");
    const res = document.getElementById("gvFairResult");
    if (!modal || !res) return;

    function sync() {
        const pending = !!res.querySelector(".fair-result-note") || /не завершена/i.test(res.textContent || "");
        modal.dataset.fairState = pending ? "pending" : "done";
    }
    new MutationObserver(sync).observe(res, {
        childList: true,
        subtree: true,
        characterData: true
    });
    sync();
})();

