document.getElementById("myGamesList").addEventListener("click", e => {
    const crashRoundTrigger = e.target.closest("[data-crash-round]");
    if (crashRoundTrigger) {
        openCrashRoundModal(crashRoundTrigger.dataset.crashRound);
        return;
    }
    const minesRoundTrigger = e.target.closest("[data-mines-round]");
    if (minesRoundTrigger) {
        openMinesRoundModal(minesRoundTrigger.dataset.minesRound);
        return;
    }
    const coinflipRoundTrigger = e.target.closest("[data-coinflip-round]");
    if (coinflipRoundTrigger) {
        openCoinflipRoundModal(coinflipRoundTrigger.dataset.coinflipRound);
        return;
    }
    const clawRoundTrigger = e.target.closest("[data-claw-round]");
    if (clawRoundTrigger) {
        openClawRoundModal(clawRoundTrigger.dataset.clawRound);
        return;
    }
    const baccaratRoundTrigger = e.target.closest("[data-baccarat-round]");
    if (baccaratRoundTrigger && window.baccaratKit) {
        window.baccaratKit.openRound(baccaratRoundTrigger.dataset.baccaratRound);
        return;
    }
    const kenoRoundTrigger = e.target.closest("[data-keno-round]");
    if (kenoRoundTrigger) {
        openKenoRoundModal(kenoRoundTrigger.dataset.kenoRound);
        return;
    }
    const hiloRoundTrigger = e.target.closest("[data-hilo-round]");
    if (hiloRoundTrigger) {
        openHiloRoundModal(hiloRoundTrigger.dataset.hiloRound);
        return;
    }
    const redblackRoundTrigger = e.target.closest("[data-redblack-round]");
    if (redblackRoundTrigger) {
        openRedBlackRoundModal(redblackRoundTrigger.dataset.redblackRound);
        return;
    }
    const ladderRoundTrigger = e.target.closest("[data-ladder-round]");
    if (ladderRoundTrigger) {
        openLadderRoundModal(ladderRoundTrigger.dataset.ladderRound);
        return;
    }
    const blackjackRoundTrigger = e.target.closest("[data-blackjack-round]");
    if (blackjackRoundTrigger) {
        openBlackjackRoundModal(blackjackRoundTrigger.dataset.blackjackRound);
        return;
    }
    const blackjackPvpRoundTrigger = e.target.closest("[data-blackjack-pvp-round]");
    if (blackjackPvpRoundTrigger) {
        openBlackjackPvpRoundModal(blackjackPvpRoundTrigger.dataset.blackjackPvpRound);
        return;
    }
    const upgradeRoundTrigger = e.target.closest("[data-upgrade-round]");
    if (upgradeRoundTrigger) {
        openUpgradeRoundModal(upgradeRoundTrigger.dataset.upgradeRound);
        return;
    }
    const rouletteRoundTrigger = e.target.closest("[data-roulette-round]");
    if (rouletteRoundTrigger) {
        openRouletteRoundModal(rouletteRoundTrigger.dataset.rouletteRound);
        return;
    }
    const wheelRoundTrigger = e.target.closest("[data-wheel-round]");
    if (wheelRoundTrigger) {
        openWheelRoundModal(wheelRoundTrigger.dataset.wheelRound);
        return;
    }
    const pvpRoundTrigger = e.target.closest("[data-pvp-round]");
    if (pvpRoundTrigger) {
        const g = pvpRoundTrigger.dataset.pvpRoundGame;
        if (!g || g === "dice") openPvpDiceRoundModal(pvpRoundTrigger.dataset.pvpRound);
        else if (g === "blackjack") openBlackjackPvpRoundModal(pvpRoundTrigger.dataset.pvpRound);
        else openPvpGenRoundModal(g, pvpRoundTrigger.dataset.pvpRound);
        return;
    }
});

