const OFFLINE_CHECK_NORMAL_MS = 3e3;

const OFFLINE_CHECK_CRASH_MS = 1400;

const OFFLINE_CHECK_SHOWN_MS = 1e3;

const OFFLINE_FETCH_TIMEOUT_MS = 4e3;

const OFFLINE_RECONNECTED_HOLD_MS = 1200;

const OFFLINE_CONFIRM_STREAK = 2;

const offlineModal = document.getElementById("offlineModal");

const offlineIcon = document.getElementById("offlineIcon");

const offlineStatus = document.getElementById("offlineStatus");

const offlineStatusValue = document.getElementById("offlineStatusValue");

if (offlineIcon) setLottieCanvasSrc(offlineIcon, "/lottie/images/ОтказаноОшибка.lottie");

let offlineModalShown = false;

let offlineCheckTimer = null;

let offlineCheckInFlight = false;

let offlineConfirmStreak = 0;

function offlineCheckIntervalMs() {
    if (offlineModalShown) return OFFLINE_CHECK_SHOWN_MS;
    return currentGame === "краш" ? OFFLINE_CHECK_CRASH_MS : OFFLINE_CHECK_NORMAL_MS;
}

function showOfflineModal() {
    offlineConfirmStreak = 0;
    if (offlineModalShown) return;
    offlineModalShown = true;
    if (offlineStatus) offlineStatus.classList.remove("online");
    if (offlineStatusValue) offlineStatusValue.textContent = "ОТКЛЮЧЕНО";
    if (offlineModal) offlineModal.classList.add("active");
    document.body.classList.add("offline-locked");
}

function showReconnectedThenHide() {
    if (offlineStatus) offlineStatus.classList.add("online");
    if (offlineStatusValue) offlineStatusValue.textContent = "ПОДКЛЮЧЕНО";
    setTimeout(() => {
        offlineModalShown = false;
        offlineConfirmStreak = 0;
        if (offlineModal) offlineModal.classList.remove("active");
        document.body.classList.remove("offline-locked");
    }, OFFLINE_RECONNECTED_HOLD_MS);
}

function pingServer() {
    const controller = typeof AbortController !== "undefined" ? new AbortController : null;
    const timeoutId = controller ? setTimeout(() => controller.abort(), OFFLINE_FETCH_TIMEOUT_MS) : null;
    return fetch("/api/ping", {
        cache: "no-store",
        signal: controller ? controller.signal : undefined
    }).then(r => {
        if (timeoutId) clearTimeout(timeoutId);
        if (!r.ok) throw new Error("bad status");
        return r.json();
    }).then(data => {
        if (data && data.banned) {
            closeBlockedApp();
            return true;
        }
        if (data && typeof data.gv === "number") gameSwitchSeen(data.gv);
        if (data && typeof data.ov === "number") ocSeen(data.ov);
        if (data && typeof data.tv === "string") siteThemeSeen(data.tv);
        return !!(data && data.ok);
    }).catch(() => {
        if (timeoutId) clearTimeout(timeoutId);
        return false;
    });
}

let offlineResumeGuardUntil = 0;

let offlineFailStreak = 0;

function checkConnection() {
    if (blockedAppClosed || offlineCheckInFlight || document.hidden) return;
    if (typeof navigator !== "undefined" && navigator.onLine === false && Date.now() >= offlineResumeGuardUntil) {
        showOfflineModal();
        return;
    }
    offlineCheckInFlight = true;
    pingServer().then(ok => {
        offlineCheckInFlight = false;
        if (ok) {
            offlineFailStreak = 0;
            offlineConfirmStreak += 1;
            if (offlineModalShown && offlineConfirmStreak >= OFFLINE_CONFIRM_STREAK) {
                showReconnectedThenHide();
            }
        } else if (!document.hidden && Date.now() >= offlineResumeGuardUntil) {
            offlineFailStreak += 1;
            if (offlineFailStreak >= 2) {
                showOfflineModal();
            } else {
                setTimeout(checkConnection, 1200);
            }
        } else {
            setTimeout(checkConnection, 1500);
        }
    });
}

function scheduleOfflineCheck() {
    if (offlineCheckTimer) clearTimeout(offlineCheckTimer);
    offlineCheckTimer = setTimeout(() => {
        checkConnection();
        scheduleOfflineCheck();
    }, offlineCheckIntervalMs());
}

window.addEventListener("offline", () => {
    if (document.hidden || Date.now() < offlineResumeGuardUntil) return;
    offlineFailStreak = 1;
    setTimeout(checkConnection, 800);
});

window.addEventListener("online", checkConnection);

document.addEventListener("visibilitychange", () => {
    if (document.hidden) return;
    offlineResumeGuardUntil = Date.now() + 4000;
    offlineFailStreak = 0;
    offlineConfirmStreak = 0;
    setTimeout(checkConnection, 1500);
});

checkConnection();

scheduleOfflineCheck();

document.getElementById("fairCheckGames").addEventListener("click", e => {
    const chip = e.target.closest(".fair-check-game-chip");
    if (!chip) return;
    const game = chip.dataset.game;
    fairCheckSelectedGame = fairCheckSelectedGame === game ? null : game;
    document.querySelectorAll("#fairCheckGames .fair-check-game-chip").forEach(b => {
        b.classList.toggle("active", b.dataset.game === fairCheckSelectedGame);
    });
    const isEmoji = EMOJI_GAME_KEYS.includes(fairCheckSelectedGame);
    const isPvp = fairCheckSelectedGame === "pvp";
    fairCheckPfFields.style.display = isEmoji || isPvp ? "none" : "";
    fairCheckEmojiFields.style.display = isEmoji ? "" : "none";
    fairCheckPvpFields.style.display = isPvp ? "" : "none";
    updateFairCheckSubmitState();
});

function updateFairCheckSubmitState() {
    if (fairCheckSelectedGame === "pvp") {
        fairCheckSubmitBtn.disabled = !fairCheckPvpIdInput.value.trim();
        return;
    }
    if (EMOJI_GAME_KEYS.includes(fairCheckSelectedGame)) {
        fairCheckSubmitBtn.disabled = !fairCheckEmojiIdInput.value.trim();
        return;
    }
    const filled = [fairCheckUidInput.value, fairCheckHashInput.value, fairCheckSeedInput.value].filter(v => v.trim()).length;
    fairCheckSubmitBtn.disabled = filled < 2;
}

[fairCheckUidInput, fairCheckHashInput, fairCheckSeedInput, fairCheckEmojiIdInput, fairCheckPvpIdInput].forEach(inp => {
    inp.addEventListener("input", updateFairCheckSubmitState);
});

function openFairCheckRoundBySource(source, roundId) {
    if (source === "mines_bot" || source === "mines_app") {
        openMinesRoundModal(roundId);
        return true;
    }
    if (source === "ladder_bot" || source === "ladder_app") {
        openLadderRoundModal(roundId);
        return true;
    }
    if (source === "crash") {
        openCrashRoundModal(roundId);
        return true;
    }
    if (source === "upgrade") {
        openUpgradeRoundModal(roundId);
        return true;
    }
    if (source === "roulette") {
        openRouletteRoundModal(roundId);
        return true;
    }
    if (source === "wheel") {
        openWheelRoundModal(roundId);
        return true;
    }
    if (source === "arena") {
        window.arenaOpenRound(roundId);
        return true;
    }
    if (source === "escape") {
        window.escapeOpenRound(roundId);
        return true;
    }
    if (source === "race") {
        window.raceOpenRound(roundId);
        return true;
    }
    if (source === "bomb" || source === "sumo") {
        window.potGames[source].openRound(roundId);
        return true;
    }
    if (source === "blackjack") {
        openBlackjackRoundModal(roundId);
        return true;
    }
    if (source === "keno") {
        openKenoRoundModal(roundId);
        return true;
    }
    if (source === "coinflip") {
        openCoinflipRoundModal(roundId);
        return true;
    }
    if (source === "claw") {
        openClawRoundModal(roundId);
        return true;
    }
    if (source === "baccarat" && window.baccaratKit) {
        window.baccaratKit.openRound(roundId);
        return true;
    }
    if (source === "hilo") {
        openHiloRoundModal(roundId);
        return true;
    }
    if (source === "redblack") {
        openRedBlackRoundModal(roundId);
        return true;
    }
    return false;
}

function fairCheckLoadingSkeletonHTML() {
    return '<div class="fair-check-loading">' + '<span class="skel-box fair-check-loading-ring"></span>' + '<span class="text-skel fair-check-loading-line" style="width:70%;">Ищем раунд</span>' + '<span class="text-skel fair-check-loading-line" style="width:50%;">Ищем раунд</span>' + "</div>";
}

fairCheckSubmitBtn.addEventListener("click", () => {
    if (fairCheckSubmitBtn.disabled) return;
    fairCheckSubmitBtn.disabled = true;
    fairCheckResultEl.innerHTML = fairCheckLoadingSkeletonHTML();
    if (fairCheckSelectedGame === "pvp") {
        const roomId = fairCheckPvpIdInput.value.trim().toUpperCase();
        fetch("/api/pvp/search?id=" + encodeURIComponent(roomId)).then(r => r.json()).then(data => {
            if (!data || !data.ok) {
                fairCheckResultEl.innerHTML = '<div class="fair-check-empty">Игра не найдена. Проверьте UID раунда.</div>';
                return;
            }
            const g = data.game;
            if (!g || g === "dice") openPvpDiceRoundModal(data.roomId);
            else if (g === "blackjack") openBlackjackPvpRoundModal(data.roomId);
            else openPvpGenRoundModal(g, data.roomId);
            fairCheckResultEl.innerHTML = "";
            closeFairCheckModal();
        }).catch(() => {
            fairCheckResultEl.innerHTML = '<div class="fair-check-empty">Не удалось выполнить проверку</div>';
        }).finally(() => {
            updateFairCheckSubmitState();
        });
        return;
    }
    if (EMOJI_GAME_KEYS.includes(fairCheckSelectedGame)) {
        const gameKey = fairCheckSelectedGame;
        const roundId = fairCheckEmojiIdInput.value.trim();
        fetch("/api/emoji/round?" + new URLSearchParams({
            game: gameKey,
            id: roundId
        }).toString()).then(r => r.json()).then(data => {
            if (!data || !data.ok) {
                fairCheckResultEl.innerHTML = '<div class="fair-check-empty">Раунд не найден. Проверьте ID игры.</div>';
                return;
            }
            let meta = {};
            try {
                meta = JSON.parse(data.meta || "{}");
            } catch (err) {}
            const r = {
                bet: data.bet,
                win_amount: data.winAmount,
                result: data.result,
                created_at: data.createdAt
            };
            openEmojiRoundModal(gameKey, r, meta, data.displayName);
            fairCheckResultEl.innerHTML = "";
            closeFairCheckModal();
        }).catch(() => {
            fairCheckResultEl.innerHTML = '<div class="fair-check-empty">Не удалось выполнить проверку</div>';
        }).finally(() => {
            updateFairCheckSubmitState();
        });
        return;
    }
    const params = new URLSearchParams({
        uid: fairCheckUidInput.value.trim(),
        hash: fairCheckHashInput.value.trim(),
        seed: fairCheckSeedInput.value.trim(),
        game: fairCheckSelectedGame || ""
    });
    fetch("/api/fairness/check?" + params.toString()).then(r => r.json()).then(data => {
        if (!data || !data.ok) {
            fairCheckResultEl.innerHTML = '<div class="fair-check-empty">' + escapeHtml(data && data.error || "Ошибка проверки") + "</div>";
            return;
        }
        if (!data.found) {
            fairCheckResultEl.innerHTML = '<div class="fair-check-empty">Раунд не найден. Проверьте введённые данные.</div>';
            return;
        }
        const opened = openFairCheckRoundBySource(data.source, data.roundId);
        if (opened) {
            fairCheckResultEl.innerHTML = "";
            closeFairCheckModal();
        } else {
            fairCheckResultEl.innerHTML = '<div class="fair-check-empty">Не удалось открыть карточку раунда</div>';
        }
    }).catch(() => {
        fairCheckResultEl.innerHTML = '<div class="fair-check-empty">Не удалось выполнить проверку</div>';
    }).finally(() => {
        updateFairCheckSubmitState();
    });
});

const GV_NEW_GAME_TEXT = "Создать новую игру";

const GV_REPEAT_ICONS = {
    repeat: "images/ПовторитьКнопка.png",
    minus: "images/Минус.png",
    plus: "images/Плюс.png"
};

function gvIsNewGameBtn(btn) {
    return !!btn && btn.textContent.trim() === GV_NEW_GAME_TEXT;
}

function gvRound2(v) {
    return Math.round(v * 100) / 100;
}

function gvBetInputEl() {
    return gvBody.querySelector(".gv-bet-input");
}

function gvInputBet() {
    const input = gvBetInputEl();
    const v = input ? parseFloat(input.value) : NaN;
    return v > 0 ? gvRound2(v) : 0;
}

function gvSetBet(bet) {
    const input = gvBetInputEl();
    if (input) input.value = gvRound2(bet) + "⭐️";
}

function gvAmountText(v) {
    return fmtNum(v).replace(/\.(\d)0$/, ".$1");
}

function gvRepeatSteps(limit, bet) {
    const lo = betMin(limit);
    const hi = betMax(limit);
    return {
        smaller: Math.min(hi, Math.max(lo, gvRound2(bet / 2))),
        bigger: Math.max(lo, Math.min(hi, gvRound2(bet * 2)))
    };
}

function gvKenoRepeat() {
    const picks = ((kenoLastResult && kenoLastResult.picks) || kenoPicks).slice();
    resetKenoUI();
    kenoPicks = picks;
    picks.forEach(n => {
        const cell = document.querySelector('#kenoGrid .gv-keno-cell[data-num="' + n + '"]');
        if (cell) cell.classList.add("selected");
    });
    updateKenoStatus();
    updateKenoStartState();
    updateKenoResetRow();
    fetchKenoTable();
    playKeno();
}

