let gvRepeatAdj = null;

function gvRepeatBetNow(cfg) {
    const base = gvRound2(Number(cfg.bet()) || 0);
    if (gvRepeatAdj && gvRepeatAdj.game === currentGame && gvRepeatAdj.base === base) return gvRepeatAdj.bet;
    gvRepeatAdj = null;
    return base;
}

function gvRepeatBarHTML(cfg, bet) {
    const s = gvRepeatSteps(cfg.limit, bet);
    const cls = v => v > currentUser.balance + 1e-9 ? " short" : "";
    const side = (dir, icon, v) => '<button class="gv-repeat-btn' + cls(v) + '" type="button" data-repeat="' + dir + '" data-amount="' + v + '"><img src="' + icon + '" alt=""><span>' + gvAmountText(v) + "⭐️</span></button>";
    return '<div class="gv-repeat-cur">Ставка: <b>' + gvAmountText(bet) + "⭐️</b></div>" + side("down", GV_REPEAT_ICONS.minus, s.smaller) + '<button class="gv-repeat-btn main' + cls(bet) + '" type="button" data-repeat="same" data-amount="' + bet + '"><img src="' + GV_REPEAT_ICONS.repeat + '" alt=""><span>Повторить</span></button>' + side("up", GV_REPEAT_ICONS.plus, s.bigger);
}

function gvRepeatRefresh() {
    const bar = document.getElementById("gvRepeatBar");
    if (!bar) return;
    bar.querySelectorAll(".gv-repeat-btn").forEach(b => {
        const short = Number(b.dataset.amount) > currentUser.balance + 1e-9;
        if (b.classList.contains("short") !== short) b.classList.toggle("short", short);
    });
}

let gvRepeatHoldUntil = 0;

const GV_REPEAT_GAP = 10;

function gvRepeatFitGap(bar) {
    let p = bar.previousElementSibling;
    while (p) {
        const cs = getComputedStyle(p);
        const skip = cs.display === "none" || cs.position === "fixed" || cs.position === "absolute" || p.classList.contains("gv-panel") || p.classList.contains("modal-overlay") || p.classList.contains("rc-info") && !p.classList.contains("open");
        if (!skip) break;
        p = p.previousElementSibling;
    }
    const mb = p ? parseFloat(getComputedStyle(p).marginBottom) || 0 : 0;
    bar.style.marginTop = (GV_REPEAT_GAP - mb) + "px";
}

function gvRepeatSetHide(on) {
    if (gvBody.classList.contains("gv-repeat-on") !== on) gvBody.classList.toggle("gv-repeat-on", on);
}

function gvRepeatSync() {
    const old = document.getElementById("gvRepeatBar");
    const cfg = GV_REPEAT[currentGame];
    if (!cfg && !old) {
        gvRepeatSetHide(false);
        return;
    }
    const btn = cfg && gameView.classList.contains("active") ? document.getElementById(cfg.btn) : null;
    const show = !!btn && gvIsNewGameBtn(btn) && !btn.classList.contains("gv-collapsed") && !btn.classList.contains("gv-hidden");
    const bet = show ? gvRepeatBetNow(cfg) : 0;
    if (!show || !(bet > 0)) {
        if (old) {
            old.remove();
            gvRepeatAdj = null;
        }
        gvRepeatSetHide(Date.now() < gvRepeatHoldUntil && !!cfg);
        return;
    }
    gvRepeatSetHide(true);
    if (old && old.nextElementSibling === btn && old.dataset.game === currentGame && Number(old.dataset.bet) === bet) {
        gvRepeatRefresh();
        return;
    }
    if (old) old.remove();
    const bar = document.createElement("div");
    bar.id = "gvRepeatBar";
    bar.className = "gv-repeat-bar";
    bar.dataset.game = currentGame;
    bar.dataset.bet = String(bet);
    bar.innerHTML = gvRepeatBarHTML(cfg, bet);
    btn.parentNode.insertBefore(bar, btn);
    gvRepeatFitGap(bar);
}

function gvRepeatFocusBet() {
    const input = gvBetInputEl();
    if (!input || !input.offsetParent) return;
    try {
        input.focus();
        input.select();
    } catch (e) {}
}

function gvRepeatAdjust(bar, cfg, cur, dir) {
    const steps = gvRepeatSteps(cfg.limit, cur);
    const bet = dir === "down" ? steps.smaller : steps.bigger;
    if (bet === cur) {
        showToast(dir === "down" ? "Минимальная ставка — " + gvAmountText(betMin(cfg.limit)) + "⭐️" : "Максимальная ставка — " + gvAmountText(betMax(cfg.limit)) + "⭐️", "warning");
        return;
    }
    const base = gvRound2(Number(cfg.bet()) || 0);
    gvRepeatAdj = bet === base ? null : {
        game: currentGame,
        base: base,
        bet: bet
    };
    bar.dataset.bet = String(bet);
    bar.innerHTML = gvRepeatBarHTML(cfg, bet);
    if (bet > currentUser.balance + 1e-9) {
        showToast("Ставка " + gvAmountText(bet) + "⭐️ — на балансе недостаточно средств", "warning");
        return;
    }
    showToast((dir === "down" ? "Ставка уменьшена: " : "Ставка увеличена: ") + gvAmountText(cur) + "⭐️ → " + gvAmountText(bet) + "⭐️", "success");
}

function gvRepeatClick(btn) {
    const bar = btn.closest("#gvRepeatBar");
    const cfg = GV_REPEAT[currentGame];
    if (!bar || !cfg || bar.dataset.busy === "1") return;
    const base = Number(bar.dataset.bet) || 0;
    if (!(base > 0)) return;
    const dir = btn.dataset.repeat;
    if (dir === "down" || dir === "up") {
        gvRepeatAdjust(bar, cfg, base, dir);
        return;
    }
    const bet = Math.min(base, betMax(cfg.limit));
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    if (bet > currentUser.balance + 1e-9) {
        showToast("Недостаточно средств для ставки " + fmtNum(bet) + "⭐️ — введите другую сумму", "error");
        haptic("notification", "error");
        cfg.fresh();
        if (cfg.ask) cfg.ask();
        else gvRepeatFocusBet();
        return;
    }
    bar.dataset.busy = "1";
    setTimeout(() => {
        if (bar.isConnected) delete bar.dataset.busy;
    }, 800);
    haptic("impact", "light");
    gvSetBet(bet);
    gvRepeatHoldUntil = Date.now() + 2200;
    setTimeout(gvRepeatSync, 2300);
    cfg.start();
}

new MutationObserver(() => gvRepeatSync()).observe(gvBody, {
    childList: true,
    subtree: true,
    characterData: true,
    attributes: true,
    attributeFilter: ["class"]
});

window.gvRepeatReady = true;

