const searchInput = document.getElementById("searchInput");

const searchBtn = document.getElementById("searchBtn");

const gameCards = document.querySelectorAll("#gamesGrid .game-card, #exclusiveScroll .game-card");

const emptyState = document.getElementById("emptyState");

function cardMatchesSearch(card, q) {
    if (!q) return true;
    const name = (card.dataset.name || "").toLowerCase();
    if (name.includes(q)) return true;
    const badgeEl = card.querySelector(".badge");
    const badgeText = badgeEl ? badgeEl.textContent.trim().toLowerCase() : "";
    if (badgeText && badgeText.includes(q)) return true;
    if (card.dataset.popular === "1" && "популярное".includes(q)) return true;
    return false;
}

function runSearch() {
    const q = searchInput.value.trim().toLowerCase();
    let visible = 0;
    gameCards.forEach(card => {
        const match = cardMatchesSearch(card, q);
        card.classList.toggle("hidden", !match);
        if (match) visible++;
    });
    const popularWrap = document.getElementById("popularWrap");
    if (popularWrap) popularWrap.classList.toggle("search-hidden", q !== "");
    const wheelPromoEl = document.getElementById("wheelPromo");
    if (wheelPromoEl) wheelPromoEl.classList.toggle("search-hidden", q !== "");
    const exclusiveWrap = document.getElementById("exclusiveWrap");
    if (exclusiveWrap) {
        const exclusiveVisible = Array.from(exclusiveWrap.querySelectorAll(".game-card")).some(c => !c.classList.contains("hidden"));
        exclusiveWrap.style.display = q !== "" && !exclusiveVisible ? "none" : "";
    }
    const fairCheckSection = document.getElementById("fairCheckSection");
    if (fairCheckSection) fairCheckSection.style.display = q === "" ? "" : "none";
    const pvpEmojiSectionEl = document.getElementById("pvpEmojiSection");
    if (pvpEmojiSectionEl) pvpEmojiSectionEl.style.display = (q === "" || "pvp".includes(q)) ? "" : "none";
    const blackjackOpenSectionEl = document.getElementById("blackjackOpenSection");
    if (blackjackOpenSectionEl) blackjackOpenSectionEl.style.display = (q === "" || "блэкджек".includes(q) || "блекджек".includes(q) || "blackjack".includes(q)) ? "" : "none";
    const dogHouseSectionEl = document.getElementById("dogHouseOpenSection");
    if (dogHouseSectionEl) dogHouseSectionEl.style.display = (q === "" || "doghouse".includes(q) || "dog house".includes(q) || "догхаус".includes(q) || "дог хаус".includes(q) || "слот".includes(q) || "slot".includes(q)) ? "" : "none";
    const arenaHubSectionEl = document.getElementById("arenaHubOpenSection");
    if (arenaHubSectionEl) arenaHubSectionEl.style.display = (q === "" || "arenahub".includes(q) || "arena hub".includes(q) || "арена".includes(q) || "арена хаб".includes(q) || "шайба".includes(q) || "pvp".includes(q)) ? "" : "none";
    const escapeSectionEl = document.getElementById("escapeOpenSection");
    if (escapeSectionEl) escapeSectionEl.style.display = (q === "" || "escape".includes(q) || "эскейп".includes(q) || "побег".includes(q) || "шарик".includes(q) || "кольцо".includes(q) || "ball".includes(q)) ? "" : "none";
    const raceSectionEl = document.getElementById("raceOpenSection");
    if (raceSectionEl) raceSectionEl.style.display = (q === "" || "race".includes(q) || "рейс".includes(q) || "гонка".includes(q) || "гонки".includes(q) || "шарики".includes(q) || "шары".includes(q) || "pvp".includes(q)) ? "" : "none";
    const bombSectionEl = document.getElementById("bombOpenSection");
    if (bombSectionEl) bombSectionEl.style.display = (q === "" || "bomb".includes(q) || "бомба".includes(q) || "горячая бомба".includes(q) || "hot bomb".includes(q) || "pvp".includes(q)) ? "" : "none";
    const sumoSectionEl = document.getElementById("sumoOpenSection");
    if (sumoSectionEl) sumoSectionEl.style.display = (q === "" || "sumo".includes(q) || "сумо".includes(q) || "выбивалка".includes(q) || "шары".includes(q) || "pvp".includes(q)) ? "" : "none";
    const kenoOpenSectionEl = document.getElementById("kenoOpenSection");
    if (kenoOpenSectionEl) kenoOpenSectionEl.style.display = (q === "" || "кено".includes(q) || "keno".includes(q)) ? "" : "none";
    const hiloOpenSectionEl = document.getElementById("hiloOpenSection");
    if (hiloOpenSectionEl) hiloOpenSectionEl.style.display = (q === "" || "hi-lo".includes(q) || "hilo".includes(q) || "хайло".includes(q)) ? "" : "none";
    const fairCheckRow = document.getElementById("kenoOpenSection") && document.getElementById("kenoOpenSection").closest(".fair-check-row");
    if (fairCheckRow) {
        const rowHasVisible = (kenoOpenSectionEl && kenoOpenSectionEl.style.display !== "none") || (hiloOpenSectionEl && hiloOpenSectionEl.style.display !== "none");
        fairCheckRow.style.display = rowHasVisible ? "" : "none";
    }
    const wheelOpenSectionEl = document.getElementById("wheelOpenSection");
    if (wheelOpenSectionEl) wheelOpenSectionEl.style.display = (q === "" || "wheel".includes(q) || "вил".includes(q)) ? "" : "none";
    const redblackOpenSectionEl = document.getElementById("redblackOpenSection");
    if (redblackOpenSectionEl) redblackOpenSectionEl.style.display = (q === "" || "red & black".includes(q) || "redblack".includes(q) || "r&b".includes(q) || "рэд".includes(q) || "рб".includes(q)) ? "" : "none";
    const wheelRow = wheelOpenSectionEl && wheelOpenSectionEl.closest(".fair-check-row");
    if (wheelRow) {
        const wheelRowHasVisible = (wheelOpenSectionEl && wheelOpenSectionEl.style.display !== "none") || (redblackOpenSectionEl && redblackOpenSectionEl.style.display !== "none");
        wheelRow.style.display = wheelRowHasVisible ? "" : "none";
    }
    if (q !== "") visible += (dogHouseSectionEl && dogHouseSectionEl.style.display !== "none" ? 1 : 0) + (arenaHubSectionEl && arenaHubSectionEl.style.display !== "none" ? 1 : 0) + (escapeSectionEl && escapeSectionEl.style.display !== "none" ? 1 : 0) + (blackjackOpenSectionEl && blackjackOpenSectionEl.style.display !== "none" ? 1 : 0) + (kenoOpenSectionEl && kenoOpenSectionEl.style.display !== "none" ? 1 : 0) + (hiloOpenSectionEl && hiloOpenSectionEl.style.display !== "none" ? 1 : 0) + (wheelOpenSectionEl && wheelOpenSectionEl.style.display !== "none" ? 1 : 0) + (redblackOpenSectionEl && redblackOpenSectionEl.style.display !== "none" ? 1 : 0) + (pvpEmojiSectionEl && pvpEmojiSectionEl.style.display !== "none" ? 1 : 0);
    const coinflipSectionEl = document.getElementById("coinflipOpenSection");
    const clawSectionEl = document.getElementById("clawOpenSection");
    let coinMatch = false;
    let clawMatch = false;
    if (coinflipSectionEl) {
        coinMatch = q === "" || "орёл".includes(q) || "орел".includes(q) || "решка".includes(q) || "монета".includes(q) || "монетка".includes(q) || "coin".includes(q) || "flip".includes(q);
        coinflipSectionEl.style.display = coinMatch ? "" : "none";
        if (q !== "" && coinMatch) visible += 1;
    }
    if (clawSectionEl) {
        clawMatch = q === "" || "автомат".includes(q) || "хваталка".includes(q) || "игрушк".includes(q) || "claw".includes(q) || "вишенка".includes(q) || "уточка".includes(q) || "собачка".includes(q) || "пепе".includes(q);
        clawSectionEl.style.display = clawMatch ? "" : "none";
        if (q !== "" && clawMatch) visible += 1;
    }
    const coinRow = (coinflipSectionEl || clawSectionEl) && (coinflipSectionEl || clawSectionEl).closest(".fair-check-row");
    if (coinRow) coinRow.style.display = coinMatch || clawMatch ? "" : "none";
    const baccaratSectionEl = document.getElementById("baccaratOpenSection");
    if (baccaratSectionEl) {
        const bacMatch = q === "" || "баккара".includes(q) || "бакара".includes(q) || "baccarat".includes(q) || "карты".includes(q) || "игрок".includes(q) || "банкир".includes(q);
        baccaratSectionEl.style.display = bacMatch ? "" : "none";
        if (q !== "" && bacMatch) visible += 1;
    }
    syncCardsRow();
    emptyState.style.display = visible === 0 ? "flex" : "none";
}

searchInput.addEventListener("input", runSearch);

searchInput.addEventListener("keydown", e => {
    if (e.key === "Enter") {
        e.preventDefault();
        runSearch();
    }
});

searchBtn.addEventListener("click", runSearch);

let leadersCategory = "turnover";

let leadersPeriod = "today";

let leadersRows = null;

let leadersMyRank = null;

let leadersMyScore = null;

let leadersMetric = {
    wins: "count",
    losses: "sum"
};

let leadersRange = null;

let leadersCalMonth = null;

let leadersCalDraft = {
    from: null,
    to: null
};

const LEADER_METRICS = {
    wins: [{
        key: "count",
        label: "Количество игр"
    }, {
        key: "sum",
        label: "Суммы"
    }],
    losses: [{
        key: "count",
        label: "Количество проигранных игр"
    }, {
        key: "sum",
        label: "Суммы"
    }]
};

const LB_MONTHS = ["Январь", "Февраль", "Март", "Апрель", "Май", "Июнь", "Июль", "Август", "Сентябрь", "Октябрь", "Ноябрь", "Декабрь"];

const LB_WEEKDAYS = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"];

const LB_CAL_ICON = '<svg class="lb-cal-ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3.5" y="5" width="17" height="15.5" rx="3"/><path d="M8 3v4M16 3v4M3.5 10h17"/></svg>';

const LEADER_CATEGORIES = [{
    key: "turnover",
    label: "Оборот"
}, {
    key: "wins",
    label: "Выигрыши"
}, {
    key: "balance",
    label: "Баланс"
}, {
    key: "losses",
    label: "Проигрыши"
}];

const LEADER_PERIODS = [{
    key: "today",
    label: "Сегодня"
}, {
    key: "yesterday",
    label: "Вчера"
}, {
    key: "week",
    label: "Неделя"
}, {
    key: "month",
    label: "Месяц"
}, {
    key: "all",
    label: "Всё время"
}];

function escapeHtml(text) {
    return String(text == null ? "" : text).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

function openLeaders() {
    showScreen("leaders");
    setNavActive("лидеры");
    if (leadersRows !== null && leadersRowsFor !== leadersKey()) leadersRows = null;
    leadersMount();
    if (leadersRows === null) leadersArmSkeleton();
    loadLeaders();
}

function leadersMetricOf(category) {
    return LEADER_METRICS[category] ? leadersMetric[category] : "";
}

function leadersKey() {
    const custom = leadersPeriod === "custom" && leadersRange ? leadersRange.from + ":" + leadersRange.to : "";
    return leadersCategory + "|" + leadersPeriod + "|" + leadersMetricOf(leadersCategory) + "|" + custom;
}

function leadersQuery() {
    let q = "category=" + leadersCategory + "&period=" + leadersPeriod;
    const metric = leadersMetricOf(leadersCategory);
    if (metric) q += "&metric=" + metric;
    if (leadersPeriod === "custom" && leadersRange) q += "&from=" + leadersRange.from + "&to=" + leadersRange.to;
    return q;
}

function formatLeaderScore(category, score) {
    const n = Number(score) || 0;
    const metric = leadersMetricOf(category);
    const isCount = category === "wins" && metric !== "sum" || category === "losses" && metric === "count";
    return category === "balance" ? balanceAmountHTML(n) : isCount ? String(Math.round(n)) : formatMoney(n);
}

function lbIso(y, m, d) {
    return y + "-" + String(m + 1).padStart(2, "0") + "-" + String(d).padStart(2, "0");
}

function lbFmtDate(iso) {
    const p = iso.split("-");
    return p[2] + "." + p[1] + (Number(p[0]) === mskNowAsLocal().getFullYear() ? "" : "." + p[0]);
}

function lbRangeLabel(range) {
    return range.from === range.to ? lbFmtDate(range.from) : lbFmtDate(range.from) + " – " + lbFmtDate(range.to);
}

function leadersCalPanelHTML() {
    const now = mskNowAsLocal();
    const cur = {
        y: now.getFullYear(),
        m: now.getMonth()
    };
    const view = leadersCalMonth || cur;
    const offset = (new Date(view.y, view.m, 1).getDay() + 6) % 7;
    const days = new Date(view.y, view.m + 1, 0).getDate();
    const todayIso = lbIso(cur.y, cur.m, now.getDate());
    const draft = leadersCalDraft;
    const lo = draft.from;
    const hi = draft.to || draft.from;
    let cells = LB_WEEKDAYS.map(w => '<span class="lb-cal-dow">' + w + "</span>").join("");
    for (let i = 0; i < offset; i++) cells += '<span class="lb-cal-cell empty"></span>';
    for (let d = 1; d <= days; d++) {
        const iso = lbIso(view.y, view.m, d);
        const future = iso > todayIso;
        let cls = "lb-cal-cell";
        if (lo && iso >= lo && iso <= hi) cls += " in";
        if (iso === lo) cls += " start";
        if (iso === hi) cls += " end";
        if (iso === todayIso) cls += " today";
        if (future) cls += " off";
        cells += '<button class="' + cls + '" type="button" data-lb-cal-day="' + iso + '"' + (future ? " disabled" : "") + ">" + d + "</button>";
    }
    const atCurrent = view.y === cur.y && view.m === cur.m;
    let hint = "Выберите дату или период";
    if (lo && !draft.to) hint = "Нажмите вторую дату или «Применить» для одного дня";
    if (lo && draft.to) hint = lbRangeLabel({
        from: lo,
        to: hi
    });
    return '<div class="lb-cal">' + '<div class="lb-cal-head">' + '<button class="lb-cal-nav" type="button" data-lb-cal-nav="-1" aria-label="Предыдущий месяц">' + '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M15 6l-6 6 6 6"/></svg></button>' + '<div class="lb-cal-title">' + LB_MONTHS[view.m] + " " + view.y + "</div>" + '<button class="lb-cal-nav" type="button" data-lb-cal-nav="1" aria-label="Следующий месяц"' + (atCurrent ? " disabled" : "") + ">" + '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M9 6l6 6-6 6"/></svg></button>' + "</div>" + '<div class="lb-cal-grid">' + cells + "</div>" + '<div class="lb-cal-foot">' + '<div class="lb-cal-hint">' + hint + "</div>" + '<div class="lb-cal-actions">' + '<button class="lb-cal-btn" type="button" data-lb-cal-reset="1">Сбросить</button>' + '<button class="lb-cal-btn primary" type="button" data-lb-cal-apply="1"' + (lo ? "" : " disabled") + ">Применить</button>" + "</div>" + "</div>" + "</div>";
}

function leadersCalendarHTML() {
    if (leadersCategory === "balance") return "";
    const active = leadersPeriod === "custom" && leadersRange;
    const label = active ? lbRangeLabel(leadersRange) : "Выбрать дату";
    return '<div class="lb-cal-wrap">' + '<button class="lb-cal-toggle' + (active ? " active" : "") + '" type="button" data-lb-cal-toggle="1">' + LB_CAL_ICON + "<span>" + label + "</span>" + "</button>" + "</div>";
}

function leadersTabsHTML() {
    const catTabs = LEADER_CATEGORIES.map(c => '<button class="lb-tab' + (c.key === leadersCategory ? " active" : "") + '" type="button" data-lb-cat="' + c.key + '">' + c.label + "</button>").join("");
    const metrics = LEADER_METRICS[leadersCategory];
    const metricRow = metrics ? '<div class="lb-metric-row">' + metrics.map(m => '<button class="lb-metric-chip' + (m.key === leadersMetric[leadersCategory] ? " active" : "") + '" type="button" data-lb-metric="' + m.key + '">' + m.label + "</button>").join("") + "</div>" : "";
    const customActive = leadersPeriod === "custom";
    const periodTabs = leadersCategory === "balance" ? "" : '<div class="lb-period-row">' + LEADER_PERIODS.map(p => '<button class="lb-period-chip' + (!customActive && p.key === leadersPeriod ? " active" : "") + '" type="button" data-lb-period="' + p.key + '">' + p.label + "</button>").join("") + "</div>";
    return '<div class="lb-tabs">' + catTabs + "</div>" + metricRow + periodTabs + leadersCalendarHTML();
}

function leadersPodiumHTML(rows) {
    const order = [1, 0, 2];
    const rankClass = ["second", "first", "third"];
    const medal = [liteAsset("/lottie/images/МедальВтороеМесто.lottie"), liteAsset("/lottie/images/МедальПервоеМесто.lottie"), liteAsset("/lottie/images/МедальТретееМесто.lottie")];
    return '<div class="lb-podium">' + order.map((rowIdx, slotIdx) => {
        const row = rows[rowIdx];
        if (!row) return '<div class="lb-podium-slot ' + rankClass[slotIdx] + ' empty"></div>';
        const isMe = row.id === currentUser.id;
        return '<div class="lb-podium-slot ' + rankClass[slotIdx] + (isMe ? " me" : "") + '" style="--i:' + slotIdx + '">' + '<div class="lb-podium-medal">' + lazyImgTag(medal[slotIdx], "", "") + "</div>" + '<div class="lb-podium-avatar"><img src="/api/avatar/' + row.id + '" alt="" loading="lazy"></div>' + '<div class="lb-podium-name">' + escapeHtml(row.username) + "</div>" + '<div class="lb-podium-score">' + formatLeaderScore(leadersCategory, row.score) + "</div>" + '<div class="lb-podium-bar"><span class="lb-podium-rank">' + (rowIdx + 1) + "</span></div>" + "</div>";
    }).join("") + "</div>";
}

function leadersListHTML(rows) {
    if (rows.length <= 3) return "";
    return '<div class="lb-list">' + rows.slice(3).map((row, i) => {
        const rank = i + 4;
        const isMe = row.id === currentUser.id;
        return '<div class="lb-row' + (isMe ? " me" : "") + '" style="--i:' + i + '">' + '<div class="lb-rank">' + rank + "</div>" + '<div class="lb-avatar"><img src="/api/avatar/' + row.id + '" alt="" loading="lazy"></div>' + '<div class="lb-name">' + escapeHtml(row.username) + (isMe ? ' <span class="lb-you-tag">Вы</span>' : "") + "</div>" + '<div class="lb-score">' + formatLeaderScore(leadersCategory, row.score) + "</div>" + "</div>";
    }).join("") + "</div>";
}

function leadersMyRankHTML(rows) {
    if (!leadersMyRank || rows.some(r => r.id === currentUser.id)) return "";
    return '<div class="lb-my-rank-label">Ваше место</div>' + '<div class="lb-row me lb-my-rank">' + '<div class="lb-rank">' + leadersMyRank + "</div>" + '<div class="lb-avatar"><img src="/api/avatar/' + currentUser.id + '" alt=""></div>' + '<div class="lb-name">Вы</div>' + '<div class="lb-score">' + formatLeaderScore(leadersCategory, leadersMyScore) + "</div>" + "</div>";
}

function leadersSkeletonHTML() {
    return '<div class="lb-podium lb-podium-skel">' + '<div class="lb-podium-slot second"><div class="skel-box lb-skel-avatar"></div><div class="skel-box lb-skel-line"></div></div>' + '<div class="lb-podium-slot first"><div class="skel-box lb-skel-avatar"></div><div class="skel-box lb-skel-line"></div></div>' + '<div class="lb-podium-slot third"><div class="skel-box lb-skel-avatar"></div><div class="skel-box lb-skel-line"></div></div>' + "</div>" + '<div class="lb-list">' + Array.from({
        length: 5
    }).map(() => '<div class="lb-row skel"><div class="skel-box lb-skel-avatar sm"></div><div class="skel-box lb-skel-line" style="flex:1"></div></div>').join("") + "</div>";
}

function leadersEmptyHTML() {
    const art = currentUser.liteUiEnabled ? '<svg class="lb-empty-svg" viewBox="0 0 64 64" fill="none" aria-hidden="true"><path d="M20 10h24v12a12 12 0 0 1-24 0V10z" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/><path d="M20 14h-8v4a8 8 0 0 0 8 8M44 14h8v4a8 8 0 0 1-8 8M32 34v10M22 54h20M26 44h12v10H26z" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>' : lazyImgTag("/lottie/images/Лидеры.lottie", "", "lb-empty-lottie");
    return '<div class="lb-empty lb-empty-art">' + art + "</div>";
}

let leadersSkelTimer = 0;

let leadersShowSkel = false;

let leadersDataKey = "";

let leadersViewKey = "";

let leadersRowsFor = "";

function leadersHeaderHTML() {
    return '<div class="gv-topbar">' + backPillHTML("leaders-exit") + walletBalancePillHTML() + "</div>" + '<h2 class="lb-title">Лидеры</h2>' + '<div class="lb-tabs-wrap" id="lbTabsWrap">' + leadersTabsHTML() + "</div>";
}

function leadersContentHTML() {
    if (leadersRows === null) return leadersShowSkel ? leadersSkeletonHTML() : "";
    if (!leadersRows.length) return leadersEmptyHTML();
    return leadersPodiumHTML(leadersRows) + leadersListHTML(leadersRows) + leadersMyRankHTML(leadersRows);
}

function leadersPopIn() {
    setTimeout(() => {
        lbBody.querySelectorAll(".lb-podium-slot:not(.empty), .lb-row:not(.skel)").forEach(el => el.classList.add("in"));
    }, 20);
}

function leadersMount() {
    leadersViewKey = leadersRows === null ? "" : leadersDataKey;
    lbBody.innerHTML = leadersHeaderHTML() + '<div class="lb-content" id="lbContent">' + leadersContentHTML() + "</div>";
    leadersPopIn();
}

function leadersRefreshTabs() {
    const wrap = document.getElementById("lbTabsWrap");
    if (!wrap) return;
    const old = wrap.querySelector(".lb-tabs");
    const left = old ? old.scrollLeft : 0;
    wrap.innerHTML = leadersTabsHTML();
    const fresh = wrap.querySelector(".lb-tabs");
    if (fresh) fresh.scrollLeft = left;
}

function leadersSwap() {
    const content = document.getElementById("lbContent");
    if (!content) return;
    content.classList.remove("busy");
    content.innerHTML = leadersContentHTML();
    leadersViewKey = leadersRows === null ? "" : leadersDataKey;
    leadersPopIn();
}

function leadersArmSkeleton() {
    clearTimeout(leadersSkelTimer);
    leadersShowSkel = false;
    leadersSkelTimer = setTimeout(() => {
        if (leadersRows !== null) return;
        leadersShowSkel = true;
        leadersSwap();
    }, 140);
}

function leadersBeginLoad() {
    leadersRefreshTabs();
    if (leadersRows === null) {
        leadersArmSkeleton();
        return;
    }
    const content = document.getElementById("lbContent");
    if (content) content.classList.add("busy");
}

function leadersFinish() {
    const content = document.getElementById("lbContent");
    if (!content) return;
    if (leadersDataKey === leadersViewKey) {
        content.classList.remove("busy");
        return;
    }
    leadersSwap();
}

function leadersStore(key, rows, myRank, myScore, ok) {
    clearTimeout(leadersSkelTimer);
    leadersShowSkel = false;
    leadersRows = rows;
    leadersMyRank = myRank;
    leadersMyScore = myScore;
    leadersRowsFor = key;
    leadersDataKey = ok ? JSON.stringify([key, rows, myRank, myScore]) : "fail|" + key;
    leadersFinish();
}

function loadLeaders() {
    const key = leadersKey();
    fetch("/api/leaders?" + leadersQuery() + "&limit=20&uid=" + currentUser.id).then(r => r.json()).then(data => {
        if (key !== leadersKey()) return;
        if (!data || !data.ok) {
            leadersStore(key, [], null, null, false);
            return;
        }
        leadersStore(key, data.rows || [], data.myRank, data.myScore, true);
    }).catch(() => {
        if (key !== leadersKey()) return;
        leadersStore(key, [], null, null, false);
    });
}

function leadersCalRender() {
    const body = document.getElementById("lbCalBody");
    if (body) body.innerHTML = leadersCalPanelHTML();
}

function leadersCalCloseModal() {
    const modal = document.getElementById("lbCalModal");
    if (modal) modal.classList.remove("active");
}

function leadersCalOpenModal() {
    const range = leadersPeriod === "custom" && leadersRange ? leadersRange : null;
    leadersCalDraft = range ? {
        from: range.from,
        to: range.to
    } : {
        from: null,
        to: null
    };
    const base = range ? range.to.split("-") : null;
    leadersCalMonth = base ? {
        y: Number(base[0]),
        m: Number(base[1]) - 1
    } : null;
    leadersCalRender();
    document.getElementById("lbCalModal").classList.add("active");
}

function leadersCalPick(iso) {
    const d = leadersCalDraft;
    if (!d.from || d.to) {
        d.from = iso;
        d.to = null;
        return;
    }
    if (iso < d.from) {
        d.to = d.from;
        d.from = iso;
        return;
    }
    d.to = iso;
}

function leadersCalShift(step) {
    const now = mskNowAsLocal();
    const view = leadersCalMonth || {
        y: now.getFullYear(),
        m: now.getMonth()
    };
    const moved = new Date(view.y, view.m + step, 1);
    if (moved.getFullYear() * 12 + moved.getMonth() > now.getFullYear() * 12 + now.getMonth()) return;
    leadersCalMonth = {
        y: moved.getFullYear(),
        m: moved.getMonth()
    };
}

lbBody.addEventListener("click", e => {
    const exitBtn = e.target.closest('[data-action="leaders-exit"]');
    if (exitBtn) {
        closeGame();
        return;
    }
    const catBtn = e.target.closest("[data-lb-cat]");
    if (catBtn) {
        const cat = catBtn.dataset.lbCat;
        if (cat === leadersCategory) return;
        leadersCategory = cat;
        leadersBeginLoad();
        loadLeaders();
        return;
    }
    const metricBtn = e.target.closest("[data-lb-metric]");
    if (metricBtn) {
        const metric = metricBtn.dataset.lbMetric;
        if (!LEADER_METRICS[leadersCategory] || metric === leadersMetric[leadersCategory]) return;
        leadersMetric[leadersCategory] = metric;
        leadersBeginLoad();
        loadLeaders();
        return;
    }
    const periodBtn = e.target.closest("[data-lb-period]");
    if (periodBtn) {
        const per = periodBtn.dataset.lbPeriod;
        if (per === leadersPeriod) return;
        leadersPeriod = per;
        leadersBeginLoad();
        loadLeaders();
        return;
    }
    if (e.target.closest("[data-lb-cal-toggle]")) {
        leadersCalOpenModal();
        return;
    }
});

document.getElementById("lbCalClose").addEventListener("click", leadersCalCloseModal);

document.getElementById("lbCalModal").addEventListener("click", e => {
    if (e.target.id === "lbCalModal") {
        leadersCalCloseModal();
        return;
    }
    const navBtn = e.target.closest("[data-lb-cal-nav]");
    if (navBtn) {
        leadersCalShift(Number(navBtn.dataset.lbCalNav));
        leadersCalRender();
        return;
    }
    const dayBtn = e.target.closest("[data-lb-cal-day]");
    if (dayBtn) {
        leadersCalPick(dayBtn.dataset.lbCalDay);
        leadersCalRender();
        return;
    }
    if (e.target.closest("[data-lb-cal-apply]")) {
        const d = leadersCalDraft;
        if (!d.from) return;
        leadersRange = {
            from: d.from,
            to: d.to || d.from
        };
        leadersPeriod = "custom";
        leadersCalCloseModal();
        leadersBeginLoad();
        loadLeaders();
        return;
    }
    if (e.target.closest("[data-lb-cal-reset]")) {
        leadersCalDraft = {
            from: null,
            to: null
        };
        if (leadersPeriod === "custom") {
            leadersRange = null;
            leadersPeriod = "today";
            leadersCalCloseModal();
            leadersBeginLoad();
            loadLeaders();
            return;
        }
        leadersCalRender();
        return;
    }
});

