let crashState = null;

let crashLastStatus = null;

let crashBusy = false;

let crashPollTimer = null;

let crashTickTimer = null;

let crashHistoryScope = "all";

let crashPingMs = null;

let crashChipsSignature = null;

let crashPlayersSignature = null;

let crashTransitioning = false;

const CRASH_TRANSITION_MS = 900;

function fmtMult(v) {
    const n = Number(v);
    return isFinite(n) ? n.toFixed(2) : "—";
}

function crashLiveMult(state) {
    if (!state) return 1;
    if (state.status === "flying" && state.flyingStartedAt) {
        const elapsed = Math.max(0, (Date.now() - state.flyingStartedAt) / 1e3);
        return Math.min(Math.exp(state.growth * elapsed), 999999);
    }
    if (state.status === "crashed") return state.crashPoint || state.currentMult || 1;
    return 1;
}

function crashProgress(mult) {
    const m = Math.max(1, Number(mult) || 1);
    return (m - 1) / (m - 1 + 6);
}

function crashPointAt(mult) {
    const p = crashProgress(mult);
    return {
        left: CRASH_PATH_START.left + p * CRASH_PATH_SPAN.left,
        top: CRASH_PATH_START.top - p * CRASH_PATH_SPAN.top
    };
}

function crashRocketPos(pt) {
    return {
        left: Math.max(pt.left, CRASH_ROCKET_MARGIN.left),
        top: Math.min(pt.top, 100 - CRASH_ROCKET_MARGIN.top)
    };
}

function crashCurvePoints(mult, elapsedSeconds, growth) {
    const steps = 20;
    if (!elapsedSeconds || elapsedSeconds <= 0) return [crashPointAt(1)];
    const g = growth || .1;
    const pts = [];
    for (let i = 0; i <= steps; i++) {
        const t = elapsedSeconds * (i / steps);
        const m = Math.min(mult, Math.exp(g * t));
        pts.push(crashPointAt(m));
    }
    return pts;
}

function crashPathsFromPoints(points) {
    const line = "M " + points.map(p => p.left.toFixed(2) + " " + p.top.toFixed(2)).join(" L ");
    const last = points[points.length - 1];
    const first = points[0];
    const fill = line + " L " + last.left.toFixed(2) + " " + CRASH_FILL_BOTTOM + " L " + first.left.toFixed(2) + " " + CRASH_FILL_BOTTOM + " Z";
    return {
        line: line,
        fill: fill
    };
}

function crashStarsHTML() {
    let html = "";
    for (let i = 0; i < 16; i++) {
        const left = (Math.random() * 96 + 2).toFixed(1);
        const top = (Math.random() * 70 + 2).toFixed(1);
        const size = (Math.random() * 1.6 + 1).toFixed(1);
        const delay = (Math.random() * 2).toFixed(2);
        html += '<div class="crash-star" style="left:' + left + "%;top:" + top + "%;width:" + size + "px;height:" + size + "px;animation-delay:" + delay + 's;"></div>';
    }
    return html;
}

