let ladderHowtoTimer = null;
let ladderHowtoLoopActive = false;

function ladderHowtoExampleHTML() {
    return '<div class="ladder-howto-example-wrap"><div class="gv-ladder-grid" id="ladderHowtoGrid">' + ladderGridHTML() + "</div></div>" + '<div class="blackjack-howto-example-total">Поднимайтесь по уровням — каждый пройденный увеличивает множитель, камень обнуляет ставку</div>';
}

function setLadderHowtoCell(level, col, cellState) {
    const cell = document.querySelector('#ladderHowtoGrid .gv-ladder-cell[data-level="' + level + '"][data-col="' + col + '"]');
    if (!cell) return;
    let cls = "gv-mine-cell gv-ladder-cell",
        src = LADDER_GIF_CLOSED;
    if (cellState === "open") {
        cls += " open";
        src = LADDER_GIF_OPEN;
    } else if (cellState === "hit") {
        cls += " bomb hit";
        src = LADDER_GIF_HIT;
    } else if (cellState === "stone") {
        cls += " bomb";
        src = LADDER_GIF_STONE;
    }
    cell.className = cls;
    cell.innerHTML = ladderCellImgHTML(src);
}

function refreshLadderHowtoRowLocks(currentLevel) {
    document.querySelectorAll("#ladderHowtoGrid .gv-ladder-row").forEach(row => {
        const level = parseInt(row.dataset.level, 10);
        row.className = "gv-ladder-row " + (level < currentLevel ? "done" : level === currentLevel ? "current" : "locked");
    });
}

function resetLadderHowtoGrid() {
    document.querySelectorAll("#ladderHowtoGrid .gv-ladder-cell").forEach(cell => {
        cell.className = "gv-mine-cell gv-ladder-cell";
        cell.innerHTML = ladderCellImgHTML(LADDER_GIF_CLOSED);
    });
    refreshLadderHowtoRowLocks(0);
}

function playLadderHowtoRound() {
    if (!ladderHowtoLoopActive) return;
    resetLadderHowtoGrid();
    const climbLevels = 2 + Math.floor(Math.random() * 3);
    let level = 0;
    const step = () => {
        if (!ladderHowtoLoopActive) return;
        const col = Math.floor(Math.random() * LADDER_COLUMNS);
        refreshLadderHowtoRowLocks(level);
        if (level < climbLevels) {
            setLadderHowtoCell(level, col, "open");
            level++;
            ladderHowtoTimer = setTimeout(step, 650);
        } else {
            setLadderHowtoCell(level, col, "hit");
            ladderHowtoTimer = setTimeout(() => {
                if (ladderHowtoLoopActive) playLadderHowtoRound();
            }, 1700);
        }
    };
    ladderHowtoTimer = setTimeout(step, 650);
}

function startLadderHowtoAnim() {
    stopLadderHowtoAnim();
    ladderHowtoLoopActive = true;
    playLadderHowtoRound();
}

function stopLadderHowtoAnim() {
    ladderHowtoLoopActive = false;
    if (ladderHowtoTimer) {
        clearTimeout(ladderHowtoTimer);
        ladderHowtoTimer = null;
    }
}

