let rouletteHowtoTimer = null;
let rouletteHowtoLoopActive = false;
let rouletteHowtoSpinToken = 0;

function rouletteHowtoStageHTML(statusHTML) {
    return '<div class="roulette-status-line" id="rouletteHowtoStatus">' + statusHTML + "</div>" + '<div class="roulette-strip-wrap">' + '<div class="roulette-pointer"></div>' + '<div class="roulette-strip" id="rouletteHowtoStrip"></div>' + "</div>";
}

function rouletteHowtoExampleHTML() {
    return '<div class="gv-crash-box roulette-box roulette-howto-box" id="rouletteHowtoBox">' + rouletteHowtoStageHTML("Крутим…") + "</div>" + '<div class="blackjack-howto-example-total">Выберите цвет и сумму ставки — если стрелка укажет на ваш цвет, получаете ставку × коэффициент</div>';
}

function rouletteHowtoPickColor() {
    const colors = ["red", "black", "red", "black", "green"];
    return colors[Math.floor(Math.random() * colors.length)];
}

function playRouletteHowtoRound() {
    if (!rouletteHowtoLoopActive) return;
    const box = document.getElementById("rouletteHowtoBox");
    if (!box) return;
    const winColor = rouletteHowtoPickColor();
    const fakeState = {
        roundId: "demo" + Date.now(),
        outcomes: ROULETTE_DEFAULT_OUTCOMES
    };
    box.innerHTML = rouletteHowtoStageHTML("Крутим…");
    const strip = document.getElementById("rouletteHowtoStrip");
    if (!strip) return;
    const wrapEl = strip.parentElement;
    const {
        cells: cells,
        targetIdx: targetIdx
    } = rouletteBuildStripCells(winColor, fakeState);
    strip.style.transition = "none";
    strip.style.transform = "translateX(0)";
    strip.innerHTML = rouletteCellsHTML(cells);
    void strip.offsetWidth;
    const token = ++rouletteHowtoSpinToken;
    const spinSeconds = 3.2;
    requestAnimationFrame(() => {
        if (token !== rouletteHowtoSpinToken) return;
        const wrapW = wrapEl ? wrapEl.clientWidth : 320;
        const targetEl = strip.children[targetIdx];
        const offset = targetEl ? targetEl.offsetLeft + targetEl.offsetWidth / 2 - wrapW / 2 : 0;
        strip.style.transition = "transform " + spinSeconds + "s " + ROULETTE_SPIN_EASE;
        strip.style.transform = "translateX(-" + offset + "px)";
        rouletteHowtoTimer = setTimeout(() => {
            if (token !== rouletteHowtoSpinToken) return;
            const statusEl = document.getElementById("rouletteHowtoStatus");
            const outcome = fakeState.outcomes.find(o => o.color === winColor) || fakeState.outcomes[0];
            if (statusEl) statusEl.innerHTML = "Выпало: <b>" + rouletteColorIconHTML(winColor) + " " + ROULETTE_COLOR_LABEL[winColor] + " x" + fmtMult(outcome.mult) + "</b>";
            if (targetEl) targetEl.classList.add("highlight");
            rouletteHowtoTimer = setTimeout(() => {
                if (rouletteHowtoLoopActive) playRouletteHowtoRound();
            }, 1600);
        }, spinSeconds * 1e3 + 100);
    });
}

function startRouletteHowtoAnim() {
    stopRouletteHowtoAnim();
    rouletteHowtoLoopActive = true;
    playRouletteHowtoRound();
}

function stopRouletteHowtoAnim() {
    rouletteHowtoLoopActive = false;
    rouletteHowtoSpinToken++;
    if (rouletteHowtoTimer) {
        clearTimeout(rouletteHowtoTimer);
        rouletteHowtoTimer = null;
    }
}

