function upgradeHowtoRingHTML(chance) {
    return upgradeWheelSVG("howto", chance, UPGRADE_IDLE_ANGLE);
}

function upgradeHowtoExampleHTML() {
    return '<div class="upgrade-ring-box" id="upgradeHowtoRingBox">' + upgradeHowtoRingHTML(50) + "</div>" + '<div class="blackjack-howto-example-total">Колесо крутится и останавливается на случайном значении — если оно попало в вашу зону, ставка умножается на коэффициент</div>';
}

function playUpgradeHowtoRound() {
    if (!upgradeHowtoLoopActive) return;
    const box = document.getElementById("upgradeHowtoRingBox");
    if (!box || !box.querySelector(".upg-arrow")) return;
    const chanceOptions = [10, 25, 50, 75];
    const chance = chanceOptions[Math.floor(Math.random() * chanceOptions.length)];
    const roll = Math.random() * 100;
    const win = roll >= UPGRADE_MIN_ROLL && roll <= chance;
    upgradeWheelSetChance(box, chance, "howto");
    upgradeWheelLabel(box, "idle");
    box.classList.add("spinning");
    upgradeSpinArrow(box, upgradeArrowTarget(chance, roll), tok => {
        upgradeHowtoTimer = setTimeout(() => {
            if (!upgradeHowtoLoopActive || box._upgTok !== tok) return;
            box.classList.remove("spinning");
            upgradeWheelLabel(box, win ? "win" : "loss", roll);
            upgradeHowtoTimer = setTimeout(() => {
                if (!upgradeHowtoLoopActive) return;
                upgradeWheelLabel(box, "idle");
                playUpgradeHowtoRound();
            }, 1400);
        }, UPGRADE_SPIN.reveal);
    });
}

function startUpgradeHowtoAnim() {
    stopUpgradeHowtoAnim();
    upgradeHowtoLoopActive = true;
    playUpgradeHowtoRound();
}

