function crashStageHTML(state) {
    if (!state) {
        return '<div class="crash-skel-stage">' + '<div class="skel-box crash-skel-full"></div>' + "</div>";
    }
    if (state.status === "waiting") {
        return '<div class="crash-gif-wrap">' + lazyImgTag(liteAsset(CRASH_WAIT_GIF), "", "crash-gif") + "</div>" + '<div class="crash-countdown" id="crashCountdownNum">' + crashCountdownSeconds(state) + "</div>" + '<div class="crash-status">до старта</div>';
    }
    const crashedNow = state.status === "crashed";
    return '<div class="crash-flight-stage" id="crashFlightStage">' + '<div class="crash-stars" id="crashStars">' + crashStarsHTML() + "</div>" + lazyImgTag(liteAsset(CRASH_MOON_GIF), "", "crash-moon-img") + '<svg class="crash-trail-svg" viewBox="0 0 100 100" preserveAspectRatio="none">' + CRASH_SVG_DEFS + '<path id="crashFillPath" class="crash-fill-path' + (crashedNow ? " crashed" : "") + '"></path>' + '<path id="crashTrailPath" class="crash-trail-path' + (crashedNow ? " crashed" : "") + '"></path>' + "</svg>" + crashRocketImgHTML(crashedNow ? liteAsset(CRASH_LOSE_GIF) : liteAsset(crashCurrentFlyGif()), crashedNow ? "crashed" : "", "crashRocketImg", null) + '<div class="crash-mult' + (crashedNow ? " crashed" : " flying") + '" id="crashMultNum">x' + fmtMult(crashedNow ? state.crashPoint : crashLiveMult(state)) + "</div>" + '<div class="crash-status">' + (crashedNow ? "Улетел" : "Летит…") + "</div>" + "</div>";
}

function crashCountdownSeconds(state) {
    if (!state.waitingStartedAt) return state.waitSeconds || 10;
    const remainMs = state.waitingStartedAt + state.waitSeconds * 1e3 - Date.now();
    return Math.max(1, Math.ceil(remainMs / 1e3));
}

function crashComputeRocketAngle(stageEl) {
    const rect = stageEl ? stageEl.getBoundingClientRect() : null;
    const w = rect && rect.width || 300;
    const h = rect && rect.height || 230;
    const dxPx = CRASH_PATH_SPAN.left / 100 * w;
    const dyPx = CRASH_PATH_SPAN.top / 100 * h;
    const lineAngle = Math.atan2(dyPx, dxPx) * 180 / Math.PI;
    return crashSkinArtAngle - lineAngle;
}

function updateCrashFlightVisual(state) {
    const rocket = document.getElementById("crashRocketImg");
    const linePath = document.getElementById("crashTrailPath");
    const fillPath = document.getElementById("crashFillPath");
    if (!rocket && !linePath) return;
    const crashRocketAngleDeg = crashComputeRocketAngle(document.getElementById("crashFlightStage"));
    const growth = state.growth || .1;
    let mult, elapsed;
    if (state.status === "crashed") {
        mult = Math.min(state.crashPoint, CRASH_VISUAL_CAP_MULT);
        elapsed = Math.log(Math.max(1.0001, mult)) / growth;
    } else {
        elapsed = state.flyingStartedAt ? Math.max(0, (Date.now() - state.flyingStartedAt) / 1e3) : 0;
        mult = Math.min(crashLiveMult(state), CRASH_VISUAL_CAP_MULT);
    }
    const points = crashCurvePoints(mult, elapsed, growth);
    const rp = crashRocketPos(points[points.length - 1]);
    points[points.length - 1] = rp;
    if (rocket) {
        rocket.style.left = rp.left + "%";
        rocket.style.top = rp.top + "%";
        if (state.status !== "crashed") {
            rocket.style.transform = "translate(-50%,-50%) rotate(" + crashRocketAngleDeg.toFixed(1) + "deg)";
        }
    }
    const paths = crashPathsFromPoints(points);
    if (linePath) linePath.setAttribute("d", paths.line);
    if (fillPath) fillPath.setAttribute("d", paths.fill);
}

function crashPlayersSkeletonHTML() {
    return '<div class="crash-players-title text-skel" style="width:70px;">Live</div>' + '<div class="crash-players-list">' + Array.from({
        length: 3
    }).map(() => '<div class="crash-player-row skel">' + '<div class="skel-box crash-player-avatar"></div>' + '<div class="crash-player-name text-skel" style="width:60%;">игрок</div>' + '<div class="crash-player-value text-skel" style="width:44px;">0⭐️</div>' + "</div>").join("") + "</div>";
}

function crashPlayersHTML(state, isHistoryView) {
    if (!state || !state.players || !state.players.length) {
        let text = "Пока никто не поставил — стань первым!";
        if (isHistoryView) text = "В этом раунде не было ставок!";
        else if (state.status && state.status !== "waiting") text = "В этом раунде никто не поставил ставку!";
        return '<div class="crash-players-empty">' + text + "</div>";
    }
    const liveMult = crashLiveMult(state);
    return '<div class="crash-players-title"><span class="live-dot"></span>Live <span>' + state.players.length + "</span></div>" + '<div class="crash-players-list">' + state.players.map(p => {
        const isMe = p.id === CURRENT_UID;
        const cashed = p.cashedOut;
        let valueText, multText, rowClass;
        if (cashed) {
            valueText = "+" + fmtNum(p.winAmount) + "⭐️";
            multText = "x" + fmtMult(p.cashoutMult);
            rowClass = " cashed";
        } else if (state.status === "flying") {
            valueText = fmtNum(Math.round(p.bet * liveMult * 100) / 100) + "⭐️";
            multText = "x" + fmtMult(liveMult);
            rowClass = "";
        } else if (state.status === "crashed") {
            valueText = "Проигрыш";
            multText = "";
            rowClass = " lost";
        } else {
            valueText = fmtNum(p.bet) + "⭐️";
            multText = "";
            rowClass = "";
        }
        return '<div class="crash-player-row' + rowClass + (isMe ? " me" : "") + '">' + '<div class="crash-player-avatar"><img src="/api/avatar/' + p.id + '" alt="" loading="lazy"></div>' + '<div class="crash-player-mid">' + '<div class="crash-player-name"><span class="crash-player-name-text">' + escapeHtml(p.username) + "</span>" + (isMe ? ' <span class="lb-you-tag">Вы</span>' : "") + "</div>" + '<div class="crash-player-sub">Ставка: ' + fmtNum(p.bet) + "⭐️</div>" + "</div>" + (multText ? '<div class="crash-player-mult">' + multText + "</div>" : '<div class="crash-player-mult"></div>') + '<div class="crash-player-value">' + valueText + "</div>" + "</div>";
    }).join("") + "</div>";
}

