function crashBetBtnState(state) {
    if (!state) return {
        text: "Загрузка…",
        mode: "off"
    };
    if (crashBusy) return {
        text: "…",
        mode: "off"
    };
    if (state.myBet) {
        if (state.myBet.cashedOut) {
            return {
                text: "Забрано x" + fmtMult(state.myBet.cashoutMult) + " (+" + fmtNum(state.myBet.winAmount) + "⭐️)",
                mode: "off done"
            };
        }
        if (state.status === "flying") {
            return {
                text: "Забрать x" + fmtMult(crashLiveMult(state)),
                mode: "cashout"
            };
        }
        return {
            text: "Ставка сделана",
            mode: "off"
        };
    }
    if (state.myQueued) {
        return {
            text: "В очереди на след. раунд",
            mode: "off"
        };
    }
    if (!betsAccepted) {
        return {
            text: "Ставки приостановлены",
            mode: "off"
        };
    }
    if (crashControlsFrozen(state)) {
        return {
            text: "Приём ставок закрыт",
            mode: "off"
        };
    }
    if (state.status === "waiting") {
        return {
            text: "Сделать ставку",
            mode: "bet"
        };
    }
    return {
        text: "Ожидаем следующий раунд",
        mode: "off"
    };
}

const CRASH_FREEZE_SECONDS = 1;

function crashControlsFrozen(state) {
    if (!state) return true;
    if (state.myBet || state.myQueued) return true;
    if (state.status === "waiting") {
        return crashCountdownSeconds(state) <= Math.min(state.freezeSeconds || CRASH_FREEZE_SECONDS, CRASH_FREEZE_SECONDS);
    }
    return true;
}

function updateCrashBetBtn() {
    const btn = document.getElementById("crashBetBtn");
    if (!btn || !crashState) return;
    const st = crashBetBtnState(crashState);
    btn.textContent = st.text;
    btn.disabled = st.mode.startsWith("off");
    btn.classList.toggle("dim", st.mode === "off");
    btn.classList.toggle("crash-cashout-btn", st.mode === "cashout");
    btn.classList.toggle("crash-done-btn", st.mode === "off done");
}

function updateCrashLocks(state) {
    const betInput = gvBody.querySelector(".gv-bet-input");
    const autoToggle = document.getElementById("crashAutoToggle");
    const autoInput = document.getElementById("crashAutoInput");
    const locked = crashControlsFrozen(state);
    [betInput, autoToggle, autoInput].forEach(el => {
        if (!el) return;
        el.disabled = locked;
        el.classList.toggle("crash-frozen", locked);
    });
    const panel = document.getElementById("crashPanel");
    if (panel) panel.classList.toggle("locked", locked);
    const historyList = document.getElementById("crashHistoryList");
    if (historyList) historyList.classList.toggle("expanded", locked);
}

function updateCrashPingBadge() {
    const el = document.getElementById("crashPing");
    if (el) el.textContent = crashPingMs != null ? crashPingMs + " ms" : "— ms";
}

let _crashLastCountdownSecond = null;

function crashUpdateStageNumbers(state) {
    if (state.status === "waiting") {
        const el = document.getElementById("crashCountdownNum");
        const seconds = crashCountdownSeconds(state);
        if (el) el.textContent = seconds;
        if (seconds !== _crashLastCountdownSecond) {
            _crashLastCountdownSecond = seconds;
            haptic("impact", "light");
        }
    } else if (state.status === "flying") {
        _crashLastCountdownSecond = null;
        const el = document.getElementById("crashMultNum");
        if (el) el.textContent = "x" + fmtMult(crashLiveMult(state));
        updateCrashFlightVisual(state);
    }
}

function crashFadeStage(stage) {
    stage.classList.remove("crash-fade-in");
    void stage.offsetWidth;
    stage.classList.add("crash-fade-in");
}

function crashPatchPlayers(container, state) {
    const ps = state.players || [];
    const list = container.querySelector(".crash-players-list");
    const rows = list ? list.querySelectorAll(".crash-player-row") : [];
    const sig = ps.map(p => p.id).join(",");
    if (!list || rows.length !== ps.length || container.dataset.playersSig !== sig || !ps.length) {
        container.innerHTML = crashPlayersHTML(state);
        container.dataset.playersSig = sig;
        return;
    }
    const tmp = document.createElement("div");
    tmp.innerHTML = crashPlayersHTML(state);
    const newRows = tmp.querySelectorAll(".crash-player-row");
    if (newRows.length !== rows.length) {
        container.innerHTML = crashPlayersHTML(state);
        return;
    }
    rows.forEach((row, i) => {
        const nr = newRows[i];
        if (row.className !== nr.className) row.className = nr.className;
        [".crash-player-sub", ".crash-player-mult", ".crash-player-value"].forEach(sel => {
            const a = row.querySelector(sel),
                b = nr.querySelector(sel);
            if (a && b && a.textContent !== b.textContent) a.textContent = b.textContent;
        });
    });
    const liveCount = container.querySelector(".crash-players-title span:last-child");
    const newCount = tmp.querySelector(".crash-players-title span:last-child");
    if (liveCount && newCount && liveCount.textContent !== newCount.textContent) liveCount.textContent = newCount.textContent;
}

function renderCrashDynamic(forceStageRebuild) {
    const state = crashState;
    const stage = document.getElementById("crashStage");
    if (stage) {
        if (!crashTransitioning && (forceStageRebuild || state.status !== crashLastStatus)) {
            stage.innerHTML = crashStageHTML(state);
            crashFadeStage(stage);
            crashLastStatus = state.status;
            if (state.status === "flying" || state.status === "crashed") updateCrashFlightVisual(state);
        } else if (!crashTransitioning) {
            crashUpdateStageNumbers(state);
        }
    }
    const roundLabel = document.getElementById("crashRoundIdLabel");
    if (roundLabel) roundLabel.textContent = state.roundId != null ? state.roundId : "—";
    const players = document.getElementById("crashPlayers");
    if (players) {
        if (state.status === "flying") {
            crashPatchPlayers(players, state);
        } else {
            const sig = JSON.stringify((state.players || []).map(p => [p.id, p.bet, p.cashedOut, p.cashoutMult, p.winAmount]));
            if (sig !== crashPlayersSignature) {
                crashPlayersSignature = sig;
                players.innerHTML = crashPlayersHTML(state);
            }
        }
    }
    const chips = document.getElementById("crashHistoryChips");
    if (chips) {
        const sig = (state.history || []).map(h => h.roundId).join(",");
        if (sig !== crashChipsSignature) {
            crashChipsSignature = sig;
            chips.innerHTML = crashHistoryChipsHTML(state);
        }
    }
    updateCrashBetBtn();
    updateCrashLocks(state);
    updateCrashPingBadge();
}

function crashTick() {
    if (!crashState || crashTransitioning) return;
    crashUpdateStageNumbers(crashState);
}

function loadCrashState() {
    const t0 = window.performance && performance.now ? performance.now() : Date.now();
    fetch("/api/crash/state?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        const t1 = window.performance && performance.now ? performance.now() : Date.now();
        crashPingMs = Math.max(1, Math.round(t1 - t0));
        if (!data || !data.ok) return;
        const statusChanged = crashState && crashState.status !== data.status;
        crashState = data;
        if (data.balance !== undefined) applyBalance(data.balance);
        renderCrashDynamic(false);
        if (statusChanged && data.status === "crashed") {
            loadCrashHistory(crashHistoryScope);
        }
        if (statusChanged && gvFairModal.classList.contains("active") && currentGame === "краш") {
            openCrashFair();
        }
    }).catch(() => {});
}

function setupCrashChipsScroll() {
    const container = document.getElementById("crashHistoryChips");
    if (!container || container.dataset.dragWired) return;
    container.dataset.dragWired = "1";
    container.addEventListener("wheel", e => {
        const row = container.querySelector(".gv-mult-row");
        if (!row) return;
        if (Math.abs(e.deltaY) > Math.abs(e.deltaX)) {
            row.scrollLeft += e.deltaY;
            e.preventDefault();
        }
    }, {
        passive: false
    });
    let isDown = false,
        startX = 0,
        startScroll = 0,
        moved = false;
    container.addEventListener("mousedown", e => {
        const row = container.querySelector(".gv-mult-row");
        if (!row) return;
        isDown = true;
        moved = false;
        startX = e.clientX;
        startScroll = row.scrollLeft;
    });
    container.addEventListener("mousemove", e => {
        if (!isDown) return;
        const row = container.querySelector(".gv-mult-row");
        if (!row) return;
        const dx = e.clientX - startX;
        if (Math.abs(dx) > 5) moved = true;
        row.scrollLeft = startScroll - dx;
    });
    ["mouseup", "mouseleave"].forEach(evt => {
        container.addEventListener(evt, () => {
            isDown = false;
        });
    });
    container.addEventListener("click", e => {
        if (moved) {
            e.stopPropagation();
            moved = false;
        }
    }, true);
}

function startCrashPolling() {
    crashState = null;
    crashLastStatus = null;
    crashHistoryScope = "all";
    crashChipsSignature = null;
    crashPlayersSignature = null;
    crashTransitioning = false;
    loadCrashSkinsState();
    loadCrashState();
    loadCrashHistory(crashHistoryScope);
    gvHistoryWireSearch("crashHistorySearchInput", () => loadCrashHistory(crashHistoryScope), value => {
        gvHistorySearch("crashHistoryList", () => "/api/crash/history?uid=" + CURRENT_UID + "&scope=" + crashHistoryScope + "&q=" + encodeURIComponent(value), rows => {
            document.getElementById("crashHistoryList").innerHTML = rows.map(crashHistoryRowHTML).join("");
        });
    });
    stopCrashPolling();
    crashPollTimer = setInterval(loadCrashState, CRASH_POLL_MS);
    crashTickTimer = setInterval(crashTick, CRASH_TICK_MS);
    setupCrashChipsScroll();
}

function stopCrashPolling() {
    if (crashPollTimer) {
        clearInterval(crashPollTimer);
        crashPollTimer = null;
    }
    if (crashTickTimer) {
        clearInterval(crashTickTimer);
        crashTickTimer = null;
    }
}

function crashBetBtnClick() {
    if (!crashState || crashBusy) return;
    const st = crashBetBtnState(crashState);
    if (st.mode === "cashout") {
        crashDoCashout();
        return;
    }
    if (st.mode === "bet") {
        crashDoBet();
        return;
    }
}

function crashDoBet() {
    if (crashBusy || !crashState || crashState.status !== "waiting" || crashControlsFrozen(crashState)) {
        showToast("Приём ставок закрыт. Дождитесь следующего раунда.", "warning");
        return;
    }
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const betInput = gvBody.querySelector(".gv-bet-input");
    const bet = amountValue(betInput ? betInput.value : "");
    if (!(bet > 0)) {
        showToast("Введите сумму ставки", "error");
        return;
    }
    if (bet > currentUser.balance) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    } {
        const limitIssue = betLimitIssue("crash", bet);
        if (limitIssue) {
            showToast(limitIssue, "error");
            return;
        }
    }
    const autoToggle = document.getElementById("crashAutoToggle");
    const autoInput = document.getElementById("crashAutoInput");
    let autoCashout = null;
    if (autoToggle && autoToggle.classList.contains("on") && autoInput) {
        const v = parseFloat((autoInput.value || "").replace(/[^0-9.]/g, ""));
        autoCashout = Math.max(CRASH_MIN_AUTO_CASHOUT, v || CRASH_MIN_AUTO_CASHOUT);
    }
    crashBusy = true;
    updateCrashBetBtn();
    fetch("/api/crash/bet", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            roundId: crashState.roundId,
            bet: bet,
            autoCashout: autoCashout
        })
    }).then(r => r.json()).then(data => {
        crashBusy = false;
        if (!data || !data.ok) {
            showToast(data && data.error || "Ошибка сервера", "error");
            updateCrashBetBtn();
            return;
        }
        applyBalance(data.balance);
        crashState = data;
        renderCrashDynamic(false);
        showToast("Ставка принята", "success");
    }).catch(() => {
        crashBusy = false;
        showToast("Не удалось связаться с сервером", "error");
        updateCrashBetBtn();
    });
}

function crashDoCashout() {
    crashBusy = true;
    updateCrashBetBtn();
    fetch("/api/crash/cashout", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID
        })
    }).then(r => r.json()).then(data => {
        crashBusy = false;
        if (!data || !data.ok) {
            showToast(data && data.error || "Ошибка сервера", "error");
            updateCrashBetBtn();
            return;
        }
        applyBalance(data.balance);
        crashState = data;
        renderCrashDynamic(false);
        showGameWinToast(data.winAmount, "Забрано x" + fmtMult(data.mult) + " (+", "⭐️)", CRASH_WIN_GIF);
    }).catch(() => {
        crashBusy = false;
        showToast("Не удалось связаться с сервером", "error");
        updateCrashBetBtn();
    });
}

function crashHistoryRowHTML(r) {
    let meta = {};
    try {
        meta = JSON.parse(r.meta || "{}");
    } catch (e) {}
    const isWin = r.result === "win";
    const isMe = r.user_id === CURRENT_UID;
    const name = isMe ? currentUser.displayName || "Игрок" : r.username || "Игрок";
    const avatarUrl = isMe ? currentUser.avatarUrl : "/api/avatar/" + r.user_id;
    const outcomeText = isWin ? "Забрано на: <b>x" + fmtMult(meta.cashoutMult) + "</b>" : meta.crashPoint != null ? "Крах на: <b>x" + fmtMult(meta.crashPoint) + "</b>" : "Не успел забрать";
    return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-avatar"><div class="skel-box"></div>' + lazyImgTag(avatarUrl, name) + "</div>" + '<div class="gv-history-mid">' + '<div class="gv-history-name">' + escapeHtml(name) + "</div>" + historyTimeHTML(r.created_at) + "</div>" + '<div class="gv-history-right">Сумма ставки: <b>' + fmtNum(r.bet) + "⭐️</b><br>" + '<span class="gv-history-outcome">' + outcomeText + "</span><br>" + (isWin ? '<span class="gv-history-win">Выигрыш: ' + fmtNum(r.win_amount) + "⭐️</span>" : '<span class="gv-history-lose">Проигрыш</span>') + "</div>" + "</div>" + (meta.roundId ? '<button class="crash-history-fair-btn" type="button" data-crash-round="' + escapeHtml(meta.roundId) + '">' + fairCheckBtnIconHTML() + "Проверить честность</button>" : "") + "</div>";
}

function loadCrashHistory(scope, append) {
    if (scope) {
        crashHistoryScope = scope;
        append = false;
    }
    gvHistoryLoad("crashHistoryList", off => "/api/crash/history?uid=" + CURRENT_UID + "&scope=" + crashHistoryScope + "&offset=" + off, 20, (rows, append) => {
        const list = document.getElementById("crashHistoryList");
        const html = rows.map(crashHistoryRowHTML).join("");
        if (append) list.insertAdjacentHTML("beforeend", html);
        else list.innerHTML = html;
    }, GV_HISTORY_EMPTY_HTML, append);
}

GV_HISTORY_BY_GAME["краш"] = {
    listId: "crashHistoryList",
    load: () => loadCrashHistory(null, true)
};

const ROULETTE_POLL_MS = 500;

const ROULETTE_SPIN_EASE = "cubic-bezier(0.16,1,0.3,1)";

const ROULETTE_COLOR_LABEL = {
    red: "Красное",
    black: "Чёрное",
    green: "Зелёное",
    yellow: "Жёлтое"
};

const ROULETTE_COLOR_EMOJI = {
    red: "🔴",
    black: "⚫",
    green: "🟢",
    yellow: "🟠"
};

const ROULETTE_COLOR_ICON = {
    red: "ИграРулетка/Красное.png",
    black: "ИграРулетка/Черное.png",
    green: "ИграРулетка/Зеленная.png"
};

function rouletteColorIconHTML(color) {
    const src = ROULETTE_COLOR_ICON[color];
    if (!src) return ROULETTE_COLOR_EMOJI[color] || "";
    return '<img class="roulette-color-icon" src="' + src + '" alt="">';
}

const ROULETTE_DEFAULT_OUTCOMES = [{
    color: "red",
    mult: 1.8,
    weight: .45
}, {
    color: "black",
    mult: 1.8,
    weight: .45
}, {
    color: "green",
    mult: 3.5,
    weight: .1
}];

let rouletteState = null;

let rouletteLastStatus = null;

let rouletteBusy = false;

let roulettePollTimer = null;

let rouletteHistoryScope = "all";

let rouletteChipsSignature = null;

let rouletteBetsSignature = null;

const rouletteSelColors = new Set;

let rouletteSpinToken = 0;

function rouletteOutcomeByColor(state, color) {
    return (state && state.outcomes || []).find(o => o.color === color) || {
        color: color,
        mult: 0,
        weight: 0
    };
}

function roulettePlacedMap(state) {
    const map = {};
    ((state && state.myBets) || []).forEach(b => {
        map[b.color] = b;
    });
    return map;
}

function rouletteCurrentBetAmount() {
    const input = gvBody.querySelector(".gv-bet-input");
    const v = amountValue(input ? input.value : "");
    return v > 0 ? v : 0;
}

function rouletteMyBetsHTML(state) {
    const bets = state && state.myBets || [];
    const queued = state && state.myQueuedBets || [];
    if (!bets.length && !queued.length) return "";
    const resolved = state.status === "resolved";
    const total = bets.concat(queued).reduce((sum, b) => sum + b.bet, 0);
    const chip = (b, isQueued) => {
        let tail = fmtNum(b.bet) + "⭐️";
        let cls = "";
        if (isQueued) tail += " · в очереди";
        else if (resolved) {
            if (b.winAmount > 0) {
                cls = " win";
                tail = "+" + fmtNum(b.winAmount) + "⭐️";
            } else {
                cls = " lose";
                tail = "−" + fmtNum(b.bet) + "⭐️";
            }
        }
        return '<span class="wheel-my-bet' + cls + '"><i class="c-' + b.color + '"></i>' + ROULETTE_COLOR_LABEL[b.color] + " <b>" + tail + "</b></span>";
    };
    return '<div class="gv-label">Ваши ставки · всего ' + fmtNum(Math.round(total * 100) / 100) + "⭐️</div>" + '<div class="wheel-my-bets-list">' + bets.map(b => chip(b, false)).join("") + queued.map(b => chip(b, true)).join("") + "</div>";
}

function updateRouletteMyBets(state) {
    const el = document.getElementById("rouletteMyBets");
    if (!el) return;
    const html = rouletteMyBetsHTML(state);
    el.innerHTML = html;
    el.style.display = html ? "" : "none";
}

function updateRouletteBetSummary() {
    const count = rouletteSelColors.size;
    const amount = rouletteCurrentBetAmount();
    const label = document.getElementById("rouletteBetLabel");
    if (label) label.textContent = count > 1 ? "Сумма на каждый исход" : "Сумма ставки";
    const el = document.getElementById("rouletteBetSummary");
    if (!el) return;
    if (count < 2 || !(amount > 0)) {
        el.style.display = "none";
        el.textContent = "";
        return;
    }
    el.style.display = "";
    el.innerHTML = "Выбрано: <b>" + wheelCountWord(count) + "</b> · всего <b>" + fmtNum(Math.round(amount * count * 100) / 100) + "⭐️</b>";
}

function rouletteColorsRowHTML(state) {
    const outcomes = state && state.outcomes || ROULETTE_DEFAULT_OUTCOMES;
    const placed = roulettePlacedMap(state);
    return '<div class="roulette-colors-row" id="rouletteColorsRow">' + outcomes.map(o => {
        const mine = placed[o.color];
        return '<button class="roulette-color-btn roulette-color-' + o.color + (rouletteSelColors.has(o.color) ? " selected" : "") + (mine ? " placed" : "") + '" ' + 'type="button" data-roulette-color="' + o.color + '">' + '<span class="roulette-color-name">' + ROULETTE_COLOR_LABEL[o.color] + "</span>" + '<span class="roulette-color-mult">' + (mine ? "✓ " + fmtNum(mine.bet) + "⭐️" : "x" + fmtMult(o.mult)) + "</span>" + "</button>";
    }).join("") + "</div>";
}

function roulettePoolFromOutcomes(outcomes) {
    const pool = [];
    outcomes.forEach(o => {
        for (let i = 0; i < Math.max(1, Math.round((o.weight || .33) * 20)); i++) pool.push(o);
    });
    return pool;
}

function rouletteSeededRandom(seedStr) {
    let h = 0;
    const s = String(seedStr || "");
    for (let i = 0; i < s.length; i++) {
        h = Math.imul(h, 31) + s.charCodeAt(i) | 0;
    }
    let a = h >>> 0 || 1;
    return function() {
        a |= 0;
        a = a + 1831565813 | 0;
        let t = Math.imul(a ^ a >>> 15, 1 | a);
        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
        return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
}

function rouletteBuildStripCells(winColor, state) {
    const outcomes = state && state.outcomes || ROULETTE_DEFAULT_OUTCOMES;
    const pool = roulettePoolFromOutcomes(outcomes);
    const rand = rouletteSeededRandom(state && state.roundId);
    const cells = [];
    for (let i = 0; i < 44; i++) cells.push(pool[Math.floor(rand() * pool.length)]);
    const targetIdx = 36;
    cells[targetIdx] = outcomes.find(o => o.color === winColor) || outcomes[0];
    return {
        cells: cells,
        targetIdx: targetIdx
    };
}

function rouletteIdleCells(state) {
    const outcomes = state && state.outcomes || ROULETTE_DEFAULT_OUTCOMES;
    const pool = roulettePoolFromOutcomes(outcomes);
    const rand = rouletteSeededRandom(state && state.roundId);
    const cells = [];
    for (let i = 0; i < 26; i++) cells.push(pool[Math.floor(rand() * pool.length)]);
    return cells;
}

function rouletteCellHTML(o, idx) {
    const num = (idx || 0) % 36 + 1;
    return '<div class="roulette-cell roulette-cell-' + o.color + '">' + '<div class="roulette-cell-coef">x' + fmtMult(o.mult) + "</div>" + '<div class="roulette-cell-num">' + num + "</div>" + "</div>";
}

function rouletteCellsHTML(list) {
    return list.map((o, i) => rouletteCellHTML(o, i)).join("");
}

function rouletteStripHTML(state) {
    if (!state || state.status === "waiting") {
        return '<div class="roulette-strip-wrap">' + '<div class="roulette-pointer"></div>' + '<div class="roulette-strip" id="rouletteStrip">' + rouletteCellsHTML(rouletteIdleCells(state)) + "</div>" + "</div>";
    }
    return '<div class="roulette-strip-wrap">' + '<div class="roulette-pointer"></div>' + '<div class="roulette-strip" id="rouletteStrip"></div>' + "</div>";
}

function rouletteBoxHTML(state) {
    return '<div class="roulette-status-line" id="rouletteStatusLine">' + rouletteStatusLineHTML(state) + "</div>" + rouletteStripHTML(state);
}

function rouletteStripTranslateX(el) {
    const t = getComputedStyle(el).transform;
    if (!t || t === "none") return 0;
    const m = t.match(/matrix\(([^)]+)\)/);
    if (!m) return 0;
    const parts = m[1].split(",").map(parseFloat);
    return parts[4] || 0;
}

function rouletteCellUnderPointer(strip, wrapW) {
    const translateX = rouletteStripTranslateX(strip);
    const pointerX = wrapW / 2 - translateX;
    let match = null;
    for (const child of strip.children) {
        if (pointerX >= child.offsetLeft && pointerX < child.offsetLeft + child.offsetWidth) {
            match = child;
            break;
        }
    }
    return match;
}

function rouletteFollowPointerHighlight(strip, wrapEl, token, prevMatch) {
    if (token !== rouletteSpinToken) return;
    const wrapW = wrapEl.clientWidth;
    const match = rouletteCellUnderPointer(strip, wrapW);
    for (const child of strip.children) {
        if (child !== match) child.classList.remove("highlight");
    }
    if (match) match.classList.add("highlight");
    if (match && match !== prevMatch) haptic("selection");
    requestAnimationFrame(() => rouletteFollowPointerHighlight(strip, wrapEl, token, match));
}

function rouletteAnimateStrip(state, instant) {
    const strip = document.getElementById("rouletteStrip");
    if (!strip) return;
    const wrapEl = strip.parentElement;
    const {
        cells: cells,
        targetIdx: targetIdx
    } = rouletteBuildStripCells(state.outcomeColor, state);
    strip.style.transition = "none";
    strip.style.transform = "translateX(0)";
    strip.innerHTML = rouletteCellsHTML(cells);
    void strip.offsetWidth;
    const token = ++rouletteSpinToken;
    let duration = state.spinSeconds || 6;
    if (instant === true) {
        duration = 0;
    } else if (state.status === "spinning" && state.spinningStartedAt) {
        const elapsedSec = Math.max(0, (Date.now() - state.spinningStartedAt) / 1e3);
        duration = Math.max(.6, (state.spinSeconds || 6) - elapsedSec);
    }
    requestAnimationFrame(() => {
        if (token !== rouletteSpinToken) return;
        const wrapW = wrapEl ? wrapEl.clientWidth : 320;
        const targetEl = strip.children[targetIdx];
        const offset = targetEl ? targetEl.offsetLeft + targetEl.offsetWidth / 2 - wrapW / 2 : 0;
        if (duration <= 0) {
            strip.style.transition = "none";
            strip.style.transform = "translateX(-" + offset + "px)";
            if (targetEl) targetEl.classList.add("highlight");
            return;
        }
        strip.style.transition = "transform " + duration + "s " + ROULETTE_SPIN_EASE;
        strip.style.transform = "translateX(-" + offset + "px)";
        if (wrapEl) requestAnimationFrame(() => rouletteFollowPointerHighlight(strip, wrapEl, token));
    });
}

function rouletteBetsColHTML(color, list, total) {
    return '<div class="roulette-bets-col roulette-bets-col-' + color + '">' + '<div class="roulette-bets-col-head">' + '<span class="roulette-bets-col-swatch roulette-cell-' + color + '"></span>' + '<span class="roulette-bets-col-total">Общая сумма ставок: <b>' + fmtNum(total) + "⭐️</b></span>" + "</div>" + '<div class="roulette-bets-col-list">' + (list.length ? list.slice(0, 10).map((p, i) => '<div class="roulette-bets-row' + (p.id === CURRENT_UID ? " me" : "") + '">' + '<span class="roulette-bets-row-i">' + (i + 1) + "</span>" + '<div class="roulette-bets-row-avatar"><img src="/api/avatar/' + p.id + '" alt="" loading="lazy"></div>' + '<span class="roulette-bets-row-name">' + escapeHtml(p.username) + "</span>" + '<span class="roulette-bets-row-amount">' + fmtNum(p.bet) + "⭐️</span>" + "</div>").join("") : '<div class="roulette-bets-empty">Пока пусто</div>') + "</div>" + "</div>";
}

function rouletteBetsHTML(state) {
    if (!state) return "";
    const byColor = state.betsByColor || {
        red: [],
        black: [],
        green: []
    };
    const totals = state.totalsByColor || {
        red: 0,
        black: 0,
        green: 0
    };
    return '<div class="roulette-bets-columns">' + ["red", "black", "green"].map(c => rouletteBetsColHTML(c, byColor[c] || [], totals[c] || 0)).join("") + "</div>";
}

function rouletteHistoryChipsHTML(state) {
    const hist = state && state.history || [];
    if (!hist.length) return '<div class="crash-players-empty" style="margin:0 16px;">Пока нет завершённых раундов</div>';
    return '<div class="gv-mult-row">' + hist.slice(0, 15).map((h, i) => (i > 0 ? '<span class="gv-mult-arrow">›</span>' : "") + '<span class="gv-mult-chip roulette-hist-chip-' + h.color + (i === 0 ? " now" : "") + '" data-roulette-round="' + escapeHtml(h.roundId) + '">' + rouletteColorIconHTML(h.color) + " x" + fmtMult(h.mult) + "</span>").join("") + "</div>";
}

function rouletteCountdownSeconds(state) {
    if (!state.waitingStartedAt) return state.waitSeconds || 15;
    const remainMs = state.waitingStartedAt + state.waitSeconds * 1e3 - Date.now();
    return Math.max(1, Math.ceil(remainMs / 1e3));
}

function rouletteStatusLineHTML(state) {
    if (!state) return "Загрузка…";
    if (state.status === "waiting") {
        return '<div class="roulette-status-title">Начало через:</div><div class="roulette-status-count">' + rouletteCountdownSeconds(state) + " секунд</div>";
    }
    if (state.status === "spinning") return '<div class="roulette-status-spinning"><img src="ИграРулетка/СтавкиЗакрыты.png" alt="">Ставки закрыты</div>';
    if (state.status === "resolved") return "Выпало: <b>" + rouletteColorIconHTML(state.outcomeColor) + " " + ROULETTE_COLOR_LABEL[state.outcomeColor] + " x" + fmtMult(state.outcomeMult) + "</b>";
    return "";
}

function rouletteBoxSkeletonHTML() {
    return '<div class="skel-box" style="width:130px; height:16px; border-radius:6px; margin-bottom:12px;"></div>' + '<div style="display:flex; gap:8px;">' + Array.from({
        length: 7
    }).map(() => '<div class="skel-box" style="width:48px; height:60px; border-radius:12px;"></div>').join("") + "</div>";
}

function renderRoulette() {
    return '<div class="crash-history-row" id="rouletteHistoryChips">' + crashChipsSkeletonHTML() + "</div>" + '<div class="gv-crash-box roulette-box" id="rouletteBox">' + rouletteBoxSkeletonHTML() + "</div>" + '<div class="gv-fair-row">' + '<div class="gv-fair" data-action="roulette-fair"><span class="gv-fair-icon">#</span><span id="rouletteRoundIdLabel">—</span></div>' + howtoHTML() + "</div>" + rouletteBetsHTML({
        betsByColor: {
            red: [],
            black: [],
            green: []
        },
        totalsByColor: {
            red: 0,
            black: 0,
            green: 0
        }
    }) + rouletteColorsRowHTML(null) + '<div class="wheel-my-bets" id="rouletteMyBets" style="display:none;"></div>' + '<div class="gv-panel" id="roulettePanel">' + '<div class="gv-label" id="rouletteBetLabel">Сумма ставки</div>' + betRowHTML() + '<div class="wheel-bet-summary" id="rouletteBetSummary" style="display:none;"></div>' + "</div>" + '<button class="gv-start-btn dim" id="rouletteBetBtn" type="button">Выберите исход</button>' + '<div class="gv-history">' + '<div class="gv-history-head">' + '<h3 class="gv-history-title">' + lazyImgTag(liteAsset("/lottie/images/ОгоньЭмоджи.lottie"), "", "flame-gif") + " Последние игры</h3>" + '<div class="gv-history-tabs">' + '<button class="gv-history-tab active" type="button" data-roulette-scope="all">Все</button>' + '<button class="gv-history-tab" type="button" data-roulette-scope="mine">Мои</button>' + "</div>" + "</div>" + gvHistorySearchRowHTML("rouletteHistorySearchInput") + '<div class="gv-history-list" id="rouletteHistoryList">' + crashHistorySkeletonHTML() + "</div>" + "</div>";
}

function rouletteBetBtnState(state) {
    if (!state) return {
        text: "Загрузка…",
        mode: "off"
    };
    if (rouletteBusy) return {
        text: "…",
        mode: "off"
    };
    const mine = state.myBets || [];
    const count = rouletteSelColors.size;
    if (mine.length && state.status === "resolved") {
        const won = mine.reduce((sum, b) => sum + (b.winAmount || 0), 0);
        return {
            text: won > 0 ? "Выигрыш +" + fmtNum(won) + "⭐️" : mine.length > 1 ? "Ставки не сыграли" : "Ставка не сыграла",
            mode: "off done"
        };
    }
    if (state.myQueued && !count) return {
        text: "В очереди на след. раунд",
        mode: "off"
    };
    if (!betsAccepted) return {
        text: "Ставки приостановлены",
        mode: "off"
    };
    if (!count) {
        if (mine.length) return {
            text: mine.length === 1 ? "Ставка сделана: " + ROULETTE_COLOR_LABEL[mine[0].color] : "Ставок сделано: " + mine.length + " · выберите ещё",
            mode: "off"
        };
        return {
            text: "Выберите исход",
            mode: "off"
        };
    }
    const amount = rouletteCurrentBetAmount();
    return {
        text: count > 1 && amount > 0 ? "Поставить " + fmtNum(Math.round(amount * count * 100) / 100) + "⭐️ · " + wheelCountWord(count) : "Сделать ставку",
        mode: "bet"
    };
}

function updateRouletteBetBtn() {
    const btn = document.getElementById("rouletteBetBtn");
    if (!btn || !rouletteState) return;
    const st = rouletteBetBtnState(rouletteState);
    btn.textContent = st.text;
    btn.classList.toggle("dim", st.mode === "off");
    btn.classList.toggle("crash-done-btn", st.mode === "off done");
    updateRouletteBetSummary();
}

function updateRouletteLocks(state) {
    const locked = !!(state && state.status !== "waiting");
    const betInput = gvBody.querySelector(".gv-bet-input");
    if (betInput) {
        betInput.disabled = locked;
        betInput.classList.toggle("crash-frozen", locked);
    }
    document.querySelectorAll(".roulette-color-btn").forEach(b => {
        b.disabled = locked || b.classList.contains("placed");
    });
    const panel = document.getElementById("roulettePanel");
    if (panel) panel.classList.toggle("locked", locked);
}

function renderRouletteDynamic(forceStageRebuild) {
    const state = rouletteState;
    if (!state) return;
    const statusLine = document.getElementById("rouletteStatusLine");
    if (statusLine) statusLine.innerHTML = rouletteStatusLineHTML(state);
    if (forceStageRebuild || state.status !== rouletteLastStatus) {
        if (rouletteLastStatus === null) {
            const box = document.getElementById("rouletteBox");
            if (box) box.innerHTML = rouletteBoxHTML(state);
            if (state.status === "resolved") {
                rouletteAnimateStrip(state, true);
            } else if (state.status === "spinning") {
                rouletteAnimateStrip(state, false);
            }
        } else if (state.status === "spinning" && rouletteLastStatus === "waiting") {
            rouletteAnimateStrip(state);
        } else if (state.status === "waiting") {
            const box = document.getElementById("rouletteBox");
            if (box) box.innerHTML = rouletteBoxHTML(state);
        }
        rouletteLastStatus = state.status;
    }
    const roundLabel = document.getElementById("rouletteRoundIdLabel");
    if (roundLabel) roundLabel.textContent = state.roundId != null ? state.roundId : "—";
    const colorsRow = document.getElementById("rouletteColorsRow");
    if (colorsRow) colorsRow.outerHTML = rouletteColorsRowHTML(state);
    const betsWrap = gvBody.querySelector(".roulette-bets-columns");
    if (betsWrap) {
        const betsSig = JSON.stringify(state.betsByColor) + "|" + JSON.stringify(state.totalsByColor);
        if (betsSig !== rouletteBetsSignature) {
            rouletteBetsSignature = betsSig;
            betsWrap.outerHTML = rouletteBetsHTML(state);
        }
    }
    const chips = document.getElementById("rouletteHistoryChips");
    if (chips) {
        const sig = (state.history || []).map(h => h.roundId).join(",");
        if (sig !== rouletteChipsSignature) {
            rouletteChipsSignature = sig;
            chips.innerHTML = rouletteHistoryChipsHTML(state);
        }
    }
    updateRouletteBetBtn();
    updateRouletteMyBets(state);
    updateRouletteLocks(state);
    const hideBetUI = state.status !== "waiting";
    ["rouletteColorsRow", "roulettePanel", "rouletteBetBtn"].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.style.display = hideBetUI ? "none" : "";
    });
}

function rouletteTick() {
    if (!rouletteState) return;
    const statusLine = document.getElementById("rouletteStatusLine");
    if (statusLine && rouletteState.status === "waiting") statusLine.innerHTML = rouletteStatusLineHTML(rouletteState);
}

function loadRouletteState() {
    fetch("/api/roulette/state?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (!data || !data.ok) return;
        const statusChanged = rouletteState && rouletteState.status !== data.status;
        rouletteState = data;
        if (data.balance !== undefined) applyBalance(data.balance);
        if (statusChanged && gvFairModal.classList.contains("active") && currentGame === "рулетка") {
            openRouletteFair();
        }
        renderRouletteDynamic(false);
        if (statusChanged && data.status === "resolved" && data.myBets && data.myBets.length) {
            const staked = data.myBets.reduce((sum, b) => sum + b.bet, 0);
            const won = data.myBets.reduce((sum, b) => sum + (b.winAmount || 0), 0);
            if (won >= staked) showGameWinToast(won);
            else if (won > 0) showToast("Выплата +" + fmtNum(won) + "⭐️ из " + fmtNum(Math.round(staked * 100) / 100) + "⭐️ ставок", "warning");
            else showGameLoseToast(data.myBets.length > 1 ? "Ставки не сыграли" : "Ставка не сыграла");
        }
        if (statusChanged && data.status === "waiting") {
            rouletteSelColors.clear();
            loadRouletteHistory(rouletteHistoryScope);
        }
    }).catch(() => {});
}

function startRoulettePolling() {
    rouletteState = null;
    rouletteLastStatus = null;
    rouletteHistoryScope = "all";
    rouletteChipsSignature = null;
    rouletteBetsSignature = null;
    rouletteSelColors.clear();
    loadRouletteState();
    loadRouletteHistory(rouletteHistoryScope);
    gvHistoryWireSearch("rouletteHistorySearchInput", () => loadRouletteHistory(rouletteHistoryScope), value => {
        gvHistorySearch("rouletteHistoryList", () => "/api/roulette/history?uid=" + CURRENT_UID + "&scope=" + rouletteHistoryScope + "&q=" + encodeURIComponent(value), rows => {
            document.getElementById("rouletteHistoryList").innerHTML = rows.map(rouletteHistoryRowHTML).join("");
        });
    });
    stopRoulettePolling();
    roulettePollTimer = setInterval(loadRouletteState, ROULETTE_POLL_MS);
}

function stopRoulettePolling() {
    if (roulettePollTimer) {
        clearInterval(roulettePollTimer);
        roulettePollTimer = null;
    }
}

function rouletteSelectColor(color) {
    if (!rouletteState || rouletteState.status !== "waiting") return;
    if (roulettePlacedMap(rouletteState)[color]) return;
    if (rouletteSelColors.has(color)) rouletteSelColors.delete(color);
    else rouletteSelColors.add(color);
    const colorsRow = document.getElementById("rouletteColorsRow");
    if (colorsRow) colorsRow.outerHTML = rouletteColorsRowHTML(rouletteState);
    updateRouletteLocks(rouletteState);
    updateRouletteBetBtn();
}

function rouletteBetBtnClick() {
    if (!rouletteState || rouletteBusy) return;
    const st = rouletteBetBtnState(rouletteState);
    if (st.mode !== "bet") return;
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const betInput = gvBody.querySelector(".gv-bet-input");
    const bet = amountValue(betInput ? betInput.value : "");
    if (!(bet > 0)) {
        showToast("Введите сумму ставки", "error");
        return;
    }
    const count = rouletteSelColors.size;
    const total = Math.round(bet * count * 100) / 100;
    if (total > currentUser.balance) {
        showToast(count > 1 ? "Недостаточно средств: нужно " + fmtNum(total) + "⭐️ (" + wheelCountWord(count) + " по " + fmtNum(bet) + "⭐️)" : "Недостаточно средств на балансе", "error");
        return;
    } {
        const limitIssue = betLimitIssue("roulette", bet);
        if (limitIssue) {
            showToast(limitIssue, "error");
            return;
        }
    }
    const items = Array.from(rouletteSelColors).map(c => ({
        color: c,
        bet: bet
    }));
    rouletteBusy = true;
    updateRouletteBetBtn();
    fetch("/api/roulette/bet", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            items: items
        })
    }).then(r => r.json()).then(data => {
        rouletteBusy = false;
        if (!data || !data.ok) {
            showToast(data && data.error || "Ошибка сервера", "error");
            updateRouletteBetBtn();
            return;
        }
        applyBalance(data.balance);
        rouletteSelColors.clear();
        rouletteState = data;
        renderRouletteDynamic(false);
        showToast(data.myQueued ? "Ставки встанут в следующий раунд" : count > 1 ? "Ставки приняты: " + wheelCountWord(count) : "Ставка принята", "success");
    }).catch(() => {
        rouletteBusy = false;
        showToast("Не удалось связаться с сервером", "error");
        updateRouletteBetBtn();
    });
}

gvBody.addEventListener("input", e => {
    if (currentGame === "рулетка" && e.target && e.target.classList && e.target.classList.contains("gv-bet-input")) updateRouletteBetBtn();
});

gvBody.addEventListener("click", e => {
    if (currentGame === "рулетка" && e.target.closest(".gv-bet-row .gv-chip")) setTimeout(updateRouletteBetBtn, 0);
});

function rouletteHistoryRowHTML(r) {
    let meta = {};
    try {
        meta = JSON.parse(r.meta || "{}");
    } catch (e) {}
    const isWin = r.result === "win";
    const isMe = r.user_id === CURRENT_UID;
    const name = isMe ? currentUser.displayName || "Игрок" : r.username || "Игрок";
    const avatarUrl = isMe ? currentUser.avatarUrl : "/api/avatar/" + r.user_id;
    const myColorLabel = meta.myColor ? ROULETTE_COLOR_LABEL[meta.myColor] : "—";
    const outcomeColorLabel = meta.outcomeColor ? rouletteColorIconHTML(meta.outcomeColor) + " " + ROULETTE_COLOR_LABEL[meta.outcomeColor] : "—";
    return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-avatar"><div class="skel-box"></div>' + lazyImgTag(avatarUrl, name) + "</div>" + '<div class="gv-history-mid">' + '<div class="gv-history-name">' + escapeHtml(name) + "</div>" + historyTimeHTML(r.created_at) + "</div>" + '<div class="gv-history-right">Ставка на: <b>' + myColorLabel + "</b><br>" + '<span class="gv-history-outcome">Выпало: ' + outcomeColorLabel + "</span><br>" + (isWin ? '<span class="gv-history-win">Выигрыш: ' + fmtNum(r.win_amount) + "⭐️</span>" : '<span class="gv-history-lose">Проигрыш</span>') + "</div>" + "</div>" + (meta.roundId ? '<button class="crash-history-fair-btn" type="button" data-roulette-round="' + escapeHtml(meta.roundId) + '">' + fairCheckBtnIconHTML() + "Проверить честность</button>" : "") + "</div>";
}

function loadRouletteHistory(scope, append) {
    if (scope) {
        rouletteHistoryScope = scope;
        append = false;
    }
    gvHistoryLoad("rouletteHistoryList", off => "/api/roulette/history?uid=" + CURRENT_UID + "&scope=" + rouletteHistoryScope + "&offset=" + off, 20, (rows, append) => {
        const list = document.getElementById("rouletteHistoryList");
        const html = rows.map(rouletteHistoryRowHTML).join("");
        if (append) list.insertAdjacentHTML("beforeend", html);
        else list.innerHTML = html;
    }, GV_HISTORY_EMPTY_HTML, append);
}

GV_HISTORY_BY_GAME["рулетка"] = {
    listId: "rouletteHistoryList",
    load: () => loadRouletteHistory(null, true)
};

function rouletteFairFormulaHTML(outcomeColor, outcomeMult) {
    return '<p class="modal-text">Секретный сид этого раунда был скрыт до его завершения, а его SHA-256-хэш публиковался ещё ДО начала приёма ставок — это и есть гарантия честности: если сид ниже не совпадает с тем хэшем, значит его подменили задним числом под чью-то ставку.</p>' + '<p class="modal-text">Выигравший цвет вычисляется из HMAC-SHA256(сид, UID раунда) детерминированным алгоритмом с разбивкой на кумулятивные веса цветов — то есть однозначно определён сидом и не может быть подобран или изменён постфактум, независимо от того, кто и сколько поставил.</p>' + (outcomeColor ? '<p class="modal-text">Раунд завершился на <b>' + rouletteColorIconHTML(outcomeColor) + " " + ROULETTE_COLOR_LABEL[outcomeColor] + " x" + fmtMult(outcomeMult) + "</b>.</p>" : "");
}

function openRouletteFair() {
    const state = rouletteState;
    const roundId = state && state.roundId != null ? state.roundId : "—";
    gvFairId.textContent = roundId;
    gvFairId.classList.remove("text-skel");
    setFairHashEl(gvFairHash, state && state.seedHash || "Загрузка…");
    let resultHtml = '<div class="fair-block"><div class="fair-label">UID раунда</div><div class="fair-hash" data-copy="' + escapeHtml(roundId) + '">' + fairHashHTML(roundId) + "</div></div>";
    if (state && state.status === "resolved" && state.serverSeed) {
        resultHtml += '<div class="fair-block"><div class="fair-label">Секретный сид</div><div class="fair-hash" data-copy="' + escapeHtml(state.serverSeed) + '">' + fairHashHTML(state.serverSeed) + "</div></div>" + '<div class="fair-block"><div class="fair-label">Выпало</div><div class="fair-result">' + rouletteColorIconHTML(state.outcomeColor) + " " + ROULETTE_COLOR_LABEL[state.outcomeColor] + " x" + fmtMult(state.outcomeMult) + "</div></div>";
        gvFairNote.style.display = "";
        gvFairNote.innerHTML = rouletteFairFormulaHTML(state.outcomeColor, state.outcomeMult);
    } else {
        resultHtml += '<div class="fair-result-note">Раунд ещё не завершён — сид раскроется сразу после результата. Окно обновляется само.</div>';
        gvFairNote.style.display = "none";
    }
    gvFairResult.innerHTML = resultHtml;
    gvFairLink.style.display = "none";
    gvFairModal.classList.add("active");
}

const rouletteRoundModal = document.getElementById("rouletteRoundModal");

const rouletteRoundReplay = document.getElementById("rouletteRoundReplay");

const rouletteRoundPlayers = document.getElementById("rouletteRoundPlayers");

const rouletteRoundFairBlock = document.getElementById("rouletteRoundFairBlock");

let rouletteReplayTimer = null;

let rouletteReplayData = null;

let rouletteReplaySpinToken = 0;

function stopRouletteReplay() {
    if (rouletteReplayTimer) {
        clearTimeout(rouletteReplayTimer);
        rouletteReplayTimer = null;
    }
}

function rouletteReplayStageHTML(statusText) {
    return '<div class="roulette-status-line" id="rouletteReplayStatus">' + statusText + "</div>" + '<div class="roulette-strip-wrap">' + '<div class="roulette-pointer"></div>' + '<div class="roulette-strip" id="rouletteReplayStrip"></div>' + "</div>";
}

function rouletteReplayCountdownTextHTML(seconds) {
    return '<div class="roulette-status-title">Начало раунда</div><div class="roulette-status-count">Через ' + seconds + " секунды…</div>";
}

function playRouletteReplayCountdown(seconds, onDone) {
    rouletteRoundReplay.innerHTML = rouletteReplayStageHTML(rouletteReplayCountdownTextHTML(seconds));
    const stripEl = document.getElementById("rouletteReplayStrip");
    if (stripEl) stripEl.innerHTML = rouletteCellsHTML(rouletteIdleCells(rouletteState));
    const step = () => {
        seconds -= 1;
        const el = document.getElementById("rouletteReplayStatus");
        if (!el) return;
        if (seconds <= 0) {
            onDone();
            return;
        }
        el.innerHTML = rouletteReplayCountdownTextHTML(seconds);
        rouletteReplayTimer = setTimeout(step, 1e3);
    };
    rouletteReplayTimer = setTimeout(step, 1e3);
}

function rouletteFollowPointerHighlightReplay(strip, wrapEl, token, prevMatch) {
    if (token !== rouletteReplaySpinToken) return;
    const wrapW = wrapEl.clientWidth;
    const match = rouletteCellUnderPointer(strip, wrapW);
    for (const child of strip.children) {
        if (child !== match) child.classList.remove("highlight");
    }
    if (match) match.classList.add("highlight");
    if (match && match !== prevMatch) haptic("selection");
    requestAnimationFrame(() => rouletteFollowPointerHighlightReplay(strip, wrapEl, token, match));
}

function playRouletteReplaySpin(data, onDone) {
    rouletteRoundReplay.innerHTML = rouletteReplayStageHTML("Крутим…");
    const strip = document.getElementById("rouletteReplayStrip");
    if (!strip) {
        if (onDone) onDone();
        return;
    }
    const wrapEl = strip.parentElement;
    const {
        cells: cells,
        targetIdx: targetIdx
    } = rouletteBuildStripCells(data.outcomeColor, data);
    strip.style.transition = "none";
    strip.style.transform = "translateX(0)";
    strip.innerHTML = rouletteCellsHTML(cells);
    void strip.offsetWidth;
    const token = ++rouletteReplaySpinToken;
    const spinSeconds = 3.5;
    requestAnimationFrame(() => {
        if (token !== rouletteReplaySpinToken) return;
        const wrapW = wrapEl ? wrapEl.clientWidth : 320;
        const targetEl = strip.children[targetIdx];
        const offset = targetEl ? targetEl.offsetLeft + targetEl.offsetWidth / 2 - wrapW / 2 : 0;
        strip.style.transition = "transform " + spinSeconds + "s " + ROULETTE_SPIN_EASE;
        strip.style.transform = "translateX(-" + offset + "px)";
        if (wrapEl) requestAnimationFrame(() => rouletteFollowPointerHighlightReplay(strip, wrapEl, token));
        rouletteReplayTimer = setTimeout(() => {
            if (token !== rouletteReplaySpinToken) return;
            const statusEl = document.getElementById("rouletteReplayStatus");
            if (statusEl) statusEl.innerHTML = "Выпало: <b>" + rouletteColorIconHTML(data.outcomeColor) + " " + ROULETTE_COLOR_LABEL[data.outcomeColor] + " x" + fmtMult(data.outcomeMult) + "</b>";
            if (targetEl) targetEl.classList.add("highlight");
            if (onDone) onDone();
        }, spinSeconds * 1e3 + 100);
    });
}

function rouletteRoundBetsHTML(bets, outcomeColor) {
    if (!bets || !bets.length) return '<div class="crash-players-empty">В этом раунде не было ставок!</div>';
    return '<div class="crash-players-title"><span>Ставки раунда</span><span>' + bets.length + "</span></div>" + '<div class="crash-players-list">' + bets.map(p => {
        const isMe = p.id === CURRENT_UID;
        const isWin = p.color === outcomeColor;
        return '<div class="crash-player-row' + (isWin ? " cashed" : " lost") + (isMe ? " me" : "") + '">' + '<div class="crash-player-avatar"><img src="/api/avatar/' + p.id + '" alt="" loading="lazy"></div>' + '<div class="crash-player-mid">' + '<div class="crash-player-name"><span class="crash-player-name-text">' + escapeHtml(p.username) + "</span>" + (isMe ? ' <span class="lb-you-tag">Вы</span>' : "") + "</div>" + '<div class="crash-player-sub">Ставка на: ' + rouletteColorIconHTML(p.color) + " " + ROULETTE_COLOR_LABEL[p.color] + " · " + fmtNum(p.bet) + "⭐️</div>" + "</div>" + '<div class="crash-player-value">' + (isWin ? "+" + fmtNum(p.winAmount) + "⭐️" : "Проигрыш") + "</div>" + "</div>";
    }).join("") + "</div>";
}

function openRouletteRoundModal(publicId) {
    if (!publicId) return;
    stopRouletteReplay();
    rouletteReplayData = null;
    rouletteRoundFairBlock.style.display = "none";
    rouletteRoundFairBlock.innerHTML = "";
    document.getElementById("rouletteRoundFairBtn").textContent = "Проверить честность";
    document.getElementById("rouletteRoundModalId").textContent = publicId;
    rouletteRoundReplay.innerHTML = rouletteReplayStageHTML("Загрузка…");
    rouletteRoundPlayers.innerHTML = crashPlayersSkeletonHTML();
    rouletteRoundModal.classList.add("active");
    fetch("/api/roulette/round?id=" + encodeURIComponent(publicId)).then(r => r.json()).then(data => {
        if (!rouletteRoundModal.classList.contains("active")) return;
        if (!data || !data.ok) {
            rouletteRoundReplay.innerHTML = '<div class="crash-players-empty">Раунд не найден</div>';
            return;
        }
        rouletteReplayData = data;
        rouletteRoundPlayers.innerHTML = rouletteRoundBetsHTML(data.bets || [], data.outcomeColor);
        playRouletteReplayCountdown(3, () => {
            playRouletteReplaySpin(data, () => {});
        });
    }).catch(() => {
        rouletteRoundReplay.innerHTML = '<div class="crash-players-empty">Не удалось загрузить раунд</div>';
    });
}

function closeRouletteRoundModal() {
    stopRouletteReplay();
    rouletteRoundModal.classList.remove("active");
}

document.getElementById("rouletteRoundClose").addEventListener("click", closeRouletteRoundModal);

rouletteRoundModal.addEventListener("click", e => {
    if (e.target === rouletteRoundModal) closeRouletteRoundModal();
});

document.getElementById("rouletteRoundFairBtn").addEventListener("click", () => {
    const data = rouletteReplayData;
    if (!data) return;
    const isHidden = rouletteRoundFairBlock.style.display === "none";
    if (isHidden) {
        rouletteRoundFairBlock.innerHTML = '<div class="fair-block"><div class="fair-label">UID раунда</div><div class="fair-hash" data-copy="' + escapeHtml(data.roundId) + '">' + fairHashHTML(data.roundId) + "</div></div>" + '<div class="fair-block"><div class="fair-label">SHA-256 hash</div><div class="fair-hash" data-copy="' + escapeHtml(data.seedHash || "") + '">' + fairHashHTML(data.seedHash || "—") + "</div></div>" + '<div class="fair-block"><div class="fair-label">Секретный сид</div><div class="fair-hash" data-copy="' + escapeHtml(data.serverSeed || "") + '">' + fairHashHTML(data.serverSeed || "—") + "</div></div>" + rouletteFairFormulaHTML(data.outcomeColor, data.outcomeMult);
        rouletteRoundFairBlock.style.display = "";
        document.getElementById("rouletteRoundFairBtn").textContent = "Скрыть информацию";
    } else {
        rouletteRoundFairBlock.style.display = "none";
        document.getElementById("rouletteRoundFairBtn").textContent = "Проверить честность";
    }
});

const WT_ORDER = [0, 32, 15, 19, 4, 21, 2, 25, 17, 34, 6, 27, 13, 36, 11, 30, 8, 23, 10, 5, 24, 16, 33, 1, 20, 14, 31, 9, 22, 18, 29, 7, 28, 12, 35, 3, 26];

const WHEEL_POCKETS = WT_ORDER;

const WT_RED = new Set([1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36]);

const WT_STEP = 360 / 37;

const WT_SPIN_MS = 10500;

const WT_DEFAULT_MULT = {
    straight: 36,
    split: 18,
    corner: 9,
    column: 3,
    dozen: 3,
    even: 2
};

const WT_COLOR_NAME = {
    red: "Красное",
    black: "Чёрное",
    green: "Зелёное"
};

function wheelColorOfNumber(n) {
    if (n === 0) return "green";
    return WT_RED.has(n) ? "red" : "black";
}

function wheelCountWord(n) {
    const t = n % 10,
        h = n % 100;
    return n + " " + (t === 1 && h !== 11 ? "исход" : t >= 2 && t <= 4 && (h < 10 || h >= 20) ? "исхода" : "исходов");
}

function wheelSectorLabel(key) {
    return {
        col1: "Колонна 1 (2:1)",
        col2: "Колонна 2 (2:1)",
        col3: "Колонна 3 (2:1)",
        doz1: "Дюжина 1–12",
        doz2: "Дюжина 13–24",
        doz3: "Дюжина 25–36"
    }[key] || key;
}

const WT_CAT = function() {
    const cat = {};
    const put = (key, kind, nums, label) => {
        cat[key] = {
            kind: kind,
            nums: nums,
            label: label
        };
    };
    for (let n = 0; n <= 36; n++) put("n:" + n, "straight", [n], "Число " + n);
    for (let n = 1; n <= 36; n++) {
        if (n % 3 !== 0) put("s:" + n + "-" + (n + 1), "split", [n, n + 1], "Сплит " + n + "/" + (n + 1));
        if (n + 3 <= 36) put("s:" + n + "-" + (n + 3), "split", [n, n + 3], "Сплит " + n + "/" + (n + 3));
    }
    for (let n = 1; n <= 3; n++) put("s:0-" + n, "split", [0, n], "Сплит 0/" + n);
    for (let n = 1; n <= 32; n++) {
        if (n % 3 !== 0) put("c:" + n + "-" + (n + 1) + "-" + (n + 3) + "-" + (n + 4), "corner", [n, n + 1, n + 3, n + 4], "Угол " + n + "/" + (n + 1) + "/" + (n + 3) + "/" + (n + 4));
    }
    const range = (a, b, step) => {
        const out = [];
        for (let i = a; i <= b; i += step || 1) out.push(i);
        return out;
    };
    put("col1", "column", range(1, 34, 3), "Колонна 1 (2:1)");
    put("col2", "column", range(2, 35, 3), "Колонна 2 (2:1)");
    put("col3", "column", range(3, 36, 3), "Колонна 3 (2:1)");
    put("doz1", "dozen", range(1, 12), "Дюжина 1–12");
    put("doz2", "dozen", range(13, 24), "Дюжина 13–24");
    put("doz3", "dozen", range(25, 36), "Дюжина 25–36");
    put("low", "even", range(1, 18), "1–18");
    put("high", "even", range(19, 36), "19–36");
    put("even", "even", range(2, 36, 2), "Чётное");
    put("odd", "even", range(1, 35, 2), "Нечётное");
    put("red", "even", range(1, 36).filter(n => WT_RED.has(n)), "Красное");
    put("black", "even", range(1, 36).filter(n => !WT_RED.has(n)), "Чёрное");
    return cat;
}();

let wtState = null;

let wtBusy = false;

let wtLast = null;

let wtLastBets = null;

let wtWheelBase = 0;

let wtRecent = [];

let wtUndo = [];

let wtEls = null;

let wtPhase = "bet";

let wtSpinTimer = null;

let wtResTimer = null;

let wtSpinHandle = null;

let wtPendingBalance = null;

let wtReplayHandle = null;

let wtReplayTimer = null;

let wheelReplayData = null;

let wheelHistoryScope = "all";

const wtBets = new Map;

function wtMult(kind) {
    const m = wtState && wtState.mults && wtState.mults[kind];
    return m > 0 ? m : WT_DEFAULT_MULT[kind];
}

function wtTone(v) {
    return v < 5 ? 0 : v < 10 ? 1 : v < 25 ? 2 : v < 50 ? 3 : v < 100 ? 4 : v < 500 ? 5 : v < 2500 ? 6 : 7;
}

function wtShort(v) {
    v = Math.round(v * 100) / 100;
    if (v >= 1e6) return Math.round(v / 1e5) / 10 + "M";
    if (v >= 1e4) return Math.round(v / 1e3) + "K";
    if (v >= 1e3) return Math.round(v / 100) / 10 + "K";
    if (v >= 100) return String(Math.round(v));
    if (v >= 10) return String(Math.round(v * 10) / 10);
    return String(v);
}

const WT_TRAY = [1, 5, 10, 25, 50, 100];

function wtChipClass(v, text) {
    return "wt-cc k" + wtTone(v) + (text.length >= 4 ? " l4" : text.length === 3 ? " l3" : "");
}

function wtTrayHTML() {
    return '<div class="wt-chips" id="wtTray">' + WT_TRAY.map(v => '<button class="wt-tc" type="button" data-wt-chip="' + v + '"><span class="' + wtChipClass(v, String(v)) + '">' + v + "</span></button>").join("") + "</div>";
}

function wtTotal() {
    let t = 0;
    wtBets.forEach(v => {
        t += v;
    });
    return Math.round(t * 100) / 100;
}

function wtChipValue() {
    const input = gvBody.querySelector(".gv-bet-input");
    const v = amountValue(input ? input.value : "");
    return v > 0 ? Math.round(v * 100) / 100 : 0;
}

function wtFacts(n) {
    if (n === 0) return "Зеро";
    const parts = [WT_COLOR_NAME[wheelColorOfNumber(n)], n % 2 === 0 ? "чёт" : "нечёт", n <= 18 ? "1–18" : "19–36", ["1-я", "2-я", "3-я"][Math.floor((n - 1) / 12)] + " дюжина", "колонна " + (n % 3 === 0 ? 3 : n % 3)];
    return parts.join(" · ");
}

function wtBadgeHTML(n, extra) {
    return '<span class="wt-badge wt-b-' + wheelColorOfNumber(n) + (extra ? " " + extra : "") + '">' + n + "</span>";
}

function wtHotHTML(key, type, x, y) {
    return '<i class="wt-hs wt-h' + type + '" data-wt="' + key + '" style="--x:' + x + ";--y:" + y + '"></i>';
}

function wtBoardHTML() {
    let inside = '<button class="wt-cell wt-green wt-zero" type="button" data-wt="n:0"><span class="wt-n">0</span></button>';
    for (let n = 1; n <= 36; n++) inside += '<button class="wt-cell wt-' + wheelColorOfNumber(n) + '" type="button" data-wt="n:' + n + '"><span class="wt-n">' + n + "</span></button>";
    let hot = "";
    for (let c = 0; c < 3; c++) hot += wtHotHTML("s:0-" + (c + 1), "h", c + .5, 1);
    for (let k = 1; k <= 12; k++) {
        for (let c = 0; c < 3; c++) {
            const n = (k - 1) * 3 + c + 1;
            if (c < 2) hot += wtHotHTML("s:" + n + "-" + (n + 1), "v", c + 1, k + .5);
            if (k < 12) {
                hot += wtHotHTML("s:" + n + "-" + (n + 3), "h", c + .5, k + 1);
                if (c < 2) hot += wtHotHTML("c:" + n + "-" + (n + 1) + "-" + (n + 3) + "-" + (n + 4), "c", c + 1, k + 1);
            }
        }
    }
    const dz = [
        ["doz1", "1–12"],
        ["doz2", "13–24"],
        ["doz3", "25–36"]
    ].map(d => '<button class="wt-oc" type="button" data-wt="' + d[0] + '"><span class="wt-vt">' + d[1] + "</span></button>").join("");
    const outs = [
        ["low", '<span class="wt-vt">1–18</span>'],
        ["even", '<span class="wt-vt">ЧЁТ</span>'],
        ["red", '<span class="wt-dia wt-dia-red"></span>'],
        ["black", '<span class="wt-dia wt-dia-black"></span>'],
        ["odd", '<span class="wt-vt">НЕЧЁТ</span>'],
        ["high", '<span class="wt-vt">19–36</span>']
    ].map(o => '<button class="wt-oc" type="button" data-wt="' + o[0] + '">' + o[1] + "</button>").join("");
    const cols = ["col1", "col2", "col3"].map(k => '<button class="wt-oc wt-col" type="button" data-wt="' + k + '"><span>2:1</span></button>').join("");
    return '<div class="wt-board">' + '<div class="wt-dz">' + dz + "</div>" + '<div class="wt-inside">' + inside + hot + "</div>" + '<div class="wt-out">' + outs + "</div>" + '<div class="wt-cols">' + cols + "</div>" + "</div>";
}

function wtPt(r, deg) {
    const a = deg * Math.PI / 180;
    return (200 + r * Math.sin(a)).toFixed(2) + " " + (200 - r * Math.cos(a)).toFixed(2);
}

function wtWedge(r1, r2, i) {
    const a0 = (i - .5) * WT_STEP,
        a1 = (i + .5) * WT_STEP;
    return "M" + wtPt(r2, a0) + " A" + r2 + " " + r2 + " 0 0 1 " + wtPt(r2, a1) + " L" + wtPt(r1, a1) + " A" + r1 + " " + r1 + " 0 0 0 " + wtPt(r1, a0) + " Z";
}

const WT_DEPTH = 24;

function wtWallsHTML() {
    const rows = [
        [74, 30, 38, 1],
        [52, 19, 26, 1],
        [40, 13, 19, 1],
        [33, 10, 15, 1],
        [30, 9, 14, .92],
        [30, 9, 14, .78],
        [31, 8, 15, .58],
        [32, 8, 15, .34],
        [32, 8, 15, .12]
    ];
    let h = "";
    rows.forEach((c, i) => {
        h += '<i class="wt-wall" style="background:radial-gradient(circle closest-side,transparent 0 83.6%,rgba(' + c[0] + "," + c[1] + "," + c[2] + "," + c[3] + ') 84.2%);transform:translateZ(calc(var(--u) * -' + (4 * (i + 1)).toFixed(1) + '))"></i>';
    });
    return h;
}

function wtFunnelHTML() {
    const n = 8,
        R0 = 168,
        R1 = 143;
    let h = "";
    for (let i = 0; i < n; i++) {
        const t0 = i / n,
            t1 = (i + 1) / n;
        const ro = R0 - (R0 - R1) * t0,
            ri = R0 - (R0 - R1) * t1;
        const zMid = -WT_DEPTH * (t0 + t1) / 2;
        const lt = [118, 66, 44, 35, 30, 27, 24, 22][i],
            lm = [34, 27, 23, 20, 18, 17, 16, 15][i],
            lb = [14, 12, 11, 10, 9, 8, 8, 7][i];
        const wine = l => "rgb(" + Math.round(l * 1.22) + "," + Math.round(l * .78) + "," + Math.round(l * .82) + ")";
        const bg = "linear-gradient(180deg," + wine(lt) + "," + wine(lm) + " 46%," + wine(lb) + ")";
        h += '<i class="wt-fn" style="--a:' + (ri / 2).toFixed(2) + "%;--b:" + (ro / 2).toFixed(2) + "%;background:" + bg + ";transform:translateZ(calc(var(--u) * " + zMid.toFixed(1) + '))"></i>';
    }
    return h;
}

function wtBowlSVG(p) {
    return '<svg class="wt-bowl" viewBox="0 0 400 400" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">' + "<defs>" + '<mask id="' + p + 'bM" maskUnits="userSpaceOnUse" x="0" y="0" width="400" height="400"><rect width="400" height="400" fill="#000"/><circle cx="200" cy="200" r="199" fill="#fff"/><circle cx="200" cy="200" r="168.4" fill="#000"/></mask>' + '<linearGradient id="' + p + 'bRim" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#d8c9cc"/><stop offset=".16" stop-color="#7b6065"/><stop offset=".46" stop-color="#2e1318"/><stop offset="1" stop-color="#0e0508"/></linearGradient>' + '<radialGradient id="' + p + 'bTop" cx="200" cy="200" r="199" gradientUnits="userSpaceOnUse"><stop offset=".82" stop-color="#2a1217"/><stop offset=".93" stop-color="#1d0a0f"/><stop offset="1" stop-color="#0c0407"/></radialGradient>' + '<linearGradient id="' + p + 'bLit" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".22"/><stop offset=".42" stop-color="#fff" stop-opacity="0"/><stop offset=".78" stop-color="#000" stop-opacity=".2"/><stop offset="1" stop-color="#000" stop-opacity=".42"/></linearGradient>' + '<radialGradient id="' + p + 'bRed" cx="200" cy="372" r="150" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#b3182d" stop-opacity=".45"/><stop offset="1" stop-color="#b3182d" stop-opacity="0"/></radialGradient>' + '<linearGradient id="' + p + 'bSpec" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset=".5" stop-color="#fff" stop-opacity=".7"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>' + "</defs>" + '<g mask="url(#' + p + 'bM)">' + '<circle cx="200" cy="200" r="199" fill="url(#' + p + 'bRim)"/>' + '<circle cx="200" cy="200" r="195" fill="url(#' + p + 'bTop)"/>' + '<circle cx="200" cy="200" r="195" fill="url(#' + p + 'bRed)"/>' + '<circle cx="200" cy="200" r="195" fill="url(#' + p + 'bLit)"/>' + '<path d="M' + wtPt(182, -122) + " A182 182 0 0 1 " + wtPt(182, -52) + '" fill="none" stroke="url(#' + p + 'bSpec)" stroke-width="3.4" stroke-linecap="round"/>' + '<circle cx="200" cy="200" r="170.4" fill="none" stroke="#b9bec7" stroke-width="3.6"/>' + "</g></svg>";
}

function wtDiscSVG(p, withNumbers, base, d3) {
    let ring = "",
        bevel = "",
        labels = "";
    WT_ORDER.forEach((n, i) => {
        const col = wheelColorOfNumber(n);
        ring += '<path class="wt-pk ' + col + '" data-n="' + n + '" d="' + wtWedge(104, 139, i) + '"/>';
        bevel += '<path class="wt-pk2 ' + col + '" d="' + wtWedge(88, 104, i) + '"/>';
        if (withNumbers) labels += '<text class="wt-pn" x="200" y="75.6" transform="rotate(' + (i * WT_STEP).toFixed(3) + ' 200 200)">' + n + "</text>";
    });
    const tf = (d3 ? "translateZ(calc(var(--u) * -" + WT_DEPTH + ")) " : "") + "rotate(" + (base || 0).toFixed(2) + "deg)";
    return '<svg class="wt-disc" id="' + p + 'Disc" viewBox="0 0 400 400" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" style="transform:' + tf + '">' + "<defs>" + '<linearGradient id="' + p + 'dSil" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f6f8fa"/><stop offset=".5" stop-color="#9aa0aa"/><stop offset="1" stop-color="#e6e9ed"/></linearGradient>' + '<radialGradient id="' + p + 'dCone" cx="200" cy="170" r="110" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#31121a"/><stop offset=".6" stop-color="#1d0a0f"/><stop offset="1" stop-color="#0d0508"/></radialGradient>' + '<radialGradient id="' + p + 'dShade" cx="200" cy="200" r="141" gradientUnits="userSpaceOnUse"><stop offset=".72" stop-color="#000" stop-opacity=".3"/><stop offset=".9" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#fff" stop-opacity=".08"/></radialGradient>' + "</defs>" + '<g id="' + p + 'DiscG">' + '<circle cx="200" cy="200" r="144.5" fill="url(#' + p + 'dSil)"/>' + '<circle cx="200" cy="200" r="140.2" fill="#0d0d0f"/>' + ring + '<circle cx="200" cy="200" r="121" fill="none" stroke="url(#' + p + 'dShade)" stroke-width="35" pointer-events="none"/>' + labels + '<circle cx="200" cy="200" r="104" fill="none" stroke="url(#' + p + 'dSil)" stroke-width="3"/>' + bevel + '<circle cx="200" cy="200" r="88.6" fill="none" stroke="url(#' + p + 'dSil)" stroke-width="3.4"/>' + '<circle cx="200" cy="200" r="87" fill="url(#' + p + 'dCone)"/>' + '' + "</g></svg>";
}

function wtWheelHTML(p, withNumbers, base, d3) {
    return '<div class="wt-wh' + (d3 ? " wt-wh3" : "") + '" id="' + p + 'Wh">' + (d3 ? wtWallsHTML() + wtFunnelHTML() : "") + wtBowlSVG(p) + wtDiscSVG(p, withNumbers, base, d3) + (d3 ? '<i class="wt-cone"></i>' : "") + '<i class="wt-bsh" id="' + p + 'BallSh"></i><i class="wt-ball" id="' + p + 'Ball"></i>' + (d3 ? wtTurretHTML() : "") + "</div>";
}

let wtTurretCv = null;

function wtBuildTurret() {
    if (wtTurretCv) return wtTurretCv;
    const U = 4,
        WU = 40,
        VMIN = -10,
        VMAX = 100,
        E = 25 * Math.PI / 180;
    const sE = Math.sin(E),
        cE = Math.cos(E);
    const w = WU * U,
        h = (VMAX - VMIN) * U;
    const STEP = .2,
        N = 520;
    const R = new Float32Array(N),
        M = new Uint8Array(N);
    const seg = (h0, r0, h1, r1, m) => {
        const i0 = Math.round(h0 / STEP),
            i1 = Math.round(h1 / STEP);
        for (let i = i0; i <= i1; i++) {
            const t = i1 === i0 ? 0 : (i - i0) / (i1 - i0);
            const v = r0 + (r1 - r0) * t;
            if (v > R[i]) {
                R[i] = v;
                M[i] = m;
            }
        }
    };
    const curve = (h0, h1, fn, m) => {
        const n = Math.max(2, Math.round((h1 - h0) / STEP));
        for (let i = 0; i < n; i++) {
            const ta = i / n,
                tb = (i + 1) / n;
            seg(h0 + (h1 - h0) * ta, fn(ta), h0 + (h1 - h0) * tb, fn(tb), m);
        }
    };
    seg(0, 14, 1.2, 16.6, 0);
    seg(1.2, 16.6, 1.4, 17, 0);
    seg(1.4, 17, 5.2, 17, 0);
    seg(5.2, 17, 5.6, 15.6, 0);
    seg(5.6, 15.6, 6.4, 15, 0);
    seg(6.4, 15, 6.8, 12.6, 0);
    curve(6.8, 24, t => 4.7 + 7.9 * Math.pow(1 - t, 2.3), 0);
    seg(24, 4.7, 24.4, 6.7, 0);
    seg(24.4, 6.7, 26.6, 6.7, 0);
    seg(26.6, 6.7, 27, 4.1, 0);
    seg(27, 4.1, 41, 4.1, 1);
    seg(41, 4.1, 41.4, 7.5, 0);
    seg(41.4, 7.5, 43, 7.5, 0);
    seg(43, 7.5, 43.4, 4.5, 0);
    curve(43.4, 60, t => 4.5 + 5.4 * Math.pow(Math.sin(Math.PI * t), .8), 0);
    seg(60, 4.5, 68, 3.7, 0);
    seg(68, 3.7, 68.4, 8.7, 0);
    seg(68.4, 8.7, 70.4, 8.7, 0);
    seg(70.4, 8.7, 70.8, 4.3, 0);
    curve(70.8, 79, t => 4.3 + 7.9 * Math.pow(t, .72), 0);
    seg(79, 12.2, 80.2, 12.7, 0);
    seg(80.2, 12.7, 81.2, 12.2, 0);
    seg(81.2, 12.2, 81.7, 8.5, 0);
    seg(81.7, 8.5, 84, 8.5, 0);
    seg(84, 8.5, 84.5, 6.3, 0);
    curve(84.5, 93, t => 6.3 * Math.sqrt(Math.max(0, 1 - t * t)), 0);
    seg(92.6, .6, 93.4, 2.4, 0);
    curve(93.4, 99.4, t => 3 * Math.sqrt(Math.max(0, 1 - Math.pow(2 * t - 1, 2))) + .4, 0);
    const clamp = v => v < 0 ? 0 : v > 255 ? 255 : v;
    const env = (rx, ry) => {
        let v = ry > 0 ? 118 + 132 * Math.pow(ry, .62) : 40 - 30 * Math.min(1, -ry * 1.4);
        v -= 70 * Math.exp(-Math.pow(ry / .06, 2));
        v += 125 * Math.exp(-Math.pow((rx + .55) / .09, 2)) + 70 * Math.exp(-Math.pow((rx - .62) / .07, 2));
        const red = Math.max(0, -ry) * 50;
        return [v + red, v * .93, v * .96];
    };
    const cv = document.createElement("canvas");
    cv.width = w;
    cv.height = h;
    const ctx = cv.getContext("2d");
    const img = ctx.createImageData(w, h);
    const px = img.data;
    const Dy = -sE,
        Dz = -cE,
        Uy = cE,
        Uz = -sE;
    const T = 150;
    const Lx = -.5,
        Ly = .7,
        Lz = .5,
        ll = Math.hypot(Lx, Ly, Lz);
    let hx = Lx / ll,
        hy = Ly / ll - Dy,
        hz = Lz / ll - Dz;
    const hl = Math.hypot(hx, hy, hz);
    hx /= hl;
    hy /= hl;
    hz /= hl;
    for (let j = 0; j < h; j++) {
        const b = VMAX - (j + .5) / U;
        for (let i = 0; i < w; i++) {
            const a = (i + .5) / U - WU / 2;
            const ox = a,
                oy = b * Uy - T * Dy,
                oz = b * Uz - T * Dz;
            const tc = (50 - oy) * Dy - oz * Dz;
            let hit = -1;
            for (let t = tc - 58; t <= tc + 58; t += .8) {
                const y = oy + t * Dy;
                if (y < 0 || y > 99.8) continue;
                const x = ox,
                    z = oz + t * Dz;
                if (Math.sqrt(x * x + z * z) <= R[(y / STEP) | 0]) {
                    hit = t;
                    break;
                }
            }
            if (hit < 0) continue;
            let lo = hit - .8,
                hi = hit;
            for (let it = 0; it < 6; it++) {
                const mid = (lo + hi) / 2;
                const y = oy + mid * Dy,
                    z = oz + mid * Dz;
                if (y >= 0 && y <= 99.8 && Math.sqrt(ox * ox + z * z) <= R[(y / STEP) | 0]) hi = mid;
                else lo = mid;
            }
            const y = oy + hi * Dy,
                z = oz + hi * Dz,
                x = ox;
            const rr = Math.sqrt(x * x + z * z) || 1e-6;
            const k = Math.max(1, Math.min(N - 2, (y / STEP) | 0));
            const dR = Math.max(-30, Math.min(30, (R[k + 1] - R[k - 1]) / (2 * STEP)));
            const len = Math.sqrt(1 + dR * dR);
            const nx = x / rr / len,
                ny = -dR / len,
                nz = z / rr / len;
            const dn = Dy * ny + Dz * nz;
            const rx = -2 * dn * nx,
                ry = Dy - 2 * dn * ny;
            const e = env(rx, ry);
            const ndh = Math.max(0, nx * hx + ny * hy + nz * hz);
            const spec = Math.pow(ndh, 70) * 230;
            const ao = y < 7 ? .62 + .38 * (y / 7) : 1;
            const black = M[k] === 1;
            const o = (j * w + i) * 4;
            if (black) {
                px[o] = clamp((10 + .3 * e[0]) * ao + spec * .6);
                px[o + 1] = clamp((9 + .28 * e[1]) * ao + spec * .6);
                px[o + 2] = clamp((11 + .3 * e[2]) * ao + spec * .6);
            } else {
                px[o] = clamp(e[0] * ao + spec);
                px[o + 1] = clamp(e[1] * ao + spec);
                px[o + 2] = clamp(e[2] * ao + spec);
            }
            px[o + 3] = 255;
        }
    }
    ctx.putImageData(img, 0, 0);
    wtTurretCv = cv;
    return cv;
}

function wtPaintTurret() {
    const el = document.getElementById("wtTcv");
    if (!el || el.dataset.ready) return;
    const draw = () => {
        const target = document.getElementById("wtTcv");
        if (!target) return;
        const src = wtBuildTurret();
        target.width = src.width;
        target.height = src.height;
        target.getContext("2d").drawImage(src, 0, 0);
        target.dataset.ready = "1";
    };
    if (wtTurretCv) draw();
    else setTimeout(draw, 60);
}

function wtTurretHTML() {
    const g = 'fill="url(#wtTG)"';
    const arm = r => '<g transform="rotate(' + r + ' 60 60)"><polygon points="63,57 94,58.2 96,60 94,61.8 63,63" fill="url(#wtTA)"/><circle cx="96.6" cy="60" r="3.1" ' + g + "/></g>";
    const arms = '<svg viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" overflow="visible"><defs><linearGradient id="wtTG" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ffffff"/><stop offset=".5" stop-color="#a8aeb8"/><stop offset="1" stop-color="#e8ebef"/></linearGradient><linearGradient id="wtTA" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#e7eaee"/><stop offset=".45" stop-color="#ffffff"/><stop offset="1" stop-color="#6b717b"/></linearGradient></defs>' + arm(0) + arm(90) + arm(180) + arm(270) + '<circle cx="60" cy="60" r="5.4" ' + g + '/><circle cx="58.6" cy="58.6" r="1.6" fill="rgba(255,255,255,.9)"/></svg>';
    return '<div class="wt-t3" id="wtT3"><i class="wt-tbase"></i><div class="wt-tstem"><canvas class="wt-tcv" id="wtTcv"></canvas></div><div class="wt-tarms" id="wtTarms">' + arms + "</div></div>";
}

const WT_POSE = {
    bet: {
        tilt: 62,
        scale: 1,
        top: 46
    },
    spin: {
        tilt: 45,
        scale: 1,
        top: 44
    },
    end: {
        tilt: 31,
        scale: 1.03,
        top: 70
    }
};

let wtPose = WT_POSE.bet;

let wtPoseRaf = 0;

function wtMix(a, b, t) {
    return {
        tilt: a.tilt + (b.tilt - a.tilt) * t,
        scale: a.scale + (b.scale - a.scale) * t,
        top: a.top + (b.top - a.top) * t
    };
}

function wtSmooth(a, b, x) {
    const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
    return t * t * (3 - 2 * t);
}

function wtPoseApply(pose) {
    wtPose = pose;
    const whw = document.getElementById("wtWhw");
    const wh = document.getElementById("wtSWh");
    if (!whw || !wh) return;
    const W = whw.offsetWidth;
    if (!W) return;
    const rad = pose.tilt * Math.PI / 180;
    const half = W / 2 * Math.cos(rad) * pose.scale * .96;
    whw.style.transform = "translateY(" + (pose.top + half - W / 2).toFixed(1) + "px) scale(" + pose.scale.toFixed(3) + ")";
    wh.style.transform = "perspective(820px) rotateX(" + pose.tilt.toFixed(2) + "deg)";
    wh.style.setProperty("--u", (W / 400).toFixed(4) + "px");
}

function wtArmsApply(deg) {
    const el = document.getElementById("wtTarms");
    if (el) el.style.transform = "translateZ(calc(var(--u) * 84)) rotate(" + deg.toFixed(2) + "deg)";
}

function wtPoseTween(to, ms, done) {
    cancelAnimationFrame(wtPoseRaf);
    const from = wtPose;
    const t0 = performance.now();
    const step = now => {
        const t = Math.min(1, (now - t0) / ms);
        const e = 1 - Math.pow(1 - t, 3);
        wtPoseApply(wtMix(from, to, e));
        if (t < 1) wtPoseRaf = requestAnimationFrame(step);
        else if (done) done();
    };
    wtPoseRaf = requestAnimationFrame(step);
}

function wtRunSpin(p, number, ms, base, cb) {
    cb = cb || {};
    const disc = document.getElementById(p + "Disc");
    const ball = document.getElementById(p + "Ball");
    const box = document.getElementById(p + "Wh");
    const sh = document.getElementById(p + "BallSh");
    const handle = {
        finished: false,
        skip: function() {},
        cancel: function() {},
        endBase: base
    };
    if (!disc || !ball || !box) {
        if (cb.onDone) cb.onDone(base);
        return handle;
    }
    const old = disc.querySelectorAll(".wt-pk-hl");
    old.forEach(n => n.remove());
    const k = box.offsetWidth / 400;
    const d3 = box.classList.contains("wt-wh3");
    const pc = WT_ORDER.indexOf(number) * WT_STEP;
    const wheelTotal = (2.1 + Math.random() * .8) * 360;
    const wheelPow = 2.2;
    const wheelAt = q => base - wheelTotal * (1 - Math.pow(1 - q, wheelPow));
    const wheelVel = q => wheelTotal * wheelPow * Math.pow(1 - q, wheelPow - 1);
    const endWheel = wheelAt(1);
    const qA = .62,
        trackDecay = 1.9,
        trackV0 = 4300 + Math.random() * 500;
    const trackAt = q => trackV0 * (1 - Math.exp(-trackDecay * q)) / trackDecay;
    const trackVel = q => trackV0 * Math.exp(-trackDecay * q);
    const slope0 = -(trackVel(qA) + wheelVel(qA)) * (1 - qA);
    const rem0 = -slope0 * (.5 + Math.random() * .1);
    const b0 = pc - rem0 + wheelAt(qA) - trackAt(qA);
    const hopFrom = .8,
        hopAmp = (.3 + Math.random() * .15) * WT_STEP;
    const hop = s => s <= hopFrom ? 0 : hopAmp * wtSmooth(0, .05, s - hopFrom) * Math.pow((1 - s) / (1 - hopFrom), 2) * Math.sin(2 * Math.PI * (s - hopFrom) / (1 - hopFrom));
    const remain = s => rem0 * (2 * s * s * s - 3 * s * s + 1) + slope0 * (s * s * s - 2 * s * s + s) + hop(s);
    const ballAt = q => q <= qA ? b0 + trackAt(q) : wheelAt(q) + pc - remain((q - qA) / (1 - qA));
    const kicks = [.66 + Math.random() * .04, .71 + Math.random() * .04, .76 + Math.random() * .03];
    const radiusAt = (q, rel) => {
        let r;
        if (q < .64) r = 162;
        else if (q < .82) {
            r = 162 - 20 * wtSmooth(.64, .82, q);
            kicks.forEach(kq => {
                if (q >= kq) r += 5 * Math.exp(-(q - kq) * 55);
            });
        } else {
            const s = (q - .82) / .18;
            r = 142 - 31 * (1 - Math.pow(1 - s, 3)) + 6 * Math.exp(-4.5 * s) * Math.abs(Math.sin(s * 15)) * (1 - s);
        }
        const w = wtSmooth(.84, .9, q) * (1 - wtSmooth(.95, 1, q));
        return r + 2.2 * Math.abs(Math.sin(Math.PI * rel)) * w;
    };
    let dropped = false;
    const apply = q => {
        const wAng = wheelAt(q);
        const bAng = ballAt(q);
        disc.style.transform = (d3 ? "translateZ(" + (-WT_DEPTH * k).toFixed(2) + "px) " : "") + "rotate(" + wAng.toFixed(2) + "deg)";
        const rel = (bAng - wAng) / WT_STEP;
        const rad = bAng * Math.PI / 180;
        const r = radiusAt(q, rel);
        const bx = (r * Math.sin(rad) * k).toFixed(2),
            by = (-r * Math.cos(rad) * k).toFixed(2);
        const zt = Math.max(0, Math.min(1, (168 - r) / 25));
        const bz = d3 ? -WT_DEPTH * k * zt : 0;
        const tilt = cb.tilt ? cb.tilt() : 0;
        ball.style.transform = "translate3d(" + bx + "px," + by + "px," + (bz + (d3 ? 8 * k : 0)).toFixed(2) + "px) rotateX(" + (-tilt).toFixed(2) + "deg)";
        if (sh) sh.style.transform = "translate3d(" + bx + "px," + by + "px," + bz.toFixed(2) + "px)";
        if (cb.onFrame) cb.onFrame(q, wAng);
        if (!dropped && q >= .8) {
            dropped = true;
            if (cb.onDrop) cb.onDrop();
        }
    };
    const t0 = performance.now();
    let raf = 0;
    const finish = () => {
        if (handle.finished) return;
        handle.finished = true;
        apply(1);
        const path = disc.querySelector('path[data-n="' + number + '"]');
        const g = document.getElementById(p + "DiscG");
        if (path && g) {
            const hl = path.cloneNode();
            hl.removeAttribute("data-n");
            hl.setAttribute("class", "wt-pk-hl");
            g.appendChild(hl);
        }
        handle.endBase = endWheel;
        if (cb.onDone) cb.onDone(endWheel);
    };
    const frame = now => {
        if (handle.finished) return;
        const q = Math.min(1, (now - t0) / ms);
        apply(q);
        if (cb.onElapsed) cb.onElapsed(now - t0);
        if (q < 1) raf = requestAnimationFrame(frame);
        else finish();
    };
    ball.style.opacity = "1";
    if (sh) sh.style.opacity = "1";
    apply(0);
    raf = requestAnimationFrame(frame);
    handle.skip = function() {
        cancelAnimationFrame(raf);
        finish();
    };
    handle.cancel = function() {
        cancelAnimationFrame(raf);
        handle.finished = true;
    };
    return handle;
}

function wtPaintRecent() {
    const el = document.getElementById("wtRecent");
    if (!el) return;
    el.innerHTML = wtRecent.length ? wtRecent.slice(0, 14).map((r, i) => '<span class="wt-badge wt-b-' + wheelColorOfNumber(r.number) + (i === 0 ? " now" : "") + '"' + (r.roundId ? ' data-wheel-round="' + escapeHtml(r.roundId) + '"' : "") + ">" + r.number + "</span>").join("") : '<span class="wt-recent-empty">Пока нет вращений крутите первым</span>';
}

function wtMiniBoard(cells) {
    const on = new Set(cells);
    let h = '<div class="wt-mb sel"><i class="wt-mbz' + (on.has(0) ? " on" : "") + '"></i>';
    for (let n = 1; n <= 36; n++) h += '<i class="wt-mbc ' + wheelColorOfNumber(n) + (on.has(n) ? " on" : "") + '"></i>';
    return h + "</div>";
}

function wtKefHTML() {
    const nums = f => Array.from({
        length: 36
    }, (_, i) => i + 1).filter(f);
    const rows = [{
        kind: "straight",
        name: "Число",
        cover: "1 число из 37",
        how: "Нажмите на клетку с нужным числом (0 — тоже число).",
        cells: [17]
    }, {
        kind: "split",
        name: "Сплит",
        cover: "2 соседних числа",
        how: "Нажмите на границу между двумя клетками. Ноль можно связать с 1, 2 или 3.",
        cells: [8, 9]
    }, {
        kind: "corner",
        name: "Угол",
        cover: "4 числа",
        how: "Нажмите на точку, где сходятся четыре клетки.",
        cells: [11, 12, 14, 15]
    }, {
        kind: "column",
        name: "Колонна «2:1»",
        cover: "12 чисел",
        how: "Кнопки «2:1» под столом — вся колонна целиком.",
        cells: nums(n => n % 3 === 1)
    }, {
        kind: "dozen",
        name: "Дюжина",
        cover: "12 чисел",
        how: "1–12, 13–24 или 25–36 — вторая колонка слева от чисел.",
        cells: nums(n => n <= 12)
    }, {
        kind: "even",
        name: "Цвет, чёт / нечёт, 1–18 / 19–36",
        cover: "18 чисел",
        how: "Крайняя левая колонка стола: красное, чёрное, чёт, нечёт, 1–18, 19–36.",
        cells: nums(n => WT_RED.has(n))
    }];
    const body = rows.map(r => {
        const x = wtMult(r.kind);
        const pay = Math.round(10 * x * 100) / 100;
        const profit = Math.round((pay - 10) * 100) / 100;
        return '<div class="wt-kef-row"><div class="wt-kef-mb">' + wtMiniBoard(r.cells) + '</div><div class="wt-kef-info"><div class="wt-kef-head"><b>' + r.name + '</b><span class="wt-kef-x">x' + fmtCoef(x) + '</span></div><div class="wt-kef-sub">' + r.cover + '</div><div class="wt-kef-how">' + r.how + '</div><div class="wt-kef-ex">Ставка 10⭐️ → выплата <b>' + fmtNum(pay) + "⭐️</b> (чистая прибыль " + fmtNum(profit) + "⭐️)</div></div></div>";
    }).join("");
    return '<p class="modal-text">Коэффициент уже включает вашу ставку: выплата = ставка × коэффициент. Подсвеченные клетки на мини-столе показывают, какие числа входят в позицию.</p>' + body + '<p class="modal-text wt-kef-note"><b>Ноль</b> не входит в колонны, дюжины и ставки на цвет, чёт / нечёт, 1–18 / 19–36 — при выпадении 0 эти позиции проигрывают. Позиций можно ставить сколько угодно: каждая считается отдельно, а итог вращения — сумма всех выплат.</p>';
}

function openWheelKef() {
    const modal = document.getElementById("wheelKefModal");
    const bodyEl = document.getElementById("wheelKefBody");
    if (!modal || !bodyEl) return;
    bodyEl.innerHTML = wtKefHTML();
    modal.classList.add("active");
    fetch("/api/wheel/state?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (!data || !data.ok || !data.mults) return;
        if (wtState) wtState.mults = data.mults;
        else wtState = data;
        if (modal.classList.contains("active")) bodyEl.innerHTML = wtKefHTML();
    }).catch(function() {});
}

function closeWheelKef() {
    const modal = document.getElementById("wheelKefModal");
    if (modal) modal.classList.remove("active");
}

function wtMoney(v) {
    return (Math.round(v * 100) / 100).toFixed(2) + " ⭐️";
}

function wtPaint(changedKey) {
    if (!wtEls) wtEls = gvBody.querySelectorAll(".wt-board [data-wt]");
    wtEls.forEach(el => {
        const key = el.dataset.wt;
        const v = wtBets.get(key);
        let chip = el.querySelector(":scope > .wt-chip");
        if (v) {
            const fresh = !chip;
            if (fresh) {
                chip = document.createElement("span");
                el.appendChild(chip);
                el.classList.add("has-chip");
            }
            const txt = wtShort(v);
            chip.className = "wt-chip " + wtChipClass(v, txt);
            chip.textContent = txt;
            if (fresh || key === changedKey) {
                chip.classList.remove("pop");
                void chip.offsetWidth;
                chip.classList.add("pop");
            }
        } else if (chip) {
            chip.remove();
            el.classList.remove("has-chip");
        }
    });
    wtUpdateUI();
}

function wtMarkHit(n) {
    gvBody.querySelectorAll(".wt-board .wt-hit").forEach(el => el.classList.remove("wt-hit"));
    if (n == null) return;
    const el = gvBody.querySelector('.wt-board [data-wt="n:' + n + '"]');
    if (el) el.classList.add("wt-hit");
}

let wtCovTimer = null;

function wtFlashCover(key) {
    const info = WT_CAT[key];
    if (!info) return;
    gvBody.querySelectorAll(".wt-board .wt-cov").forEach(el => el.classList.remove("wt-cov"));
    info.nums.forEach(n => {
        const el = gvBody.querySelector('.wt-board [data-wt="n:' + n + '"]');
        if (el) el.classList.add("wt-cov");
    });
    clearTimeout(wtCovTimer);
    wtCovTimer = setTimeout(() => {
        gvBody.querySelectorAll(".wt-board .wt-cov").forEach(el => el.classList.remove("wt-cov"));
    }, 750);
}

function wtFlyChip(key, value, done) {
    const src = gvBody.querySelector(".wt-tc.on .wt-cc") || gvBody.querySelector(".wt-chips .wt-cc");
    const dst = gvBody.querySelector('.wt-board [data-wt="' + key + '"]');
    if (!src || !dst || !src.animate) {
        done();
        return;
    }
    const a = src.getBoundingClientRect(),
        b = dst.getBoundingClientRect();
    const txt = wtShort(value);
    const el = document.createElement("span");
    el.className = wtChipClass(value, txt) + " wt-fly";
    el.textContent = txt;
    el.style.cssText = "left:" + a.left.toFixed(1) + "px;top:" + a.top.toFixed(1) + "px;width:" + a.width.toFixed(1) + "px;height:" + a.height.toFixed(1) + "px;font-size:" + (a.width * .3).toFixed(1) + "px";
    document.body.appendChild(el);
    const dx = b.left + b.width / 2 - (a.left + a.width / 2),
        dy = b.top + b.height / 2 - (a.top + a.height / 2);
    const end = 31 / a.width;
    const anim = el.animate([{
        transform: "translate(0,0) scale(1)"
    }, {
        transform: "translate(" + (dx * .5).toFixed(1) + "px," + (dy * .5 - 30).toFixed(1) + "px) scale(1.14)",
        offset: .5
    }, {
        transform: "translate(" + dx.toFixed(1) + "px," + dy.toFixed(1) + "px) scale(" + end.toFixed(3) + ")"
    }], {
        duration: 320,
        easing: "cubic-bezier(.3,.55,.4,1)"
    });
    anim.onfinish = () => {
        el.remove();
        done();
    };
}

function wtSnapshot() {
    wtUndo.push(Array.from(wtBets.entries()));
    if (wtUndo.length > 80) wtUndo.shift();
}

function wtAdd(key) {
    if (wtBusy || !WT_CAT[key]) return;
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const chip = wtChipValue();
    if (!(chip > 0)) {
        showToast("Введите номинал фишки", "error");
        return;
    }
    const next = Math.round(((wtBets.get(key) || 0) + chip) * 100) / 100;
    const issue = betLimitIssue("wheel", next);
    if (issue) {
        showToast(issue, "error");
        return;
    }
    if (wtTotal() + chip > currentUser.balance + 1e-9) {
        showToast("Недостаточно средств на балансе", "error");
        return;
    }
    wtSnapshot();
    wtBets.set(key, next);
    haptic("selection");
    wtMarkHit(null);
    wtFlashCover(key);
    wtUpdateUI();
    wtFlyChip(key, chip, () => wtPaint(key));
}

function wtFits(map) {
    let total = 0;
    for (const [key, v] of map) {
        const issue = betLimitIssue("wheel", v);
        if (issue) return issue;
        total += v;
    }
    if (total > currentUser.balance + 1e-9) return "Недостаточно средств: нужно " + fmtNum(Math.round(total * 100) / 100) + "⭐️";
    return null;
}

function wtAct(act) {
    if (act === "kef") {
        openWheelKef();
        return;
    }
    if (act === "skip") {
        if (wtSpinHandle) wtSpinHandle.skip();
        return;
    }
    if (act === "spin") {
        wheelBetBtnClick();
        return;
    }
    if (wtBusy) return;
    if (act === "undo") {
        if (!wtUndo.length) return;
        const prev = wtUndo.pop();
        wtBets.clear();
        prev.forEach(e => wtBets.set(e[0], e[1]));
        haptic("selection");
        wtPaint();
    } else if (act === "clear") {
        if (!wtBets.size) return;
        wtSnapshot();
        wtBets.clear();
        wtPaint();
    } else if (act === "double") {
        if (!wtBets.size) return;
        const next = new Map;
        wtBets.forEach((v, k) => next.set(k, Math.round(v * 200) / 100));
        const issue = wtFits(next);
        if (issue) {
            showToast(issue, "error");
            return;
        }
        wtSnapshot();
        next.forEach((v, k) => wtBets.set(k, v));
        haptic("impact", "light");
        wtPaint();
    } else if (act === "repeat") {
        if (wtBets.size || !wtLastBets || !wtLastBets.length) return;
        const next = new Map;
        wtLastBets.forEach(b => next.set(b.key, b.amount));
        const issue = wtFits(next);
        if (issue) {
            showToast(issue, "error");
            return;
        }
        wtSnapshot();
        next.forEach((v, k) => wtBets.set(k, v));
        haptic("impact", "light");
        wtMarkHit(null);
        wtPaint();
    }
}

function wtUpdateUI() {
    const total = wtTotal();
    const count = wtBets.size;
    const spin = document.getElementById("wheelBetBtn");
    if (spin) {
        const ready = !wtBusy && count > 0;
        spin.classList.toggle("dim", !ready);
        spin.disabled = !ready;
    }
    const sum = document.getElementById("wheelBetSummary");
    if (sum) {
        const chip = wtChipValue();
        sum.innerHTML = count ? "Позиций на столе: <b>" + count + "</b> · общая ставка <b>" + fmtNum(total) + "⭐️</b>" : chip > 0 ? "Одно нажатие на стол фишка <b>" + fmtNum(chip) + "⭐️</b>" : "Введите номинал фишки";
    }
    const set = (act, on) => {
        const b = gvBody.querySelector('[data-wt-act="' + act + '"]');
        if (b) b.disabled = !on || wtBusy;
    };
    const canRepeat = count === 0 && !!wtLastBets && wtLastBets.length > 0;
    set("undo", wtUndo.length > 0);
    set("clear", count > 0);
    set("double", count > 0);
    set("repeat", canRepeat);
    const undoBox = gvBody.querySelector(".wt-cb-undo");
    const repBox = gvBody.querySelector(".wt-cb-rep");
    if (undoBox && repBox) {
        undoBox.hidden = canRepeat;
        repBox.hidden = !canRepeat;
    }
    const cv = wtChipValue();
    gvBody.querySelectorAll("[data-wt-chip]").forEach(b => {
        b.classList.toggle("on", Math.abs(Number(b.dataset.wtChip) - cv) < 1e-9);
    });
    const sb = document.getElementById("wtSbBet");
    if (sb) sb.textContent = wtMoney(total);
    const sbal = document.getElementById("wtSbBal");
    if (sbal) sbal.textContent = wtMoney(currentUser.balance);
    const ctl = gvBody.querySelector(".wt-ctl");
    if (ctl) ctl.classList.toggle("wt-ctl-off", wtPhase !== "bet");
}

function updateWheelBetBtn() {
    wtUpdateUI();
}

function wtControlsHTML() {
    const rb = (act, icon, label, cls) => '<div class="wt-cb ' + (cls || "") + '"><button class="wt-rb" type="button" data-wt-act="' + act + '" disabled>' + icon + "</button><span>" + label + "</span></div>";
    return '<div class="wt-ctl">' + rb("clear", '<svg viewBox="0 0 24 24" fill="none"><path d="M7 7l10 10M17 7 7 17" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>', "Убрать") + rb("undo", '<svg viewBox="0 0 24 24" fill="none"><path d="M9 14 4 9l5-5M4 9h10a6 6 0 0 1 0 12h-3" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>', "Отмена", "wt-cb-undo") + rb("repeat", '<svg viewBox="0 0 24 24" fill="none"><path d="M4 11V9a3 3 0 0 1 3-3h12M16 3l3 3-3 3M20 13v2a3 3 0 0 1-3 3H5M8 21l-3-3 3-3" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>', "Повтор", "wt-cb-rep") + wtTrayHTML() + rb("double", '<b class="wt-x2">×2</b>', "Удвоить") + '<div class="wt-cb wt-cb-spin"><button class="wt-spin dim" id="wheelBetBtn" type="button" data-wt-act="spin" disabled><svg viewBox="0 0 24 24" fill="none"><path d="M20 12a8 8 0 1 1-2.6-5.9" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/><path d="M20 4v5h-5" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></button><span>Крутить</span></div>' + "</div>" + '<div class="wt-sbrow"><div class="wt-sb"><div>Ставка <b id="wtSbBet">0.00 ⭐️</b></div><div>Баланс <b id="wtSbBal">—</b></div></div><button class="wt-kef" type="button" data-wt-act="kef">Кэфы</button></div>';
}

function renderWheel() {
    wtEls = null;
    wtPose = WT_POSE.bet;
    return '<div class="wt-head">' + '<div class="wt-head-mid">' + '<div class="wt-head-title">Ваши последние числа</div>' + '<div class="wt-recent" id="wtRecent"><span class="wt-recent-empty">Загрузка…</span></div>' + "</div>" + "</div>" + '<div class="wt-room">' + '<div class="wt-stage" id="wtStage">' + '<div class="wt-cam" id="wtCam"><div class="wt-whw" id="wtWhw">' + wtWheelHTML("wtS", true, wtWheelBase, true) + "</div></div>" + '<div class="wt-status" id="wtStatus">Делайте ставки</div>' + '<button class="wt-skip" type="button" data-wt-act="skip">Пропустить</button>' + '<div class="wt-bw" id="wtBw"><div class="wt-felt">' + wtBoardHTML() + "</div></div>" + '<div class="wt-result" id="wtResult"></div>' + "</div>" + wtControlsHTML() + "</div>" + '<div class="gv-fair-row">' + '<div class="gv-fair" data-action="wheel-fair"><span class="gv-fair-icon">#</span><span id="wheelRoundIdLabel" class="text-skel">WHXXXXXXXX</span></div>' + howtoHTML() + "</div>" + '<div class="gv-panel" id="wheelPanel">' + '<div class="gv-label" id="wheelBetLabel">Своя сумма фишки</div>' + betRowHTML("10") + '<div class="wheel-bet-summary" id="wheelBetSummary"></div>' + "</div>" + '<div class="gv-history">' + '<div class="gv-history-head">' + '<h3 class="gv-history-title">' + lazyImgTag(liteAsset("/lottie/images/ОгоньЭмоджи.lottie"), "", "flame-gif") + " Последние игры</h3>" + '<div class="gv-history-tabs">' + '<button class="gv-history-tab active" type="button" data-wheel-scope="all">Все</button>' + '<button class="gv-history-tab" type="button" data-wheel-scope="mine">Мои</button>' + "</div>" + "</div>" + gvHistorySearchRowHTML("wheelHistorySearchInput") + '<div class="gv-history-list" id="wheelHistoryList">' + crashHistorySkeletonHTML() + "</div>" + "</div>";
}

function loadWheelState() {
    fetch("/api/wheel/state?uid=" + CURRENT_UID).then(r => r.json()).then(data => {
        if (!data || !data.ok) return;
        wtState = data;
        if (!wtBusy) wtRecent = (data.recent || []).slice();
        wtPaintRecent();
        wtUpdateUI();
    }).catch(function() {});
}

function startWheelPolling() {
    wtCleanupSpin();
    wtState = null;
    wtBusy = false;
    wtPhase = "bet";
    wtLast = null;
    wtLastBets = null;
    wtRecent = [];
    wtUndo = [];
    wtBets.clear();
    wtEls = null;
    wheelHistoryScope = "all";
    loadWheelState();
    loadWheelHistory(wheelHistoryScope);
    gvHistoryWireSearch("wheelHistorySearchInput", () => loadWheelHistory(wheelHistoryScope), value => {
        gvHistorySearch("wheelHistoryList", () => "/api/wheel/history?uid=" + CURRENT_UID + "&scope=" + wheelHistoryScope + "&q=" + encodeURIComponent(value), rows => {
            document.getElementById("wheelHistoryList").innerHTML = rows.map(wheelHistoryRowHTML).join("");
        });
    });
    wtUpdateUI();
    requestAnimationFrame(() => {
        wtPoseApply(WT_POSE.bet);
        wtPaintTurret();
    });
}

function stopWheelPolling() {
    wtCleanupSpin();
}

function wtCleanupSpin() {
    if (wtSpinHandle) {
        wtSpinHandle.cancel();
        wtSpinHandle = null;
    }
    cancelAnimationFrame(wtPoseRaf);
    clearTimeout(wtSpinTimer);
    clearTimeout(wtResTimer);
    document.querySelectorAll(".wt-fly, .wt-fly-badge").forEach(n => n.remove());
    if (wtPendingBalance != null) {
        applyBalance(wtPendingBalance);
        wtPendingBalance = null;
    }
    wtBusy = false;
    wtPhase = "bet";
}

function wtShowSpin(d) {
    wtCleanupSpin();
    wtBusy = true;
    wtPhase = "spin";
    wtLast = d;
    wtLastBets = d.bets.map(b => ({
        key: b.key,
        amount: b.amount
    }));
    wtPendingBalance = d.balance;
    applyBalance(Math.round((d.balance - d.totalWin) * 100) / 100);
    const stage = document.getElementById("wtStage");
    if (!stage) {
        wtCleanupSpin();
        return;
    }
    stage.classList.remove("wt-show-result");
    stage.classList.add("wt-away");
    const status = document.getElementById("wtStatus");
    if (status) status.textContent = "Ставки закрыты";
    if (stage.scrollIntoView) stage.scrollIntoView({
        behavior: "smooth",
        block: "start"
    });
    wtUpdateUI();
    haptic("impact", "light");
    const ms = currentUser.liteUiEnabled ? 6500 : WT_SPIN_MS;
    wtPoseTween(WT_POSE.spin, 750);
    wtSpinTimer = setTimeout(() => {
        if (wtPhase !== "spin") return;
        wtSpinHandle = wtRunSpin("wtS", d.number, ms, wtWheelBase, {
            tilt: () => wtPose.tilt,
            onFrame: (q, wAng) => {
                if (q > .5) wtPoseApply(wtMix(WT_POSE.spin, WT_POSE.end, wtSmooth(.56, .93, q)));
                wtArmsApply(wAng);
            },
            onDrop: () => haptic("impact", "medium"),
            onDone: endBase => {
                wtWheelBase = (endBase % 360 + 360) % 360;
                wtSpinHandle = null;
                wtShowResult(d);
            }
        });
    }, 450);
}

function wtResultHTML(d) {
    const net = Math.round((d.totalWin - d.totalBet) * 100) / 100;
    let money;
    if (d.totalWin > 0) money = "<small>" + (net > 0 ? "Выигрыш" : "Выплата") + "</small><b>" + wtMoney(d.totalWin) + "</b>";
    else money = '<small class="none">Не повезло</small>';
    return '<div class="wt-rbadge wt-rb-' + wheelColorOfNumber(d.number) + '">' + d.number + "</div>" + '<div class="wt-rwin' + (net > 0 ? " win" : "") + '">' + money + "</div>";
}

function wtShowResult(d) {
    wtPhase = "result";
    const stage = document.getElementById("wtStage");
    if (!stage) return;
    wtRecent.unshift({
        roundId: d.roundId,
        number: d.number,
        color: d.color
    });
    if (wtRecent.length > 24) wtRecent.length = 24;
    if (wtPendingBalance != null) {
        applyBalance(wtPendingBalance);
        wtPendingBalance = null;
    }
    const net = d.totalWin - d.totalBet;
    haptic("notification", net > 0 ? "success" : "warning");
    const res = document.getElementById("wtResult");
    if (res) res.innerHTML = wtResultHTML(d);
    const whw = document.getElementById("wtWhw");
    if (res && whw) {
        const end = WT_POSE.end;
        const bottom = end.top + whw.offsetWidth * Math.cos(end.tilt * Math.PI / 180) * end.scale * .96 + 20;
        res.style.top = Math.round(bottom) + "px";
    }
    stage.classList.add("wt-show-result");
    const label = document.getElementById("wheelRoundIdLabel");
    if (label) {
        label.textContent = d.roundId;
        label.classList.remove("text-skel");
    }
    wtUpdateUI();
    clearTimeout(wtResTimer);
    wtResTimer = setTimeout(wtEndRound, 3200);
}

function wtEndRound() {
    if (wtPhase !== "result") return;
    wtPhase = "return";
    clearTimeout(wtResTimer);
    const stage = document.getElementById("wtStage");
    if (!stage) {
        wtCleanupSpin();
        return;
    }
    const badge = stage.querySelector(".wt-rbadge");
    const from = badge ? badge.getBoundingClientRect() : null;
    wtPaintRecent();
    const first = document.querySelector("#wtRecent .wt-badge");
    const to = first ? first.getBoundingClientRect() : null;
    if (badge && from && to && badge.animate) {
        const clone = badge.cloneNode(true);
        clone.classList.add("wt-fly-badge");
        clone.style.cssText = "left:" + from.left.toFixed(1) + "px;top:" + from.top.toFixed(1) + "px;width:" + from.width.toFixed(1) + "px;height:" + from.height.toFixed(1) + "px";
        document.body.appendChild(clone);
        first.style.visibility = "hidden";
        const dx = to.left + to.width / 2 - (from.left + from.width / 2),
            dy = to.top + to.height / 2 - (from.top + from.height / 2);
        clone.animate([{
            transform: "translate(0,0) scale(1)"
        }, {
            transform: "translate(" + dx.toFixed(1) + "px," + dy.toFixed(1) + "px) scale(" + (to.width / from.width).toFixed(3) + ")"
        }], {
            duration: 650,
            easing: "cubic-bezier(.4,.1,.2,1)"
        }).onfinish = () => {
            clone.remove();
            first.style.visibility = "";
            first.classList.add("pop");
        };
    }
    stage.classList.remove("wt-show-result");
    stage.classList.remove("wt-away");
    const status = document.getElementById("wtStatus");
    if (status) status.textContent = "Делайте ставки";
    wtPoseTween(WT_POSE.bet, 900);
    wtBets.clear();
    wtUndo = [];
    wtPaint();
    if (wtLast) wtMarkHit(wtLast.number);
    loadWheelHistory(wheelHistoryScope);
    clearTimeout(wtSpinTimer);
    wtSpinTimer = setTimeout(() => {
        wtBusy = false;
        wtPhase = "bet";
        wtUpdateUI();
    }, 900);
}

function wheelBetBtnClick() {
    if (wtBusy) return;
    if (!wtBets.size) {
        showToast("Положите фишки на стол", "error");
        return;
    }
    if (!betsAccepted) {
        showToast(BETS_PAUSED_TOAST, "warning");
        return;
    }
    const total = wtTotal();
    if (total > currentUser.balance + 1e-9) {
        showToast("Недостаточно средств: нужно " + fmtNum(total) + "⭐️", "error");
        return;
    }
    const items = [];
    for (const [key, amount] of wtBets) {
        const issue = betLimitIssue("wheel", amount);
        if (issue) {
            showToast(issue, "error");
            return;
        }
        items.push({
            key: key,
            amount: amount
        });
    }
    wtBusy = true;
    updateWheelBetBtn();
    fetch("/api/wheel/spin", {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            uid: CURRENT_UID,
            items: items
        })
    }).then(r => r.json()).then(data => {
        if (!data || !data.ok) {
            wtBusy = false;
            showToast(data && data.error || "Ошибка сервера", "error");
            updateWheelBetBtn();
            return;
        }
        wtShowSpin(data);
    }).catch(() => {
        wtBusy = false;
        showToast("Не удалось связаться с сервером", "error");
        updateWheelBetBtn();
    });
}

gvBody.addEventListener("input", e => {
    if (currentGame === "wheel" && e.target && e.target.classList && e.target.classList.contains("gv-bet-input")) wtUpdateUI();
});

gvBody.addEventListener("click", e => {
    if (currentGame !== "wheel") return;
    if (e.target.closest(".gv-bet-row .gv-chip")) {
        setTimeout(wtUpdateUI, 0);
        return;
    }
    if (e.target.closest("#wtResult")) {
        wtEndRound();
        return;
    }
    const tray = e.target.closest("[data-wt-chip]");
    if (tray) {
        if (wtBusy) return;
        const input = gvBody.querySelector(".gv-bet-input");
        if (input) input.value = tray.dataset.wtChip + "⭐️";
        haptic("selection");
        wtUpdateUI();
        return;
    }
    const act = e.target.closest("[data-wt-act]");
    if (act) {
        wtAct(act.dataset.wtAct);
        return;
    }
    if (wtPhase === "spin" && e.target.closest("#wtStage")) {
        if (wtSpinHandle) wtSpinHandle.skip();
        return;
    }
    const cell = e.target.closest(".wt-board [data-wt]");
    if (cell) wtAdd(cell.dataset.wt);
});

window.addEventListener("resize", () => {
    if (currentGame === "wheel") wtPoseApply(wtPose);
});

function wheelHistoryRowHTML(r) {
    let meta = {};
    try {
        meta = JSON.parse(r.meta || "{}");
    } catch (e) {}
    const isMe = r.user_id === CURRENT_UID;
    const name = isMe ? currentUser.displayName || "Игрок" : r.username || "Игрок";
    const avatarUrl = isMe ? currentUser.avatarUrl : "/api/avatar/" + r.user_id;
    let betLine, outLine, resLine;
    if (meta.mode === "solo") {
        const bet = Number(r.bet) || 0,
            pay = Number(r.win_amount) || 0;
        betLine = "Ставок: <b>" + (meta.betsCount || (meta.bets || []).length) + "</b> на <b>" + fmtNum(bet) + "⭐️</b>";
        outLine = "Выпало: " + wtBadgeHTML(meta.number, "mini") + " " + (WT_COLOR_NAME[meta.color] || "");
        if (r.result === "win") resLine = '<span class="gv-history-win">Выигрыш: +' + fmtNum(Math.round((pay - bet) * 100) / 100) + "⭐️</span>";
        else if (pay > 0 && Math.abs(pay - bet) < 1e-9) resLine = '<span class="gv-history-lose">Ставка возвращена</span>';
        else if (pay > 0) resLine = '<span class="gv-history-lose">Выплата ' + fmtNum(pay) + "⭐️ (−" + fmtNum(Math.round((bet - pay) * 100) / 100) + "⭐️)</span>";
        else resLine = '<span class="gv-history-lose">Проигрыш</span>';
    } else {
        const myBetLabel = meta.myBetType === "number" ? "Число " + meta.myBetValue : meta.myBetType === "sector" ? wheelSectorLabel(meta.myBetValue) : meta.myColor ? ROULETTE_COLOR_LABEL[meta.myColor] : "—";
        betLine = "Ставка на: <b>" + myBetLabel + "</b>";
        outLine = meta.outcomeColor ? "Выпало: " + rouletteColorIconHTML(meta.outcomeColor) + " " + ROULETTE_COLOR_LABEL[meta.outcomeColor] + (meta.outcomeNumber != null ? " (" + meta.outcomeNumber + ")" : "") : "—";
        resLine = r.result === "win" ? '<span class="gv-history-win">Выигрыш: ' + fmtNum(r.win_amount) + "⭐️</span>" : '<span class="gv-history-lose">Проигрыш</span>';
    }
    return '<div class="gv-history-row crash-history-row-item">' + '<div class="gv-history-row-top">' + '<div class="gv-history-avatar"><div class="skel-box"></div>' + lazyImgTag(avatarUrl, name) + "</div>" + '<div class="gv-history-mid">' + '<div class="gv-history-name">' + escapeHtml(name) + "</div>" + historyTimeHTML(r.created_at) + "</div>" + '<div class="gv-history-right">' + betLine + "<br>" + '<span class="gv-history-outcome">' + outLine + "</span><br>" + resLine + "</div>" + "</div>" + (meta.roundId ? '<button class="crash-history-fair-btn" type="button" data-wheel-round="' + escapeHtml(meta.roundId) + '">' + fairCheckBtnIconHTML() + "Проверить честность</button>" : "") + "</div>";
}

function loadWheelHistory(scope, append) {
    if (scope) {
        wheelHistoryScope = scope;
        append = false;
    }
    gvHistoryLoad("wheelHistoryList", off => "/api/wheel/history?uid=" + CURRENT_UID + "&scope=" + wheelHistoryScope + "&offset=" + off, 20, (rows, append) => {
        const list = document.getElementById("wheelHistoryList");
        const html = rows.map(wheelHistoryRowHTML).join("");
        if (append) list.insertAdjacentHTML("beforeend", html);
        else list.innerHTML = html;
    }, GV_HISTORY_EMPTY_HTML, append);
}

GV_HISTORY_BY_GAME["wheel"] = {
    listId: "wheelHistoryList",
    load: () => loadWheelHistory(null, true)
};

function wtChanceStr(v) {
    return (Math.round(Number(v) * 100) / 100).toString();
}

function wheelFairFormulaHTML(number, chances) {
    return '<p class="modal-text">Для каждого вращения заранее создаётся секретный сид. Его SHA-256-хэш записывается в лог раунда, а сам сид раскрывается сразу после вращения — если хэш сида совпадает с записанным, значит сид не подменяли под ваши ставки.</p>' + '<p class="modal-text">Выпавшее число вычисляется так: берём HMAC-SHA256(сид, UID раунда), первые 13 hex-символов переводим в число и делим на 16<sup>13</sup> — получается число u от 0 до 1. При стандартных шансах рулетки номер = целая часть от u × 37 (от 0 до 36). Если шансы цветов на столе изменены, u так же раскладывается по накопленным вероятностям ячеек (внутри цвета все числа равновероятны). Это можно пересчитать самостоятельно.</p>' + (chances && chances.red != null ? '<p class="modal-text">Шансы в этом вращении: красное <b>' + wtChanceStr(chances.red) + '%</b>, чёрное <b>' + wtChanceStr(chances.black) + '%</b>, зеро <b>' + wtChanceStr(chances.green) + '%</b>.</p>' : '') + (number != null ? '<p class="modal-text">В этом вращении выпало <b>' + number + " (" + (WT_COLOR_NAME[wheelColorOfNumber(number)] || "").toLowerCase() + ")</b>.</p>" : "");
}

function wtFairBlocksHTML(d) {
    return '<div class="fair-block"><div class="fair-label">UID раунда</div><div class="fair-hash" data-copy="' + escapeHtml(d.roundId) + '">' + fairHashHTML(d.roundId) + "</div></div>" + '<div class="fair-block"><div class="fair-label">SHA-256 hash</div><div class="fair-hash" data-copy="' + escapeHtml(d.seedHash || "") + '">' + fairHashHTML(d.seedHash || "—") + "</div></div>" + '<div class="fair-block"><div class="fair-label">Секретный сид</div><div class="fair-hash" data-copy="' + escapeHtml(d.serverSeed || "") + '">' + fairHashHTML(d.serverSeed || "—") + "</div></div>";
}

function openWheelFair() {
    const d = wtLast;
    if (d) {
        gvFairId.textContent = d.roundId;
        gvFairId.classList.remove("text-skel");
    } else {
        gvFairId.textContent = "WHXXXXXXXX";
        gvFairId.classList.add("text-skel");
    }
    if (d && d.seedHash) setFairHashEl(gvFairHash, d.seedHash);
    else setFairHashSkeleton(gvFairHash);
    if (d) {
        gvFairResult.innerHTML = wtFairBlocksHTML(d) + '<div class="fair-block"><div class="fair-label">Выпало</div><div class="fair-result">' + wtBadgeHTML(d.number, "mini") + " " + wtFacts(d.number) + "</div></div>";
        gvFairNote.style.display = "";
        gvFairNote.innerHTML = wheelFairFormulaHTML(d.number, d.chances);
    } else {
        gvFairResult.innerHTML = '<div class="fair-result-note">Сид и хэш показываются сразу после вращения. Крутните колесо — и здесь появятся UID, сид и формула проверки. Старые вращения можно проверить в истории ниже.</div>';
        gvFairNote.style.display = "none";
    }
    gvFairLink.style.display = "none";
    gvFairModal.classList.add("active");
}

const wheelRoundModal = document.getElementById("wheelRoundModal");

const wheelRoundReplay = document.getElementById("wheelRoundReplay");

const wheelRoundPlayers = document.getElementById("wheelRoundPlayers");

const wheelRoundFairBlock = document.getElementById("wheelRoundFairBlock");

function stopWheelReplay() {
    if (wtReplayTimer) {
        clearTimeout(wtReplayTimer);
        wtReplayTimer = null;
    }
    if (wtReplayHandle) {
        wtReplayHandle.cancel();
        wtReplayHandle = null;
    }
}

function wtPlayReplay(d) {
    stopWheelReplay();
    const box = document.getElementById("wtRpWheel");
    const cap = document.getElementById("wtRpCap");
    if (!box) return;
    const base = Math.random() * 360;
    box.innerHTML = wtWheelHTML("wtR", true, base);
    if (cap) cap.innerHTML = '<span class="wt-rp-spin">Крутим колесо…</span>';
    wtReplayTimer = setTimeout(() => {
        wtReplayHandle = wtRunSpin("wtR", d.number, 5600, base, {
            onDone: () => {
                wtReplayHandle = null;
                if (cap) cap.innerHTML = wtBadgeHTML(d.number, "big") + '<div class="wt-rp-facts">' + wtFacts(d.number) + "</div>";
            }
        });
    }, 350);
}

function wtDetailBetsHTML(d) {
    const bets = d.bets || [];
    if (!bets.length) return '<div class="crash-players-empty">Нет данных о ставках</div>';
    const net = Math.round((d.totalWin - d.totalBet) * 100) / 100;
    const rows = bets.map(b => {
        const info = WT_CAT[b.key];
        return '<div class="wt-dt-row' + (b.win > 0 ? " win" : "") + '"><span class="wt-dt-l">' + escapeHtml(info ? info.label : b.key) + '</span><span class="wt-dt-b">' + fmtNum(b.amount) + "⭐️ · x" + fmtCoef(b.mult) + '</span><b class="wt-dt-w">' + (b.win > 0 ? "+" + fmtNum(b.win) + "⭐️" : "—") + "</b></div>";
    }).join("");
    return '<div class="crash-players-title"><span>Ставки игрока ' + escapeHtml(d.username || "") + "</span><span>" + bets.length + "</span></div>" + '<div class="wt-dt">' + rows + "</div>" + '<div class="wt-dt-total"><span>Ставка <b>' + fmtNum(d.totalBet) + "⭐️</b></span><span>Выплата <b>" + fmtNum(d.totalWin) + "⭐️</b></span><span>Итог <b class=\"" + (net > 0 ? "plus" : net < 0 ? "minus" : "") + '">' + (net > 0 ? "+" : "") + fmtNum(net) + "⭐️</b></span></div>";
}

function wheelRoundBetsHTML(bets) {
    if (!bets || !bets.length) return '<div class="crash-players-empty">В этом раунде не было ставок!</div>';
    return '<div class="crash-players-title"><span>Ставки раунда</span><span>' + bets.length + "</span></div>" + '<div class="crash-players-list">' + bets.map(p => {
        const isMe = p.id === CURRENT_UID;
        const isWin = p.winAmount > 0;
        const betLabel = p.betType === "number" ? "Число " + p.value : p.betType === "sector" ? wheelSectorLabel(p.value) : rouletteColorIconHTML(p.value) + " " + ROULETTE_COLOR_LABEL[p.value];
        return '<div class="crash-player-row' + (isWin ? " cashed" : " lost") + (isMe ? " me" : "") + '">' + '<div class="crash-player-avatar"><img src="/api/avatar/' + p.id + '" alt="" loading="lazy"></div>' + '<div class="crash-player-mid">' + '<div class="crash-player-name"><span class="crash-player-name-text">' + escapeHtml(p.username) + "</span>" + (isMe ? ' <span class="lb-you-tag">Вы</span>' : "") + "</div>" + '<div class="crash-player-sub">Ставка на: ' + betLabel + " · " + fmtNum(p.bet) + "⭐️</div>" + "</div>" + '<div class="crash-player-value">' + (isWin ? "+" + fmtNum(p.winAmount) + "⭐️" : "Проигрыш") + "</div>" + "</div>";
    }).join("") + "</div>";
}

function openWheelRoundModal(publicId) {
    if (!publicId) return;
    stopWheelReplay();
    wheelReplayData = null;
    wheelRoundFairBlock.style.display = "none";
    wheelRoundFairBlock.innerHTML = "";
    document.getElementById("wheelRoundFairBtn").textContent = "Проверить честность";
    document.getElementById("wheelRoundModalId").textContent = publicId;
    wheelRoundReplay.innerHTML = '<div class="crash-players-empty">Загрузка…</div>';
    wheelRoundPlayers.innerHTML = crashPlayersSkeletonHTML();
    wheelRoundModal.classList.add("active");
    fetch("/api/wheel/round?id=" + encodeURIComponent(publicId)).then(r => r.json()).then(data => {
        if (!wheelRoundModal.classList.contains("active")) return;
        if (!data || !data.ok) {
            wheelRoundReplay.innerHTML = '<div class="crash-players-empty">Раунд не найден</div>';
            wheelRoundPlayers.innerHTML = "";
            return;
        }
        wheelReplayData = data;
        const number = data.number != null ? data.number : data.outcomeNumber;
        data.number = number;
        if (number == null) {
            wheelRoundReplay.innerHTML = '<div class="crash-players-empty">Раунд ещё не завершён</div>';
            wheelRoundPlayers.innerHTML = "";
            return;
        }
        wheelRoundReplay.innerHTML = '<div class="wt-rp"><div class="wt-rp-wheel" id="wtRpWheel" title="Показать ещё раз"></div><div class="wt-rp-cap" id="wtRpCap"></div></div>';
        wheelRoundPlayers.innerHTML = data.mode === "solo" ? wtDetailBetsHTML(data) : wheelRoundBetsHTML(data.bets || []);
        wtPlayReplay(data);
    }).catch(() => {
        wheelRoundReplay.innerHTML = '<div class="crash-players-empty">Не удалось загрузить раунд</div>';
    });
}

function closeWheelRoundModal() {
    stopWheelReplay();
    wheelRoundModal.classList.remove("active");
}

