    function readMode() {
        if (gameSwitchOff.has("escape_pvp")) return "solo";
        if (gameSwitchOff.has("escape")) return "pvp";
        try {
            return localStorage.getItem(MODE_KEY) === "pvp" ? "pvp" : "solo";
        } catch (e) {
            return "solo";
        }
    }

    function saveMode(v) {
        try {
            localStorage.setItem(MODE_KEY, v);
        } catch (e) {}
    }

    function readPvpLevel() {
        try {
            const v = localStorage.getItem(PVP_LEVEL_KEY);
            return v === "lite" || v === "epic" ? v : "mid";
        } catch (e) {
            return "mid";
        }
    }

