            const stages = [];
            let y = 0;

            const ring = makeRing();
            stages.push({
                kind: "ring",
                y0: 0,
                y1: RING_H
            });
            y = RING_H;

            const lib = STAGE_KINDS;
            let finalePre = o.finale;
            if (!finalePre) {
                let tot = 0;
                for (let i = 0; i < FINALES.length; i++) tot += FINALE_W[FINALES[i]];
                let r = rng() * tot;
                finalePre = FINALES[FINALES.length - 1];
                for (let i = 0; i < FINALES.length; i++) {
                    r -= FINALE_W[FINALES[i]];
                    if (r <= 0) {
                        finalePre = FINALES[i];
                        break;
                    }
                }
            }
            const picked = [];
            if (o.kinds) {
                for (let i = 0; i < o.kinds.length; i++) picked.push(o.kinds[i]);
            } else if (o.mids !== undefined) {
                while (picked.length < mids) {
                    const k = lib[Math.floor(rng() * lib.length)];
                    if (picked.indexOf(k) < 0) picked.push(k);
                }
            } else {
                const budget = STAGE_BUDGET - FINALE_NET[finalePre];
                const pool = lib.slice();
                let sum = 0;
                while (picked.length < 7 && pool.length) {
                    if (picked.length >= 4 && sum >= budget - 0.6) break;
                    let tot = 0;
                    for (let i = 0; i < pool.length; i++) tot += KIND_INFO[pool[i]].w;
                    let r = rng() * tot;
                    let idx = pool.length - 1;
                    for (let i = 0; i < pool.length; i++) {
                        r -= KIND_INFO[pool[i]].w;
                        if (r <= 0) {
                            idx = i;
                            break;
                        }
                    }
                    const k = pool.splice(idx, 1)[0];
                    picked.push(k);
                    sum += KIND_INFO[k].c + 0.3;
                }
            }

            function addRot(stage, cx, cy, w, phase, locals, extra) {
                const m = {
                    type: "rot",
                    mode: "lin",
                    cx: cx,
                    cy: cy,
                    w: w,
                    phase: phase,
                    amp: 0,
                    local: locals,
                    stage: stage
                };
                if (extra)
                    for (const k in extra) m[k] = extra[k];
                movers.push(m);
                return m;
            }

