        if (info && info.serverSeed) resultHtml += '<div class="fair-block"><div class="fair-label">Прошлый раунд ' + escapeHtml(info.roundId) + ": секретный сид</div>" + '<div class="fair-hash" data-copy="' + escapeHtml(info.serverSeed) + '">' + fairHashHTML(info.serverSeed) + "</div></div>";
